#!/usr/bin/env bash
#
# Kit productization tests for egresslock (ARC-74-D2): the kit blocks moved
# out of the site consumer harness. Covers install-kit (ARC-16, kit-only
# asserts), uninstall-kit (ARC-17), setup-account (ARC-18), --init-conf
# (ARC-19), packaging (ARC-22), AppArmor work (ARC-22-D3 / ARC-66 / ARC-69
# / ARC-72) and the drift-signal hint (ARC-70). Fixtures are synthetic
# (example.test hosts, docs-range IPs, throwaway prefixes) so the tree
# relocates to the public repo (ARC-13-D5); nothing references the site
# tree or its conf.
#
# Consumer-bound actuals that exec the site's consumer wrapper or its
# copy_files.sh stay with their consumers (ARC-74-D7).
#
# Run:  bash tests/test-kit.sh   (or tests/run.sh; either way as a
#       non-root user — direct root invocation is refused, EGL-434)

# EGL-434 F1 (R-EGL-434-3; reopened R-EGL-434-6, R-EGL-434-8): refuse
# direct root invocation BEFORE any side effect. run.sh already refuses
# uid 0, but its guard is bypassed by the documented direct form above.
# Under real root several fake-root legs (the no-flag kit destination pins)
# hit their production paths and would write/remove /etc/systemd/system
# and /usr/local/{bin,sbin}. Refuse, never skip (EGL-86-D2); a "skip" here
# would falsely report a green security battery.
#
# The effective UID is read from the kernel's /proc/self/status `Uid:`
# line. Neither `id -u` nor bash's EUID is caller-safe: PATH lets an `id`
# shim hide a uid-0 run (R-EGL-434-6 F1), and bash imports a pre-set EUID
# from the environment at startup, so `env EUID=<nonzero>` hides one too
# (R-EGL-434-8). /proc/self/status is generated by the kernel for this
# process and cannot be forged. Fail closed if it is unreadable or the
# effective UID is not numeric instead of running with unknown privilege.
egl434_euid=""
if [[ -r /proc/self/status ]]; then
    while IFS=$' \t' read -r egl434_key egl434_real egl434_eff egl434_saved egl434_fs; do
        if [[ "$egl434_key" == "Uid:" ]]; then
            egl434_euid="$egl434_eff"
            break
        fi
    done < /proc/self/status
fi
if [[ ! "${egl434_euid:-}" =~ ^[0-9]+$ ]]; then
    echo "test-kit.sh: FAIL cannot determine the effective UID (kernel Uid='${egl434_euid:-}') — refusing to run the kit battery with unknown privilege, because its mocked root-guard and no-flag destination legs are invalid under uid 0 and would write the real /etc and /usr/local targets (EGL-434 F1)" >&2
    exit 2
fi
if (( egl434_euid == 0 )); then
    echo "test-kit.sh: FAIL run tests as an unprivileged account — the kit battery's mocked root-guard and no-flag destination legs are structurally invalid under uid 0 and would write the real /etc and /usr/local targets, so root execution is refused, not skipped (EGL-434 F1 / EGL-86-D2)" >&2
    echo "test-kit.sh: in a root-only container, run mapped: setpriv --reuid=nobody --regid=nogroup --clear-groups env HOME=/tmp bash tests/test-kit.sh" >&2
    exit 2
fi

# EGL-434 F1 probe seam: the root-guard pin runs this file with
# EGL434_ROOT_GUARD_PROBE=1 and a throwaway HOME, then checks which side
# of the guard the child reached. Exit here — before `source lib.sh` or any
# HOME side effect — so a non-refused probe is bounded and cannot run the
# battery. Normal runs never set it.
if [[ -n "${EGL434_ROOT_GUARD_PROBE:-}" ]]; then
    printf 'guard-pass euid=%s\n' "$egl434_euid"
    exit 0
fi

source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"

# EGL-491-D7: the no-flag strict controls compare full output against an
# unset-hook run. The new ignored-hook warning is the one permitted delta,
# so strip exactly its two sentences (never another WARNING line) before
# the compare; every re-pinned control also asserts the warning fired, so
# a filter that hides a regressed site cannot pass.
strip_egl491_warnings() {
    grep -vE 'is set but (ignored: it is a test-harness override and requires EGRESSLOCK_KIT_ALLOW_NON_ROOT=1; the production default applies\.|is not the exact value 1, so test mode is off; test-harness overrides are ignored\.)$' || true
}

# EGL-513: kit success lines (`Building`, `Done:`,
# `the scheduled check will verify every profile whose anchor is running`,
# `PATH wrapper installed:`) must be paste-safe. A `>` in one is a shell
# redirect: `X -> <path>` truncates <path> and a leading `>>` append-creates
# a file named after the next word. Assert the captured transcript has a
# line matching the family and none carries `>` (no vacuous pass on absence).
assert_kit_lines_paste_safe() { # <label> <transcript> <ERE>
    local lines bad
    lines="$(grep -E "$3" <<<"$2" || true)"
    bad="$(grep -F '>' <<<"$lines" || true)"
    if [[ -z "$lines" ]]; then
        assert fail "$1 transcript has no line matching $3"
    elif [[ -n "$bad" ]]; then
        assert fail "$1 line carries a shell redirect: $bad"
    else
        assert pass
        echo "PASS: $1 lines are paste-safe (no '>')"
    fi
}

# EGL-555: --init-conf now publishes with `ln -T`. The legacy EGL-433
# legs exercise the documented `mv -T` fallback (a filesystem without
# hard links); an `ln` that fails for a non-EEXIST reason selects that
# path without changing the race each leg injects at the rename.
force_mv_publish_fallback() { # <shim-dir>
    cat > "$1/ln" <<'EOF'
#!/usr/bin/env bash
# Simulate a filesystem without hard links; the publisher falls back.
exit 1
EOF
    chmod +x "$1/ln"
}

# EGL-517: setup help/usage text is paste-inert. Same shape as the engine
# helper: select command-shaped lines (summary index, page synopsis,
# Example body, usage/error) and assert no unquoted shell operator.
assert_setup_help_lines_paste_safe() { # <label> <transcript>
    local lines bad
    lines="$(awk '
        BEGIN { head = 1; inex = 0 }
        head && /^[[:space:]]*$/ { head = 0 }
        head && /^[[:space:]]*egresslock-setup[ -]/ { print; next }
        /^Examples?:$/ { inex = 1; next }
        /^[[:space:]]*$/ { inex = 0 }
        /^  egresslock-setup[ -]/ { print; next }
        /^usage: / { print; next }
        /^Error: / { print; next }
        inex { print }
    ' <<<"$2")"
    bad="$(sed -E "s/'[^']*'//g" <<<"$lines" | grep -E '[<>|&;`]' || true)"
    if [[ -z "$lines" ]]; then
        assert fail "$1 transcript has no command-shaped line"
    elif [[ -n "$bad" ]]; then
        assert fail "$1 command-shaped line carries a shell operator: $bad"
    else
        assert pass
        echo "PASS: $1 command-shaped lines are paste-inert"
    fi
}

# EGL-517-D2: every captured setup help-page line carries no angle bracket.
assert_setup_help_page_no_angles() { # <label> <transcript>
    local bad
    bad="$(grep -F -e '<' -e '>' <<<"$2" || true)"
    if [[ -z "$2" ]]; then
        assert fail "$1 transcript is empty"
    elif [[ -n "$bad" ]]; then
        assert fail "$1 help line carries an angle bracket: $bad"
    else
        assert pass
        echo "PASS: $1 help lines carry no angle bracket"
    fi
}

# EGL-517-D2/D3: emitted non-help setup/kit text is paste-inert. Same source
# scan as the engine: no `<...>` placeholder, no word|word alternation;
# full-line comments, podman's `<no value>` literal, and the generated
# Squid `#include <local/...>` line are allowlisted.
assert_setup_source_clean() { # <file> <label>
    local bad
    bad="$(awk '
        /^[[:space:]]*#/ { next }
        /"<no value>"/ { next }
        /#include[[:space:]]*<local\// { next }
        !/^[[:space:]]*(echo|printf|die|config_error)[[:space:]]/ { next }
        {
            if ($0 ~ /<[A-Za-z][^<>]*>/) {
                print "placeholder " FNR ": " $0
                next
            }
            line = $0
            gsub(/\|\|/, "", line)
            if (line ~ /[A-Za-z0-9_.)]\|[A-Za-z0-9_(]/) print "alternation " FNR ": " $0
        }
    ' "$1")"
    if [[ -n "$bad" ]]; then
        assert fail "$2 emitted text is not paste-inert: $bad"
    else
        assert pass
        echo "PASS: $2 emitted text has no placeholder/alternation"
    fi
}

# Synthetic conf for the kit's engine-side exercises (neutral hosts).
# EGL-325: there is no runtime conf selector. The account confdir is fixed
# at <passwd-home>/.config/egresslock and the file basename must match the
# profile it defines, so the fixture lives there as workstation.conf.
export ARCMOCK_DNS_BASE="git.example.test=192.0.2.10,cache.example.test=192.0.2.11"
mkdir -p "$HOME/.config/egresslock"
KITCONF="$HOME/.config/egresslock/workstation.conf"
cat > "$KITCONF" <<'EOF'
profile workstation 10.50.0.0/24
    rule allow-host git.example.test:443
    rule allow-host git.example.test:2222
    rule allow-host cache.example.test:11434
    gateway 10.50.0.2 3128 workstation-allowlist
EOF
: > "$HOME/.config/egresslock/workstation-allowlist"
export PATH="$TESTROOT/bin:$TREE_ROOT:$PATH"
# EGL-352: capture this harness process's own fd 2; the unconditional tail
# check fails a green run that wrote to it.
harness_stderr_guard_init

# The mock state mirrors the fixture assumptions the moved kit blocks
# relied on (gateway image marker, IPAM dir).
mkdir -p "$STATE/images" "$STATE/ips"
: > "$STATE/images/localhost_egresslock-gateway_latest"
# EGL-206-D2a: the alpine:latest anchor marker the kit's engine-side
# exercises inspect is already seeded by tests/lib.sh (the mock `podman
# run` never pulls) — do not re-seed here.

# EGL-550-D6: the packaging producers are absent on the extracted kit
# (ARC-22-D4), so their consumers skip with a named cause. These flags
# used to live inside the deleted egl12 window; they stay outside every
# section because egl420, egl49, arc22, egl27/egl72/egl83/egl491 and more
# consume them (a naive section delete broke ~20 later skips under set -u).
HAVE_BUILD_DEB=0; [[ -f "$TREE_ROOT/packaging/build-deb.sh" ]] && HAVE_BUILD_DEB=1
HAVE_BUILD_TARBALL=0; [[ -f "$TREE_ROOT/packaging/build-tarball.sh" ]] && HAVE_BUILD_TARBALL=1
PKG_SKIP_TAG="packaging-build-scripts absent"

# --- ARC-16: kit productization ---
section_begin arc16 "ARC-16 kit productization"

a16() { assert "$@"; }
KIT="$TREE_ROOT/install-kit.sh"
OPT="$STATE/opt-kit"          # mock --prefix
UNITS="$STATE/units"          # mock unit dir
: > "$STATE/systemctl.log"

mkdir -p "$UNITS" "$OPT"

# 1. install-kit: non-root hook, kit files, unit templates, per-account
#    timer enable.
# Direct exec (no `bash` wrapper): catches a committed-non-executable
# installer — R-016-2 F5.
a16_x=1
[[ -x "$KIT" ]] || { a16_x=0; a16 fail "install-kit.sh is executable in git"; }
[[ -x "$TREE_ROOT/egresslock-verify" ]] || { a16_x=0; a16 fail "egresslock-verify is executable in git (F6)"; }
if (( a16_x )); then a16 pass; fi
i_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$OPT/wbin" EGRESSLOCK_PATH_SBINDIR="$OPT/wsbin" \
    "$KIT" --prefix "$OPT" 2>&1)"; i_rc=$?
if [[ "$i_rc" == 0 ]]; then a16 pass; else a16 fail "install-kit run (rc=$i_rc, out: $i_out)"; fi
# EGL-121 positive control: on a systemd host (mock systemctl) the reload
# runs and the new no-systemd warning stays silent.
grep -q '^systemctl daemon-reload$' "$STATE/systemctl.log" \
    && a16 pass || a16 fail "install reloads the units on a systemctl host"
[[ "$i_out" != *"WARNING - systemd did not confirm"* ]] \
    && a16 pass || a16 fail "no reload warning on a systemctl host (out: $i_out)"
for f in egresslock egresslock-start egresslock-verify VERSION egresslock-setup; do
    [[ -f "$OPT/$f" ]] && a16 pass || a16 fail "kit file deployed: $f"
done
# ARC-23: the deployed egresslock-setup is a byte copy of the repo copy.
cmp -s "$TREE_ROOT/egresslock-setup" "$OPT/egresslock-setup" \
    && a16 pass || a16 fail "egresslock-setup deployed byte-identical (ARC-23)"
[[ -d "$OPT/gateway" && -f "$OPT/gateway/Containerfile" ]] \
    && a16 pass || a16 fail "gateway build context deployed (D6)"
# EGL-69-D2: the prefix ships the pasta AppArmor snippet (root-owned).
[[ -f "$OPT/apparmor/usr.bin.pasta.local" && -f "$OPT/apparmor/README.md" ]] \
    && a16 pass || a16 fail "apparmor snippet deployed to prefix (EGL-69-D2)"
# EGL-556-D2: the prefix ships the docs pages the messages point at —
# regular .md only, structure preserved, and `go-w` like the other trees;
# tickets/ and the generated BOARD.md stay process material.
a16_docs_leaves() { ( cd "$1" && find docs -type f -name '*.md' \
    ! -path 'docs/tickets/*' ! -name 'BOARD.md' -printf '%P\n' | sort ); }
if [[ -f "$OPT/docs/reference/operator-obligations.md" \
      && -f "$OPT/docs/troubleshooting/pasta-apparmor.md" \
      && -f "$OPT/docs/README.md" \
      && ! -e "$OPT/docs/tickets" && ! -e "$OPT/docs/BOARD.md" \
      && -z "$(find "$OPT/docs" -perm /022 -print)" \
      && "$(a16_docs_leaves "$TREE_ROOT")" == "$(a16_docs_leaves "$OPT")" ]]; then
    a16 pass
else
    a16 fail "prefix docs stage ships the selected .md pages, go-w, no process material (diff: $(diff <(a16_docs_leaves "$TREE_ROOT") <(a16_docs_leaves "$OPT") 2>/dev/null | tr '\n' '|'))"
fi
# EGL-232: the shared example base image (egl-base) ships with the kit;
# EGL-240: the build helper ships executable beside it.
[[ -f "$OPT/examples/egl-base/Containerfile" && -f "$OPT/examples/egl-base/README.md" && -x "$OPT/examples/egl-base/build-egl-base" ]] \
    && a16 pass || a16 fail "egl-base build context deployed (EGL-232)"
# EGL-549: one manifest drives the gate and the copy, so the installed
# tree is exactly the source tree's leaf set (a new source leaf must be
# added to the manifest or this reds) and the deployed modes are the
# documented 0644/0755 set even under a nonstandard umask (install -m,
# not cp -R).
a16_tree_leaves() { ( cd "$1" && find gateway apparmor examples -type f -printf '%p\n' | sort ); }
if [[ "$(a16_tree_leaves "$TREE_ROOT")" == "$(a16_tree_leaves "$OPT")" ]]; then
    a16 pass
else
    a16 fail "installed kit leaf set matches the source tree (diff: $(diff <(a16_tree_leaves "$TREE_ROOT") <(a16_tree_leaves "$OPT") | tr '\n' '|'))"
fi
if [[ "$(stat -c %a "$OPT/gateway/squid.conf")" == 644 ]] \
   && [[ "$(stat -c %a "$OPT/examples/egl-base/build-egl-base")" == 755 ]] \
   && [[ -x "$OPT/examples/egl-base/build-egl-base" ]] \
   && [[ "$(stat -c %a "$OPT/examples/recipes")" == 755 ]] \
   && [[ -z "$(find "$OPT/examples/recipes" -maxdepth 0 -perm /022 -print)" ]]; then
    a16 pass
else
    a16 fail "installed kit modes are the documented 0644/0755 set (squid.conf=$(stat -c %a "$OPT/gateway/squid.conf" 2>/dev/null), build-egl-base=$(stat -c %a "$OPT/examples/egl-base/build-egl-base" 2>/dev/null), recipes=$(stat -c %a "$OPT/examples/recipes" 2>/dev/null))"
fi
# EGL-549 mutation controls on a scratch kit tree: a listed-but-missing
# leaf must fail the gate closed before any write, and a
# present-but-unlisted source leaf must diverge from the installed set
# (the pin is dynamic; a hardcoded expected list would pass the unlisted
# case and fail the control).
sc="$TESTROOT/kit549"
scp="$TESTROOT/kit549-prefix"
a16_kit549_run() { # <kit tree> <prefix>
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
        EGRESSLOCK_UNIT_DIR="$TESTROOT/kit549-units" \
        EGRESSLOCK_PATH_BINDIR="$TESTROOT/kit549-wbin" \
        EGRESSLOCK_PATH_SBINDIR="$TESTROOT/kit549-wsbin" \
        "$1/install-kit.sh" --prefix "$2" 2>&1
}
rm -rf "$sc" "$scp"
mkdir -p "$sc" "$TESTROOT/kit549-units" "$TESTROOT/kit549-wbin" "$TESTROOT/kit549-wsbin"
cp -a "$TREE_ROOT/install-kit.sh" "$TREE_ROOT/VERSION_BASE" \
      "$TREE_ROOT/egresslock" "$TREE_ROOT/egresslock-start" \
      "$TREE_ROOT/egresslock-verify" "$TREE_ROOT/egresslock-setup" \
      "$TREE_ROOT/gateway" "$TREE_ROOT/apparmor" "$TREE_ROOT/examples" \
      "$TREE_ROOT/docs" "$TREE_ROOT/systemd" "$sc/"
# 1. listed-but-missing: the gate names the leaf and writes nothing.
rm -f "$sc/gateway/squid.conf"
o="$(a16_kit549_run "$sc" "$scp")"; rc=$?
if [[ "$rc" == 1 && "$o" == *"missing: gateway/squid.conf"* && ! -e "$scp" ]]; then
    a16 pass
else
    a16 fail "listed-but-missing kit leaf fails closed before any write (rc=$rc, prefix exists: $([[ -e "$scp" ]] && echo yes || echo no), out: $(tail -2 <<<"$o" | tr '\n' '|'))"
fi
# 2. present-but-unlisted: the install succeeds and the pin sees the
# divergence (the source set carries a leaf the installed set does not).
cp -a "$TREE_ROOT/gateway/squid.conf" "$sc/gateway/squid.conf"
: > "$sc/gateway/zz-unlisted"
rm -rf "$scp"
o="$(a16_kit549_run "$sc" "$scp")"; rc=$?
if [[ "$rc" == 0 && "$(a16_tree_leaves "$sc")" != "$(a16_tree_leaves "$scp")" ]]; then
    a16 pass
else
    a16 fail "present-but-unlisted kit leaf diverges from the installed set (rc=$rc, diff: $(diff <(a16_tree_leaves "$sc") <(a16_tree_leaves "$scp") 2>/dev/null | tr '\n' '|'), out: $(tail -2 <<<"$o" | tr '\n' '|'))"
fi
# EGL-556-D2: the docs tree joins the source gate. A missing docs/ and a
# symlinked docs/ both fail closed before any copy, naming `docs`.
rm -rf "$scp"
rm -rf "$sc/docs"
o="$(a16_kit549_run "$sc" "$scp")"; rc=$?
if [[ "$rc" == 1 && "$o" == *"(missing: docs)"* && ! -e "$scp" ]]; then
    a16 pass
else
    a16 fail "missing docs/ fails closed pre-copy (rc=$rc, prefix exists: $([[ -e "$scp" ]] && echo yes || echo no), out: $(tail -2 <<<"$o" | tr '\n' '|'))"
fi
ln -s "$TREE_ROOT/docs" "$sc/docs"
rm -rf "$scp"
o="$(a16_kit549_run "$sc" "$scp")"; rc=$?
if [[ "$rc" == 1 && "$o" == *"(missing: docs)"* && ! -e "$scp" ]]; then
    a16 pass
else
    a16 fail "symlinked docs/ fails closed pre-copy (rc=$rc, prefix exists: $([[ -e "$scp" ]] && echo yes || echo no), out: $(tail -2 <<<"$o" | tr '\n' '|'))"
fi
rm -rf "$sc" "$scp"
[[ -f "$UNITS/egresslock-verify@.service" && -f "$UNITS/egresslock-verify@.timer" ]] \
    && a16 pass || a16 fail "instanced templates installed (D1)"
grep -qxF 'PartOf=egresslock-verify@%i.timer' "$UNITS/egresslock-verify@.service" \
    && a16 pass || a16 fail "installed unit stops the verify oneshot with its timer (PartOf=)"
# EGL-103-D1: shipped unit text carries the generated-file notice and
# short comments — no internal ticket IDs ride along.
if grep -q "do not edit" "$UNITS/egresslock-verify@.service" \
   && grep -q "do not edit" "$UNITS/egresslock-verify@.timer"; then
    a16 pass
else
    a16 fail "installed unit files carry the generated-file notice (EGL-103)"
fi
if grep -qE 'EGL-|ARC-' "$UNITS/egresslock-verify@.service" \
                        "$UNITS/egresslock-verify@.timer"; then
    a16 fail "shipped unit text leaks ticket IDs (EGL-103)"
else
    a16 pass
fi
# ARC-18-D4: install-kit is kit-level; it must NOT enable any per-account
# timer (that is setup-account --enable, after the account is configured).
grep -qE "enable --now egresslock-verify@" "$STATE/systemctl.log" \
    && a16 fail "install-kit enabled a timer (moved to setup-account)" \
    || a16 pass
v_out="$("$OPT/egresslock" --version 2>&1)"
grep -q "^commit: " <<<"$v_out" && a16 pass || a16 fail "--version prints kit stamp (D5): $v_out"
# ARC-18-D4: --account is no longer an install-kit argument.
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$OPT/wbin" EGRESSLOCK_PATH_SBINDIR="$OPT/wsbin" \
    "$KIT" --prefix "$OPT" --account root >/dev/null 2>&1
[[ $? == 2 ]] && a16 pass || a16 fail "install-kit rejects --account (rc 2)"
# 2. Wrapper (D2 explicit-only, D4 resolution): deployed copy.
w_out="$(env -u EGRESSLOCK_PROFILE "$OPT/egresslock-start" daemon 2>&1)"; w_rc=$?
if [[ "$w_rc" == 1 && "$w_out" == *"EGRESSLOCK_PROFILE is required"* ]]; then
    a16 pass
else
    a16 fail "wrapper fails closed without EGRESSLOCK_PROFILE (rc=$w_rc, out: $w_out)"
fi
w_out="$(env EGRESSLOCK_PROFILE=workstation "$OPT/egresslock-start" daemon 2>&1)"; w_rc=$?
[[ "$w_rc" == 1 && "$w_out" == *"RUNNER_BIN is required"* ]] \
    && a16 pass || a16 fail "wrapper fails closed without RUNNER_BIN (rc=$w_rc, out: $w_out)"
w_out="$(env EGRESSLOCK_PROFILE=workstation \
    RUNNER_BIN=echo "$OPT/egresslock-start" daemon -c /tmp/cfg 2>&1)"; w_rc=$?
if [[ "$w_rc" == 0 && "$w_out" == *"daemon -c /tmp/cfg"* ]]; then
    a16 pass
else
    a16 fail "wrapper ensure+exec with explicit env (rc=$w_rc, out: $w_out)"
fi
# D4: a broken EGRESSLOCK_DIR wins over the working script dir.
w_out="$(env EGRESSLOCK_DIR="$STATE/empty-dir" EGRESSLOCK_PROFILE=workstation \
    RUNNER_BIN=echo "$OPT/egresslock-start" daemon 2>&1)"; w_rc=$?
[[ "$w_rc" == 1 && "$w_out" == *"$STATE/empty-dir/egresslock"* ]] \
    && a16 pass || a16 fail "wrapper honors EGRESSLOCK_DIR first (rc=$w_rc, out: $w_out)"

# 3. egresslock-verify (D3 hybrid), deployed copy.
# EGL-325: nothing but the engine is required. Sweep mode with no profile
# and nothing ensured is rc 0 with only the aggregate resolution line.
egresslock teardown workstation >/dev/null 2>&1 || true
va_out="$(env -u EGRESSLOCK_PROFILE "$OPT/egresslock-verify" 2>&1)"; va_rc=$?
[[ "$va_rc" == 0 && "$va_out" == "using configs in $HOME/.config/egresslock (1 profiles)"* \
   && "$va_out" != *"verified (ensured)"* ]] \
    && a16 pass || a16 fail "egresslock-verify sweep with nothing ensured (rc=$va_rc, out: $va_out)"
# EGL-333-D6: a set EGRESSLOCK_PROFILE is ignored silently — the wrapper
# still runs bare `verify --ensured` (it belongs to egresslock-start).
# Ensure workstation first so the sweep has something to check.
egresslock ensure workstation >/dev/null 2>&1
va_out="$(env EGRESSLOCK_PROFILE=workstation "$OPT/egresslock-verify" 2>&1)"; va_rc=$?
[[ "$va_rc" == 0 && "$va_out" == *"verified (ensured)"* \
   && "$va_out" != *"EGRESSLOCK_PROFILE"* ]] \
    && a16 pass || a16 fail "egresslock-verify ignores a set EGRESSLOCK_PROFILE (rc=$va_rc, out: $va_out)"
# ensured mode (PROFILE unset): the sweep runs bare `verify --ensured`
# against the account's fixed confdir aggregate. The workstation fixture
# already lives in that confdir, so the named-mode ensure above is the
# anchor the sweep must find.
# EGL-140-D1: the pin record is a sibling of the RESOLVED conf; re-ensure
# so the record is present beside the confdir conf the sweep resolves.
egresslock ensure workstation >/dev/null 2>&1
va_out="$(env -u EGRESSLOCK_PROFILE "$OPT/egresslock-verify" 2>&1)"; va_rc=$?
[[ "$va_rc" == 0 && "$va_out" == *"verified (ensured)"* ]] \
    && a16 pass || a16 fail "egresslock-verify ensured mode (rc=$va_rc, out: $va_out)"
# tamper: drift in the ensured profile's chain must fail the timer entry.
sed -i '/dport 2222/d' "$STATE/nft/egresslock.p_workstation"
va_out="$(env -u EGRESSLOCK_PROFILE "$OPT/egresslock-verify" 2>&1)"; va_rc=$?
[[ "$va_rc" == 1 ]] && a16 pass || a16 fail "egresslock-verify fails on drift (rc=$va_rc, out: $va_out)"
egresslock ensure workstation >/dev/null 2>&1

section_end arc16

# --- EGL-85: verify wrapper's bounded-probe failure modes (deployed
# --- copy; the ARC-26 engine test covers the engine path) ---------------
# The netns preflight (EGL-78) has two uncovered branches: timeout(1)
# absent (fail closed) and probe expiry (named 5s failure). Both run
# BEFORE the engine exec, so chain state is untouched. D2: real 5s wait,
# far under the 600s harness bound (EGL-225).
section_begin egl85 "EGL-85 verify timeout paths"
a85() { assert "$@"; }

# 1. timeout(1) absent -> rc 1 + the coreutils message, before any
#    engine run. Isolated PATH (bin-doctor-none technique): only what
#    the wrapper needs before the probe gate, deliberately NO timeout.
ntk="$TESTROOT/bin-verify-notimeout"
rm -rf "$ntk"; mkdir -p "$ntk"
for t in env bash dirname id cat head; do ln -s "$(command -v "$t")" "$ntk/$t"; done
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$ntk" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
[[ "$v_rc" == 1 && "$v_out" == *"timeout(1) (coreutils) is required for the netns probe"* ]] \
    && a85 pass || a85 fail "verify without timeout(1) fails closed (rc=$v_rc, out: $v_out)"

# 2. probe expiry: podman shim sleeps 60s on the probe command only;
#    the wrapper must die with the named 5s-timeout message well under
#    the harness bound (and never fall through to the engine verify).
mkdir -p "$TESTROOT/bin-verify-hang"
cat > "$TESTROOT/bin-verify-hang/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    sleep 60
    exit 0
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-hang/podman"
v_start=$SECONDS
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-hang:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
v_elapsed=$(( SECONDS - v_start ))
[[ "$v_rc" == 1 && "$v_out" == *"netns probe timed out after 5s"* \
    && "$v_out" != *"ignored TERM"* && "$v_elapsed" -lt 15 ]] \
    && a85 pass || a85 fail "verify probe expiry is a named 5s failure (rc=$v_rc, elapsed=${v_elapsed}s, out: $v_out)"

# 2b. EGL-583: a probe that ignores TERM is KILLed after the 1s grace
#     (`timeout -k 1 5`), so the 5s bound still holds; the named timeout
#     line says so and echoes the real probe (no generic "broken"
#     branch, which would blame podman for the bound working).
mkdir -p "$TESTROOT/bin-verify-termtrap"
cat > "$TESTROOT/bin-verify-termtrap/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    trap '' TERM
    # EGL-609: single process on purpose. The KILL must take the direct
    # child on every timeout(1) implementation; a separate sleep 30
    # grandchild can survive it and hold the captured pipe for the full
    # 30s, so the elapsed bound would measure the leak, not the wrapper.
    exec sleep 30
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-termtrap/podman"
v_start=$SECONDS
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-termtrap:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
v_elapsed=$(( SECONDS - v_start ))
[[ "$v_rc" == 1 \
    && "$v_out" == *"netns probe timed out after 5s"* \
    && "$v_out" == *"timeout -k 1 5 podman unshare --rootless-netns true"* \
    && "$v_out" == *"the probe ignored TERM and was killed after the 1s grace"* \
    && "$v_out" != *"rootless-netns is broken"* \
    && "$v_elapsed" -lt 15 ]] \
    && a85 pass || a85 fail "verify TERM-ignoring probe is KILLed after the grace (rc=$v_rc, elapsed=${v_elapsed}s, out: $v_out)"

# 2c. F1 (R-EGL-583-2): timeout(1) reports 137 for any SIGKILL death of
#     the probe, so one killed from outside well under the 5s bound
#     (here: a self-kill) must take the generic branch and report the
#     real rc — never the 5s/TERM/grace timeout narrative.
mkdir -p "$TESTROOT/bin-verify-selfkill"
cat > "$TESTROOT/bin-verify-selfkill/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    kill -9 "\$\$"
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-selfkill/podman"
v_start=$SECONDS
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-selfkill:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
v_elapsed=$(( SECONDS - v_start ))
[[ "$v_rc" == 1 \
    && "$v_out" == *"rootless-netns is broken"* \
    && "$v_out" == *"rc=137"* \
    && "$v_out" != *"netns probe timed out after 5s"* \
    && "$v_out" != *"ignored TERM"* ]] \
    && a85 pass || a85 fail "verify externally SIGKILLed probe reports the real cause (rc=$v_rc, elapsed=${v_elapsed}s, out: $v_out)"

# 2d. F6 (R-EGL-583-4): a 137 that lands inside the (0s, 5s) window is an
#     external SIGKILL, not the grace KILL, so the elapsed gate must send
#     it to the generic branch. This also pins the gate threshold itself:
#     the extreme-only legs would miss a drift like `>= 5` -> `>= 1`.
mkdir -p "$TESTROOT/bin-verify-midkill"
cat > "$TESTROOT/bin-verify-midkill/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    sleep 2
    kill -9 "\$\$"
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-midkill/podman"
v_start=$SECONDS
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-midkill:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
v_elapsed=$(( SECONDS - v_start ))
[[ "$v_rc" == 1 \
    && "$v_out" == *"rootless-netns is broken"* \
    && "$v_out" == *"rc=137"* \
    && "$v_out" != *"netns probe timed out after 5s"* \
    && "$v_out" != *"ignored TERM"* ]] \
    && a85 pass || a85 fail "verify mid-window SIGKILL stays off the timeout path (rc=$v_rc, elapsed=${v_elapsed}s, out: $v_out)"

# 2e. F5 (R-EGL-583-4): timeout(1) also propagates a probe's own 124, so
#     an early 124 must take the generic branch with the real rc — never
#     the 5s narrative on a probe that never reached the bound.
mkdir -p "$TESTROOT/bin-verify-exit124"
cat > "$TESTROOT/bin-verify-exit124/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    exit 124
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-exit124/podman"
v_start=$SECONDS
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-exit124:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
v_elapsed=$(( SECONDS - v_start ))
[[ "$v_rc" == 1 \
    && "$v_out" == *"rootless-netns is broken"* \
    && "$v_out" == *"rc=124"* \
    && "$v_out" != *"netns probe timed out after 5s"* \
    && "$v_out" != *"ignored TERM"* ]] \
    && a85 pass || a85 fail "verify early 124 exit reports the real cause (rc=$v_rc, elapsed=${v_elapsed}s, out: $v_out)"

# 3. EGL-347-D1: the wrapper reports podman's actual error and routes the
# AppArmor-shaped failure through the checker (no fixed claim, and the
# disruptive `systemctl restart user@` fallback is gone).
mkdir -p "$TESTROOT/bin-verify-pasta"
cat > "$TESTROOT/bin-verify-pasta/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    echo "Error: rootless netns: kill network process: permission denied" >&2
    exit 126
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-pasta/podman"
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-pasta:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
e556_vpasta="$OPT/docs/troubleshooting/pasta-apparmor.md"
[[ "$v_rc" == 1 \
    && "$v_out" == *"egresslock-verify: Error: podman rootless-netns is broken"* \
    && "$v_out" == *"rootless netns: kill network process: permission denied"* \
    && "$v_out" == *"egresslock-setup apparmor check"* \
    && "$v_out" == *"egresslock-setup apparmor add"* \
    && "$v_out" == *"the pasta/AppArmor troubleshooting page: $e556_vpasta"* \
    && "$v_out" == *"the pasta/AppArmor troubleshooting page (Diagnosis): $e556_vpasta"* \
    && "$(grep -cF "the pasta/AppArmor troubleshooting page: $e556_vpasta" <<<"$v_out")" == 2 \
    && "$v_out" != *"systemctl restart user@"* ]] \
    && a85 pass || a85 fail "verify pasta probe is checker-led, no fixed claim (rc=$v_rc, out: $v_out)"

# 4. EGL-347-D1: a stray/manual inherited-CWD line is excluded from the
# AppArmor shape rule and gets the netns pointer, with no CWD-specific
# advice and no AppArmor pointer.
mkdir -p "$TESTROOT/bin-verify-cwd"
cat > "$TESTROOT/bin-verify-cwd/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    echo "cannot chdir to /home/ben: Permission denied" >&2
    exit 126
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-cwd/podman"
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-cwd:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
[[ "$v_rc" == 1 \
    && "$v_out" == *"cannot chdir to /home/ben: Permission denied"* \
    && "$v_out" == *"the shared-netns troubleshooting page: $OPT/docs/troubleshooting/netns-inspection.md"* \
    && "$v_out" != *"apparmor check"* && "$v_out" != *"apparmor add"* \
    && "$v_out" != *"sudo -iu"* \
    && "$v_out" != *"cannot use the directory"* ]] \
    && a85 pass || a85 fail "verify CWD probe gets netns pointer, not AppArmor (rc=$v_rc, out: $v_out)"

# 4b. EGL-347-D1: a probe that fails with no output still reports the
#     placeholder and routes the rc-126 shape through the checker — the
#     empty-output branch is a pinned failure path, not a silent pass.
mkdir -p "$TESTROOT/bin-verify-silent"
cat > "$TESTROOT/bin-verify-silent/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "unshare" && "\$2" == "--rootless-netns" && "\$3" == "true" ]]; then
    exit 126
fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$TESTROOT/bin-verify-silent/podman"
v_out="$(env -u EGRESSLOCK_PROFILE PATH="$TESTROOT/bin-verify-silent:$PATH" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
[[ "$v_rc" == 1 \
    && "$v_out" == *"egresslock-verify:   (probe printed no output)"* \
    && "$v_out" == *"egresslock-setup apparmor check"* \
    && "$v_out" == *"the pasta/AppArmor troubleshooting page: $e556_vpasta"* \
    && "$v_out" != *"systemctl restart user@"* ]] \
    && a85 pass || a85 fail "verify silent probe gets placeholder + checker route (rc=$v_rc, out: $v_out)"

# 4c. EGL-556-D4: a kit with no docs tree prints the page title alone —
#     the resolver never invents a path the operator cannot open.
e556_vkit="$TESTROOT/verify-egl556-nodocs"; rm -rf "$e556_vkit"; mkdir -p "$e556_vkit"
printf '#!/usr/bin/env bash\nexit 0\n' > "$e556_vkit/egresslock"
chmod +x "$e556_vkit/egresslock"
v_out="$(env -u EGRESSLOCK_PROFILE EGRESSLOCK_DIR="$e556_vkit" \
    PATH="$TESTROOT/bin-verify-cwd:$PATH" "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
[[ "$v_rc" == 1 \
    && "$v_out" == *"the shared-netns troubleshooting page"* \
    && "$v_out" != *"the shared-netns troubleshooting page:"* \
    && "$v_out" != *"docs/troubleshooting/netns-inspection.md"* ]] \
    && a85 pass || a85 fail "verify missing docs tree prints the title only (rc=$v_rc, out: $v_out)"

# 5. EGL-378-D4/D5: the probe itself runs from /, so an inherited CWD
#    the account cannot traverse no longer kills the wrapper before the
#    engine runs. Mutation: revert the wrapper's cd / -> the mock probe
#    fails at startup -> the wrapper prints the probe failure -> reds.
mk378="$STATE/mockkit378"; rm -rf "$mk378"; mkdir -p "$mk378"
cat > "$mk378/egresslock" <<'EOF'
#!/usr/bin/env bash
exit 0
EOF
chmod +x "$mk378/egresslock"
v378cwd="$TESTROOT/verify-cwd378"; mkdir -p "$v378cwd"
: > "$STATE/podman-cwd-egl378.log"
( cd "$v378cwd" && chmod 000 . && env -u EGRESSLOCK_PROFILE \
    EGRESSLOCK_DIR="$mk378" ARCMOCK_PODMAN_CWD_LOG="$STATE/podman-cwd-egl378.log" \
    "$OPT/egresslock-verify" ) > "$TESTROOT/egl378-verify.out" 2>&1; v378_rc=$?
chmod 755 "$v378cwd"
v378_log="$(sort -u "$STATE/podman-cwd-egl378.log")"
if [[ "$v378_rc" == 0 && "$v378_log" == "/" \
      && "$(cat "$TESTROOT/egl378-verify.out")" != *"rootless-netns is broken"* ]]; then
    a85 pass
else
    a85 fail "verify probe runs from / under an untraversable CWD (rc=$v378_rc, cwd-log: $(printf '%s' "$v378_log" | tr '\n' '|'), out: $(cat "$TESTROOT/egl378-verify.out"))"
fi

# 6. R-EGL-378-8: the wrapper probe must preserve a relative Podman
#    path-valued setting across its own cd / seam. The mock podman
#    resolves CONTAINERS_CONF at startup from the inherited CWD; with
#    preservation the relative file opens, without it /podman.conf is
#    missing and the probe reports the netns broken. Mutation: drop
#    vprobe_env -> probe rc 125 -> wrapper rc 1 -> reds.
v378env="$TESTROOT/verify-env378"; rm -rf "$v378env"; mkdir -p "$v378env"
printf '[engine]\n' > "$v378env/podman.conf"
: > "$STATE/podman-env-egl378.log"
( cd "$v378env" && env -u EGRESSLOCK_PROFILE \
    EGRESSLOCK_DIR="$mk378" ARCMOCK_PODMAN_CONFIG_VARS=CONTAINERS_CONF \
    ARCMOCK_PODMAN_CONFIG_LOG="$STATE/podman-env-egl378.log" \
    CONTAINERS_CONF=./podman.conf \
    "$OPT/egresslock-verify" ) > "$TESTROOT/egl378-verify-env.out" 2>&1; v378env_rc=$?
v378envlog="$(sort -u "$STATE/podman-env-egl378.log")"
if [[ "$v378env_rc" == 0 \
      && "$v378envlog" == "CONTAINERS_CONF=$v378env/./podman.conf" \
      && "$(cat "$TESTROOT/egl378-verify-env.out")" != *"rootless-netns is broken"* ]]; then
    a85 pass
else
    a85 fail "wrapper probe preserves relative CONTAINERS_CONF (rc=$v378env_rc, log: $(printf '%s' "$v378envlog" | tr '\n' '|'), out: $(cat "$TESTROOT/egl378-verify-env.out"))"
fi

# 7. Absolute control for the wrapper seam: an absolute CONTAINERS_CONF
#    passes through byte-identical (no prefix, no second copy).
: > "$STATE/podman-env-egl378-abs.log"
( cd "$v378env" && env -u EGRESSLOCK_PROFILE \
    EGRESSLOCK_DIR="$mk378" ARCMOCK_PODMAN_CONFIG_VARS=CONTAINERS_CONF \
    ARCMOCK_PODMAN_CONFIG_LOG="$STATE/podman-env-egl378-abs.log" \
    CONTAINERS_CONF="$v378env/podman.conf" \
    "$OPT/egresslock-verify" ) > "$TESTROOT/egl378-verify-env-abs.out" 2>&1; v378abs_rc=$?
v378abslog="$(sort -u "$STATE/podman-env-egl378-abs.log")"
if [[ "$v378abs_rc" == 0 \
      && "$v378abslog" == "CONTAINERS_CONF=$v378env/podman.conf" \
      && "$v378abslog" != *"/./"* ]]; then
    a85 pass
else
    a85 fail "wrapper probe leaves absolute CONTAINERS_CONF unchanged (rc=$v378abs_rc, log: $(printf '%s' "$v378abslog" | tr '\n' '|'), out: $(cat "$TESTROOT/egl378-verify-env-abs.out"))"
fi

section_end egl85

# --- EGL-115: sweep-mode wrapper scoping (deployed copy) ----------------
# The timer's sweep must exec the BARE `verify --ensured`; the engine then
# default-probes the account's fixed confdir and aggregates every *.conf
# there (EGL-325 removed --config and EGRESSLOCK_CONF entirely). Named
# mode passes only the profile name. Neither mode may leak a selector
# into the engine child.
section_begin egl115 "EGL-115 sweep-mode wrapper scoping"
a115() { assert "$@"; }

# Recording engine: EGRESSLOCK_DIR wins the kit-dir resolution, so the
# wrapper execs this instead of the real engine and we can pin the
# exact argv + child env. Netns probe skipped (argv is the subject).
mk115="$STATE/mockkit115"; rm -rf "$mk115"; mkdir -p "$mk115"
cat > "$mk115/egresslock" <<EOF
#!/usr/bin/env bash
{
    printf 'argv:'
    for a in "\$@"; do printf ' <%s>' "\$a"; done
    printf '\n'
    printf 'conf-env:%s\n' "\${EGRESSLOCK_CONF:-<unset>}"
} >> "$mk115/record"
exit 0
EOF
chmod +x "$mk115/egresslock"

# 1. Sweep mode: PROFILE unset -> argv is exactly `verify --ensured` and
#    the child env carries no EGRESSLOCK_CONF (EGL-325: no conf wiring).
: > "$mk115/record"
v_out="$(env -u EGRESSLOCK_PROFILE EGRESSLOCK_SKIP_NETNS_PROBE=1 \
    EGRESSLOCK_DIR="$mk115" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
if [[ "$v_rc" == 0 \
      && "$(sed -n 1p "$mk115/record")" == "argv: <verify> <--ensured>" \
      && "$(sed -n 2p "$mk115/record")" == "conf-env:<unset>" ]]; then
    a115 pass
else
    a115 fail "sweep argv is bare --ensured with no conf env (rc=$v_rc, record: $(cat "$mk115/record"), out: $v_out)"
fi

# 2. EGL-333-D6: a set EGRESSLOCK_PROFILE is ignored silently. The argv
#    stays bare `verify --ensured` (no named branch), no conf env, and the
#    wrapper prints no warning about the live egresslock-start variable.
: > "$mk115/record"
v_out="$(env EGRESSLOCK_PROFILE=workstation EGRESSLOCK_SKIP_NETNS_PROBE=1 \
    EGRESSLOCK_DIR="$mk115" \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
if [[ "$v_rc" == 0 \
      && "$(sed -n 1p "$mk115/record")" == "argv: <verify> <--ensured>" \
      && "$(sed -n 2p "$mk115/record")" == "conf-env:<unset>" \
      && "$v_out" != *"EGRESSLOCK_PROFILE"* ]]; then
    a115 pass
else
    a115 fail "set EGRESSLOCK_PROFILE is ignored, argv stays --ensured (rc=$v_rc, record: $(cat "$mk115/record"), out: $v_out)"
fi

# 3. End-to-end aggregate: two *.conf in the fixed confdir, both anchors
#    ensured -> the sweep verifies BOTH profiles (and the engine's
#    aggregate disclosure names the confdir).
cat > "$HOME/.config/egresslock/second.conf" <<'EOF'
profile second 10.50.1.0/24
    rule allow-host git.example.test:443
    gateway 10.50.1.2 3128 second-allowlist
EOF
: > "$HOME/.config/egresslock/second-allowlist"
egresslock ensure second >/dev/null 2>&1
# EGL-140-D1: re-ensure workstation so its pin record is a sibling of the
# conf the sweep resolves (the tamper drill above expects a green sweep
# baseline for the tampered half only).
egresslock ensure workstation >/dev/null 2>&1
v_out="$(env -u EGRESSLOCK_PROFILE \
    "$OPT/egresslock-verify" 2>&1)"; v_rc=$?
if [[ "$v_rc" == 0 \
      && "$v_out" == *"profile 'workstation' verified (ensured)"* \
      && "$v_out" == *"profile 'second' verified (ensured)"* \
      && "$v_out" == *"using configs in"*"(2 profiles)"* ]]; then
    a115 pass
else
    a115 fail "sweep verifies every ensured profile in the confdir (rc=$v_rc, out: $v_out)"
fi

# Cleanup: restore the harness's fixed-confdir and profile state. The
# workstation fixture (KITCONF) stays for the rest of the harness.
egresslock teardown second >/dev/null 2>&1 || true
rm -f "$HOME/.config/egresslock/second.conf" \
      "$HOME/.config/egresslock/second-allowlist" \
      "$HOME/.config/egresslock/workstation.pins" "$HOME/.config/egresslock/second.pins"

section_end egl115

# --- ARC-17: uninstall-kit --------------------------------------------------
section_begin arc17 "ARC-17 uninstall-kit"
a17() { assert "$@"; }
UKIT="$TREE_ROOT/uninstall-kit.sh"

# Exec bit committed (R-016-2 F5 failure class: mode lost in git).
[[ -x "$UKIT" ]] && a17 pass || a17 fail "uninstall-kit.sh is executable in git"

# Pre-state: prefix kit + templates + timers + account data. EGL-89-D1:
# the prefix must be a REAL kit — the marker quadruple (egresslock
# executable, egresslock-verify, VERSION, gateway/Containerfile) —
# because a lone egresslock/VERSION pair no longer authorizes rm -rf.
u17="$STATE/u17"
mkdir -p "$u17/prefix/gateway" "$u17/units" "$u17/home/runner/.config/egresslock"
cp "$OPT/egresslock" "$u17/prefix/" 2>/dev/null \
    || { : > "$u17/prefix/egresslock"; chmod +x "$u17/prefix/egresslock"; }
: > "$u17/prefix/egresslock-verify"
: > "$u17/prefix/VERSION"
: > "$u17/prefix/gateway/Containerfile"
: > "$u17/units/egresslock-verify@.service"
: > "$u17/units/egresslock-verify@.timer"
: > "$u17/home/runner/.config/egresslock/main.conf"
: > "$STATE/systemctl.log"
# R-017-1 F5: a marker-less prefix must NOT be rm -rf'd.
mkdir -p "$u17/notakit"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/notakit" --account root >/dev/null 2>&1
[[ -d "$u17/notakit" ]] && a17 pass || a17 fail "uninstall refuses a marker-less prefix"

# EGL-102-D6-R2: stage a dangling kit wants symlink (template gone) so
# the uninstall's sweep has something to clear. Staged after the F5
# refusal run — that run sweeps wants/ too and would consume it.
mkdir -p "$u17/units/timers.target.wants"
ln -s "$u17/units/egresslock-verify@ghost.timer" "$u17/units/timers.target.wants/egresslock-verify@ghost.timer"

# EGL-462: the log is shared with the marker-less refusal run above, which
# still reaches the per-account disable and the final reload. Clear it
# before the real-prefix run so the disable/reload asserts below read only
# this run's own calls (otherwise removing them here stays green).
: > "$STATE/systemctl.log"

u_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u17/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/prefix" --account root 2>&1)"; u_rc=$?
[[ "$u_rc" == 0 ]] && a17 pass || a17 fail "uninstall-kit run (rc=$u_rc, out: $u_out)"
# EGL-102-D6-R2: a dangling kit wants symlink (template already gone,
# disable cannot clear it) is swept by the uninstall.
[[ ! -L "$u17/units/timers.target.wants/egresslock-verify@ghost.timer" \
    && "$u_out" == *"removed dangling timer enablement"* ]] \
    && a17 pass || a17 fail "dangling kit wants symlink swept (out: $u_out)"
# EGL-535-D4: a dangling wants link is not an enabled instance, so the
# stop sweep must never attempt it. The harness mock returns 0 for every
# disable, so the summary alone cannot reveal the over-reach; the call log
# can (mutation: drop the `-e` test from the wants source -> red).
grep -qF 'disable --now egresslock-verify@ghost.timer' "$STATE/systemctl.log" \
    && a17 fail "dangling wants link was never passed to disable" || a17 pass
[[ ! -e "$u17/units/egresslock-verify@.service" && ! -e "$u17/units/egresslock-verify@.timer" ]] \
    && a17 pass || a17 fail "templates removed"
[[ ! -e "$u17/prefix/egresslock" && ! -e "$u17/prefix/VERSION" ]] \
    && a17 pass || a17 fail "prefix kit removed"
[[ ! -d "$u17/prefix" ]] && a17 pass || a17 fail "prefix dir removed"
grep -q "disable --now egresslock-verify@root.timer" "$STATE/systemctl.log" \
    && a17 pass || a17 fail "per-account timer stopped/disabled"
# R-017-1 F4: ALL enabled instances get disabled, not just named ones.
grep -qE "disable --now egresslock-verify@[a-z0-9-]+\.timer" "$STATE/systemctl.log" \
    && a17 pass || a17 fail "enabled-instance sweep (list-unit-files | xargs disable)"
# R-017-1 F1: installed template ExecStart carries the requested prefix.
grep -q "ExecStart=$OPT/egresslock-verify" "$UNITS/egresslock-verify@.service" \
    && a17 pass || a17 fail "installed template ExecStart uses the deployed prefix"
grep -q "__EGRESSLOCK_PREFIX__" "$TREE_ROOT/systemd/egresslock-verify@.service" \
    && a17 pass || a17 fail "repo template keeps the prefix placeholder"
grep -q "daemon-reload" "$STATE/systemctl.log" \
    && a17 pass || a17 fail "daemon-reload after removal"
# EGL-121 positive control: the guarded reload is silent on a systemd host
# and the confirmed path keeps the `timers stopped` summary.
[[ "$u_out" != *"WARNING - systemd did not confirm"* ]] \
    && a17 pass || a17 fail "no reload warning on a systemctl host (out: $u_out)"
[[ "$u_out" == *"instanced templates removed; timers stopped"* ]] \
    && a17 pass || a17 fail "confirmed summary says timers stopped (out: $u_out)"
[[ -f "$u17/home/runner/.config/egresslock/main.conf" ]] \
    && a17 pass || a17 fail "account data preserved by default (D2)"
grep -qF "teardown all --yes" <<<"$u_out" \
    && a17 pass || a17 fail "reminder points at teardown all --yes (EGL-519)"
grep -qF "teardown --orphans" <<<"$u_out" \
    && a17 pass || a17 fail "reminder points at teardown --orphans (EGL-519)"
grep -qF "teardown --runtime" <<<"$u_out" \
    && a17 fail "reminder still says teardown --runtime (EGL-519 migration)" || a17 pass

# --purge-account-data removes the confdir. EGL-140-D1:
# the pin record rides the confdir — a fixture <profile>.pins is kept by
# the default keep path and removed by the purge, never orphaned.
mkdir -p "$u17/home/runner/.config/egresslock"
: > "$u17/home/runner/.config/egresslock/main.conf"
: > "$u17/home/runner/.config/egresslock/main.pins"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u17/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/prefix" --account root --purge-account-data >/dev/null 2>&1
[[ ! -e "$u17/home/runner/.config/egresslock" ]] \
    && a17 pass || a17 fail "--purge-account-data removes the confdir"

# EGL-140-D1: the default (no --purge) keep path keeps the pin record
# WITH the confdir (account data, no root-side orphans).
mkdir -p "$u17/home/runner/.config/egresslock"
: > "$u17/home/runner/.config/egresslock/main.conf"
: > "$u17/home/runner/.config/egresslock/main.pins"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u17/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/prefix" --account root >/dev/null 2>&1
[[ -f "$u17/home/runner/.config/egresslock/main.pins" ]] \
    && a17 pass || a17 fail "uninstall-kit default keeps the pin record with the confdir (EGL-140-D1)"

# Unknown account fails closed; missing value is a usage error (exit 2).
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/prefix" --account nosuch-user >/dev/null 2>&1
[[ $? == 1 ]] && a17 pass || a17 fail "uninstall-kit fails on unknown account"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 "$UKIT" --account >/dev/null 2>&1
[[ $? == 2 ]] && a17 pass || a17 fail "missing --account value exits 2"

# --- EGL-89-D2: rm -rf guard hardening (audit I-01) ---
# e89run: uninstall-kit with the mock env, capturing rc + output.
e89run() {
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u17/units" \
        EGRESSLOCK_ACCOUNT_HOME="$u17/home/runner" \
        EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
        "$UKIT" --prefix "$1" --account root 2>&1
}
# 1. Victim dir with only VERSION + a precious file -> NOT removed, and
#    the closing line must not claim "kit removed from" (honest summary).
mkdir -p "$u17/victim-ver"
: > "$u17/victim-ver/VERSION"
echo precious > "$u17/victim-ver/important.txt"
e89_out="$(e89run "$u17/victim-ver")"; e89_rc=$?
[[ "$e89_rc" == 0 && -d "$u17/victim-ver" && -f "$u17/victim-ver/important.txt" \
    && "$e89_out" == *"not a real kit prefix"* \
    && "$e89_out" == *"left in place"* && "$e89_out" != *"kit removed from"* ]] \
    && a17 pass || a17 fail "VERSION-only victim kept (rc=$e89_rc, out: $e89_out)"
# 2. Checkout-shape victim: an egresslock file only -> NOT removed.
mkdir -p "$u17/victim-co"
: > "$u17/victim-co/egresslock"
e89_out="$(e89run "$u17/victim-co")"; e89_rc=$?
[[ "$e89_rc" == 0 && -d "$u17/victim-co" && "$e89_out" == *"not a real kit prefix"* ]] \
    && a17 pass || a17 fail "checkout-shape victim kept (rc=$e89_rc, out: $e89_out)"
# 3. Non-absolute / traversal --prefix -> rc 2, nothing deleted.
e89_sentinel="$u17/victim-ver/important.txt"
for e89_p in . .. not/absolute "$u17/prefix/../victim-ver" "$u17//victim-ver"; do
    e89_out="$(e89run "$e89_p")"; e89_rc=$?
    if [[ "$e89_rc" == 2 && "$e89_out" == *"must be an absolute kit path"* \
          && -f "$e89_sentinel" && -f "$TREE_ROOT/uninstall-kit.sh" ]]; then
        a17 pass
    else
        a17 fail "bad --prefix '$e89_p' rejected rc 2 (rc=$e89_rc, out: $e89_out)"
    fi
done
# 4. Charset-illegal absolute --prefix -> rc 2.
e89_out="$(e89run "$u17/eg;id")"; e89_rc=$?
[[ "$e89_rc" == 2 && "$e89_out" == *"must be an absolute kit path"* ]] \
    && a17 pass || a17 fail "charset-illegal --prefix rejected rc 2 (rc=$e89_rc, out: $e89_out)"
# 4b. EGL-185: whitespace-class --prefix rejects (parity with e90's
#     '/tmp/a b' pin; the newline case hits the explicit branch at
#     uninstall-kit.sh's whitespace-class branch, which had zero coverage).
#     Both internal branches exit 2 with the same message, so the
#     branch that fired is not pinned — only the rc/behavior class.
e89_out="$(e89run '/tmp/a b')"; e89_rc=$?
[[ "$e89_rc" == 2 && "$e89_out" == *"must be an absolute kit path"* \
    && -f "$e89_sentinel" && -f "$TREE_ROOT/uninstall-kit.sh" ]] \
    && a17 pass || a17 fail "space --prefix rejected rc 2 (rc=$e89_rc)"
e89_out="$(e89run $'/tmp/a\tb')"; e89_rc=$?
[[ "$e89_rc" == 2 && "$e89_out" == *"must be an absolute kit path"* \
    && -f "$e89_sentinel" && -f "$TREE_ROOT/uninstall-kit.sh" ]] \
    && a17 pass || a17 fail "tab --prefix rejected rc 2 (rc=$e89_rc)"
e89_out="$(e89run $'/tmp/a\nb')"; e89_rc=$?
[[ "$e89_rc" == 2 && "$e89_out" == *"must be an absolute kit path"* \
    && -f "$e89_sentinel" && -f "$TREE_ROOT/uninstall-kit.sh" ]] \
    && a17 pass || a17 fail "newline --prefix rejected rc 2 (rc=$e89_rc)"
# 5. Positive path: a real kit (the quadruple) IS still removed — the
#    full run above already asserts it; re-check the quadruple guard
#    explicitly with a throwaway fake kit.
mkdir -p "$u17/fakekit/gateway"
: > "$u17/fakekit/egresslock"; chmod +x "$u17/fakekit/egresslock"
: > "$u17/fakekit/egresslock-verify"; : > "$u17/fakekit/VERSION"
: > "$u17/fakekit/gateway/Containerfile"
e89_out="$(e89run "$u17/fakekit")"; e89_rc=$?
[[ "$e89_rc" == 0 && ! -e "$u17/fakekit" ]] \
    && a17 pass || a17 fail "real-kit quadruple still removed (rc=$e89_rc, out: $e89_out)"

# EGL-382: the account-home hook is test-only. Fake root (id -u -> 0)
# plus a getent passwd stub: without the flag the passwd-resolved home is
# used and the hook home is untouched; with the flag the hook wins.
e89_bin="$u17/e89-root-bin"; mkdir -p "$e89_bin"
cat > "$e89_bin/id" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "-u" ]]; then
    echo 0
    exit 0
fi
exec /usr/bin/id "$@"
EOF
cat > "$e89_bin/getent" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "passwd" && "\$2" == "root" ]]; then
    printf 'root:x:0:0:root:%s:/bin/sh\n' "$u17/e89home"
    exit 0
fi
exec /usr/bin/getent "\$@"
EOF
chmod +x "$e89_bin/id" "$e89_bin/getent"
# EGL-434: the unit/PATH hooks are test-only too, so the ungated negative
# below reads the production defaults. A selective rm/sed shim keeps that
# run harmless: it logs the target, and runs the real tool only for
# fixture paths under $STATE. The log proves the defaults were used.
cat > "$e89_bin/rm" <<EOF
#!/usr/bin/env bash
printf 'rm %s\n' "\$*" >> "$STATE/e89-path-hooks.log"
for _a in "\$@"; do
    case "\$_a" in
        -*) continue ;;
        "$STATE"/*|./*) ;;
        *) exit 0 ;;
    esac
done
exec /bin/rm "\$@"
EOF
cat > "$e89_bin/sed" <<EOF
#!/usr/bin/env bash
printf 'sed %s\n' "\$*" >> "$STATE/e89-path-hooks.log"
exec /usr/bin/sed "\$@"
EOF
chmod +x "$e89_bin/rm" "$e89_bin/sed"
# Hook sentinels: a gate-less run would remove these (the names match),
# so their survival is the mutation-red pin.
: > "$u17/units/egresslock-verify@.service"
: > "$u17/units/egresslock-verify@.timer"
mkdir -p "$u17/wbin"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec true\n' "$u17/e89negprefix" \
    > "$u17/wbin/egresslock"
: > "$u17/wbin/egresslock-setup"
: > "$STATE/e89-path-hooks.log"
mkdir -p "$u17/e89home/.config/egresslock" "$u17/e89sentinel/.config/egresslock"
: > "$u17/e89home/.config/egresslock/main.conf"
: > "$u17/e89sentinel/.config/egresslock/main.conf"
e89_out="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT PATH="$e89_bin:$PATH" \
    EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u17/e89sentinel" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/e89negprefix" --account root --purge-account-data 2>&1)"; e89_rc=$?
e89_log="$(cat "$STATE/e89-path-hooks.log" 2>/dev/null || true)"
[[ "$e89_rc" == 0 && ! -e "$u17/e89home/.config/egresslock" \
    && -e "$u17/e89sentinel/.config/egresslock" \
    && -e "$u17/units/egresslock-verify@.service" \
    && -e "$u17/units/egresslock-verify@.timer" \
    && -e "$u17/wbin/egresslock" && -e "$u17/wbin/egresslock-setup" \
    && "$e89_log" == *"/etc/systemd/system/egresslock-verify@.service"* \
    && "$e89_log" != *"$u17/units"* && "$e89_log" != *"$u17/wbin"* ]] \
    && a17 pass || a17 fail "account-home hook ignored without the test flag (rc=$e89_rc, out: $e89_out, log: $e89_log)"
mkdir -p "$u17/e89home/.config/egresslock"
: > "$u17/e89home/.config/egresslock/main.conf"
e89_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$e89_bin:$PATH" \
    EGRESSLOCK_UNIT_DIR="$u17/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u17/e89sentinel" \
    EGRESSLOCK_PATH_BINDIR="$u17/wbin" EGRESSLOCK_PATH_SBINDIR="$u17/wbin" \
    "$UKIT" --prefix "$u17/e89negprefix" --account root --purge-account-data 2>&1)"; e89_rc=$?
[[ "$e89_rc" == 0 && -e "$u17/e89home/.config/egresslock" \
    && ! -e "$u17/e89sentinel/.config/egresslock" ]] \
    && a17 pass || a17 fail "account-home hook honored with the test flag (rc=$e89_rc, out: $e89_out)"
section_end arc17

# --- EGL-433: destination-replacement guards (kit scripts) ------------------
# A2/A3: a symlinked --prefix (with or without one trailing /) is refused
# by name before any marker read, service stop, template removal, copy, or
# delete; the link and the referent stay byte-identical. Positive controls
# keep the real-prefix install/uninstall paths (including one trailing /)
# working. A1 legs live in arc19; A4 legs live in arc22.
section_begin egl433 "EGL-433 destination-replacement guards"
e433() { assert "$@"; }

e433d="$STATE/egl433"; rm -rf "$e433d"; mkdir -p "$e433d"

# A2 fixture: a real kit prefix (the four markers), a sentinel, and a
# gateway secret, reached through a symlink.
mkdir -p "$e433d/u/units" "$e433d/u/home/root/.config/egresslock" "$e433d/u/kit/gateway"
cp "$OPT/egresslock" "$e433d/u/kit/" 2>/dev/null \
    || { : > "$e433d/u/kit/egresslock"; chmod +x "$e433d/u/kit/egresslock"; }
: > "$e433d/u/kit/egresslock-verify"
: > "$e433d/u/kit/VERSION"
: > "$e433d/u/kit/gateway/Containerfile"
printf 'operator notes\n' > "$e433d/u/kit/operator-notes.txt"
printf 'gateway-secret\n' > "$e433d/u/kit/gateway/secret.txt"
: > "$e433d/u/home/root/.config/egresslock/main.conf"
: > "$e433d/u/units/egresslock-verify@.service"
: > "$e433d/u/units/egresslock-verify@.timer"
ln -s "$e433d/u/kit" "$e433d/u/link"

e433_urun() { # <prefix> — uninstall-kit with the mock env
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e433d/u/units" \
        EGRESSLOCK_ACCOUNT_HOME="$e433d/u/home/root" \
        EGRESSLOCK_PATH_BINDIR="$e433d/u/wbin" EGRESSLOCK_PATH_SBINDIR="$e433d/u/wbin" \
        "$UKIT" --prefix "$1" --account root
}
: > "$STATE/systemctl.log"
for e433_form in "$e433d/u/link/" "$e433d/u/link"; do
    o="$(e433_urun "$e433_form" 2>&1)"; rc=$?
    if [[ "$rc" == 2 \
          && "$o" == *"uninstall-kit: refusing: --prefix is a symbolic link: $e433_form"* \
          && "$o" == *"pass the real directory the link points to (only that directory is removed); nothing was stopped, removed, or disabled:"* \
          && "$o" == *"    sudo ./uninstall-kit.sh --prefix $e433d/u/kit"* \
          && -L "$e433d/u/link" && -d "$e433d/u/kit" \
          && "$(cat "$e433d/u/kit/operator-notes.txt")" == "operator notes" \
          && "$(cat "$e433d/u/kit/gateway/secret.txt")" == "gateway-secret" \
          && -f "$e433d/u/kit/VERSION" && -f "$e433d/u/kit/gateway/Containerfile" ]]; then
        e433 pass
    else
        e433 fail "A2 uninstall refuses symlinked --prefix '$e433_form' (rc=$rc, out: $o)"
    fi
done
# The refusal lands before the timer stop and template removal: the
# systemctl mock saw no call, and both templates are still in place.
[[ ! -s "$STATE/systemctl.log" ]] \
    && e433 pass || e433 fail "A2 refusal stops before any systemctl call (log: $(cat "$STATE/systemctl.log"))"
[[ -f "$e433d/u/units/egresslock-verify@.service" && -f "$e433d/u/units/egresslock-verify@.timer" ]] \
    && e433 pass || e433 fail "A2 refusal leaves the unit templates in place"
# Positive control: the real directory still uninstalls when named
# directly (the argument is not rewritten).
o="$(e433_urun "$e433d/u/kit" 2>&1)"; rc=$?
[[ "$rc" == 0 && ! -d "$e433d/u/kit" && "$o" == *"kit removed from $e433d/u/kit"* ]] \
    && e433 pass || e433 fail "A2 real prefix still uninstalls directly (rc=$rc, out: $o)"
# Positive control: a real prefix with one trailing / still uninstalls.
mkdir -p "$e433d/u/kit2/gateway"
cp "$OPT/egresslock" "$e433d/u/kit2/" 2>/dev/null \
    || { : > "$e433d/u/kit2/egresslock"; chmod +x "$e433d/u/kit2/egresslock"; }
: > "$e433d/u/kit2/egresslock-verify"; : > "$e433d/u/kit2/VERSION"
: > "$e433d/u/kit2/gateway/Containerfile"
o="$(e433_urun "$e433d/u/kit2/" 2>&1)"; rc=$?
[[ "$rc" == 0 && ! -d "$e433d/u/kit2" ]] \
    && e433 pass || e433 fail "A2 real prefix with one trailing / still uninstalls (rc=$rc, out: $o)"
# An unresolvable link has no real directory to name: drop the command
# line and keep the "nothing was stopped" clause.
e433_dangling="$e433d/u/dangling"
ln -s "$e433d/u/missing-dir" "$e433_dangling"
o="$(e433_urun "$e433_dangling" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"uninstall-kit: refusing: --prefix is a symbolic link: $e433_dangling"* \
    && "$o" == *"the link does not resolve to a directory; pass the real kit prefix. nothing was stopped, removed, or disabled."* \
    && "$o" != *"sudo ./uninstall-kit.sh --prefix"* \
    && -L "$e433_dangling" ]] \
    && e433 pass || e433 fail "A2 unresolvable prefix link refuses without a resolved-path command (rc=$rc, out: $o)"
# Shape gate (D7): a link target that the --prefix parser cannot name is
# still refused by name, but no retry command is offered (it would be
# rejected); every path is %q-rendered, so spaces/apostrophes stay one
# literal argument.
e433_bad_ref="$e433d/u/kit space'quote"
e433_bad_link="$e433d/u/bad-link"
mkdir -p "$e433_bad_ref/gateway"
cp "$OPT/egresslock" "$e433_bad_ref/" 2>/dev/null \
    || { : > "$e433_bad_ref/egresslock"; chmod +x "$e433_bad_ref/egresslock"; }
: > "$e433_bad_ref/egresslock-verify"; : > "$e433_bad_ref/VERSION"
: > "$e433_bad_ref/gateway/Containerfile"
printf 'bad-referent notes\n' > "$e433_bad_ref/operator-notes.txt"
ln -s "$e433_bad_ref" "$e433_bad_link"
printf -v e433_q_ref '%q' "$e433_bad_ref"
printf -v e433_q_link '%q' "$e433_bad_link"
o="$(e433_urun "$e433_bad_link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"uninstall-kit: refusing: --prefix is a symbolic link: $e433_q_link"* \
    && "$o" == *"the link points to $e433_q_ref, which --prefix cannot name (only letters, digits, '.', '_', '-', and '/' are allowed); nothing was stopped, removed, or disabled."* \
    && "$o" != *"sudo ./uninstall-kit.sh --prefix"* \
    && -L "$e433_bad_link" \
    && "$(cat "$e433_bad_ref/operator-notes.txt")" == "bad-referent notes" ]] \
    && e433 pass || e433 fail "A2 shape-gate link target refuses without an unusable retry command (rc=$rc, out: $o)"
# B5 (D8): a trailing newline in the link target is a pathname byte. The
# old command-substitution capture named the newline-free sibling `kit`
# and offered a retry that removed it; the byte-preserving capture says
# the target cannot pass the --prefix shape gate, so no retry is offered
# and both trees stay byte-identical.
e433_nl_root="$e433d/u/nl"
rm -rf "$e433_nl_root"; mkdir -p "$e433_nl_root"
e433_nl_ref="$e433_nl_root/kit"$'\n'
e433_nl_sib="$e433_nl_root/kit"
mkdir -p "$e433_nl_ref/gateway" "$e433_nl_sib/gateway"
for e433_nlkit in "$e433_nl_ref" "$e433_nl_sib"; do
    cp "$OPT/egresslock" "$e433_nlkit/" 2>/dev/null \
        || { : > "$e433_nlkit/egresslock"; chmod +x "$e433_nlkit/egresslock"; }
    : > "$e433_nlkit/egresslock-verify"
    : > "$e433_nlkit/VERSION"
    : > "$e433_nlkit/gateway/Containerfile"
done
printf 'newline referent notes\n' > "$e433_nl_ref/operator-notes.txt"
printf 'sibling notes\n' > "$e433_nl_sib/operator-notes.txt"
ln -s "$e433_nl_ref" "$e433_nl_root/link"
printf -v e433_nl_qref '%q' "$e433_nl_ref"
printf -v e433_nl_qlink '%q' "$e433_nl_root/link"
o="$(e433_urun "$e433_nl_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"uninstall-kit: refusing: --prefix is a symbolic link: $e433_nl_qlink"* \
    && "$o" == *"the link points to $e433_nl_qref, which --prefix cannot name"* \
    && "$o" != *"sudo ./uninstall-kit.sh --prefix"* \
    && -L "$e433_nl_root/link" \
    && "$(cat "$e433_nl_ref/operator-notes.txt")" == "newline referent notes" \
    && "$(cat "$e433_nl_sib/operator-notes.txt")" == "sibling notes" \
    && -f "$e433_nl_ref/VERSION" && -f "$e433_nl_ref/gateway/Containerfile" \
    && -f "$e433_nl_sib/VERSION" && -f "$e433_nl_sib/gateway/Containerfile" ]] \
    && e433 pass || e433 fail "A2 B5 newline link target keeps both trees, no retry (rc=$rc, out: $o)"

# A3 fixture: a referent tree with a lone VERSION and a gateway/ holding
# an operator file; the installer's old marker loop treats the lone
# VERSION as proof the tree is its own.
e433_iref="$e433d/i/ref"
mkdir -p "$e433d/i/units" "$e433d/i/ref/gateway"
printf 'lone marker\n' > "$e433d/i/ref/VERSION"
printf 'operator data\n' > "$e433d/i/ref/gateway/operator.txt"
ln -s "$e433d/i/ref" "$e433d/i/link"
e433_irun() { # <prefix> — install-kit with the mock env
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e433d/i/units" \
        EGRESSLOCK_PATH_BINDIR="$e433d/i/wbin" EGRESSLOCK_PATH_SBINDIR="$e433d/i/wsbin" \
        "$KIT" --prefix "$1"
}
for e433_form in "$e433d/i/link" "$e433d/i/link/"; do
    o="$(e433_irun "$e433_form" 2>&1)"; rc=$?
    if [[ "$rc" == 2 \
          && "$o" == *"install-kit: refusing: --prefix is a symbolic link: $e433_form"* \
          && "$o" == *"pass the real directory the link points to (the installer does not follow the link); nothing was written or removed:"* \
          && "$o" == *"    sudo ./install-kit.sh --prefix $e433d/i/ref"* \
          && -L "$e433d/i/link" \
          && "$(cat "$e433d/i/ref/gateway/operator.txt")" == "operator data" \
          && "$(cat "$e433d/i/ref/VERSION")" == "lone marker" \
          && ! -e "$e433d/i/ref/egresslock" && ! -e "$e433d/i/ref/gateway.tmp" ]]; then
        e433 pass
    else
        e433 fail "A3 install refuses symlinked --prefix '$e433_form' (rc=$rc, out: $o)"
    fi
done
# Positive control: the same tree named directly still installs (the
# EGL-68-D1 lone-VERSION trade stays; the installer replaces gateway/).
o="$(e433_irun "$e433d/i/ref" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e433d/i/ref/egresslock" && -f "$e433d/i/ref/VERSION" ]] \
    && e433 pass || e433 fail "A3 lone-VERSION tree named directly still installs (rc=$rc, out: $o)"
e433_idangling="$e433d/i/dangling"
ln -s "$e433d/i/missing-ref" "$e433_idangling"
o="$(e433_irun "$e433_idangling" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"install-kit: refusing: --prefix is a symbolic link: $e433_idangling"* \
    && "$o" == *"the link does not resolve to a directory; pass the real kit prefix. nothing was written or removed."* \
    && "$o" != *"sudo ./install-kit.sh --prefix"* \
    && -L "$e433_idangling" ]] \
    && e433 pass || e433 fail "A3 unresolvable prefix link refuses without a resolved-path command (rc=$rc, out: $o)"
# Shape gate (D7) for install: same rule and %q rendering as A2.
e433_i_bad_ref="$e433d/i/ref space'quote"
e433_i_bad_link="$e433d/i/bad-link"
mkdir -p "$e433_i_bad_ref/gateway"
printf 'lone marker\n' > "$e433_i_bad_ref/VERSION"
printf 'install-shape-gate data\n' > "$e433_i_bad_ref/gateway/operator.txt"
ln -s "$e433_i_bad_ref" "$e433_i_bad_link"
printf -v e433_iq_ref '%q' "$e433_i_bad_ref"
printf -v e433_iq_link '%q' "$e433_i_bad_link"
o="$(e433_irun "$e433_i_bad_link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"install-kit: refusing: --prefix is a symbolic link: $e433_iq_link"* \
    && "$o" == *"the link points to $e433_iq_ref, which --prefix cannot name (only letters, digits, '.', '_', '-', and '/' are allowed); nothing was written or removed."* \
    && "$o" != *"sudo ./install-kit.sh --prefix"* \
    && -L "$e433_i_bad_link" \
    && "$(cat "$e433_i_bad_ref/gateway/operator.txt")" == "install-shape-gate data" \
    && ! -e "$e433_i_bad_ref/egresslock" ]] \
    && e433 pass || e433 fail "A3 shape-gate link target refuses without an unusable retry command (rc=$rc, out: $o)"
# B5 (D8) for install: the sibling is a lone-VERSION tree the old
# newline-stripped retry would have installed into (replacing its
# gateway/). The real newline referent and the sibling both stay intact.
e433_i_nl_root="$e433d/i/nl"
rm -rf "$e433_i_nl_root"; mkdir -p "$e433_i_nl_root"
e433_i_nl_ref="$e433_i_nl_root/kit"$'\n'
e433_i_nl_sib="$e433_i_nl_root/kit"
mkdir -p "$e433_i_nl_ref" "$e433_i_nl_sib/gateway"
printf 'newline referent marker\n' > "$e433_i_nl_ref/VERSION"
printf 'sibling marker\n' > "$e433_i_nl_sib/VERSION"
printf 'sibling operator data\n' > "$e433_i_nl_sib/gateway/operator.txt"
ln -s "$e433_i_nl_ref" "$e433_i_nl_root/link"
printf -v e433_i_nl_qref '%q' "$e433_i_nl_ref"
printf -v e433_i_nl_qlink '%q' "$e433_i_nl_root/link"
o="$(e433_irun "$e433_i_nl_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"install-kit: refusing: --prefix is a symbolic link: $e433_i_nl_qlink"* \
    && "$o" == *"the link points to $e433_i_nl_qref, which --prefix cannot name"* \
    && "$o" != *"sudo ./install-kit.sh --prefix"* \
    && -L "$e433_i_nl_root/link" \
    && "$(cat "$e433_i_nl_ref/VERSION")" == "newline referent marker" \
    && "$(cat "$e433_i_nl_sib/VERSION")" == "sibling marker" \
    && "$(cat "$e433_i_nl_sib/gateway/operator.txt")" == "sibling operator data" \
    && ! -e "$e433_i_nl_ref/egresslock" && ! -e "$e433_i_nl_sib/egresslock" ]] \
    && e433 pass || e433 fail "A3 B5 newline link target keeps the sibling tree, no retry (rc=$rc, out: $o)"

# F1 (D8): a path producer that exits nonzero is unresolvable even when it
# printed a complete record. A `readlink` shim names a different real kit
# prefix and exits 1: both scripts take the unresolved branch (no retry),
# and the link, its referent, and the emitted prefix stay byte-identical.
# An exit-0 empty record is unresolvable too; the real `readlink` control
# still offers the retry.
e433_f1_root="$e433d/u/f1"
rm -rf "$e433_f1_root"; mkdir -p "$e433_f1_root/referent/gateway" "$e433_f1_root/emitted/gateway"
for e433_f1t in "$e433_f1_root/referent" "$e433_f1_root/emitted"; do
    cp "$OPT/egresslock" "$e433_f1t/" 2>/dev/null \
        || { : > "$e433_f1t/egresslock"; chmod +x "$e433_f1t/egresslock"; }
    : > "$e433_f1t/egresslock-verify"; : > "$e433_f1t/VERSION"
    : > "$e433_f1t/gateway/Containerfile"
done
printf 'referent f1 notes\n' > "$e433_f1_root/referent/operator-notes.txt"
printf 'emitted f1 notes\n' > "$e433_f1_root/emitted/operator-notes.txt"
ln -s "$e433_f1_root/referent" "$e433_f1_root/link"
printf -v e433_f1_qref '%q' "$e433_f1_root/referent"
e433_f1shim="$e433d/u/f1-shim"
mkdir -p "$e433_f1shim"
cat > "$e433_f1shim/readlink" <<EOF
#!/usr/bin/env bash
printf '%s\0' "$e433_f1_root/emitted"
exit 1
EOF
chmod +x "$e433_f1shim/readlink"
o="$(PATH="$e433_f1shim:$PATH" e433_urun "$e433_f1_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"uninstall-kit: refusing: --prefix is a symbolic link: $e433_f1_root/link"* \
    && "$o" == *"the link does not resolve to a directory; pass the real kit prefix. nothing was stopped, removed, or disabled."* \
    && "$o" != *"sudo ./uninstall-kit.sh --prefix"* \
    && -L "$e433_f1_root/link" \
    && "$(cat "$e433_f1_root/referent/operator-notes.txt")" == "referent f1 notes" \
    && "$(cat "$e433_f1_root/emitted/operator-notes.txt")" == "emitted f1 notes" \
    && -f "$e433_f1_root/referent/VERSION" && -f "$e433_f1_root/emitted/VERSION" ]] \
    && e433 pass || e433 fail "A2 F1 failed readlink is unresolvable, no retry (rc=$rc, out: $o)"
e433_f1eshim="$e433d/u/f1-empty-shim"
mkdir -p "$e433_f1eshim"
cat > "$e433_f1eshim/readlink" <<'EOF'
#!/usr/bin/env bash
exit 0
EOF
chmod +x "$e433_f1eshim/readlink"
o="$(PATH="$e433_f1eshim:$PATH" e433_urun "$e433_f1_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"the link does not resolve to a directory; pass the real kit prefix. nothing was stopped, removed, or disabled."* \
    && "$o" != *"sudo ./uninstall-kit.sh --prefix"* \
    && -L "$e433_f1_root/link" ]] \
    && e433 pass || e433 fail "A2 F1 empty producer record is unresolvable, no retry (rc=$rc, out: $o)"
o="$(e433_urun "$e433_f1_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"sudo ./uninstall-kit.sh --prefix $e433_f1_qref"* \
    && -L "$e433_f1_root/link" ]] \
    && e433 pass || e433 fail "A2 F1 positive control: real readlink still offers the retry (rc=$rc, out: $o)"
o="$(PATH="$e433_f1shim:$PATH" e433_irun "$e433_f1_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"install-kit: refusing: --prefix is a symbolic link: $e433_f1_root/link"* \
    && "$o" == *"the link does not resolve to a directory; pass the real kit prefix. nothing was written or removed."* \
    && "$o" != *"sudo ./install-kit.sh --prefix"* \
    && -L "$e433_f1_root/link" \
    && "$(cat "$e433_f1_root/referent/operator-notes.txt")" == "referent f1 notes" \
    && "$(cat "$e433_f1_root/emitted/operator-notes.txt")" == "emitted f1 notes" \
    && -f "$e433_f1_root/referent/VERSION" && -f "$e433_f1_root/emitted/VERSION" ]] \
    && e433 pass || e433 fail "A3 F1 failed readlink is unresolvable, no retry (rc=$rc, out: $o)"
o="$(e433_irun "$e433_f1_root/link" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"sudo ./install-kit.sh --prefix $e433_f1_qref"* \
    && -L "$e433_f1_root/link" ]] \
    && e433 pass || e433 fail "A3 F1 positive control: real readlink still offers the retry (rc=$rc, out: $o)"

section_end egl433

# --- EGL-555: anchored prefix replacement (H2) ------------------------------
# The probe captures a no-follow dev:ino; every prefix-scoped delete/write
# runs in a subshell whose cwd is that directory and whose `stat .` must
# still match. A swap before the anchor refuses with nothing written or
# removed; a swap after the anchor cannot redirect a relative operation.
section_begin egl555 "EGL-555 anchored prefix replacement"
e555() { assert "$@"; }
e555d="$STATE/egl555"; rm -rf "$e555d"; mkdir -p "$e555d"
e555_real_stat="$(type -P stat)"
e555_real_rm="$(type -P rm)"
e555_real_find="$(type -P find)"
e555_real_mkdir="$(type -P mkdir)"
mkdir -p "$e555d/units" "$e555d/home/root/.config/egresslock"
e555_install() { # <prefix>
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e555d/units" \
        EGRESSLOCK_PATH_BINDIR="$1.bin" EGRESSLOCK_PATH_SBINDIR="$1.sbin" \
        "$KIT" --prefix "$1"
}
e555_uninstall() { # <prefix>
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e555d/units" \
        EGRESSLOCK_ACCOUNT_HOME="$e555d/home/root" \
        EGRESSLOCK_PATH_BINDIR="$1.bin" EGRESSLOCK_PATH_SBINDIR="$1.sbin" \
        "$UKIT" --prefix "$1" --account root
}

# 1. Install, existing prefix: the identity capture is the last read of the
#    name before the anchor. A swap right after it makes `cd` land in the
#    referent and `stat .` mismatch; nothing is written or removed.
e555_i1="$e555d/i1"; mkdir -p "$e555_i1/kit" "$e555_i1/victim" "$e555_i1/shim"
e555_install "$e555_i1/kit" >/dev/null 2>&1
printf 'victim sentinel\n' > "$e555_i1/victim/sentinel"
e555_i1_ver="$(cat "$e555_i1/kit/VERSION")"
cat > "$e555_i1/shim/stat" <<EOF
#!/usr/bin/env bash
"$e555_real_stat" "\$@" > "$e555_i1/shim/out" || exit \$?
if [[ "\${@: -1}" == "$e555_i1/kit" && ! -e "$e555_i1/shim/swapped" ]]; then
    : > "$e555_i1/shim/swapped"
    mv -- "$e555_i1/kit" "$e555_i1/kit.real"
    ln -s "$e555_i1/victim" "$e555_i1/kit"
fi
cat "$e555_i1/shim/out"
rm -f "$e555_i1/shim/out"
EOF
chmod +x "$e555_i1/shim/stat"
o="$(PATH="$e555_i1/shim:$PATH" e555_install "$e555_i1/kit" 2>&1)"; rc=$?
[[ "$rc" == 1 \
    && "$o" == *"install-kit: refusing: --prefix changed while the kit checked it: $e555_i1/kit"* \
    && "$o" == *"nothing was written or removed; name the real kit prefix and re-run."* \
    && -L "$e555_i1/kit" \
    && "$(cat "$e555_i1/victim/sentinel")" == "victim sentinel" \
    && ! -e "$e555_i1/victim/egresslock" && ! -e "$e555_i1/victim/VERSION" \
    && -f "$e555_i1/kit.real/egresslock" \
    && "$(cat "$e555_i1/kit.real/VERSION")" == "$e555_i1_ver" ]] \
    && e555 pass || e555 fail "install refuses a prefix swapped after the probe (rc=$rc, out: $o)"

# 2. Install, absent prefix: it appears between the absent probe and the
#    leaf mkdir. The leaf `mkdir` (no -p) sees EEXIST and refuses as
#    appeared; the racing path and its referent stay untouched.
e555_i2="$e555d/i2"; mkdir -p "$e555_i2/victim" "$e555_i2/shim"
printf 'i2 sentinel\n' > "$e555_i2/victim/sentinel"
cat > "$e555_i2/shim/mkdir" <<EOF
#!/usr/bin/env bash
if [[ "\${@: -1}" == "$e555_i2/kit" ]]; then
    ln -s "$e555_i2/victim" "$e555_i2/kit"
fi
exec "$e555_real_mkdir" "\$@"
EOF
chmod +x "$e555_i2/shim/mkdir"
o="$(PATH="$e555_i2/shim:$PATH" e555_install "$e555_i2/kit" 2>&1)"; rc=$?
[[ "$rc" == 1 \
    && "$o" == *"install-kit: refusing: --prefix changed while the kit checked it: $e555_i2/kit"* \
    && "$o" == *"it appeared after the check, so this run cannot claim it; nothing was written or removed. Re-run when no other install is running."* \
    && -L "$e555_i2/kit" \
    && "$(cat "$e555_i2/victim/sentinel")" == "i2 sentinel" \
    && ! -e "$e555_i2/victim/egresslock" && ! -e "$e555_i2/victim/gateway" ]] \
    && e555 pass || e555 fail "install refuses a prefix that appeared after an absent probe (rc=$rc, out: $o)"

# 3. Install, swap after the anchor: the first tree-temp `rm -rf` moves the
#    verified directory aside and points the name at a victim. Every
#    relative write still lands in the held inode; the victim stays empty.
e555_i3="$e555d/i3"; mkdir -p "$e555_i3/kit" "$e555_i3/victim" "$e555_i3/shim"
e555_install "$e555_i3/kit" >/dev/null 2>&1
printf 'i3 sentinel\n' > "$e555_i3/victim/sentinel"
cat > "$e555_i3/shim/rm" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "-rf" && ! -e "$e555_i3/shim/swapped" ]]; then
    : > "$e555_i3/shim/swapped"
    mv -- "$e555_i3/kit" "$e555_i3/kit.moved"
    ln -s "$e555_i3/victim" "$e555_i3/kit"
fi
exec "$e555_real_rm" "\$@"
EOF
chmod +x "$e555_i3/shim/rm"
o="$(PATH="$e555_i3/shim:$PATH" e555_install "$e555_i3/kit" 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && -L "$e555_i3/kit" \
    && "$(cat "$e555_i3/victim/sentinel")" == "i3 sentinel" \
    && ! -e "$e555_i3/victim/egresslock" && ! -e "$e555_i3/victim/VERSION" \
    && -f "$e555_i3/kit.moved/egresslock" && -f "$e555_i3/kit.moved/VERSION" \
    && -f "$e555_i3/kit.moved/gateway/Containerfile" ]] \
    && e555 pass || e555 fail "install swap after the anchor cannot redirect the relative copies (rc=$rc, out: $o)"

# 4. Uninstall, existing prefix: a swap after the identity capture makes
#    the anchor see the referent and refuse; neither tree is touched.
e555_u1="$e555d/u1"; mkdir -p "$e555_u1/kit" "$e555_u1/victim" "$e555_u1/shim"
e555_install "$e555_u1/kit" >/dev/null 2>&1
e555_install "$e555_u1/victim" >/dev/null 2>&1
printf 'u1 sentinel\n' > "$e555_u1/victim/sentinel"
cat > "$e555_u1/shim/stat" <<EOF
#!/usr/bin/env bash
"$e555_real_stat" "\$@" > "$e555_u1/shim/out" || exit \$?
if [[ "\${@: -1}" == "$e555_u1/kit" && ! -e "$e555_u1/shim/swapped" ]]; then
    : > "$e555_u1/shim/swapped"
    mv -- "$e555_u1/kit" "$e555_u1/kit.real"
    ln -s "$e555_u1/victim" "$e555_u1/kit"
fi
cat "$e555_u1/shim/out"
rm -f "$e555_u1/shim/out"
EOF
chmod +x "$e555_u1/shim/stat"
o="$(PATH="$e555_u1/shim:$PATH" e555_uninstall "$e555_u1/kit" 2>&1)"; rc=$?
[[ "$rc" == 1 \
    && "$o" == *"uninstall-kit: refusing: --prefix changed while the kit checked it: $e555_u1/kit"* \
    && "$o" == *"no kit files were removed from it;"* \
    && -L "$e555_u1/kit" \
    && "$(cat "$e555_u1/victim/sentinel")" == "u1 sentinel" \
    && -f "$e555_u1/victim/egresslock" && -f "$e555_u1/victim/VERSION" \
    && -f "$e555_u1/kit.real/egresslock" && -f "$e555_u1/kit.real/VERSION" ]] \
    && e555 pass || e555 fail "uninstall refuses a prefix swapped after the probe (rc=$rc, out: $o)"

# 5. Uninstall, swap after the anchor: `find .` empties the held inode, and
#    the final `rmdir` of the name fails because the name is now a link —
#    never an `rm -rf` through it. The referent keeps every file.
e555_u2="$e555d/u2"; mkdir -p "$e555_u2/kit" "$e555_u2/victim" "$e555_u2/shim"
e555_install "$e555_u2/kit" >/dev/null 2>&1
e555_install "$e555_u2/victim" >/dev/null 2>&1
printf 'u2 sentinel\n' > "$e555_u2/victim/sentinel"
cat > "$e555_u2/shim/find" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "." && ! -e "$e555_u2/shim/swapped" ]]; then
    : > "$e555_u2/shim/swapped"
    mv -- "$e555_u2/kit" "$e555_u2/kit.moved"
    ln -s "$e555_u2/victim" "$e555_u2/kit"
fi
exec "$e555_real_find" "\$@"
EOF
chmod +x "$e555_u2/shim/find"
o="$(PATH="$e555_u2/shim:$PATH" e555_uninstall "$e555_u2/kit" 2>&1)"; rc=$?
[[ "$rc" == 1 \
    && "$o" == *"uninstall-kit: FAIL - could not remove the emptied kit prefix: $e555_u2/kit"* \
    && -L "$e555_u2/kit" \
    && "$(cat "$e555_u2/victim/sentinel")" == "u2 sentinel" \
    && -f "$e555_u2/victim/egresslock" && -f "$e555_u2/victim/VERSION" \
    && -d "$e555_u2/kit.moved" \
    && -z "$(ls -A "$e555_u2/kit.moved")" ]] \
    && e555 pass || e555 fail "uninstall swap after the anchor empties the held dir, rmdir fails closed (rc=$rc, out: $o)"

section_end egl555

# --- EGL-121: guarded final daemon-reload -----------------------------------
# A host without systemd (no systemctl on PATH, or a systemctl that cannot
# reach a running systemd) must still complete the (un)install: rc 0, one
# named warning, and the trailing advisories/account-data lines that the
# bare reload used to skip under `set -e`. A zero-exit reload that logs the
# chroot/offline ignored-command notice is NOT confirmed either (B1): the
# guard captures the attempt (stdout+stderr) and requires rc 0 + no output.
# The systemd positive side is the a16/a17 mock-systemctl run (no warning)
# plus the silent-shim control here. Absence is a PATH property: the
# absence leg REPLACES PATH (the harness PATH starts with the mock
# systemctl), the shim legs prepend their own systemctl. The captured raw
# text is never echoed — the named warning is the operator contract.
section_begin egl121 "EGL-121 guarded final daemon-reload"
a121() { assert "$@"; }

w121_i="install-kit: WARNING - systemd did not confirm the unit-file reload; the verify timer templates are installed but may not be loaded."
w121_u="uninstall-kit: WARNING - systemd did not confirm the unit-file reload; the verify timer templates were removed, but a running systemd may still have them loaded."
next121_i="  An already-enabled verify timer may still run the previous unit definition; when systemd is available, run: systemctl daemon-reload"
next121_u="  An enabled verify timer may still be active; when systemd is available, run: systemctl daemon-reload"
stop121_u="  If a verify timer is still active, stop it: systemctl disable --now egresslock-verify@ACCT.timer"
unconfirmed121="timer stop not confirmed"

n121="$TESTROOT/bin-kit-nosystemctl"
rm -rf "$n121"; mkdir -p "$n121"
for t in env bash dirname id git grep sed awk tr cut getent date install cp rm mv chmod mkdir cat xargs stat find rmdir; do
    _t="$(command -v "$t" 2>/dev/null)" || continue
    ln -s "$_t" "$n121/$t"
done
unset _t

# Prepended shims (each logs the attempted call): failing (exit 1 + a
# distinctive diagnostic), zero-exit chroot/offline no-op (B1), and a
# silent zero-exit positive control (a real systemd host's shape).
s121="$TESTROOT/bin-kit-systemctl-fail"
rm -rf "$s121"; mkdir -p "$s121"
cat > "$s121/systemctl" <<EOF
#!/usr/bin/env bash
echo "systemctl \$*" >> "$s121/shim.log"
echo "egl121-failing-shim-diagnostic" >&2
exit 1
EOF
chmod +x "$s121/systemctl"

z121="$TESTROOT/bin-kit-systemctl-chroot-noop"
rm -rf "$z121"; mkdir -p "$z121"
cat > "$z121/systemctl" <<EOF
#!/usr/bin/env bash
echo "systemctl \$*" >> "$z121/shim.log"
echo "Running in chroot, ignoring command 'daemon-reload'" >&2
exit 0
EOF
chmod +x "$z121/systemctl"

q121="$TESTROOT/bin-kit-systemctl-silent"
rm -rf "$q121"; mkdir -p "$q121"
cat > "$q121/systemctl" <<EOF
#!/usr/bin/env bash
echo "systemctl \$*" >> "$q121/shim.log"
exit 0
EOF
chmod +x "$q121/systemctl"

# 1. install, no systemctl on PATH: rc 0, the named two-line warning, the
#    success + version lines, no raw command-not-found, kit deployed.
i121="$STATE/egl121"; rm -rf "$i121"
mkdir -p "$i121/units" "$i121/wbin" "$i121/wsbin"
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$i121/units" \
    EGRESSLOCK_PATH_BINDIR="$i121/wbin" EGRESSLOCK_PATH_SBINDIR="$i121/wsbin" \
    PATH="$n121" "$KIT" --prefix "$i121/prefix" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "install without systemctl exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_i"* ]] && a121 pass \
    || a121 fail "install names the unloaded templates (out: $o121)"
[[ "$o121" == *"$next121_i"* ]] && a121 pass \
    || a121 fail "install names the daemon-reload next step (out: $o121)"
[[ "$o121" == *"successfully installed! kit is at: $i121/prefix"* ]] \
    && a121 pass || a121 fail "install success line survives the warning (out: $o121)"
grep -q '^  version: ' <<<"$o121" \
    && a121 pass || a121 fail "install version line survives the warning (out: $o121)"
[[ "$o121" != *"command not found"* ]] && a121 pass \
    || a121 fail "install absence leg has no raw command-not-found (out: $o121)"
[[ -f "$i121/prefix/egresslock" && -f "$i121/prefix/VERSION" \
    && -f "$i121/units/egresslock-verify@.timer" ]] \
    && a121 pass || a121 fail "install completes the deploy despite the failed reload"

# 2. install, failing systemctl shim (prepended): same rc/warning/trailing
#    lines, the raw shim diagnostic is not echoed, and the shim proves the
#    guarded call was attempted.
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$i121/units" \
    EGRESSLOCK_PATH_BINDIR="$i121/wbin" EGRESSLOCK_PATH_SBINDIR="$i121/wsbin" \
    PATH="$s121:$PATH" "$KIT" --prefix "$i121/prefix" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "install with a failing systemctl shim exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_i"* ]] && a121 pass \
    || a121 fail "failing shim: install warning prints (out: $o121)"
[[ "$o121" == *"$next121_i"* ]] && a121 pass \
    || a121 fail "failing shim: install names the previous-definition risk (out: $o121)"
[[ "$o121" == *"successfully installed! kit is at: $i121/prefix"* ]] \
    && a121 pass || a121 fail "failing shim: install success line prints (out: $o121)"
[[ "$o121" != *"egl121-failing-shim-diagnostic"* ]] && a121 pass \
    || a121 fail "failing shim: raw diagnostic is not echoed (out: $o121)"
[[ "$o121" != *"command not found"* ]] && a121 pass \
    || a121 fail "failing shim: no raw command-not-found (out: $o121)"
grep -q '^systemctl daemon-reload$' "$s121/shim.log" \
    && a121 pass || a121 fail "failing shim recorded the install daemon-reload"

# 3. install, zero-exit shim printing the chroot/offline ignored-command
#    diagnostic (B1): rc 0 but NOT confirmed — warning, trailing lines, and
#    no raw systemctl text echoed.
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$i121/units" \
    EGRESSLOCK_PATH_BINDIR="$i121/wbin" EGRESSLOCK_PATH_SBINDIR="$i121/wsbin" \
    PATH="$z121:$PATH" "$KIT" --prefix "$i121/prefix" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "install with a zero-exit chroot shim exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_i"* ]] && a121 pass \
    || a121 fail "zero-exit chroot shim: install warns (out: $o121)"
[[ "$o121" == *"successfully installed! kit is at: $i121/prefix"* ]] \
    && a121 pass || a121 fail "zero-exit chroot shim: success line prints (out: $o121)"
[[ "$o121" != *"Running in chroot"* ]] && a121 pass \
    || a121 fail "zero-exit chroot shim: raw diagnostic is not echoed (out: $o121)"
grep -q '^systemctl daemon-reload$' "$z121/shim.log" \
    && a121 pass || a121 fail "zero-exit chroot shim recorded the install daemon-reload"

# 4. install, silent zero-exit shim (positive control): a systemd host whose
#    reload runs cleanly gets no warning.
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$i121/units" \
    EGRESSLOCK_PATH_BINDIR="$i121/wbin" EGRESSLOCK_PATH_SBINDIR="$i121/wsbin" \
    PATH="$q121:$PATH" "$KIT" --prefix "$i121/prefix" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "install with a silent systemctl shim exits 0 (rc=$rc, out: $o121)"
[[ "$o121" != *"$w121_i"* ]] && a121 pass \
    || a121 fail "silent shim: no install warning (out: $o121)"
[[ "$o121" == *"successfully installed! kit is at: $i121/prefix"* ]] \
    && a121 pass || a121 fail "silent shim: install success line prints (out: $o121)"
grep -q '^systemctl daemon-reload$' "$q121/shim.log" \
    && a121 pass || a121 fail "silent shim recorded the install daemon-reload"

# 3. uninstall, no systemctl: rc 0, warning, kept account-data line and the
#    final summary; templates/prefix removed.
u121="$STATE/egl121u"
mk121_prefix() {
    rm -rf "$u121"
    mkdir -p "$u121/prefix/gateway" "$u121/units" "$u121/home/runner/.config/egresslock"
    : > "$u121/prefix/egresslock"; chmod +x "$u121/prefix/egresslock"
    : > "$u121/prefix/egresslock-verify"
    : > "$u121/prefix/VERSION"
    : > "$u121/prefix/gateway/Containerfile"
    : > "$u121/units/egresslock-verify@.service"
    : > "$u121/units/egresslock-verify@.timer"
    : > "$u121/home/runner/.config/egresslock/main.conf"
}
mk121_prefix
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    PATH="$n121" "$UKIT" --prefix "$u121/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "uninstall without systemctl exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_u"* ]] && a121 pass \
    || a121 fail "uninstall names the possibly-loaded templates (out: $o121)"
[[ "$o121" == *"$next121_u"* ]] && a121 pass \
    || a121 fail "uninstall names the daemon-reload next step (out: $o121)"
[[ "$o121" == *"$stop121_u"* ]] && a121 pass \
    || a121 fail "uninstall names the timer stop check (out: $o121)"
[[ "$o121" == *"uninstall-kit: kept $u121/home/runner/.config/egresslock"* ]] \
    && a121 pass || a121 fail "uninstall account-data line survives the warning (out: $o121)"
[[ "$o121" == *"uninstall-kit: kit removed from $u121/prefix"* \
    && "$o121" == *"instanced templates removed; $unconfirmed121"* ]] \
    && a121 pass || a121 fail "uninstall final summary is state-honest (out: $o121)"
[[ "$o121" != *"; timers stopped"* ]] && a121 pass \
    || a121 fail "uninstall absence leg does not claim timers stopped (out: $o121)"
[[ "$o121" != *"command not found"* ]] && a121 pass \
    || a121 fail "uninstall absence leg has no raw command-not-found (out: $o121)"
[[ ! -e "$u121/prefix" && ! -e "$u121/units/egresslock-verify@.service" \
    && ! -e "$u121/units/egresslock-verify@.timer" ]] \
    && a121 pass || a121 fail "uninstall completes despite the failed reload"

# 5. uninstall, failing shim (prepended, --purge-account-data): same
#    rc/warning/trailing lines; the purged line, the stop check, the
#    unconfirmed summary, and the shim call are pinned.
mk121_prefix
: > "$s121/shim.log"
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    PATH="$s121:$PATH" "$UKIT" --prefix "$u121/prefix" --account root \
    --purge-account-data 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "uninstall with a failing systemctl shim exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_u"* ]] && a121 pass \
    || a121 fail "failing shim: uninstall warning prints (out: $o121)"
[[ "$o121" == *"$stop121_u"* ]] && a121 pass \
    || a121 fail "failing shim: uninstall names the timer stop check (out: $o121)"
[[ "$o121" == *"uninstall-kit: purged $u121/home/runner/.config/egresslock"* ]] \
    && a121 pass || a121 fail "failing shim: purged account-data line prints (out: $o121)"
[[ "$o121" == *"uninstall-kit: kit removed from $u121/prefix"* \
    && "$o121" == *"instanced templates removed; $unconfirmed121"* ]] \
    && a121 pass || a121 fail "failing shim: uninstall summary is state-honest (out: $o121)"
[[ "$o121" != *"egl121-failing-shim-diagnostic"* \
    && "$o121" != *"; timers stopped"* ]] \
    && a121 pass || a121 fail "failing shim: no raw diagnostic and no false timer claim (out: $o121)"
grep -q '^systemctl daemon-reload$' "$s121/shim.log" \
    && a121 pass || a121 fail "failing shim recorded the uninstall daemon-reload (log: $(cat "$s121/shim.log" 2>&1))"

# 5b. EGL-532-D2: a symlinked account confdir is removed as a link, never
#     called purged account data; its target (the real policy tree) stays.
mk121_prefix
rm -rf "$u121/home/runner/.config/egresslock"
mkdir -p "$u121/home/runner/policy-target"
printf 'marker\n' > "$u121/home/runner/policy-target/keep"
ln -s "$u121/home/runner/policy-target" "$u121/home/runner/.config/egresslock"
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    PATH="$s121:$PATH" "$UKIT" --prefix "$u121/prefix" --account root \
    --purge-account-data 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "symlink purge: uninstall exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"uninstall-kit: removed $u121/home/runner/.config/egresslock (symbolic link; its target was not touched)"* ]] \
    && a121 pass || a121 fail "symlink purge: named removed-symlink line prints (out: $o121)"
[[ "$o121" != *"uninstall-kit: purged $u121/home/runner/.config/egresslock (account data)"* ]] \
    && a121 pass || a121 fail "symlink purge: no false purged-account-data line (out: $o121)"
[[ ! -L "$u121/home/runner/.config/egresslock" && ! -e "$u121/home/runner/.config/egresslock" ]] \
    && a121 pass || a121 fail "symlink purge: only the link is removed"
[[ -d "$u121/home/runner/policy-target" && "$(cat "$u121/home/runner/policy-target/keep")" == "marker" ]] \
    && a121 pass || a121 fail "symlink purge: the link target is untouched"

# 6. uninstall, zero-exit chroot/offline shim (B1): the successful no-op is
#    still unconfirmed — warning with the stop check and `timer stop not
#    confirmed`, never `timers stopped`; the raw diagnostic is not echoed.
mk121_prefix
: > "$z121/shim.log"
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    PATH="$z121:$PATH" "$UKIT" --prefix "$u121/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "uninstall with a zero-exit chroot shim exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"$w121_u"* && "$o121" == *"$stop121_u"* ]] && a121 pass \
    || a121 fail "zero-exit chroot shim: uninstall warning and stop check print (out: $o121)"
[[ "$o121" == *"$unconfirmed121"* && "$o121" != *"; timers stopped"* ]] \
    && a121 pass || a121 fail "zero-exit chroot shim: summary is state-honest (out: $o121)"
[[ "$o121" != *"Running in chroot"* ]] && a121 pass \
    || a121 fail "zero-exit chroot shim: raw diagnostic is not echoed (out: $o121)"
[[ ! -e "$u121/prefix" && ! -e "$u121/units/egresslock-verify@.timer" ]] \
    && a121 pass || a121 fail "zero-exit chroot shim: removal completes"
grep -q '^systemctl daemon-reload$' "$z121/shim.log" \
    && a121 pass || a121 fail "zero-exit chroot shim recorded the uninstall daemon-reload"

# 7. uninstall, harness mock systemctl (positive control): the confirmed
#    path keeps `timers stopped` and stays warning-free.
mk121_prefix
: > "$STATE/systemctl.log"
o121="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    "$UKIT" --prefix "$u121/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "uninstall with the mock systemctl exits 0 (rc=$rc, out: $o121)"
[[ "$o121" == *"timers stopped"* ]] && a121 pass \
    || a121 fail "mock systemctl: confirmed summary says timers stopped (out: $o121)"
[[ "$o121" != *"$w121_u"* ]] && a121 pass \
    || a121 fail "mock systemctl: no uninstall warning (out: $o121)"

# 8. Stream separation: the warning is stderr-only and the trailing lines
#    are stdout; no raw systemctl text appears in either stream.
o121out="$STATE/egl121-stream.out"; o121err="$STATE/egl121-stream.err"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$i121/units" \
    EGRESSLOCK_PATH_BINDIR="$i121/wbin" EGRESSLOCK_PATH_SBINDIR="$i121/wsbin" \
    PATH="$s121:$PATH" "$KIT" --prefix "$i121/prefix" \
    > "$o121out" 2> "$o121err"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "stream-separated install exits 0 (rc=$rc)"
[[ "$(cat "$o121err")" == *"$w121_i"* && "$(cat "$o121err")" == *"$next121_i"* ]] \
    && a121 pass || a121 fail "stream-separated install: warning is on stderr (err: $(cat "$o121err"))"
[[ "$(cat "$o121out")" != *"WARNING - systemd did not confirm"* ]] \
    && a121 pass || a121 fail "stream-separated install: warning is not on stdout"
[[ "$(cat "$o121out")" == *"successfully installed! kit is at: $i121/prefix"* ]] \
    && a121 pass || a121 fail "stream-separated install: success line is on stdout"
[[ "$(cat "$o121out")$(cat "$o121err")" != *"egl121-failing-shim-diagnostic"* ]] \
    && a121 pass || a121 fail "stream-separated install: raw diagnostic absent from both streams"

mk121_prefix
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u121/units" \
    EGRESSLOCK_ACCOUNT_HOME="$u121/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$u121/wbin" EGRESSLOCK_PATH_SBINDIR="$u121/wsbin" \
    PATH="$s121:$PATH" "$UKIT" --prefix "$u121/prefix" --account root \
    > "$o121out" 2> "$o121err"; rc=$?
[[ "$rc" == 0 ]] && a121 pass \
    || a121 fail "stream-separated uninstall exits 0 (rc=$rc)"
[[ "$(cat "$o121err")" == *"$w121_u"* && "$(cat "$o121err")" == *"$stop121_u"* ]] \
    && a121 pass || a121 fail "stream-separated uninstall: warning is on stderr (err: $(cat "$o121err"))"
[[ "$(cat "$o121out")" != *"WARNING - systemd did not confirm"* ]] \
    && a121 pass || a121 fail "stream-separated uninstall: warning is not on stdout"
[[ "$(cat "$o121out")" == *"uninstall-kit: kept $u121/home/runner/.config/egresslock"* \
    && "$(cat "$o121out")" == *"$unconfirmed121"* ]] \
    && a121 pass || a121 fail "stream-separated uninstall: trailing lines are on stdout"
[[ "$(cat "$o121out")$(cat "$o121err")" != *"egl121-failing-shim-diagnostic"* ]] \
    && a121 pass || a121 fail "stream-separated uninstall: raw diagnostic absent from both streams"
section_end egl121

# --- EGL-463: honest timer-stop disclosure ----------------------------------
# The pre-existing half of B2: a failed per-account disable, a failed sweep
# instance, or an unreadable enabled-timer list must not leave the closing
# summary claiming `timers stopped`. The prepended shim logs every call,
# succeeds silently for daemon-reload (so EGL-121's reload term cannot
# confound), and fails only a chosen `disable --now` unit. The harness mock
# is the confirmed positive control.
section_begin egl463 "EGL-463 uninstall timer-stop disclosure"
a463() { assert "$@"; }

w463="uninstall-kit: WARNING - could not confirm the verify timers stopped."
d463_fail="  systemd did not disable:"
d463_list="  The enabled verify timers could not be listed."
n463_check="  When systemd is available, check: systemctl list-timers 'egresslock-verify@*.timer'"
n463_stop="  If a verify timer is still active, stop it: systemctl disable --now egresslock-verify@ACCOUNT.timer"
u463="timer stop not confirmed"

d463="$STATE/egl463"; rm -rf "$d463"; mkdir -p "$d463"
s463="$TESTROOT/bin-kit-egl463"
rm -rf "$s463"; mkdir -p "$s463"
cat > "$s463/systemctl" <<'EOF'
#!/usr/bin/env bash
printf 'systemctl %s\n' "$*" >> "${EGL463_SHIM_LOG:?}"
case "$1" in
    daemon-reload)
        exit 0 ;;
    list-unit-files)
        [[ "${EGL463_LIST_RC:-0}" == 0 ]] || exit "$EGL463_LIST_RC"
        if [[ -n "${EGL463_LIST_OUT:-}" ]]; then
            printf '%s\n' "$EGL463_LIST_OUT"
        fi
        exit 0 ;;
    # EGL-535-D5: the manager's loaded view is a separate source. Default
    # empty/rc 0 keeps cases 1-7 byte-identical.
    list-units)
        [[ "${EGL463_UNITS_RC:-0}" == 0 ]] || exit "$EGL463_UNITS_RC"
        if [[ -n "${EGL463_UNITS_OUT:-}" ]]; then
            printf '%s\n' "$EGL463_UNITS_OUT"
        fi
        exit 0 ;;
    disable)
        if [[ -n "${EGL463_FAIL_UNIT:-}" && "${!#}" == "$EGL463_FAIL_UNIT" ]]; then
            echo "egl463-shim-diagnostic" >&2
            exit 1
        fi
        # Real `systemctl disable` prints the removed symlink on stdout
        # (stderr stays empty). Off by default so cases 1-4 keep their
        # byte-stable streams; case 7 turns it on to pin the pass-through.
        if [[ "${EGL463_DISABLE_ECHO:-0}" == 1 ]]; then
            printf 'Removed /etc/systemd/system/timers.target.wants/%s.\n' "${!#}"
        fi
        exit 0 ;;
esac
exit 0
EOF
chmod +x "$s463/systemctl"

mk463_prefix() {
    rm -rf "$d463/prefix" "$d463/units" "$d463/home" "$d463/wbin" "$d463/wsbin"
    mkdir -p "$d463/prefix/gateway" "$d463/units" \
        "$d463/units/timers.target.wants" \
        "$d463/home/runner/.config/egresslock"
    : > "$d463/prefix/egresslock"; chmod +x "$d463/prefix/egresslock"
    : > "$d463/prefix/egresslock-verify"
    : > "$d463/prefix/VERSION"
    : > "$d463/prefix/gateway/Containerfile"
    : > "$d463/units/egresslock-verify@.service"
    : > "$d463/units/egresslock-verify@.timer"
    : > "$d463/home/runner/.config/egresslock/main.conf"
}

# 1. Per-account disable fails: rc 0, one named warning, no false summary,
#    removal completes; stdout and stderr captured separately.
mk463_prefix
: > "$d463/shim.log"
o463out="$d463/a.out"; o463err="$d463/a.err"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_FAIL_UNIT="egresslock-verify@root.timer" \
    "$UKIT" --prefix "$d463/prefix" --account root \
    > "$o463out" 2> "$o463err"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "per-account failure: rc 0 (rc=$rc)"
[[ "$(cat "$o463err")" == *"$w463"* ]] && a463 pass \
    || a463 fail "per-account failure: warning first line on stderr (err: $(cat "$o463err"))"
[[ "$(cat "$o463err")" == *"$d463_fail egresslock-verify@root.timer"* ]] && a463 pass \
    || a463 fail "per-account failure: failed unit named (err: $(cat "$o463err"))"
[[ "$(cat "$o463err")" == *"$n463_check"* && "$(cat "$o463err")" == *"$n463_stop"* ]] \
    && a463 pass || a463 fail "per-account failure: check and stop commands print"
[[ "$(cat "$o463err")" != *"$d463_list"* ]] && a463 pass \
    || a463 fail "per-account failure: no list-query detail"
[[ "$(cat "$o463out")" == *"uninstall-kit: kit removed from $d463/prefix; instanced templates removed; $u463"* ]] \
    && a463 pass || a463 fail "per-account failure: qualified summary on stdout (out: $(cat "$o463out"))"
[[ "$(cat "$o463out")" != *"; timers stopped"* ]] && a463 pass \
    || a463 fail "per-account failure: summary never says timers stopped"
[[ "$(cat "$o463out")" != *"$w463"* ]] && a463 pass \
    || a463 fail "per-account failure: warning is not on stdout"
[[ "$(cat "$o463out")$(cat "$o463err")" != *"egl463-shim-diagnostic"* ]] && a463 pass \
    || a463 fail "per-account failure: raw shim diagnostic is not echoed"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "per-account failure: removal completes"
grep -qF 'systemctl disable --now egresslock-verify@root.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "per-account failure: disable attempt recorded"
grep -qF 'systemctl daemon-reload' "$d463/shim.log" \
    && a463 pass || a463 fail "per-account failure: silent reload attempted"

# 2. Enabled-instance sweep fails: the list returns the bare template (must
#    be skipped) and one instance whose disable fails; rc 0, that unit
#    named, the template never disabled, qualified summary, removal done.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_FAIL_UNIT="egresslock-verify@acct2.timer" \
    EGL463_LIST_OUT=$'egresslock-verify@.timer enabled\negresslock-verify@acct2.timer enabled' \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "sweep failure: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_fail egresslock-verify@acct2.timer"* ]] \
    && a463 pass || a463 fail "sweep failure: failed instance named (out: $o463)"
[[ "$o463" != *"$d463_fail egresslock-verify@.timer"* ]] && a463 pass \
    || a463 fail "sweep failure: template is not named as failed (out: $o463)"
[[ "$o463" != *"$d463_list"* ]] && a463 pass \
    || a463 fail "sweep failure: no list-query detail (out: $o463)"
[[ "$o463" == *"uninstall-kit: kit removed from $d463/prefix; instanced templates removed; $u463"* ]] \
    && a463 pass || a463 fail "sweep failure: qualified summary (out: $o463)"
[[ "$o463" != *"; timers stopped"* ]] && a463 pass \
    || a463 fail "sweep failure: summary never says timers stopped"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "sweep failure: removal completes"
grep -qF 'systemctl disable --now egresslock-verify@acct2.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "sweep failure: sweep instance disabled once"
grep -qF 'systemctl disable --now egresslock-verify@.timer' "$d463/shim.log" \
    && a463 fail "sweep failure: bare template was not disabled" || a463 pass
grep -qF 'systemctl list-unit-files egresslock-verify@*.timer --no-legend' "$d463/shim.log" \
    && a463 pass || a463 fail "sweep failure: list query recorded"
[[ "$o463" != *"egl463-shim-diagnostic"* ]] && a463 pass \
    || a463 fail "sweep failure: raw shim diagnostic is not echoed"

# 3. List-query failure: rc 0, the unreadable list is named, no unit is
#    falsely blamed, the summary is qualified, and removal completes.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_LIST_RC=1 \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "list-query failure: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_list"* ]] && a463 pass \
    || a463 fail "list-query failure: unreadable list named (out: $o463)"
[[ "$o463" != *"$d463_fail"* ]] && a463 pass \
    || a463 fail "list-query failure: no unit is falsely blamed (out: $o463)"
[[ "$o463" == *"uninstall-kit: kit removed from $d463/prefix; instanced templates removed; $u463"* ]] \
    && a463 pass || a463 fail "list-query failure: qualified summary (out: $o463)"
[[ "$o463" != *"; timers stopped"* ]] && a463 pass \
    || a463 fail "list-query failure: summary never says timers stopped"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "list-query failure: removal completes"
grep -qF 'systemctl list-unit-files egresslock-verify@*.timer --no-legend' "$d463/shim.log" \
    && a463 pass || a463 fail "list-query failure: query recorded"
grep -qF 'systemctl disable --now egresslock-verify@root.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "list-query failure: per-account disable still attempted"

# 4. Harness mock positive control: both stop attempts and the silent reload
#    are confirmed, so the summary keeps `timers stopped` and no warning.
mk463_prefix
: > "$STATE/systemctl.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "positive control: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"timers stopped"* ]] && a463 pass \
    || a463 fail "positive control: confirmed summary says timers stopped (out: $o463)"
[[ "$o463" != *"$w463"* && "$o463" != *"$d463_fail"* && "$o463" != *"$d463_list"* ]] \
    && a463 pass || a463 fail "positive control: no warning or cause detail (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "positive control: removal completes"
grep -qF 'systemctl disable --now egresslock-verify@root.timer' "$STATE/systemctl.log" \
    && a463 pass || a463 fail "positive control: per-account disable recorded"
grep -qF 'systemctl list-unit-files egresslock-verify@*.timer --no-legend' "$STATE/systemctl.log" \
    && a463 pass || a463 fail "positive control: list query recorded"

# 5. The latch (EGL-463 F1): an earlier failed disable is not undone by a
#    later success — the run keeps `timer stop not confirmed` and names
#    the failed unit. Mutation: re-set timer_stop_confirmed=1 on a later
#    success (`uninstall-kit.sh:240-247`) -> the summary flips to
#    `timers stopped` and this case reds.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_FAIL_UNIT="egresslock-verify@acct1.timer" \
    EGL463_LIST_OUT=$'egresslock-verify@acct1.timer enabled\negresslock-verify@acct2.timer enabled' \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "latch: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_fail egresslock-verify@acct1.timer"* ]] \
    && a463 pass || a463 fail "latch: earlier failure stays warned and named (out: $o463)"
grep -qF 'systemctl disable --now egresslock-verify@acct1.timer' "$d463/shim.log" \
    && grep -qF 'systemctl disable --now egresslock-verify@acct2.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "latch: both sweep disable attempts recorded"
[[ "$o463" == *"$u463"* && "$o463" != *"; timers stopped"* ]] \
    && a463 pass || a463 fail "latch: summary stays qualified (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "latch: removal completes"

# 6. No-account sweep failure (EGL-463 F2): without --account the sweep
#    still lists and names a failed instance. Mutation: move the sweep
#    inside the `for acct` loop (`uninstall-kit.sh:262-278`) -> no list
#    query, no warning, and the summary wrongly says `timers stopped`.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_FAIL_UNIT="egresslock-verify@acct2.timer" \
    EGL463_LIST_OUT='egresslock-verify@acct2.timer enabled' \
    "$UKIT" --prefix "$d463/prefix" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "no-account sweep: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_fail egresslock-verify@acct2.timer"* ]] \
    && a463 pass || a463 fail "no-account sweep: failed instance named (out: $o463)"
grep -qF 'systemctl list-unit-files egresslock-verify@*.timer --no-legend' "$d463/shim.log" \
    && a463 pass || a463 fail "no-account sweep: list query recorded"
[[ "$o463" == *"$u463"* && "$o463" != *"; timers stopped"* ]] \
    && a463 pass || a463 fail "no-account sweep: summary stays qualified (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "no-account sweep: removal completes"

# 7. Disable-success stdout (EGL-463 F3): a real `systemctl disable`
#    prints `Removed …` on stdout with stderr empty; the shim mirrors
#    that on success, so capturing/suppressing `_stop_disable`'s stdout
#    reds here. The harness mock (case 4) is silent and cannot catch it.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" EGL463_DISABLE_ECHO=1 \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "shim stdout: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"timers stopped"* ]] && a463 pass \
    || a463 fail "shim stdout: confirmed summary says timers stopped (out: $o463)"
[[ "$o463" != *"$w463"* && "$o463" != *"$d463_fail"* && "$o463" != *"$d463_list"* ]] \
    && a463 pass || a463 fail "shim stdout: no warning or cause detail (out: $o463)"
[[ "$o463" == *"Removed /etc/systemd/system/timers.target.wants/egresslock-verify@root.timer"* ]] \
    && a463 pass || a463 fail "shim stdout: the disable's Removed line is not swallowed (out: $o463)"

# 8. EGL-535-D5 (wants-only, the live systemd 257 shape): the file query
#    returns only the template row and the manager's loaded set is empty;
#    the enablement link is the only source naming the instance. It must
#    be attempted exactly once, the summary must keep `timers stopped`,
#    and the template must never be disabled. Mutation: drop source (4)
#    (the `timers.target.wants` glob) -> no attempt, red.
mk463_prefix
ln -s "$d463/units/egresslock-verify@.timer" \
    "$d463/units/timers.target.wants/egresslock-verify@acct3.timer"
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_LIST_OUT='egresslock-verify@.timer indirect enabled' \
    EGL463_UNITS_OUT='' \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "wants-only: rc 0 (rc=$rc, out: $o463)"
grep -qF 'systemctl list-units --all --type=timer --plain --no-legend egresslock-verify@*.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "wants-only: loaded-set query recorded (EGL-535-D1 source 2)"
[[ "$(grep -cF 'systemctl disable --now egresslock-verify@acct3.timer' "$d463/shim.log")" == 1 ]] \
    && a463 pass || a463 fail "wants-only: enablement-link instance disabled exactly once"
[[ "$o463" == *"instanced templates removed; timers stopped"* ]] && a463 pass \
    || a463 fail "wants-only: summary keeps timers stopped (out: $o463)"
[[ "$o463" != *"$w463"* && "$o463" != *"$d463_fail"* && "$o463" != *"$d463_list"* ]] \
    && a463 pass || a463 fail "wants-only: no warning or cause detail (out: $o463)"
grep -qF 'systemctl disable --now egresslock-verify@.timer' "$d463/shim.log" \
    && a463 fail "wants-only: bare template was not disabled" || a463 pass
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "wants-only: removal completes"

# 9. EGL-535-D5 (loaded-only): no wants link and an empty file query, but
#    the manager's loaded set names the instance. Its failed disable must
#    be named and the summary qualified. Mutation: drop source (2) (the
#    `list-units --all` capture) -> no attempt, red.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_UNITS_OUT='egresslock-verify@acct4.timer loaded active waiting Periodic network policy verification for acct4' \
    EGL463_FAIL_UNIT='egresslock-verify@acct4.timer' \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "loaded-only: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_fail egresslock-verify@acct4.timer"* ]] \
    && a463 pass || a463 fail "loaded-only: failed loaded instance is named (out: $o463)"
grep -qF 'systemctl disable --now egresslock-verify@acct4.timer' "$d463/shim.log" \
    && a463 pass || a463 fail "loaded-only: loaded instance disable attempted"
[[ "$o463" == *"$u463"* && "$o463" != *"; timers stopped"* ]] \
    && a463 pass || a463 fail "loaded-only: summary stays qualified (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "loaded-only: removal completes"

# 9b. EGL-535-D3: the NEW source's own failure path — the file query
#     answers (template row only) while `list-units` exits nonzero. The
#     union is authoritative only for what the answering sources could
#     see, so the unreadable-list line prints and the summary is
#     qualified. Mutation: drop the `|| _stop_list_rc=$?` capture on the
#     loaded-set query -> the summary wrongly says `timers stopped`, red.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_LIST_OUT='egresslock-verify@.timer indirect enabled' \
    EGL463_UNITS_RC=1 \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "loaded-set query failure: rc 0 (rc=$rc, out: $o463)"
[[ "$o463" == *"$w463"* && "$o463" == *"$d463_list"* ]] && a463 pass \
    || a463 fail "loaded-set query failure: unreadable list named (out: $o463)"
[[ "$o463" != *"$d463_fail"* ]] && a463 pass \
    || a463 fail "loaded-set query failure: no unit is falsely blamed (out: $o463)"
[[ "$o463" == *"$u463"* && "$o463" != *"; timers stopped"* ]] && a463 pass \
    || a463 fail "loaded-set query failure: summary stays qualified (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "loaded-set query failure: removal completes"

# 10. EGL-535-D5 (over-broad output): both listings carry a `.service`
#     unit and a foreign timer; neither may be disabled, and the run keeps
#     `timers stopped`. Mutation: drop the name-shape filter in
#     `_stop_try_unit` -> both foreign names are disabled, red.
mk463_prefix
: > "$d463/shim.log"
o463="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$d463/units" \
    EGRESSLOCK_ACCOUNT_HOME="$d463/home/runner" \
    EGRESSLOCK_PATH_BINDIR="$d463/wbin" EGRESSLOCK_PATH_SBINDIR="$d463/wsbin" \
    PATH="$s463:$PATH" EGL463_SHIM_LOG="$d463/shim.log" \
    EGL463_LIST_OUT=$'egresslock-verify@.timer enabled\negresslock-verify@acct5.service enabled\nother@acct.timer enabled' \
    EGL463_UNITS_OUT=$'egresslock-verify@acct5.service loaded active running kit service\nother@acct.timer loaded active waiting foreign timer' \
    "$UKIT" --prefix "$d463/prefix" --account root 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && a463 pass || a463 fail "over-broad: rc 0 (rc=$rc, out: $o463)"
grep -qF 'disable --now egresslock-verify@acct5.service' "$d463/shim.log" \
    && a463 fail "over-broad: a .service listing is never disabled" || a463 pass
grep -qF 'disable --now other@acct.timer' "$d463/shim.log" \
    && a463 fail "over-broad: a foreign timer is never disabled" || a463 pass
[[ "$o463" == *"instanced templates removed; timers stopped"* ]] && a463 pass \
    || a463 fail "over-broad: summary keeps timers stopped (out: $o463)"
[[ "$o463" != *"$w463"* ]] && a463 pass \
    || a463 fail "over-broad: no warning (out: $o463)"
[[ ! -e "$d463/prefix" && ! -e "$d463/units/egresslock-verify@.timer" ]] && a463 pass \
    || a463 fail "over-broad: removal completes"
# EGL-535-D1 amendment (standing): an unmatched path glob yields its own
# literal, and a pattern-shaped test would admit it. The unit dir here has
# no instance files, so the existence guards plus `_stop_try_unit`'s
# metacharacter rejection must keep that literal away from disable
# (mutation: remove both the `-e`/`-L -e` guards and the metacharacter
# test -> the literal is disabled, red).
grep -qF 'disable --now egresslock-verify@*.timer' "$d463/shim.log" \
    && a463 fail "glob literal: an unmatched-glob literal is never disabled" || a463 pass
section_end egl463

# --- EGL-258: timer stop stops a running verify (PartOf) --------------------
# A running verify must not survive the timer stop: the shipped template
# declares PartOf=, and both uninstall recipes stop the timer before
# teardown. The host has no systemd, so the live propagation is the VM case
# S9-timer-stop-stops-verify; these pins keep the line and the order from
# drifting back.
section_begin egl258 "EGL-258 timer-stop stops verify"
e258() { assert "$@"; }
e258_unit="$TREE_ROOT/systemd/egresslock-verify@.service"
e258_doc="$TREE_ROOT/docs/setup/uninstall.md"

grep -qxF 'PartOf=egresslock-verify@%i.timer' "$e258_unit" \
    && e258 pass || e258 fail "repo unit declares PartOf=egresslock-verify@%i.timer"

# Docs order: the timer stop precedes the first teardown command.
e258_stop_ln=$(grep -nF 'systemctl disable --now egresslock-verify@' "$e258_doc" | head -1 | cut -d: -f1)
e258_teardown_ln=$(grep -nF 'egresslock teardown' "$e258_doc" | head -1 | cut -d: -f1)
if [[ -n "$e258_stop_ln" && -n "$e258_teardown_ln" && "$e258_stop_ln" -lt "$e258_teardown_ln" ]]; then
    e258 pass
else
    e258 fail "uninstall.md stops the verify timer before teardown (stop=$e258_stop_ln teardown=$e258_teardown_ln)"
fi

# Step 1 owns the one timer-stop block; step 2 must not repeat it.
e258_step1=$(awk '/^### 1\./{f=1} f&&/^### 2\./{exit} f' "$e258_doc")
e258_step2=$(awk '/^### 2\./{f=1} f&&/^### 3\./{exit} f' "$e258_doc")
grep -qF 'systemctl disable --now egresslock-verify@' <<<"$e258_step1" \
    && e258 pass || e258 fail "uninstall.md step 1 stops the verify timer"
grep -qF 'systemctl disable --now egresslock-verify@' <<<"$e258_step2" \
    && e258 fail "uninstall.md step 2 repeats the timer stop" \
    || e258 pass
grep -qF 'stopping the timer also stops a' <<<"$e258_step1" \
    && e258 pass || e258 fail "uninstall.md step 1 states the timer stop aborts a running verify"

# packaging/README orders the deb recipe timer stop -> teardown -> remove.
e258_readme="$TREE_ROOT/packaging/README.md"
if [[ -f "$e258_readme" ]]; then
    e258_stop_ln=$(grep -nF 'systemctl disable --now egresslock-verify@' "$e258_readme" | head -1 | cut -d: -f1)
    e258_teardown_ln=$(grep -nF 'egresslock teardown' "$e258_readme" | head -1 | cut -d: -f1)
    e258_remove_ln=$(grep -nF 'apt remove egresslock' "$e258_readme" | head -1 | cut -d: -f1)
    if [[ -n "$e258_stop_ln" && -n "$e258_teardown_ln" && -n "$e258_remove_ln" \
          && "$e258_stop_ln" -lt "$e258_teardown_ln" && "$e258_teardown_ln" -lt "$e258_remove_ln" ]]; then
        e258 pass
    else
        e258 fail "packaging/README orders timer stop -> teardown -> apt remove (stop=$e258_stop_ln teardown=$e258_teardown_ln remove=$e258_remove_ln)"
    fi
else
    skip "$PKG_SKIP_TAG" "EGL-258 packaging/README recipe order — packaging/README.md is not on this tree (extracted kit)"
fi
section_end egl258

# --- EGL-43: install-kit PATH wrappers (D1–D4) ------------------------------
section_begin egl43 "EGL-43 install-kit PATH wrappers"
a43() { assert "$@"; }
p43="$STATE/egl43"; rm -rf "$p43"
mkdir -p "$p43/units" "$p43/bin" "$p43/sbin" "$p43/opt"
a43_env() {  # wrapper install with the mock PATH dirs
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
        EGRESSLOCK_PATH_BINDIR="$p43/bin" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
        "$TREE_ROOT/install-kit.sh" --prefix "$1" 2>&1
}

# 1. Fresh install writes wrappers whose exec line names the mock prefix.
o="$(a43_env "$p43/opt")"; rc=$?
[[ "$rc" == 0 && -x "$p43/bin/egresslock" && -x "$p43/sbin/egresslock-setup" ]] \
    && a43 pass || a43 fail "wrappers installed (rc=$rc, out: $o)"
[[ "$o" == *"PATH wrapper installed: $p43/bin/egresslock to $p43/opt/egresslock"* ]] \
    && a43 pass || a43 fail "wrapper success line joins with 'to' (out: $o)"
assert_kit_lines_paste_safe "PATH wrapper install" "$o" '^PATH wrapper installed:'
[[ "$(sed -n '2p' "$p43/bin/egresslock")" == "# egresslock-path-wrapper prefix=$p43/opt" ]] \
    && a43 pass || a43 fail "wrapper marker carries the prefix (D1)"
grep -qF "exec \"$p43/opt/egresslock\" \"\$@\"" "$p43/bin/egresslock" \
    && a43 pass || a43 fail "engine wrapper execs the prefix copy, quoted (D1, EGL-90-D1.2)"
grep -qF "exec \"$p43/opt/egresslock-setup\" \"\$@\"" "$p43/sbin/egresslock-setup" \
    && a43 pass || a43 fail "setup wrapper execs the prefix copy, quoted (D2, EGL-90-D1.2)"

# 2. Same prefix re-run: upgrade overwrite, rc 0, marker still this prefix.
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec stale "$@"\n' "$p43/opt" > "$p43/bin/egresslock"
o="$(a43_env "$p43/opt")"; rc=$?
[[ "$rc" == 0 ]] && grep -qF "exec \"$p43/opt/egresslock\" \"\$@\"" "$p43/bin/egresslock" \
    && a43 pass || a43 fail "same-prefix re-run overwrites (upgrade, D3) (rc=$rc, out: $o)"

# 3. Dest file without the marker -> rc 1, file unchanged (D3).
mkdir -p "$p43/opt2" "$p43/bin2"
printf 'not-a-wrapper\n' > "$p43/bin2/egresslock"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="$p43/bin2" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
    "$TREE_ROOT/install-kit.sh" --prefix "$p43/opt2" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$(cat "$p43/bin2/egresslock")" == "not-a-wrapper" ]] \
    && a43 pass || a43 fail "foreign dest refused, file unchanged (rc=$rc, out: $o)"

# 4. Another prefix's wrapper -> rc 1 (no PATH fights, D3).
mkdir -p "$p43/bin3"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=/elsewhere\nexec /elsewhere/egresslock "$@"\n' > "$p43/bin3/egresslock"
cp "$p43/bin3/egresslock" "$p43/bin3/pre-image"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="$p43/bin3" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
    "$TREE_ROOT/install-kit.sh" --prefix "$p43/opt" 2>&1)"; rc=$?
if [[ "$rc" == 1 ]] && cmp -s "$p43/bin3/egresslock" "$p43/bin3/pre-image"; then
    a43 pass
else
    a43 fail "different-prefix wrapper refused (rc=$rc, out: $o)"
fi

# 5. Installed .deb -> rc 1 naming 'apt remove egresslock' (D3/ARC-22-D1).
mkdir -p "$p43/stubbin"
printf '#!/bin/sh\necho "install ok installed"\n' > "$p43/stubbin/dpkg-query"
chmod 0755 "$p43/stubbin/dpkg-query"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="$p43/bin" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
    PATH="$p43/stubbin:$PATH" \
    "$TREE_ROOT/install-kit.sh" --prefix "$p43/opt" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *'apt remove egresslock'* ]] \
    && a43 pass || a43 fail "deb co-install refused (rc=$rc, out: $o)"

# 5b. EGL-80-L2: the deb-shape guard is env-pinnable — a NON-wrapper
#     file at EGRESSLOCK_UB_BIN refuses rc 1. Hermetic coverage for the
#     guard that previously read the real /usr/bin/egresslock (present
#     on deployed hosts, where it made every install-kit run refuse).
mkdir -p "$p43/ub"
printf '#!/bin/sh\n# the deb engine, not a kit PATH wrapper\n' > "$p43/ub/egresslock"
chmod 0755 "$p43/ub/egresslock"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="$p43/bin" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
    EGRESSLOCK_UB_BIN="$p43/ub/egresslock" \
    "$TREE_ROOT/install-kit.sh" --prefix "$p43/opt" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"exists and is not an egresslock kit PATH"* ]] \
    && a43 pass || a43 fail "deb-shape /usr/bin guard refused (rc=$rc, out: $o)"

# 6. Uninstall removes only THIS prefix's wrappers (D4); another
#    prefix's wrapper in the same dir is kept.
mkdir -p "$p43/bin4"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec %s "$@"\n' "$p43/opt" "$p43/opt/egresslock" > "$p43/bin4/egresslock"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=/elsewhere\nexec /elsewhere/egresslock-setup "$@"\n' > "$p43/bin4/egresslock-setup"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="$p43/bin4" EGRESSLOCK_PATH_SBINDIR="$p43/bin4" \
    "$TREE_ROOT/uninstall-kit.sh" --prefix "$p43/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && ! -e "$p43/bin4/egresslock" && -e "$p43/bin4/egresslock-setup" ]] \
    && a43 pass || a43 fail "uninstall removes only this prefix's wrappers (rc=$rc, out: $o)"

# 7. Unwritable PATH dir -> warning, rc 0 (convenience step, not fatal;
#    the prefix kit itself is already deployed).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$p43/units" \
    EGRESSLOCK_PATH_BINDIR="/proc/no-such-writable-dir" EGRESSLOCK_PATH_SBINDIR="$p43/sbin" \
    "$TREE_ROOT/install-kit.sh" --prefix "$p43/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"cannot install PATH wrapper"* ]] \
    && a43 pass || a43 fail "unwritable PATH dir warns and continues (rc=$rc, out: $o)"

section_end egl43


# --- EGL-420: build-deb must not dereference a recipe symlink -------------
# Sibling of EGL-399 (docs loop): the recipes loop admitted a symlink via
# [[ -f ]] and install(1) copied the referent's private bytes. The pin
# covers a resolving link and a dangling link, the clean regular-recipe
# control, and the built artifact when dpkg-deb is present.
section_begin egl420 "EGL-420 recipe symlink publication guard"
e420() { assert "$@"; }
if [[ "$HAVE_BUILD_DEB" == 0 ]]; then
    skip "$PKG_SKIP_TAG" "EGL-420 recipe symlink pins — packaging/build-deb.sh is not on this tree (extracted kit)"
else
p420="$STATE/egl420"; rm -rf "$p420"; mkdir -p "$p420/kit"
(cd "$TREE_ROOT" && tar -cf - --exclude=./.git .) | tar -xf - -C "$p420/kit"
# Canary literal is split so this shipped file never contains the bytes
# the pin searches for. The link resolves in the source tree to a file
# outside examples/recipes/; it must never be followed into a stage.
e420_canary='EGL420-synthetic-'"canary"' bytes must never publish'
printf '%s\n' "$e420_canary" > "$p420/kit/private-canary.md"
DEB420="$p420/kit/packaging/build-deb.sh"
ln -s ../../private-canary.md "$p420/kit/examples/recipes/review-only-canary.md"
ln -s no-such-egl420-target "$p420/kit/examples/recipes/dangling-canary.md"

s420="$p420/stage"; rm -rf "$s420"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$s420" EGRESSLOCK_DEB_OUT="$p420/stage-build.deb" "$DEB420" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && e420 pass || e420 fail "recipe symlink staging run rc 0 (rc=$rc, out: $o)"
[[ ! -L "$s420/usr/share/egresslock/examples/recipes/review-only-canary.md" \
   && ! -e "$s420/usr/share/egresslock/examples/recipes/review-only-canary.md" ]] \
    && e420 pass || e420 fail "resolving recipe symlink not staged"
[[ ! -L "$s420/usr/share/egresslock/examples/recipes/dangling-canary.md" \
   && ! -e "$s420/usr/share/egresslock/examples/recipes/dangling-canary.md" ]] \
    && e420 pass || e420 fail "dangling recipe symlink not staged"
grep -rIlF -- "$e420_canary" "$s420" >/dev/null 2>&1 \
    && e420 fail "recipe symlink canary bytes absent from the stage" \
    || e420 pass
[[ -f "$s420/usr/share/egresslock/examples/recipes/github.md" ]] \
    && e420 pass || e420 fail "regular recipes still staged (clean control)"
[[ "$o" == *"skipping recipe symlink"* && "$o" == *"review-only-canary.md"* \
   && "$o" == *"dangling-canary.md"* ]] \
    && e420 pass || e420 fail "each recipe symlink is named on stderr (out: $o)"

# Artifact shape: the built .deb carries neither link name and no
# referent bytes (stage-only builds skip dpkg-deb by design).
if command -v dpkg-deb >/dev/null 2>&1; then
    d420="$p420/e420.deb"; rm -f "$d420"
    o="$(env EGRESSLOCK_DEB_OUT="$d420" "$DEB420" 2>&1)"; rc=$?
    if [[ "$rc" == 0 && -f "$d420" ]]; then
        e420 pass
    else
        e420 fail "built .deb run (rc=$rc, out: $o)"
    fi
    if [[ -f "$d420" ]]; then
        ! dpkg-deb -c "$d420" | grep -qE 'review-only-canary|dangling-canary' \
            && e420 pass || e420 fail "built .deb lists no recipe symlink entry"
        x420="$p420/extract"; rm -rf "$x420"
        dpkg-deb -x "$d420" "$x420" 2>/dev/null || true
        grep -rIlF -- "$e420_canary" "$x420" >/dev/null 2>&1 \
            && e420 fail "built .deb carries no canary bytes" \
            || e420 pass
    fi
else
    skip "dpkg-deb absent" "EGL-420 built-.deb artifact check — dpkg-deb not available"
fi

# Dir-symlink shape (R-EGL-420-2 F1): examples/recipes itself a link to a
# private directory. Its children pass [[ -f ]]; the guard must refuse the
# whole input, name the link, and stage nothing from the referent.
mv "$p420/kit/examples/recipes" "$p420/private-recipes"
printf '%s\n' "$e420_canary" > "$p420/private-recipes/leaked-recipe.md"
ln -s ../../private-recipes "$p420/kit/examples/recipes"
s420d="$p420/stage-dir-symlink"; rm -rf "$s420d"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$s420d" EGRESSLOCK_DEB_OUT="$p420/dir-symlink.deb" "$DEB420" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && e420 pass || e420 fail "dir-symlink recipes run rc 0 (rc=$rc, out: $o)"
grep -qxF 'build-deb: skipping recipe symlink: examples/recipes' <<< "$o" \
    && e420 pass || e420 fail "examples/recipes symlink named on stderr (out: $o)"
[[ ! -e "$s420d/usr/share/egresslock/examples/recipes/leaked-recipe.md" \
   && ! -e "$s420d/usr/share/egresslock/examples/recipes/github.md" ]] \
    && e420 pass || e420 fail "dir-symlink recipes not staged (leaked + regular referent files)"
grep -rIlF -- "$e420_canary" "$s420d" >/dev/null 2>&1 \
    && e420 fail "dir-symlink canary bytes absent from the stage" \
    || e420 pass
if command -v dpkg-deb >/dev/null 2>&1; then
    d420d="$p420/dir-symlink.deb"; rm -f "$d420d"
    o="$(env EGRESSLOCK_DEB_OUT="$d420d" "$DEB420" 2>&1)"; rc=$?
    [[ "$rc" == 0 && -f "$d420d" ]] \
        && e420 pass || e420 fail "dir-symlink built .deb run (rc=$rc, out: $o)"
    if [[ -f "$d420d" ]]; then
        ! dpkg-deb -c "$d420d" | grep -qE 'leaked-recipe|github\.md' \
            && e420 pass || e420 fail "built .deb lists no dir-symlink recipe entry"
        x420d="$p420/extract-dir-symlink"; rm -rf "$x420d"
        dpkg-deb -x "$d420d" "$x420d" 2>/dev/null || true
        grep -rIlF -- "$e420_canary" "$x420d" >/dev/null 2>&1 \
            && e420 fail "built .deb carries no dir-symlink canary bytes" \
            || e420 pass
    fi
else
    skip "dpkg-deb absent" "EGL-420 dir-symlink built-.deb artifact check — dpkg-deb not available"
fi

# Parent-dir shape: examples itself a link to a private directory. The
# fixed-input checks still pass (they follow the link), so the recipes
# loop must detect the linked parent and skip the whole input too.
p420x="$p420/kit-parent-link"; rm -rf "$p420x"; mkdir -p "$p420x"
(cd "$TREE_ROOT" && tar -cf - --exclude=./.git .) | tar -xf - -C "$p420x"
mv "$p420x/examples" "$p420/private-examples"
printf '%s\n' "$e420_canary" > "$p420/private-examples/recipes/leaked-parent-recipe.md"
ln -s ../private-examples "$p420x/examples"
DEB420X="$p420x/packaging/build-deb.sh"
s420x="$p420/stage-parent-symlink"; rm -rf "$s420x"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$s420x" EGRESSLOCK_DEB_OUT="$p420/parent-symlink.deb" "$DEB420X" 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && e420 pass || e420 fail "parent-symlink recipes run rc 0 (rc=$rc, out: $o)"
grep -qxF 'build-deb: skipping recipe symlink: examples' <<< "$o" \
    && e420 pass || e420 fail "examples symlink named on stderr (out: $o)"
[[ ! -e "$s420x/usr/share/egresslock/examples/recipes/leaked-parent-recipe.md" \
   && ! -e "$s420x/usr/share/egresslock/examples/recipes/github.md" ]] \
    && e420 pass || e420 fail "parent-symlink recipes not staged (leaked + regular referent files)"
grep -rIlF -- "$e420_canary" "$s420x" >/dev/null 2>&1 \
    && e420 fail "parent-symlink canary bytes absent from the stage" \
    || e420 pass
if command -v dpkg-deb >/dev/null 2>&1; then
    d420x="$p420/parent-symlink.deb"; rm -f "$d420x"
    o="$(env EGRESSLOCK_DEB_OUT="$d420x" "$DEB420X" 2>&1)"; rc=$?
    [[ "$rc" == 0 && -f "$d420x" ]] \
        && e420 pass || e420 fail "parent-symlink built .deb run (rc=$rc, out: $o)"
    if [[ -f "$d420x" ]]; then
        ! dpkg-deb -c "$d420x" | grep -qE 'leaked-parent-recipe|github\.md' \
            && e420 pass || e420 fail "built .deb lists no parent-symlink recipe entry"
        x420x="$p420/extract-parent-symlink"; rm -rf "$x420x"
        dpkg-deb -x "$d420x" "$x420x" 2>/dev/null || true
        grep -rIlF -- "$e420_canary" "$x420x" >/dev/null 2>&1 \
            && e420 fail "built .deb carries no parent-symlink canary bytes" \
            || e420 pass
    fi
else
    skip "dpkg-deb absent" "EGL-420 parent-symlink built-.deb artifact check — dpkg-deb not available"
fi
fi
section_end egl420


# --- EGL-49: .deb other-readable for apt's _apt sandbox (D1) ----------------
section_begin egl49 "EGL-49 deb other-readable"
a49() { assert "$@"; }
if command -v dpkg-deb >/dev/null 2>&1 && [[ "$HAVE_BUILD_DEB" == 1 ]]; then
    p49="$STATE/egl49"; rm -rf "$p49"; mkdir -p "$p49"
    # Build under umask 077 (the defect shape).
    o="$(env EGRESSLOCK_DEB_OUT="$p49/e2.deb" bash -c 'umask 077; bash "$1" 2>&1' _ "$TREE_ROOT/packaging/build-deb.sh")"; rc=$?
    if [[ "$rc" == 0 && -f "$p49/e2.deb" ]]; then
        mode="$(stat -c '%a' "$p49/e2.deb")"
        (( (8#$mode & 4) != 0 )) \
            && a49 pass || a49 fail "umask 077 .deb lacks other-read (mode $mode, out: $o)"
    else
        a49 fail "umask 077 deb build (rc=$rc, out: $o)"
    fi
    # D1: KEEP_STAGE exits before the build (no artifact, no chmod) —
    # pinned by the earlier ARC-22 flow.
elif [[ "$HAVE_BUILD_DEB" == 0 ]]; then
    skip "$PKG_SKIP_TAG" "EGL-49 umask build assert — packaging/build-deb.sh is not on this tree (extracted kit)"
else
    skip "dpkg-deb absent" "EGL-49 dpkg-deb not available; skipping mode assert"
fi

section_end egl49
section_begin arc18 "ARC-18 setup-account"

# --- ARC-18: setup-account ---------------------------------------------------
a18() { assert "$@"; }
SKIT="$TREE_ROOT/egresslock-setup"

[[ -x "$SKIT" ]] && a18 pass || a18 fail "egresslock-setup is executable in git"

a18d="$STATE/a18"
SKITP="$OPT"
rm -rf "$a18d"
mkdir -p "$a18d/home/cacct/.config/egresslock"
# Minimal conf with one gateway profile; allowlist next to the conf.
printf 'profile p1 10.99.0.0/24\n    gateway 10.99.0.2 3128 p1-allowlist\n' \
    > "$a18d/site.conf"
printf '# starter\n' > "$a18d/p1-allowlist"
# Pathless/aggregate fixture used by the derived-prefix and AppArmor legs.
printf 'profile p2 10.99.1.0/24\n    gateway 10.99.1.2 3128 p2-allowlist\n' \
    > "$a18d/plain.conf"
printf '# starter\n' > "$a18d/p2-allowlist"
: > "$STATE/systemctl.log"; : > "$STATE/buildlog"

# Root-only refusal (no hook).
env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" >/dev/null 2>&1
[[ $? == 1 ]] && a18 pass || a18 fail "refuses non-root without the test hook"
# Usage errors → rc 2.
a18_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT --prefix "$SKITP" --account cacct 2>&1)"; a18_rc=$?
[[ "$a18_rc" == 1 && "$a18_out" == *"no profile configs in"* \
    && "$a18_out" == *"--init-conf"* && "$a18_out" == *"import cacct --from"* ]] \
    && a18 pass || a18 fail "pathless init on an empty confdir → rc 1 naming both writers (rc=$a18_rc, out: $a18_out)"
$SKIT --prefix "$SKITP" -h 2>/dev/null | grep -q "one-command" \
    && a18 pass || a18 fail "-h prints the header (mawk-safe)"
# Preflight failures fail closed BEFORE writing anything. Hook mode so
# the run reaches the check (without it the root guard exits first and
# the assertion is vacuous — R-EGL-325-2 F3).
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/missing.conf" >/dev/null 2>&1
[[ $? == 1 && ! -e "$a18d/home/cacct/.config/egresslock/unit.env" ]] \
    && a18 pass || a18 fail "missing conf → rc 1, nothing written"
chmod 000 "$a18d/site.conf"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" >/dev/null 2>&1
[[ $? == 1 && ! -e "$a18d/home/cacct/.config/egresslock/unit.env" ]] \
    && a18 pass || a18 fail "unreadable conf → rc 1, nothing written"
chmod 644 "$a18d/site.conf"

# Happy path: aggregate init, gateway conf -> imported pair + gateway
# build, and no per-account wiring file (EGL-333-D2).
s_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:test \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 ]] && a18 pass || a18 fail "setup-account run (rc=$s_rc, out: $s_out)"
# EGL-200 M1: the tail ends on the next-step block, naming the confdir's
# first profile (the imported p1) and the aggregate timer behavior.
[[ "$s_out" == *"next steps (as the account):"* \
    && "$s_out" == *"  sudo -iu cacct"* \
    && "$s_out" == *"  egresslock ensure p1"* \
    && "$s_out" == *"  egresslock verify p1"* \
    && "$s_out" == *"read more: egresslock-setup help"* ]] \
    && a18 pass || a18 fail "EGL-200 M1: next-step block names account + profile (out: $s_out)"
# EGL-600 P3: --enable was absent, so no scheduled-check claim may print.
[[ "$s_out" != *"the scheduled check"* ]] \
    && a18 pass || a18 fail "EGL-600 P3: no scheduled-check claim without --enable (out: $s_out)"
p1conf="$a18d/home/cacct/.config/egresslock/p1.conf"
[[ -f "$p1conf" ]] \
    && a18 pass || a18 fail "--from installs as <profile>.conf in the fixed confdir"
[[ ! -e "$a18d/home/cacct/.config/egresslock/unit.env" ]] \
    && a18 pass || a18 fail "init writes no unit.env (EGL-333-D2)"
[[ "$(stat -c %a "$p1conf")" == 600 ]] && a18 pass || a18 fail "imported conf is 0600"
grep -q "build -t localhost/egresslock-gateway:test" "$STATE/buildlog" \
    && a18 pass || a18 fail "gateway image built as the account (build-if-missing)"
# Idempotent re-run: same pair, still no wiring file.
s_rc=0
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:test \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" >/dev/null 2>&1 || s_rc=$?
[[ "$s_rc" == 0 && ! -e "$a18d/home/cacct/.config/egresslock/unit.env" ]] \
    && a18 pass || a18 fail "re-run is a no-op and writes no unit.env (rc=$s_rc)"

# A conf with no gateway line is rejected at staged validation (EGL-366):
# rc 1 with the engine's named cause, nothing imported, the existing conf
# and the build log untouched.
printf 'profile p2 10.99.1.0/24\n' > "$a18d/nogw.conf"
builds_before="$(wc -l < "$STATE/buildlog")"
p1conf_before="$(cat "$p1conf")"
plain_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/nogw.conf" 2>&1)"; plain_rc=$?
if [[ "$plain_rc" == 1 \
      && "$plain_out" == *"staged pair failed validation"* \
      && "$plain_out" == *"profile 'p2' has no 'gateway' directive"* \
      && "$(cat "$p1conf")" == "$p1conf_before" \
      && ! -e "$a18d/home/cacct/.config/egresslock/p2.conf" \
      && "$(wc -l < "$STATE/buildlog")" == "$builds_before" ]]; then
    a18 pass
else
    a18 fail "no-gateway conf is rejected named before wiring (rc=$plain_rc, out: $plain_out)"
fi

# Conf that fails engine validation → rc 1, the existing conf untouched,
# and the install really rolled back (hook mode so install/validation
# actually run — R-EGL-325-2 F3; without the hook the root guard exits
# first).
printf 'profile p3 10.99.2.0/24\n    rule bogus-directive\n' > "$a18d/bad.conf"
p3conf="$a18d/home/cacct/.config/egresslock/p3.conf"
rm -f "$p3conf"
p1conf_before="$(cat "$p1conf")"
bad_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/bad.conf" 2>&1)"; bad_rc=$?
if [[ "$bad_rc" == 1 && "$bad_out" == *"staged pair failed validation"* ]]; then
    a18 pass
else
    a18 fail "unparseable conf → rc 1 at import validation (rc=$bad_rc, out: $bad_out)"
fi
[[ "$(cat "$p1conf")" == "$p1conf_before" ]] \
    && a18 pass || a18 fail "unparseable conf → existing conf unchanged"
[[ ! -e "$p3conf" ]] \
    && a18 pass || a18 fail "unparseable conf → no partial dest"
# A pre-existing different destination is never replaced (A1): import
# refuses before validation/copy; the prior bytes stay.
printf 'profile p3 10.99.77.0/24\n' > "$p3conf"; chmod 600 "$p3conf"
cp -p "$p3conf" "$a18d/p3.prior"
bad_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/bad.conf" 2>&1)"; bad_rc=$?
[[ "$bad_rc" == 1 && "$bad_out" == *"destination conf differs"* ]] \
    && a18 pass || a18 fail "differing prior dest refused (A1; rc=$bad_rc, out: $bad_out)"
cmp -s "$a18d/p3.prior" "$p3conf" \
    && a18 pass || a18 fail "differing prior dest untouched byte-identically"
rm -f "$p3conf" "$a18d/p3.prior"

# EGL-333-D9: --profile is a doctor-only flag; init rejects it with the
# specific usage error before any account-side work (hook mode so the
# refusal is the verb gate, not the root guard).
bad_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" --profile nope 2>&1)"; bad_rc=$?
if [[ "$bad_rc" == 2 \
      && "$bad_out" == *"--profile is a doctor flag only (inspection narrowing); the verify timer checks every profile"* \
      && "$bad_out" == *"egresslock-setup doctor ACCOUNT --profile NAME"* ]]; then
    a18 pass
else
    a18 fail "init --profile → rc 2 with the D9 doctor-flag message (rc=$bad_rc, out: $bad_out)"
fi

# EGL-333-F4 (R-EGL-333-2): the D9 gate keys on the --profile FLAG, not a
# nonempty value. An empty value on a non-doctor form takes the same rc 2
# usage error instead of silently running the pathless bundle.
bad_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" --prefix "$SKITP" --account cacct --profile '' 2>&1)"; bad_rc=$?
if [[ "$bad_rc" == 2 \
      && "$bad_out" == *"--profile is a doctor flag only (inspection narrowing); the verify timer checks every profile"* ]]; then
    a18 pass
else
    a18 fail "empty --profile (legacy bundle) → rc 2 with the D9 doctor-flag message (rc=$bad_rc, out: $bad_out)"
fi
bad_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" --profile '' --enable 2>&1)"; bad_rc=$?
if [[ "$bad_rc" == 2 \
      && "$bad_out" == *"--profile is a doctor flag only (inspection narrowing); the verify timer checks every profile"* ]]; then
    a18 pass
else
    a18 fail "empty --profile (init verb) → rc 2 with the D9 doctor-flag message (rc=$bad_rc, out: $bad_out)"
fi

# Prefix derivation (R-follow-up): no --prefix → read the deployed
# prefix from the installed unit template's ExecStart ($UNITS points at
# the a16-installed template for $OPT).
sd="$STATE/a18-derived"
rm -rf "$sd"; mkdir -p "$sd/home/dacct"
s_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$sd/home/dacct" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" init --account dacct --from "$a18d/plain.conf" 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 ]] && a18 pass || a18 fail "no --prefix derives from the installed template (rc=$s_rc, out: $s_out)"
[[ -f "$sd/home/dacct/.config/egresslock/p2.conf" ]] \
    && a18 pass || a18 fail "derived-prefix run installs <profile>.conf"
# And a custom --prefix still wins over the derived one.
s_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$sd/home/dacct" \
    "$SKIT" init --prefix "$a18d" --account dacct --from "$a18d/plain.conf" 2>&1)"; s_rc=$?
[[ "$s_rc" == 1 && "$s_out" == *"no engine at $a18d/egresslock"* ]] \
    && a18 pass || a18 fail "explicit --prefix overrides the derivation (rc=$s_rc, out: $s_out)"

# --enable asks systemd for the timer and enables linger (ARC-28).
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" --enable >/dev/null 2>&1
grep -q "enable --now egresslock-verify@cacct.timer" "$STATE/systemctl.log" \
    && a18 pass || a18 fail "--enable enables the per-account timer"
grep -q "enable-linger cacct" "$STATE/loginctl.log" \
    && a18 pass || a18 fail "--enable enables linger for the account (ARC-28)"
grep -q "show-user cacct -p Linger --value" "$STATE/loginctl.log" \
    && a18 pass || a18 fail "--enable verifies linger (ARC-28)"
# Plain run (no --enable) must not touch loginctl (ARC-28-D3).
: > "$STATE/loginctl.log"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" >/dev/null 2>&1
[[ ! -s "$STATE/loginctl.log" ]] \
    && a18 pass || a18 fail "no --enable -> no loginctl (ARC-28-D3)"
# Fail-closed linger branch (ARC-28 review note 2 follow-up): when
# logind reports Linger=no, --enable exits 1 with the account + manual
# fallback named, and the success lines are not printed.
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
f_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    ARCMOCK_LINGER_ANSWER=no \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" --enable 2>&1)"; f_rc=$?
if [[ "$f_rc" == 1 && "$f_out" == *"linger for 'cacct' did not stick"* \
      && "$f_out" == *"loginctl enable-linger cacct"* ]]; then
    a18 pass
else
    a18 fail "linger Linger=no fails closed (rc=$f_rc, out: $f_out)"
fi
section_end arc18

# --- EGL-328: import pair writer; pathless init; doctor resolve -------------
section_begin egl328 "EGL-328 import pair writer + pathless init"
e328() { assert "$@"; }
e328d="$STATE/e328"
rm -rf "$e328d"; mkdir -p "$e328d/home"
printf 'profile ci 10.98.0.0/24\n    gateway 10.98.0.2 3128 ci-allowlist\n' \
    > "$e328d/site.conf"
printf '# ci allowlist\n.example.test\n' > "$e328d/ci-allowlist"
printf 'profile p2 10.98.1.0/24\n    gateway 10.98.1.2 3128 p2-allowlist\n' > "$e328d/p2.conf"
printf '# starter\n' > "$e328d/p2-allowlist"
printf 'profile p2 10.98.1.0/24\n' > "$e328d/nogw.conf"
printf 'profile abs 10.98.2.0/24\n    gateway 10.98.2.2 3128 %s/abs-allowlist\n' "$e328d" \
    > "$e328d/abs.conf"
printf '.abs.example.test\n' > "$e328d/abs-allowlist"
e328_run() { # <home> <setup args...>
    local h="$1"; shift
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$h" \
        EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:latest \
        "$SKIT" "$@" --prefix "$SKITP"
}
e328_run_bounded() { # <home> <setup args...> — FIFO legs must fail, not hang
    local h="$1"; shift
    timeout 10 env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$h" \
        EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:latest \
        "$SKIT" "$@" --prefix "$SKITP"
}
e328_h="$e328d/home/u1"

# EGL-366 F4/R-EGL-366-17 F-W1: `help import` states the required gateway
# with a generic <port> (3128 is the `init` default, not an import
# requirement) and no longer claims a gateway-less source is a conf-only
# import.
o="$("$SKIT" help import 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"every profile needs a gateway"* \
      && "$o" == *"refused at staged validation"* \
      && "$o" == *'gateway IP PORT PROFILE-allowlist'* \
      && "$o" == *"both destination halves"*"must be regular files or absent"* \
      && "$o" == *"non-regular half        refuse, rc 1, nothing moved or deleted"* \
      && "$o" == *"regular files only; refused for a directory"* \
      && "$o" == *"private mount namespace"* \
      && "$o" == *"Import does not write into the confdir beyond the"*"pair, alter linger/timer/user@, or run ensure."* \
      && "$o" == *"A forced replacement deletes the"*"regular files it replaces, after the staged pair validates"* \
      && "$o" != *"No gateway line means conf only"* ]]; then
    e328 pass
else
    e328 fail "help import requires a gateway and states the regular-file rule (rc=$rc, out: $o)"
fi

# 1. import copies the pair; dest name comes from the source profile line
#    (source basename differs), mode 0600, no unit.env written.
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"installed conf $e328_h/.config/egresslock/ci.conf (profile 'ci')"* \
    && "$o" == *"installed allowlist $e328_h/.config/egresslock/ci-allowlist"* \
    && -f "$e328_h/.config/egresslock/ci.conf" \
    && -f "$e328_h/.config/egresslock/ci-allowlist" \
    && ! -e "$e328_h/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "import pair + dest-name from profile, no unit.env (rc=$rc, out: $o)"
cmp -s "$e328d/site.conf" "$e328_h/.config/egresslock/ci.conf" \
    && e328 pass || e328 fail "import conf byte-identical"
cmp -s "$e328d/ci-allowlist" "$e328_h/.config/egresslock/ci-allowlist" \
    && e328 pass || e328 fail "import allowlist byte-identical"
[[ "$(stat -c %a "$e328_h/.config/egresslock/ci.conf")" == 600 \
    && "$(stat -c %a "$e328_h/.config/egresslock/ci-allowlist")" == 600 ]] \
    && e328 pass || e328 fail "import halves are 0600"

# 2. Identical re-run = no-op rc 0 (same inode, no temp leftovers).
ci_conf="$e328_h/.config/egresslock/ci.conf"
ci_ino="$(stat -c %i "$ci_conf")"; ci_sum="$(sha256sum "$ci_conf" | cut -d' ' -f1)"
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"unchanged"* \
    && "$(stat -c %i "$ci_conf")" == "$ci_ino" \
    && "$(sha256sum "$ci_conf" | cut -d' ' -f1)" == "$ci_sum" \
    && -z "$(find "$e328_h/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
    && e328 pass || e328 fail "identical import is a no-op (rc=$rc, out: $o)"

# 2a. EGL-366 F3: a gateway-less source and an identical existing
#     destination are not an unchanged success — the destination is
#     validated first. rc 1 names the source; the destination bytes stay.
printf 'profile legacy 10.98.6.0/24\n' > "$e328d/legacy.conf"
legacy_conf="$e328_h/.config/egresslock/legacy.conf"
cp -p "$e328d/legacy.conf" "$legacy_conf"
legacy_sum="$(sha256sum "$legacy_conf" | cut -d' ' -f1)"
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/legacy.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"destination pair failed validation"* \
      && "$o" == *"profile 'legacy' has no 'gateway' directive"* \
      && "$o" == *"fix: edit the source conf $e328d/legacy.conf"* \
      && "$(sha256sum "$legacy_conf" | cut -d' ' -f1)" == "$legacy_sum" \
      && -z "$(find "$e328_h/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "identical legacy destination fails validation (rc=$rc, out: $o)"
fi
rm -f "$legacy_conf"

# 2b. EGL-366 F4: staged validation names the --from source to fix,
#     never the temp validation home/destination, and does not suggest
#     `ensure` before the import succeeds.
printf 'profile staged 10.98.7.0/24\n' > "$e328d/staged.conf"
e328_h6="$e328d/home/u6"
o="$(e328_run "$e328_h6" import --account u6 --from "$e328d/staged.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"staged pair failed validation"* \
      && "$o" == *"Error: $e328d/staged.conf:1: profile 'staged' has no 'gateway' directive"* \
      && "$o" != *".import."* && "$o" != *"egresslock ensure"* \
      && "$o" == *"fix: edit the source conf $e328d/staged.conf"* \
      && ! -e "$e328_h6/.config/egresslock/staged.conf" ]]; then
    e328 pass
else
    e328 fail "staged import names the source, not staging (rc=$rc, out: $o)"
fi

# 2b2. EGL-366 F4 (renamed source): the relay maps the full staged file
#      name back to the --from source, never <src-dir>/<profile>.conf.
printf 'profile renamed 10.98.10.0/24\n' > "$e328d/actual-name.conf"
e328_h7="$e328d/home/u7"
o="$(e328_run "$e328_h7" import --account u7 --from "$e328d/actual-name.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"staged pair failed validation"* \
      && "$o" == *"Error: $e328d/actual-name.conf:1: profile 'renamed' has no 'gateway' directive"* \
      && "$o" != *"renamed.conf"* && "$o" != *".import."* && "$o" != *"egresslock ensure"* \
      && "$o" == *"fix: edit the source conf $e328d/actual-name.conf"* \
      && ! -e "$e328_h7/.config/egresslock/renamed.conf" ]]; then
    e328 pass
else
    e328 fail "renamed source import names the --from file (rc=$rc, out: $o)"
fi

# 2c. EGL-366 F3: the pair branch is validated too — an identical
#     destination pair that no longer parses is not "unchanged".
printf 'profile badpair 10.98.8.0/24\n    gateway 10.98.8.2 3128 badpair-allowlist\n    rule bogus\n' > "$e328d/badpair.conf"
printf '# pair\n' > "$e328d/badpair-allowlist"
badpair_conf="$e328_h/.config/egresslock/badpair.conf"
badpair_al="$e328_h/.config/egresslock/badpair-allowlist"
cp -p "$e328d/badpair.conf" "$badpair_conf"
cp -p "$e328d/badpair-allowlist" "$badpair_al"
badpair_conf_sum="$(sha256sum "$badpair_conf" | cut -d' ' -f1)"
badpair_al_sum="$(sha256sum "$badpair_al" | cut -d' ' -f1)"
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/badpair.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"destination pair failed validation"* \
      && "$o" == *"unknown rule kind 'bogus'"* \
      && "$o" == *"fix: edit the source conf $e328d/badpair.conf"* \
      && -f "$badpair_conf" && -f "$badpair_al" \
      && "$(sha256sum "$badpair_conf" | cut -d' ' -f1)" == "$badpair_conf_sum" \
      && "$(sha256sum "$badpair_al" | cut -d' ' -f1)" == "$badpair_al_sum" \
      && -z "$(find "$e328_h/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "identical invalid pair fails validation, both halves untouched (rc=$rc, out: $o)"
fi
rm -f "$badpair_conf" "$badpair_al"

# 3. A differing destination is refused without clobbering (A1).
printf 'profile ci 10.98.9.0/24\n' > "$e328d/site.conf"
printf 'this is the live allowlist\n' > "$e328_h/.config/egresslock/ci-allowlist"
cp -p "$ci_conf" "$e328d/ci.prior"
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"destination conf differs"* \
    && "$o" == *"fix: re-run with --force to replace it (the destination conf must be a regular file), or move the destination conf aside"* ]] \
    && e328 pass || e328 fail "differing conf refused rc 1 (rc=$rc, out: $o)"
cmp -s "$e328d/ci.prior" "$ci_conf" \
    && e328 pass || e328 fail "refused import leaves the dest conf byte-identical"

# 4. Missing source allowlist is A2: refuse before any dest write.
printf 'profile ci 10.98.0.0/24\n    gateway 10.98.0.2 3128 ci-allowlist\n' \
    > "$e328d/site.conf"
e328_h2="$e328d/home/u2"
mv "$e328d/ci-allowlist" "$e328d/ci-allowlist.away"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"allowlist not found"* \
    && ! -e "$e328_h2/.config/egresslock/ci.conf" \
    && ! -e "$e328_h2/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "missing allowlist refuses before dest write (rc=$rc, out: $o)"
mv "$e328d/ci-allowlist.away" "$e328d/ci-allowlist"

# 5. Torn destination: refused by default; --force replaces both halves
#    (never writes only the missing half). Restore the source first.
printf 'profile ci 10.98.0.0/24\n    gateway 10.98.0.2 3128 ci-allowlist\n' \
    > "$e328d/site.conf"
printf '# ci allowlist\n.example.test\n' > "$e328d/ci-allowlist"
e328_h3="$e328d/home/u3"
mkdir -p "$e328_h3/.config/egresslock"
cp "$e328d/site.conf" "$e328_h3/.config/egresslock/ci.conf"
o="$(e328_run "$e328_h3" import --account u3 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"destination pair is torn"* \
    && "$o" == *"fix: re-run with --force to replace the whole pair (both halves must be regular files), or restore the missing half first"* \
    && ! -e "$e328_h3/.config/egresslock/ci-allowlist" ]] \
    && e328 pass || e328 fail "torn destination refused, no half written (rc=$rc, out: $o)"
o="$(e328_run "$e328_h3" import --account u3 --from "$e328d/site.conf" --force 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e328_h3/.config/egresslock/ci-allowlist" \
    && -f "$e328_h3/.config/egresslock/ci.conf" ]] \
    && e328 pass || e328 fail "import --force replaces a torn pair (rc=$rc, out: $o)"

# 6. --force replaces a differing pair (allowlist and conf together).
printf 'profile ci 10.98.3.0/24\n    gateway 10.98.3.2 3128 ci-allowlist\n' \
    > "$e328d/site.conf"
printf '.forced.example.test\n' > "$e328d/ci-allowlist"
o="$(e328_run "$e328_h" import --account u1 --from "$e328d/site.conf" --force 2>&1)"; rc=$?
[[ "$rc" == 0 ]] && e328 pass || e328 fail "import --force replaces a differing pair (rc=$rc, out: $o)"
cmp -s "$e328d/site.conf" "$ci_conf" \
    && cmp -s "$e328d/ci-allowlist" "$e328_h/.config/egresslock/ci-allowlist" \
    && e328 pass || e328 fail "--force installed both source halves byte-identically"

# 6d. EGL-418: the reported repro — a destination allowlist directory
#     holding an operator file is refused rc 1, with and without --force;
#     nothing is moved or deleted, and the printed move-aside command
#     makes the same import succeed with the marker preserved.
e418d="$e328d/e418"
mkdir -p "$e418d"
printf 'profile ci 10.98.30.0/24\n    gateway 10.98.30.2 3128 ci-allowlist\n' \
    > "$e418d/ci.conf"
printf '# e418 source\n.e418.example.test\n' > "$e418d/ci-allowlist"
e418_h40="$e328d/home/e418-u40"
rm -rf "$e418_h40"; mkdir -p "$e418_h40/.config/egresslock/ci-allowlist"
printf 'marker\n' > "$e418_h40/.config/egresslock/ci-allowlist/marker"
e418_dir="$e418_h40/.config/egresslock/ci-allowlist"
e418_q="$(printf '%q' "$e418_dir")"; e418_qbak="$(printf '%q' "$e418_dir.bak")"
for force in "" "--force"; do
    o="$(e328_run "$e418_h40" import --account e418u40 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination allowlist is a directory: $e418_dir"* \
          && "$o" == *"fix: move it aside (only that directory moves; its contents are not deleted), then re-run this import; --force cannot replace it:"* \
          && "$o" == *"         mv -n -T -- $e418_q $e418_qbak"* \
          && "$o" == *"if that name already exists, nothing moves; pick another name."* \
          && -d "$e418_dir" && "$(cat "$e418_dir/marker")" == "marker" \
          && ! -e "$e418_h40/.config/egresslock/ci.conf" \
          && -z "$(find "$e418_h40/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "destination allowlist directory refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
# 6d-occupied. EGL-532-D3: the printed move-aside is non-clobbering — an
#     occupied `.bak` name moves nothing (`-n`), so the source and the
#     occupant both stay.
mkdir -p "$e418_dir.bak"
occ_cmd="$(printf '%s\n' "$o" | sed -n "s/^         \(mv .*\)$/\1/p" | head -n 1)"
eval "$occ_cmd" 2>/dev/null
[[ -d "$e418_dir" && "$(cat "$e418_dir/marker")" == "marker" \
   && -d "$e418_dir.bak" && -z "$(ls -A "$e418_dir.bak")" ]] \
    && e328 pass || e328 fail "occupied .bak: printed mv -n moves nothing (out: $o)"
rmdir "$e418_dir.bak"
fix_cmd="$(printf '%s\n' "$o" | sed -n "s/^         \(mv .*\)$/\1/p" | head -n 1)"
eval "$fix_cmd" 2>/dev/null
[[ -d "$e418_dir.bak" && "$(cat "$e418_dir.bak/marker")" == "marker" ]] \
    && e328 pass || e328 fail "printed move-aside command moves only the directory (out: $o)"
o="$(e328_run "$e418_h40" import --account e418u40 --from "$e418d/ci.conf" 2>&1)"; rc=$?
if [[ "$rc" == 0 && -f "$e418_dir" && ! -L "$e418_dir" \
      && "$(cat "$e418_dir.bak/marker")" == "marker" \
      && -z "$(find "$e418_h40/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
   && cmp -s "$e418d/ci-allowlist" "$e418_dir"; then
    e328 pass
else
    e328 fail "import after the printed move-aside succeeds, marker preserved (rc=$rc, out: $o)"
fi

# 6e. EGL-418: the conf half as a directory is refused the same way with
#     and without --force; both bad halves are named (conf first).
e418_h41="$e328d/home/e418-u41"
rm -rf "$e418_h41"; mkdir -p "$e418_h41/.config/egresslock/ci.conf"
printf 'conf-marker\n' > "$e418_h41/.config/egresslock/ci.conf/marker"
e418_cdir="$e418_h41/.config/egresslock/ci.conf"
for force in "" "--force"; do
    o="$(e328_run "$e418_h41" import --account e418u41 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination conf is a directory: $e418_cdir"* \
          && "$o" == *"--force cannot replace it:"* \
          && -d "$e418_cdir" && "$(cat "$e418_cdir/marker")" == "conf-marker" \
          && -z "$(find "$e418_h41/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "destination conf directory refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h42="$e328d/home/e418-u42"
rm -rf "$e418_h42"; mkdir -p "$e418_h42/.config/egresslock/ci.conf" "$e418_h42/.config/egresslock/ci-allowlist"
printf 'c\n' > "$e418_h42/.config/egresslock/ci.conf/marker"
printf 'a\n' > "$e418_h42/.config/egresslock/ci-allowlist/marker"
o="$(e328_run "$e418_h42" import --account e418u42 --from "$e418d/ci.conf" --force 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"destination conf is a directory: $e418_h42/.config/egresslock/ci.conf"*"destination allowlist is a directory: $e418_h42/.config/egresslock/ci-allowlist"* \
      && -d "$e418_h42/.config/egresslock/ci.conf" \
      && -d "$e418_h42/.config/egresslock/ci-allowlist" \
      && -z "$(find "$e418_h42/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "both non-regular halves named, nothing moved (rc=$rc, out: $o)"
fi

# 6f. EGL-418: a symlink (live target and dangling) and a FIFO are
#     refused by kind, with and without --force; the link target and the
#     FIFO stay untouched. The FIFO legs are bounded so a regression
#     fails instead of hanging.
e418_target="$e328d/e418-target"
printf 'target-bytes\n' > "$e418_target"
e418_h43="$e328d/home/e418-u43"
rm -rf "$e418_h43"; mkdir -p "$e418_h43/.config/egresslock"
ln -s "$e418_target" "$e418_h43/.config/egresslock/ci-allowlist"
for force in "" "--force"; do
    o="$(e328_run "$e418_h43" import --account e418u43 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination allowlist is a symbolic link: $e418_h43/.config/egresslock/ci-allowlist"* \
          && "$o" == *"move the link aside (only the link moves; the file it points to is not touched)"* \
          && -L "$e418_h43/.config/egresslock/ci-allowlist" \
          && "$(cat "$e418_target")" == "target-bytes" \
          && -z "$(find "$e418_h43/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "live symlink destination refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h44="$e328d/home/e418-u44"
rm -rf "$e418_h44"; mkdir -p "$e418_h44/.config/egresslock"
ln -s "$e328d/e418-no-such-target" "$e418_h44/.config/egresslock/ci.conf"
for force in "" "--force"; do
    o="$(e328_run "$e418_h44" import --account e418u44 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination conf is a symbolic link: $e418_h44/.config/egresslock/ci.conf"* \
          && -L "$e418_h44/.config/egresslock/ci.conf" \
          && ! -e "$e418_h44/.config/egresslock/ci.conf" \
          && -z "$(find "$e418_h44/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "dangling symlink destination refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h43b="$e328d/home/e418-u43b"
rm -rf "$e418_h43b"; mkdir -p "$e418_h43b/.config/egresslock"
ln -s "$e418_target" "$e418_h43b/.config/egresslock/ci.conf"
for force in "" "--force"; do
    o="$(e328_run "$e418_h43b" import --account e418u43b --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination conf is a symbolic link: $e418_h43b/.config/egresslock/ci.conf"* \
          && -L "$e418_h43b/.config/egresslock/ci.conf" \
          && "$(cat "$e418_target")" == "target-bytes" \
          && -z "$(find "$e418_h43b/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "live symlink at the conf half refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h44b="$e328d/home/e418-u44b"
rm -rf "$e418_h44b"; mkdir -p "$e418_h44b/.config/egresslock"
ln -s "$e328d/e418-no-such-target" "$e418_h44b/.config/egresslock/ci-allowlist"
for force in "" "--force"; do
    o="$(e328_run "$e418_h44b" import --account e418u44b --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination allowlist is a symbolic link: $e418_h44b/.config/egresslock/ci-allowlist"* \
          && -L "$e418_h44b/.config/egresslock/ci-allowlist" \
          && ! -e "$e418_h44b/.config/egresslock/ci-allowlist" \
          && -z "$(find "$e418_h44b/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "dangling symlink at the allowlist half refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h45="$e328d/home/e418-u45"
rm -rf "$e418_h45"; mkdir -p "$e418_h45/.config/egresslock"
mkfifo "$e418_h45/.config/egresslock/ci.conf"
for force in "" "--force"; do
    o="$(e328_run_bounded "$e418_h45" import --account e418u45 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination conf is not a regular file: $e418_h45/.config/egresslock/ci.conf"* \
          && -p "$e418_h45/.config/egresslock/ci.conf" \
          && -z "$(find "$e418_h45/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "FIFO destination conf refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done
e418_h46="$e328d/home/e418-u46"
rm -rf "$e418_h46"; mkdir -p "$e418_h46/.config/egresslock"
mkfifo "$e418_h46/.config/egresslock/ci-allowlist"
for force in "" "--force"; do
    o="$(e328_run_bounded "$e418_h46" import --account e418u46 --from "$e418d/ci.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 \
          && "$o" == *"refusing: destination allowlist is not a regular file: $e418_h46/.config/egresslock/ci-allowlist"* \
          && -p "$e418_h46/.config/egresslock/ci-allowlist" \
          && -z "$(find "$e418_h46/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "FIFO destination allowlist refused${force:+ with --force} (rc=$rc, out: $o)"
    fi
done

# 6g. EGL-418-D3: the final pre-commit classification sees a destination
#     that appeared (non-forced, S5b) or became non-regular during
#     staging (forced, S5a); staging is removed and the destination is
#     left as the race left it.
e418_real_cp="$(type -P cp)"
e418_h47="$e328d/home/e418-u47"
rm -rf "$e418_h47"; mkdir -p "$e418_h47"
e418_cp_appeared="$e328d/cp-shim-e418-appeared"
mkdir -p "$e418_cp_appeared"
cat > "$e418_cp_appeared/cp" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e418_real_cp" "\$@" || exit \$?
if [[ "\$dst" == *"/.import."*"/ci.conf" ]]; then
    printf 'appeared\n' > "$e418_h47/.config/egresslock/ci-allowlist"
fi
exit 0
EOF
chmod +x "$e418_cp_appeared/cp"
o="$(PATH="$e418_cp_appeared:$PATH" e328_run "$e418_h47" import --account e418u47 --from "$e418d/ci.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"refusing: destination allowlist appeared during the import: $e418_h47/.config/egresslock/ci-allowlist"* \
      && "$o" == *"fix: re-run this import to apply the normal pair rules; nothing from this run was kept"* \
      && "$(cat "$e418_h47/.config/egresslock/ci-allowlist" 2>/dev/null)" == "appeared" \
      && ! -e "$e418_h47/.config/egresslock/ci.conf" \
      && -z "$(find "$e418_h47/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "non-forced import refuses a destination that appeared (rc=$rc, out: $o)"
fi
e418_h48="$e328d/home/e418-u48"
rm -rf "$e418_h48"; mkdir -p "$e418_h48/.config/egresslock"
printf 'prior conf\n' > "$e418_h48/.config/egresslock/ci.conf"
printf 'prior allowlist\n' > "$e418_h48/.config/egresslock/ci-allowlist"
cp -p "$e418_h48/.config/egresslock/ci-allowlist" "$e328d/e418-prior.allowlist"
e418_cp_changed="$e328d/cp-shim-e418-changed"
mkdir -p "$e418_cp_changed"
cat > "$e418_cp_changed/cp" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e418_real_cp" "\$@" || exit \$?
if [[ "\$dst" == *"/.import."*"/ci.conf" ]]; then
    rm -f "$e418_h48/.config/egresslock/ci.conf"
    mkdir "$e418_h48/.config/egresslock/ci.conf"
    printf 'race-dir\n' > "$e418_h48/.config/egresslock/ci.conf/marker"
fi
exit 0
EOF
chmod +x "$e418_cp_changed/cp"
o="$(PATH="$e418_cp_changed:$PATH" e328_run "$e418_h48" import --account e418u48 --from "$e418d/ci.conf" --force 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"refusing: destination conf changed during the import and is now a directory: $e418_h48/.config/egresslock/ci.conf"* \
      && "$o" == *"fix: move it aside (only that path moves), then re-run this import; nothing from this run was kept"* \
      && -d "$e418_h48/.config/egresslock/ci.conf" \
      && "$(cat "$e418_h48/.config/egresslock/ci.conf/marker")" == "race-dir" \
      && -z "$(find "$e418_h48/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
   && cmp -s "$e328d/e418-prior.allowlist" "$e418_h48/.config/egresslock/ci-allowlist"; then
    e328 pass
else
    e328 fail "forced import refuses a half that became non-regular (rc=$rc, out: $o)"
fi

# 6h. EGL-418-D3: a directory that races in between the final check and
#     the install rename is refused by mv -T, not absorbed; the staged
#     file is not left inside it.
e418_h49="$e328d/home/e418-u49"
rm -rf "$e418_h49"; mkdir -p "$e418_h49"
e418_real_mv="$(type -P mv)"
e418_mv_dir="$e328d/mv-shim-e418-commit-dir"
mkdir -p "$e418_mv_dir"
cat > "$e418_mv_dir/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.import."* && "\$dst" == */ci-allowlist ]]; then
    mkdir -p "\$dst"
    printf 'race-dir\n' > "\$dst/marker"
fi
exec "$e418_real_mv" "\$@"
EOF
chmod +x "$e418_mv_dir/mv"
o="$(PATH="$e418_mv_dir:$PATH" e328_run "$e418_h49" import --account e418u49 --from "$e418d/ci.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"could not commit the pair; destination restored"* \
      && -d "$e418_h49/.config/egresslock/ci-allowlist" \
      && "$(cat "$e418_h49/.config/egresslock/ci-allowlist/marker")" == "race-dir" \
      && ! -e "$e418_h49/.config/egresslock/ci-allowlist/ci-allowlist" \
      && ! -e "$e418_h49/.config/egresslock/ci.conf" \
      && -z "$(find "$e418_h49/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "mv -T refuses a directory at commit instead of absorbing it (rc=$rc, out: $o)"
fi

# 6i. EGL-418-D3/S6: cleanup removes only known names. An unexpected file
#     in the stage (or backup) directory is left in place and named; a
#     successful install still returns 0.
e418_h50="$e328d/home/e418-u50"
rm -rf "$e418_h50"; mkdir -p "$e418_h50"
e418_mv_stage="$e328d/mv-shim-e418-leftover-stage"
mkdir -p "$e418_mv_stage"
cat > "$e418_mv_stage/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.import."* && "\$dst" == */ci-allowlist ]]; then
    printf 'unexpected\n' > "\${src%/*}/unexpected"
fi
exec "$e418_real_mv" "\$@"
EOF
chmod +x "$e418_mv_stage/mv"
o="$(PATH="$e418_mv_stage:$PATH" e328_run "$e418_h50" import --account e418u50 --from "$e418d/ci.conf" 2>&1)"; rc=$?
e418_leftover_stage="$(find "$e418_h50/.config/egresslock" -maxdepth 1 -name '.import.*' -print -quit 2>/dev/null)"
if [[ "$rc" == 0 \
      && "$o" == *"leftover not empty: $e418_h50/.config/egresslock/.import."* \
      && "$o" == *"inspect it, then remove it; the destination pair was installed"* \
      && -f "$e418_h50/.config/egresslock/ci.conf" \
      && -f "$e418_h50/.config/egresslock/ci-allowlist" \
      && -n "$e418_leftover_stage" \
      && "$(cat "$e418_leftover_stage/unexpected" 2>/dev/null)" == "unexpected" ]]; then
    e328 pass
else
    e328 fail "non-empty stage is left and named after a successful install (rc=$rc, out: $o)"
fi
rm -rf "$e418_leftover_stage"

e418_h51="$e328d/home/e418-u51"
rm -rf "$e418_h51"; mkdir -p "$e418_h51/.config/egresslock"
printf 'prior conf\n' > "$e418_h51/.config/egresslock/ci.conf"
printf 'prior allowlist\n' > "$e418_h51/.config/egresslock/ci-allowlist"
e418_mv_backup="$e328d/mv-shim-e418-leftover-backup"
mkdir -p "$e418_mv_backup"
cat > "$e418_mv_backup/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e418_real_mv" "\$@"; rc=\$?
if (( rc == 0 )) && [[ "\$dst" == *"/.import-backup."*"/conf" ]]; then
    printf 'unexpected\n' > "\${dst%/*}/unexpected"
fi
exit \$rc
EOF
chmod +x "$e418_mv_backup/mv"
o="$(PATH="$e418_mv_backup:$PATH" e328_run "$e418_h51" import --account e418u51 --from "$e418d/ci.conf" --force 2>&1)"; rc=$?
e418_leftover_backup="$(find "$e418_h51/.config/egresslock" -maxdepth 1 -name '.import-backup.*' -print -quit 2>/dev/null)"
if [[ "$rc" == 0 \
      && "$o" == *"leftover not empty: $e418_h51/.config/egresslock/.import-backup."* \
      && "$o" == *"inspect it, then remove it; the destination pair was installed"* \
      && -n "$e418_leftover_backup" \
      && "$(cat "$e418_leftover_backup/unexpected" 2>/dev/null)" == "unexpected" \
      && ! -e "$e418_leftover_backup/conf" && ! -e "$e418_leftover_backup/allowlist" ]] \
   && cmp -s "$e418d/ci.conf" "$e418_h51/.config/egresslock/ci.conf" \
   && cmp -s "$e418d/ci-allowlist" "$e418_h51/.config/egresslock/ci-allowlist"; then
    e328 pass
else
    e328 fail "non-empty backup is left and named after a successful install (rc=$rc, out: $o)"
fi
rm -rf "$e418_leftover_backup"

# A failed validation path also names a non-empty stage, with the
# destination-unchanged wording, and installs nothing.
e418_bad_src="$e328d/e418bad"
mkdir -p "$e418_bad_src"
printf 'profile e418bad 10.98.31.0/24\n    gateway 10.98.31.2 3128 e418bad-allowlist\n' \
    > "$e418_bad_src/e418bad.conf"
printf '+ .bad.example.test\n' > "$e418_bad_src/e418bad-allowlist"
e418_h52="$e328d/home/e418-u52"
rm -rf "$e418_h52"; mkdir -p "$e418_h52"
e418_cp_fail="$e328d/cp-shim-e418-leftover-fail"
mkdir -p "$e418_cp_fail"
cat > "$e418_cp_fail/cp" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e418_real_cp" "\$@" || exit \$?
if [[ "\$dst" == *"/.import."*"/e418bad.conf" ]]; then
    printf 'unexpected\n' > "\${dst%/*}/unexpected"
fi
exit 0
EOF
chmod +x "$e418_cp_fail/cp"
o="$(PATH="$e418_cp_fail:$PATH" e328_run "$e418_h52" import --account e418u52 --from "$e418_bad_src/e418bad.conf" 2>&1)"; rc=$?
e418_leftover_fail="$(find "$e418_h52/.config/egresslock" -maxdepth 1 -name '.import.*' -print -quit 2>/dev/null)"
if [[ "$rc" == 1 \
      && "$o" == *"staged pair failed validation"* \
      && "$o" == *"leftover not empty: $e418_h52/.config/egresslock/.import."* \
      && "$o" == *"inspect it, then remove it; the destination was not changed"* \
      && ! -e "$e418_h52/.config/egresslock/e418bad.conf" \
      && ! -e "$e418_h52/.config/egresslock/e418bad-allowlist" \
      && -n "$e418_leftover_fail" \
      && "$(cat "$e418_leftover_fail/unexpected" 2>/dev/null)" == "unexpected" ]]; then
    e328 pass
else
    e328 fail "non-empty stage is left and named on validation failure (rc=$rc, out: $o)"
fi
rm -rf "$e418_leftover_fail"

# The harness validation temp home is removed without recursion.
e418_h53="$e328d/home/e418-u53"
rm -rf "$e418_h53"; mkdir -p "$e418_h53" "$e328d/tmp418"
o="$(TMPDIR="$e328d/tmp418" e328_run "$e418_h53" import --account e418u53 --from "$e418d/ci.conf" 2>&1)"; rc=$?
if [[ "$rc" == 0 && -f "$e418_h53/.config/egresslock/ci.conf" \
      && -z "$(find "$e328d/tmp418" -mindepth 1 -print -quit)" ]]; then
    e328 pass
else
    e328 fail "staged-validation temp home is cleaned without recursion (rc=$rc, out: $o)"
fi

# 6b. Commit-failure restore: fail the install-half renames with an mv
#     shim. The prior pair must come back byte-identically and no staging
#     or backup directory may survive; an absent destination must not be
#     left with a torn half. F1/R-EGL-328-3.
rb_src="$e328d/rb.conf"
cat > "$rb_src" <<'EOF'
profile rbci 10.98.4.0/24
    gateway 10.98.4.2 3128 rbci-allowlist
EOF
printf '.new.example.test\n' > "$e328d/rbci-allowlist"
rb_conf="$e328_h/.config/egresslock/rbci.conf"
rb_al="$e328_h/.config/egresslock/rbci-allowlist"
printf 'profile rbci 10.98.5.0/24\n' > "$rb_conf"
printf '# prior\n.prior.example.test\n' > "$rb_al"
rb_conf_sum="$(sha256sum "$rb_conf" | cut -d' ' -f1)"
rb_al_sum="$(sha256sum "$rb_al" | cut -d' ' -f1)"

real_mv="$(type -P mv)"
imp_shim="$e328d/mv-shim-import"
mkdir -p "$imp_shim"
cat > "$imp_shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.import."* && ( "\$dst" == */rbci.conf || "\$dst" == */rbci-allowlist ) ]]; then
    echo "mv-shim: refusing install-half rename" >&2
    exit 1
fi
exec "$real_mv" "\$@"
EOF
chmod +x "$imp_shim/mv"
o="$(PATH="$imp_shim:$PATH" e328_run "$e328_h" import --account u1 --from "$rb_src" --force 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"could not commit the pair; destination restored"* \
    && "$(sha256sum "$rb_conf" | cut -d' ' -f1)" == "$rb_conf_sum" \
    && "$(sha256sum "$rb_al" | cut -d' ' -f1)" == "$rb_al_sum" \
    && -z "$(find "$e328_h/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
    && e328 pass || e328 fail "failed commit restores the prior pair, no leftovers (rc=$rc, out: $o)"

conf_shim="$e328d/mv-shim-import-conf"
order_marker="$e328d/commit-order.marker"
mkdir -p "$conf_shim"
cat > "$conf_shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.import."* && "\$dst" == */rbci.conf ]]; then
    # F1/R-EGL-328-9: witness the commit order at the conf rename. The
    # allowlist must already be installed (byte-identical to the source)
    # or a conf-first commit would leave a live conf with no allowlist
    # after a crash in the window (A2).
    d="\${dst%/*}"
    if [[ -f "\$d/rbci-allowlist" ]] && cmp -s "\$d/rbci-allowlist" "$e328d/rbci-allowlist"; then
        printf 'allowlist-installed-before-conf\n' > "$order_marker"
    else
        printf 'allowlist-missing-or-differs-before-conf\n' > "$order_marker"
    fi
    echo "mv-shim: refusing conf rename" >&2
    exit 1
fi
exec "$real_mv" "\$@"
EOF
chmod +x "$conf_shim/mv"
o="$(PATH="$conf_shim:$PATH" e328_run "$e328_h" import --account u1 --from "$rb_src" --force 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"could not commit the pair; destination restored"* \
    && "$(sha256sum "$rb_conf" | cut -d' ' -f1)" == "$rb_conf_sum" \
    && "$(sha256sum "$rb_al" | cut -d' ' -f1)" == "$rb_al_sum" \
    && -z "$(find "$e328_h/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
    && e328 pass || e328 fail "conf-half failure removes the newly installed allowlist (rc=$rc, out: $o)"

rb_h2="$e328d/home/u13"
mkdir -p "$rb_h2"
o="$(PATH="$imp_shim:$PATH" e328_run "$rb_h2" import --account u13 --from "$rb_src" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"could not commit the pair; destination restored"* \
    && ! -e "$rb_h2/.config/egresslock/rbci.conf" \
    && ! -e "$rb_h2/.config/egresslock/rbci-allowlist" \
    && -z "$(find "$rb_h2/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
    && e328 pass || e328 fail "failed commit into an absent dest leaves no torn pair (rc=$rc, out: $o)"

# The absent-dest case above fails the allowlist rename, so it never
# reaches the new_al rollback. Exercise the same absent dest with the
# conf-only shim: the allowlist installs first, the conf rename fails,
# and the newly-installed allowlist must be removed. F1/R-EGL-328-5.
rb_h4="$e328d/home/u15"
mkdir -p "$rb_h4"
rm -f "$order_marker"
o="$(PATH="$conf_shim:$PATH" e328_run "$rb_h4" import --account u15 --from "$rb_src" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"could not commit the pair; destination restored"* \
    && ! -e "$rb_h4/.config/egresslock/rbci.conf" \
    && ! -e "$rb_h4/.config/egresslock/rbci-allowlist" \
    && -z "$(find "$rb_h4/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]] \
    && e328 pass || e328 fail "failed conf rename into an absent dest removes the installed allowlist (rc=$rc, out: $o)"
# F1/R-EGL-328-9: the same run's shim also witnesses the commit order.
# The allowlist dest must exist, byte-identical to the source, when the
# conf rename is attempted; a conf-first commit leaves it absent there
# (the crash window would be conf-present/allowlist-missing, A2).
[[ "$(cat "$order_marker" 2>/dev/null)" == "allowlist-installed-before-conf" ]] \
    && e328 pass || e328 fail "commit installs the allowlist before the conf (marker: $(cat "$order_marker" 2>/dev/null || echo missing))"

# 6b-rev. Reverse torn destination (stray allowlist, no conf) is refused
#     before any dest write; the stray allowlist is untouched. F2/
#     R-EGL-328-9.
rb_h5="$e328d/home/u16"
mkdir -p "$rb_h5/.config/egresslock"
printf '# stray allowlist\n.stray.example.test\n' > "$rb_h5/.config/egresslock/rbci-allowlist"
cp -p "$rb_h5/.config/egresslock/rbci-allowlist" "$e328d/rbci-allowlist.prior"
o="$(e328_run "$rb_h5" import --account u16 --from "$rb_src" 2>&1)"; rc=$?
[[ "$rc" == 1 \
    && "$o" == *"destination pair is torn: missing $rb_h5/.config/egresslock/rbci.conf, present $rb_h5/.config/egresslock/rbci-allowlist"* \
    && "$o" == *"fix: re-run with --force to replace the whole pair (both halves must be regular files), or move the stray allowlist aside"* \
    && ! -e "$rb_h5/.config/egresslock/rbci.conf" \
    && ! -e "$rb_h5/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "reverse torn destination refused, no conf written (rc=$rc, out: $o)"
cmp -s "$e328d/rbci-allowlist.prior" "$rb_h5/.config/egresslock/rbci-allowlist" \
    && e328 pass || e328 fail "reverse torn refusal leaves the stray allowlist untouched"

# 6c. init --init-conf rename failure: the starter allowlist is created
#     first, then the conf rename fails. EGL-433-D5: the published
#     allowlist is never unlinked (a deny-all starter is reused on
#     re-run); only a temp file may be cleaned up. F1/R-EGL-328-3.
init_shim="$e328d/mv-shim-init"
mkdir -p "$init_shim"
cat > "$init_shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    echo "mv-shim: refusing starter conf rename" >&2
    exit 1
fi
exec "$real_mv" "\$@"
EOF
chmod +x "$init_shim/mv"
force_mv_publish_fallback "$init_shim"
rb_h3="$e328d/home/u14"
mkdir -p "$rb_h3"
o="$(PATH="$init_shim:$PATH" e328_run "$rb_h3" init --account u14 --init-conf 2>&1)"; rc=$?
if [[ "$rc" == 1 \
    && ! -e "$rb_h3/.config/egresslock/main.conf" \
    && -f "$rb_h3/.config/egresslock/main-allowlist" \
    && -z "$(find "$rb_h3/.config/egresslock" -maxdepth 1 \( -name '.main.conf.init.*' -o -name '.main-allowlist.init.*' \) -print -quit)" ]] \
      && cmp -s "$SKITP/examples/main-allowlist" "$rb_h3/.config/egresslock/main-allowlist"; then
    e328 pass
else
    e328 fail "failed init-conf rename leaves the published allowlist in place (rc=$rc, out: $o)"
fi

# 7. Import usage surface: --from required; no --conf/--profile/--init-conf.
o="$(e328_run "$e328_h2" import --account u2 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"import requires --from"* ]] \
    && e328 pass || e328 fail "import missing --from rc 2 (rc=$rc)"
o="$(e328_run "$e328_h2" import --account u2 --conf "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"takes --from, not --conf"* ]] \
    && e328 pass || e328 fail "import --conf rc 2 (rc=$rc, out: $o)"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" --profile ci 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"--profile is a doctor flag only (inspection narrowing)"* \
    && "$o" == *"import names the dest from the source conf's profile line"* ]] \
    && e328 pass || e328 fail "import --profile rc 2 (rc=$rc, out: $o)"
# EGL-333-F4 (R-EGL-333-2): an empty value is the same flag, same refusal.
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" --profile '' 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"--profile is a doctor flag only (inspection narrowing)"* \
    && "$o" == *"import names the dest from the source conf's profile line"* ]] \
    && e328 pass || e328 fail "import --profile '' rc 2 (rc=$rc, out: $o)"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" --init-conf 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"belong to init"* ]] \
    && e328 pass || e328 fail "import --init-conf rc 2 (rc=$rc, out: $o)"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" --enable 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"belong to init"* ]] \
    && e328 pass || e328 fail "import --enable rc 2 (rc=$rc, out: $o)"

# 7b. --allowlist overrides the source sibling; the destination name is
#     still <profile>-allowlist. Source bytes stay untouched.
printf '.override.example.test\n' > "$e328d/ci-override"
cp -p "$e328d/ci-allowlist" "$e328d/ci-allowlist.before-override"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/site.conf" --allowlist "$e328d/ci-override" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e328_h2/.config/egresslock/ci-allowlist" \
    && "$(cat "$e328_h2/.config/egresslock/ci-allowlist")" == ".override.example.test" \
    && "$(cat "$e328d/ci-allowlist")" == "$(cat "$e328d/ci-allowlist.before-override")" ]] \
    && e328 pass || e328 fail "import --allowlist override installs the pair (rc=$rc, out: $o)"

# 7c. EGL-381-D3/R-EGL-381-4 F4: the source gateway line must name
#     exactly <profile>-allowlist; another profile's basename is refused
#     with the named fix (and safe copy guidance) before any dest write
#     (the file exists, so the refusal is the name rule, not a missing
#     source half). A fresh home gets no confdir/staging; a pre-existing
#     destination pair keeps its bytes, with and without --force.
printf 'profile collide 10.98.6.0/24\n    gateway 10.98.6.2 3128 shared-allowlist\n' \
    > "$e328d/collide.conf"
printf '# another profile\n' > "$e328d/shared-allowlist"
rm -rf "$e328d/home/u12"
o="$(e328_run "$e328d/home/u12" import --account u12 --from "$e328d/collide.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"must be 'collide-allowlist'"* \
    && "$o" == *"fix: edit the gateway line in $e328d/collide.conf to name 'collide-allowlist'"* \
    && "$o" == *"copy the entries you intend"* \
    && "$o" == *"do not move or overwrite it"* \
    && ! -e "$e328d/home/u12/.config/egresslock" \
    && -z "$(find "$e328d/home/u12" -name '.import*' -print -quit 2>/dev/null)" ]] \
    && e328 pass || e328 fail "nonconforming source allowlist name refused before any write (rc=$rc, out: $o)"
o="$(e328_run "$e328d/home/u12" import --account u12 --from "$e328d/collide.conf" --force 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"must be 'collide-allowlist'"* \
    && "$o" == *"fix: edit the gateway line in $e328d/collide.conf to name 'collide-allowlist'"* \
    && ! -e "$e328d/home/u12/.config/egresslock" ]] \
    && e328 pass || e328 fail "--force does not bypass the nonconforming source refusal (rc=$rc, out: $o)"
# Pre-existing destination pair: the refusal is before any write, so
# both halves keep their exact pre-run bytes and no staging survives.
e328_h12="$e328d/home/u12b"
rm -rf "$e328_h12"; mkdir -p "$e328_h12/.config/egresslock"
printf 'profile collide 10.98.6.0/24\n' > "$e328_h12/.config/egresslock/collide.conf"
printf '# prior collide\n.prior.example.test\n' > "$e328_h12/.config/egresslock/collide-allowlist"
cp -p "$e328_h12/.config/egresslock/collide.conf" "$e328d/collide.prior.conf"
cp -p "$e328_h12/.config/egresslock/collide-allowlist" "$e328d/collide.prior.allowlist"
for force in "" "--force"; do
    o="$(e328_run "$e328_h12" import --account u12b --from "$e328d/collide.conf" $force 2>&1)"; rc=$?
    if [[ "$rc" == 1 && "$o" == *"must be 'collide-allowlist'"* \
          && "$o" == *"fix: edit the gateway line in $e328d/collide.conf to name 'collide-allowlist'"* ]] \
       && cmp -s "$e328d/collide.prior.conf" "$e328_h12/.config/egresslock/collide.conf" \
       && cmp -s "$e328d/collide.prior.allowlist" "$e328_h12/.config/egresslock/collide-allowlist" \
       && [[ -z "$(find "$e328_h12/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
        e328 pass
    else
        e328 fail "nonconforming refusal preserves prior dest bytes${force:+ with --force} (rc=$rc, out: $o)"
    fi
done

# 7d. --allowlist with a conf that has no gateway line is refused.
o="$(e328_run "$e328d/home/u12" import --account u12 --from "$e328d/nogw.conf" --allowlist "$e328d/ci-override" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"no gateway line"* \
    && ! -e "$e328d/home/u12/.config/egresslock/p2.conf" ]] \
    && e328 pass || e328 fail "--allowlist without gateway refused (rc=$rc, out: $o)"

# 8. EGL-381-D1/D3: an absolute allowlist reference is refused before
#    any dest write (the source file exists, so the refusal is the name
#    rule), and --force does not bypass it.
e328_h4="$e328d/home/u4"
o="$(e328_run "$e328_h4" import --account u4 --from "$e328d/abs.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"must be 'abs-allowlist'"* \
    && "$o" == *"fix: edit the gateway line in $e328d/abs.conf to name 'abs-allowlist'"* \
    && "$o" == *"copy the entries you intend"* \
    && ! -e "$e328_h4/.config/egresslock" ]] \
    && e328 pass || e328 fail "absolute allowlist refused before any write (rc=$rc, out: $o)"
o="$(e328_run "$e328_h4" import --account u4 --from "$e328d/abs.conf" --force 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"must be 'abs-allowlist'"* \
    && "$o" == *"fix: edit the gateway line in $e328d/abs.conf to name 'abs-allowlist'"* \
    && ! -e "$e328_h4/.config/egresslock" ]] \
    && e328 pass || e328 fail "--force does not bypass the absolute allowlist refusal (rc=$rc, out: $o)"
# Pre-existing destination pair keeps its bytes (the name refusal runs
# before the destination is read or staged).
e328_h4b="$e328d/home/u4b"
rm -rf "$e328_h4b"; mkdir -p "$e328_h4b/.config/egresslock"
printf 'profile abs 10.98.2.0/24\n' > "$e328_h4b/.config/egresslock/abs.conf"
printf '# prior abs\n.prior-abs.example.test\n' > "$e328_h4b/.config/egresslock/abs-allowlist"
cp -p "$e328_h4b/.config/egresslock/abs.conf" "$e328d/abs.prior.conf"
cp -p "$e328_h4b/.config/egresslock/abs-allowlist" "$e328d/abs.prior.allowlist"
o="$(e328_run "$e328_h4b" import --account u4b --from "$e328d/abs.conf" --force 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"must be 'abs-allowlist'"* ]] \
   && cmp -s "$e328d/abs.prior.conf" "$e328_h4b/.config/egresslock/abs.conf" \
   && cmp -s "$e328d/abs.prior.allowlist" "$e328_h4b/.config/egresslock/abs-allowlist" \
   && [[ -z "$(find "$e328_h4b/.config/egresslock" -maxdepth 1 -name '.import*' -print -quit)" ]]; then
    e328 pass
else
    e328 fail "absolute refusal preserves prior dest bytes (rc=$rc, out: $o)"
fi

# 8b. R-EGL-381-4 F3: import reads the gateway field the way the engine
#     does (strip a `#` comment, CR, and surrounding whitespace). A
#     conforming inline-comment or CRLF pair must import and validate
#     in place, not be mistaken for a non-pair refusal.
printf 'profile commented 10.98.12.0/24\n    gateway 10.98.12.2 3128 commented-allowlist#pair-half\n' \
    > "$e328d/commented.conf"
printf '# commented\n' > "$e328d/commented-allowlist"
printf 'profile crlf 10.98.13.0/24\r\n    gateway 10.98.13.2 3128 crlf-allowlist\r\n' \
    > "$e328d/crlf.conf"
printf '# crlf\r\n' > "$e328d/crlf-allowlist"
for form in commented crlf; do
    h="$e328d/home/u20$form"
    o="$(e328_run "$h" import --account "u20$form" --from "$e328d/$form.conf" 2>&1)"; rc=$?
    [[ "$rc" == 0 && -f "$h/.config/egresslock/$form.conf" \
        && -f "$h/.config/egresslock/$form-allowlist" ]] \
        && e328 pass || e328 fail "$form source imports (rc=$rc, out: $o)"
done
for form in commented crlf; do
    h="$e328d/home/u21$form"
    mkdir -p "$h/.config/egresslock"
    cp "$e328d/$form.conf" "$h/.config/egresslock/$form.conf"
    cp "$e328d/$form-allowlist" "$h/.config/egresslock/$form-allowlist"
    o="$(e328_run "$h" import --account "u21$form" --from "$h/.config/egresslock/$form.conf" 2>&1)"; rc=$?
    [[ "$rc" == 0 && "$o" == *"source is the destination"* ]] \
        && e328 pass || e328 fail "$form in-place import validates (rc=$rc, out: $o)"
done

# 8c. R-EGL-381-8 F1: recognize a gateway line exactly as the engine
#     does — after stripping a `#` comment, leading [[:space:]] (space,
#     tab, CR, VT, FF) is trimmed before the directive match. Selecting
#     with raw awk fields missed a line whose indentation starts with
#     CR/VT: a conforming pair imported as conf-only success (the old
#     allowlist stayed), and a non-pair reached staged validation and
#     created the destination confdir before its refusal.
for lead in cr vt; do
    case "$lead" in
        cr) lpre=$'\r' ;;
        vt) lpre=$'\v' ;;
    esac
    form="lead$lead"
    printf 'profile %s 10.98.14.0/24\n%s    gateway 10.98.14.2 3128 %s-allowlist\n' \
        "$form" "$lpre" "$form" > "$e328d/$form.conf"
    printf '# %s source\n.%s.example.test\n' "$lead" "$lead" > "$e328d/$form-allowlist"
    # Fresh import: both halves, byte-identical.
    h="$e328d/home/u22$lead"
    o="$(e328_run "$h" import --account "u22$lead" --from "$e328d/$form.conf" 2>&1)"; rc=$?
    if [[ "$rc" == 0 && -f "$h/.config/egresslock/$form.conf" \
          && -f "$h/.config/egresslock/$form-allowlist" ]] \
       && cmp -s "$e328d/$form.conf" "$h/.config/egresslock/$form.conf" \
       && cmp -s "$e328d/$form-allowlist" "$h/.config/egresslock/$form-allowlist"; then
        e328 pass
    else
        e328 fail "$lead-prefixed gateway fresh import installs both halves (rc=$rc, out: $o)"
    fi
    # Forced import over a differing pair: both halves come from the source
    # (a missed gateway line would leave the old allowlist bytes).
    printf '.new-%s.example.test\n' "$lead" > "$e328d/$form-allowlist"
    o="$(e328_run "$h" import --account "u22$lead" --from "$e328d/$form.conf" --force 2>&1)"; rc=$?
    if [[ "$rc" == 0 ]] \
       && cmp -s "$e328d/$form.conf" "$h/.config/egresslock/$form.conf" \
       && cmp -s "$e328d/$form-allowlist" "$h/.config/egresslock/$form-allowlist"; then
        e328 pass
    else
        e328 fail "$lead-prefixed gateway --force imports both source halves (rc=$rc, out: $o)"
    fi
    # In-place torn pair: the gateway line is seen, so the missing half is
    # refused (not an unchanged rc 0 that leaves the torn pair live).
    h2="$e328d/home/u23$lead"
    mkdir -p "$h2/.config/egresslock"
    cp "$e328d/$form.conf" "$h2/.config/egresslock/$form.conf"
    o="$(e328_run "$h2" import --account "u23$lead" --from "$h2/.config/egresslock/$form.conf" 2>&1)"; rc=$?
    [[ "$rc" == 1 && "$o" == *"allowlist not found"* \
        && ! -e "$h2/.config/egresslock/$form-allowlist" ]] \
        && e328 pass || e328 fail "$lead-prefixed gateway in-place torn pair refused (rc=$rc, out: $o)"
    # Non-pair with the same leading whitespace: refused by name before
    # staging or any destination write (no fresh confdir).
    npform="nonpair$lead"
    printf 'profile %s 10.98.15.0/24\n%s    gateway 10.98.15.2 3128 shared-allowlist\n' \
        "$npform" "$lpre" > "$e328d/$npform.conf"
    printf '# shared\n' > "$e328d/shared-allowlist"
    h3="$e328d/home/u24$lead"
    o="$(e328_run "$h3" import --account "u24$lead" --from "$e328d/$npform.conf" 2>&1)"; rc=$?
    if [[ "$rc" == 1 && "$o" == *"must be '$npform-allowlist'"* \
          && "$o" == *"fix: edit the gateway line in $e328d/$npform.conf to name '$npform-allowlist'"* \
          && ! -e "$h3/.config/egresslock" \
          && -z "$(find "$h3" -name '.import*' -print -quit 2>/dev/null)" ]]; then
        e328 pass
    else
        e328 fail "$lead-prefixed non-pair gateway refused before any write (rc=$rc, out: $o)"
    fi
done

# 8d. EGL-375-D8: import/init inherit the engine's strict allowlist-entry
#     validation through the bare `allowlist` probe. An invalid entry is
#     refused before commit and named; the destination is untouched.
printf 'profile inv 10.98.20.0/24\n    gateway 10.98.20.2 3128 inv-allowlist\n' \
    > "$e328d/inv.conf"
printf '# invalid entry\n+ .bad.example.test\n' > "$e328d/inv-allowlist"
inv_bad="invalid allowlist entry '+.bad.example.test'"

# (b) fresh/staged import: rc 1, engine error mapped to the --from source,
#     no destination half and no staging/backup survives.
inv_h="$e328d/home/u30"
o="$(e328_run "$inv_h" import --account u30 --from "$e328d/inv.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"staged pair failed validation as u30:"* \
      && "$o" == *"$inv_bad"* \
      && "$o" == *"fix: edit the source conf $e328d/inv.conf"* \
      && ! -e "$inv_h/.config/egresslock/inv.conf" \
      && ! -e "$inv_h/.config/egresslock/inv-allowlist" \
      && -z "$(find "$inv_h" \( -name '.import*' -o -name '.import-backup.*' \) -print -quit 2>/dev/null)" ]]; then
    e328 pass
else
    e328 fail "invalid-entry staged import refused before commit (rc=$rc, out: $o)"
fi

# (c) identical/live halves still validate: rc 1, destination-pair refusal
#     (not `unchanged`), destination bytes untouched.
inv_h2="$e328d/home/u31"
mkdir -p "$inv_h2/.config/egresslock"
cp "$e328d/inv.conf" "$inv_h2/.config/egresslock/inv.conf"
cp "$e328d/inv-allowlist" "$inv_h2/.config/egresslock/inv-allowlist"
cp -p "$inv_h2/.config/egresslock/inv.conf" "$e328d/inv.prior.conf"
cp -p "$inv_h2/.config/egresslock/inv-allowlist" "$e328d/inv.prior.allowlist"
o="$(e328_run "$inv_h2" import --account u31 --from "$e328d/inv.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"destination pair failed validation: $inv_h2/.config/egresslock/inv.conf"* \
      && "$o" == *"$inv_bad"* && "$o" != *"unchanged"* ]] \
   && cmp -s "$e328d/inv.prior.conf" "$inv_h2/.config/egresslock/inv.conf" \
   && cmp -s "$e328d/inv.prior.allowlist" "$inv_h2/.config/egresslock/inv-allowlist"; then
    e328 pass
else
    e328 fail "invalid identical pair refused as failed validation, dest untouched (rc=$rc, out: $o)"
fi

# (d) files-in-place: the wrapper names the allowlist and relays the
#     engine's entry error (it used to discard stderr); bytes/modes stay.
inv_h3="$e328d/home/u32"
mkdir -p "$inv_h3/.config/egresslock"
cp "$e328d/inv.conf" "$inv_h3/.config/egresslock/inv.conf"
cp "$e328d/inv-allowlist" "$inv_h3/.config/egresslock/inv-allowlist"
cp -p "$inv_h3/.config/egresslock/inv.conf" "$e328d/inv.inplace.conf"
cp -p "$inv_h3/.config/egresslock/inv-allowlist" "$e328d/inv.inplace.allowlist"
inv_modes="$(stat -c '%a %n' "$inv_h3/.config/egresslock/inv.conf" "$inv_h3/.config/egresslock/inv-allowlist")"
o="$(e328_run "$inv_h3" import --account u32 --from "$inv_h3/.config/egresslock/inv.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"allowlist failed validation in place: $inv_h3/.config/egresslock/inv-allowlist"* \
      && "$o" == *"fix: correct the allowlist at $inv_h3/.config/egresslock/inv-allowlist (the --from source is also the destination), then re-run this import; nothing was changed."* \
      && "$o" == *"$inv_bad"* && "$o" != *"unchanged"* \
      && "$(stat -c '%a %n' "$inv_h3/.config/egresslock/inv.conf" "$inv_h3/.config/egresslock/inv-allowlist")" == "$inv_modes" ]] \
   && cmp -s "$e328d/inv.inplace.conf" "$inv_h3/.config/egresslock/inv.conf" \
   && cmp -s "$e328d/inv.inplace.allowlist" "$inv_h3/.config/egresslock/inv-allowlist"; then
    e328 pass
else
    e328 fail "files-in-place refusal relays the engine entry error (rc=$rc, out: $o)"
fi

# (d2) files-in-place: a conf that fails the deployed engine's load is
#      refused in place, the engine line relayed, with the staged
#      sibling's fix naming the in-place file; bytes/modes stay.
inv_h4b="$e328d/home/u40"
mkdir -p "$inv_h4b/.config/egresslock"
printf 'profile invc 10.98.21.0/24\n    bogus-directive yes\n' > "$inv_h4b/.config/egresslock/invc.conf"
cp -p "$inv_h4b/.config/egresslock/invc.conf" "$e328d/invc.inplace.conf"
inv_c_modes="$(stat -c '%a %n' "$inv_h4b/.config/egresslock/invc.conf")"
o="$(e328_run "$inv_h4b" import --account u40 --from "$inv_h4b/.config/egresslock/invc.conf" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"conf failed validation in place: $inv_h4b/.config/egresslock/invc.conf"* \
      && "$o" == *"fix: correct the conf at $inv_h4b/.config/egresslock/invc.conf (the --from source is also the destination), then re-run this import; nothing was changed."* \
      && "$o" != *"unchanged"* \
      && "$(stat -c '%a %n' "$inv_h4b/.config/egresslock/invc.conf")" == "$inv_c_modes" ]] \
   && cmp -s "$e328d/invc.inplace.conf" "$inv_h4b/.config/egresslock/invc.conf"; then
    e328 pass
else
    e328 fail "files-in-place conf refusal carries the fix line (rc=$rc, out: $o)"
fi

# (d3) files-in-place torn pair: the gateway names its sibling allowlist,
#      which is missing; --allowlist supplies a readable stand-in so the
#      in-place torn branch (not the source-pair "allowlist not found"
#      gate) is reached. The fix names the in-place allowlist and the
#      account, advises no --force, and nothing is created.
inv_h4c="$e328d/home/u41"
mkdir -p "$inv_h4c/.config/egresslock"
printf 'profile invt 10.98.22.0/24\n    gateway 10.98.22.2 3128 invt-allowlist\n' \
    > "$inv_h4c/.config/egresslock/invt.conf"
: > "$e328d/invt-standin-allowlist"
o="$(e328_run "$inv_h4c" import --account u41 --from "$inv_h4c/.config/egresslock/invt.conf" \
    --allowlist "$e328d/invt-standin-allowlist" 2>&1)"; rc=$?
if [[ "$rc" == 1 \
      && "$o" == *"destination pair is torn (source --from is the destination)"* \
      && "$o" == *"fix: create the missing allowlist at $inv_h4c/.config/egresslock/invt-allowlist as u41 (an empty file is the valid deny-all starter), then re-run this import; nothing was changed."* \
      && "$o" != *"--force"* \
      && ! -e "$inv_h4c/.config/egresslock/invt-allowlist" ]]; then
    e328 pass
else
    e328 fail "files-in-place torn refusal carries the no-force fix line (rc=$rc, out: $o)"
fi

# (e) init --from: refused at import before any account wiring/timer work.
inv_h4="$e328d/home/u33"
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
o="$(e328_run "$inv_h4" init --account u33 --from "$e328d/inv.conf" --enable 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"$inv_bad"* \
      && ! -e "$inv_h4/.config/egresslock/inv.conf" \
      && ! -e "$inv_h4/.config/egresslock/inv-allowlist" \
      && ! -e "$inv_h4/.config/egresslock/unit.env" \
      && ! -s "$STATE/systemctl.log" ]]; then
    e328 pass
else
    e328 fail "init --from refuses an invalid-entry pair before wiring (rc=$rc, out: $o)"
fi

# (f) --force does not skip the check: a prior pair keeps its bytes and no
#     staging/backup survives.
inv_h5="$e328d/home/u34"
mkdir -p "$inv_h5/.config/egresslock"
printf 'profile inv 10.98.99.0/24\n    gateway 10.98.99.2 3128 inv-allowlist\n' \
    > "$inv_h5/.config/egresslock/inv.conf"
printf '.prior.example.test\n' > "$inv_h5/.config/egresslock/inv-allowlist"
cp -p "$inv_h5/.config/egresslock/inv.conf" "$e328d/inv.force.conf"
cp -p "$inv_h5/.config/egresslock/inv-allowlist" "$e328d/inv.force.allowlist"
o="$(e328_run "$inv_h5" import --account u34 --from "$e328d/inv.conf" --force 2>&1)"; rc=$?
if [[ "$rc" == 1 && "$o" == *"staged pair failed validation as u34:"* \
      && "$o" == *"$inv_bad"* ]] \
   && cmp -s "$e328d/inv.force.conf" "$inv_h5/.config/egresslock/inv.conf" \
   && cmp -s "$e328d/inv.force.allowlist" "$inv_h5/.config/egresslock/inv-allowlist" \
   && [[ -z "$(find "$inv_h5/.config/egresslock" -maxdepth 1 \( -name '.import*' -o -name '.import-backup.*' \) -print -quit)" ]]; then
    e328 pass
else
    e328 fail "--force still refuses an invalid entry, dest untouched (rc=$rc, out: $o)"
fi

# 9. --from already the destination: validate in place, no-op rc 0.
o="$(e328_run "$e328_h" import --account u1 --from "$ci_conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"source is the destination"* ]] \
    && e328 pass || e328 fail "import --from dest validates in place (rc=$rc, out: $o)"

# 10. init --from wires after import; the timer is aggregate and no
#     per-account wiring file is written (EGL-333-D2).
e328_h5="$e328d/home/u5"
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
o="$(e328_run "$e328_h5" init --account u5 --from "$e328d/site.conf" --enable 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e328_h5/.config/egresslock/ci.conf" \
    && ! -e "$e328_h5/.config/egresslock/unit.env" \
    && "$o" == *"the scheduled check will verify every profile whose anchor is running"* ]] \
    && e328 pass || e328 fail "init --from imports, wires aggregate, writes no unit.env (rc=$rc, out: $o)"
assert_kit_lines_paste_safe "setup aggregate line" "$o" '^egresslock-setup: the scheduled check will verify every profile whose anchor is running$'
grep -q "enable --now egresslock-verify@u5.timer" "$STATE/systemctl.log" \
    && e328 pass || e328 fail "init --from --enable arms the timer"

# 11. init --from --profile is rejected by the EGL-333-D9 verb gate
#     (rc 2, no writes) — --profile is doctor's inspection narrowing only.
e328_h6="$e328d/home/u6"
o="$(e328_run "$e328_h6" init --account u6 --from "$e328d/site.conf" --profile nope 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"--profile is a doctor flag only (inspection narrowing); the verify timer checks every profile"* \
    && ! -e "$e328_h6/.config/egresslock/ci.conf" \
    && ! -e "$e328_h6/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "init --from --profile rc 2 at the D9 gate before wiring (rc=$rc, out: $o)"

# 11b. EGL-380: 'all' stays reserved at the setup CLI edge — rc 2 before
#      any account-side read/write. init now rejects --profile earlier
#      (D9), so the reserved edge is exercised through doctor, which still
#      parses the flag.
e328_h12="$e328d/home/u12"
o="$(e328_run "$e328_h12" doctor --account u12 --profile all 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"reserved"* && "$o" == *"teardown all"* \
    && "$o" == *"choose another name"* \
    && ! -e "$e328_h12/.config/egresslock" ]] \
    && e328 pass || e328 fail "doctor --profile all reserved, no writes (rc=$rc, out: $o)"

# 11c. EGL-380: importing a source whose profile line names 'all' is rc 1
#      (the source-check shape) and leaves the destination untouched.
printf 'profile all 10.98.3.0/24\n    gateway 10.98.3.2 3128 all-allowlist\n' \
    > "$e328d/all-src.conf"
printf '# all\n' > "$e328d/all-allowlist"
e328_h13="$e328d/home/u13"
o="$(e328_run "$e328_h13" import --account u13 --from "$e328d/all-src.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"reserved"* && "$o" == *"teardown all"* \
    && "$o" == *"choose another name"* \
    && ! -e "$e328_h13/.config/egresslock/all.conf" \
    && ! -e "$e328_h13/.config/egresslock/all-allowlist" ]] \
    && e328 pass || e328 fail "import of profile all rc 1, no dest pair (rc=$rc, out: $o)"

# 11d. EGL-573/EGL-519-P6: 'v6deny' is reserved at the same setup CLI
#      edge — rc 2 before any account-side read/write, naming the shared
#      IPv6-deny chain it would derive.
e328_h14="$e328d/home/u519d"
o="$(e328_run "$e328_h14" doctor --account u519d --profile v6deny 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"profile name 'v6deny' is reserved"* \
    && "$o" == *"shared IPv6-deny chain 'p_v6deny'"* \
    && "$o" == *"choose another name"* \
    && ! -e "$e328_h14/.config/egresslock" ]] \
    && e328 pass || e328 fail "doctor --profile v6deny reserved, no writes (rc=$rc, out: $o)"

# 11e. EGL-573/EGL-519-P6: importing a source whose profile line names
#      'v6deny' is rc 1 (the source-check shape) and leaves the
#      destination untouched.
printf 'profile v6deny 10.98.4.0/24\n    gateway 10.98.4.2 3128 v6deny-allowlist\n' \
    > "$e328d/v6deny-src.conf"
printf '# v6deny\n' > "$e328d/v6deny-allowlist"
e328_h15="$e328d/home/u519i"
o="$(e328_run "$e328_h15" import --account u519i --from "$e328d/v6deny-src.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"profile name 'v6deny' is reserved"* \
    && "$o" == *"shared IPv6-deny chain 'p_v6deny'"* \
    && "$o" == *"choose another name"* \
    && ! -e "$e328_h15/.config/egresslock/v6deny.conf" \
    && ! -e "$e328_h15/.config/egresslock/v6deny-allowlist" ]] \
    && e328 pass || e328 fail "import of profile v6deny rc 1, no dest pair (rc=$rc, out: $o)"

# 12. Pathless re-arm is aggregate: init writes no wiring file, and
#     importing another profile never creates one (EGL-333-D2/D5).
e328_h7="$e328d/home/u7"
e328_run "$e328_h7" import --account u7 --from "$e328d/site.conf" >/dev/null 2>&1
: > "$STATE/systemctl.log"
e328_run "$e328_h7" init --account u7 --enable >/dev/null 2>&1; rc=$?
[[ "$rc" == 0 && ! -e "$e328_h7/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "pathless init arms the timer and writes no unit.env (rc=$rc)"
grep -q "enable --now egresslock-verify@u7.timer" "$STATE/systemctl.log" \
    && e328 pass || e328 fail "pathless init without --from arms the timer"
e328_run "$e328_h7" import --account u7 --from "$e328d/p2.conf" >/dev/null 2>&1; rc=$?
[[ "$rc" == 0 && ! -e "$e328_h7/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "import of another profile creates no unit.env (A4, rc=$rc)"
e328_run "$e328_h7" init --account u7 --enable >/dev/null 2>&1; rc=$?
[[ "$rc" == 0 && ! -e "$e328_h7/.config/egresslock/unit.env" ]] \
    && e328 pass || e328 fail "re-run init stays aggregate with no unit.env (rc=$rc)"

# 13. Doctor inspects the confdir without unit.env; a missing conf fails
#     rc 1 with the import fix, and no unit.env row exists (EGL-333-D2).
e328_h8="$e328d/home/u8"
e328_run "$e328_h8" import --account u8 --from "$e328d/site.conf" >/dev/null 2>&1
: > "$STATE/systemctl.log"
e328_run "$e328_h8" init --account u8 --enable >/dev/null 2>&1
grep -q "enable --now egresslock-verify@u8.timer" "$STATE/systemctl.log" \
    && e328 pass || e328 fail "pathless init arms the timer without --from"
o="$(e328_run "$e328_h8" doctor --account u8 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"OK: conf parse: ok ($e328_h8/.config/egresslock)"* \
    && "$o" != *"unit.env"* ]] \
    && e328 pass || e328 fail "doctor inspects the confdir with no unit.env row (rc=$rc, out: $o)"
rm -f "$e328_h8/.config/egresslock/ci.conf"
o="$(e328_run "$e328_h8" doctor --account u8 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"PROBLEM: conf parse: FAIL ($e328_h8/.config/egresslock)"* \
    && "$o" == *"import u8 --from"* && "$o" != *"OK: conf parse"* \
    && "$o" != *"unit.env"* ]] \
    && e328 pass || e328 fail "doctor on an emptied confdir names import fix, no unit.env (rc=$rc, out: $o)"

# 14. Doctor on an empty confdir fails closed, naming both writers (never
#     inventing main.conf).
e328_h9="$e328d/home/u9"
mkdir -p "$e328_h9"
o="$(e328_run "$e328_h9" doctor --account u9 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"PROBLEM: conf parse: FAIL ($e328_h9/.config/egresslock)"* \
    && "$o" == *"init u9 --init-conf"* \
    && "$o" == *"import u9 --from"* ]] \
    && e328 pass || e328 fail "empty-confdir doctor names --init-conf/import --from (rc=$rc, out: $o)"

# 14b. A --conf hint selects the profile for inspection but is NOT a
#      named-mode request: doctor's pathless timer fix must not carry
#      --profile even while the hint selects 'ci'.
e328_h11="$e328d/home/u11"
e328_run "$e328_h11" import --account u11 --from "$e328d/site.conf" >/dev/null 2>&1
: > "$STATE/systemctl-timer-off"
o="$(e328_run "$e328_h11" doctor --account u11 --conf "$e328_h11/.config/egresslock/ci.conf" 2>&1)"; rc=$?
rm -f "$STATE/systemctl-timer-off"
[[ "$rc" == 1 \
    && "$o" == *"OK: conf parse: ok (profile 'ci'"* \
    && "$o" == *"fix: sudo egresslock-setup init u11 --enable"* \
    && "$o" != *"init u11 --profile ci --enable"* ]] \
    && e328 pass || e328 fail "doctor --conf hint does not narrow the fix (rc=$rc, out: $o)"

# 14c. EGL-333-D5: an existing unit.env is inert. A legacy/invalid token
#      neither adds a doctor row nor changes rc or the rest of the output.
o1="$(e328_run "$e328_h11" doctor --account u11 2>&1)"; rc1=$?
printf 'EGRESSLOCK_PROFILE=../evil\nEGRESSLOCK_CONF=/stale/path.conf\n' \
    > "$e328_h11/.config/egresslock/unit.env"
o="$(e328_run "$e328_h11" doctor --account u11 2>&1)"; rc=$?
[[ "$rc" == "$rc1" && "$o" == "$o1" && "$o" != *"unit.env"* \
    && "$o" != *"../evil"* ]] \
    && e328 pass || e328 fail "legacy unit.env is ignored by doctor (rc=$rc/$rc1, out: $o)"
rm -f "$e328_h11/.config/egresslock/unit.env"

# 15. Unreadable source refused before dest write.
chmod 000 "$e328d/p2.conf"
o="$(e328_run "$e328_h2" import --account u2 --from "$e328d/p2.conf" 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"cannot read"* \
    && ! -e "$e328_h2/.config/egresslock/p2.conf" ]] \
    && e328 pass || e328 fail "unreadable source refused (rc=$rc, out: $o)"
chmod 644 "$e328d/p2.conf"

# 16. init --init-conf and --from are mutually exclusive (rc 2, no writes).
e328_h10="$e328d/home/u10"
o="$(e328_run "$e328_h10" init --account u10 --init-conf --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"mutually exclusive"* \
    && ! -e "$e328_h10/.config/egresslock/main.conf" ]] \
    && e328 pass || e328 fail "--init-conf + --from rc 2, no writes (rc=$rc, out: $o)"
# 16b. EGL-329: the retired init alias is a flag-keyed rc 2 refusal; the
#      verb-less bundle takes the same line, and nothing is written.
o="$(e328_run "$e328_h10" --account u10 --conf "$e328d/site.conf" --init-conf 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"init no longer accepts --conf; use init ACCOUNT --from PATH, or import ACCOUNT --from PATH"* \
    && ! -e "$e328_h10/.config/egresslock/main.conf" \
    && ! -e "$e328_h10/.config/egresslock/ci.conf" ]] \
    && e328 pass || e328 fail "flat --conf + --init-conf refusal rc 2, no writes (rc=$rc, out: $o)"

# 16c. EGL-329 fresh pins: init --conf PATH and init --conf '' take the
#      same refusal (the check keys on the flag, not the value), and
#      init --conf PATH --init-conf ships no starter.
e328_h12="$e328d/home/u12"
o="$(e328_run "$e328_h12" init --account u12 --conf "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"init no longer accepts --conf; use init ACCOUNT --from PATH, or import ACCOUNT --from PATH"* \
    && ! -e "$e328_h12/.config/egresslock" ]] \
    && e328 pass || e328 fail "init --conf rc 2 before any write (rc=$rc, out: $o)"
o="$(e328_run "$e328_h12" init --account u12 --conf '' 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"init no longer accepts --conf; use init ACCOUNT --from PATH, or import ACCOUNT --from PATH"* \
    && ! -e "$e328_h12/.config/egresslock" ]] \
    && e328 pass || e328 fail "init --conf '' rc 2 keys on the flag (rc=$rc, out: $o)"
o="$(e328_run "$e328_h12" init --account u12 --conf "$e328d/site.conf" --init-conf 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"init no longer accepts --conf; use init ACCOUNT --from PATH, or import ACCOUNT --from PATH"* \
    && ! -e "$e328_h12/.config/egresslock/main.conf" ]] \
    && e328 pass || e328 fail "init --conf + --init-conf rc 2, no starter (rc=$rc, out: $o)"
o="$(e328_run "$e328_h12" --account u12 --conf "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"init no longer accepts --conf; use init ACCOUNT --from PATH, or import ACCOUNT --from PATH"* \
    && ! -e "$e328_h12/.config/egresslock" ]] \
    && e328 pass || e328 fail "verb-less --conf rc 2 before any write (rc=$rc, out: $o)"
o="$(e328_run "$e328_h12" --account u12 --from "$e328d/site.conf" 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"--from is only valid with init or import"* ]] \
    && e328 pass || e328 fail "verb-less --from stays rc 2 at the from-gate (rc=$rc, out: $o)"

# 17. EGL-408: import's first write creates the confdir leaf 0700 while a
#     missing ~/.config stays at the ambient umask; an existing 0755
#     confdir keeps its mode.
printf 'profile e408 10.98.40.0/24\n    gateway 10.98.40.2 3128 e408-allowlist\n' \
    > "$e328d/e408.conf"
printf '# e408\n' > "$e328d/e408-allowlist"
e408_h="$e328d/home/e408-fresh"
rm -rf "$e408_h"
o="$( ( umask 022; e328_run "$e408_h" import --account e408u --from "$e328d/e408.conf" ) 2>&1 )"; rc=$?
[[ "$rc" == 0 \
      && "$(stat -c %a "$e408_h/.config/egresslock" 2>/dev/null)" == 700 \
      && "$(stat -c %a "$e408_h/.config" 2>/dev/null)" == 755 ]] \
    && e328 pass || e328 fail "import creates a fresh confdir 0700, ~/.config stays 0755 (rc=$rc, out: $o)"
e408_e="$e328d/home/e408-existing"
rm -rf "$e408_e"; mkdir -p "$e408_e/.config/egresslock"
chmod 755 "$e408_e/.config/egresslock"
o="$( ( umask 022; e328_run "$e408_e" import --account e408u --from "$e328d/e408.conf" ) 2>&1 )"; rc=$?
[[ "$rc" == 0 \
      && "$(stat -c %a "$e408_e/.config/egresslock")" == 755 ]] \
    && e328 pass || e328 fail "import leaves an existing 0755 confdir unchanged (rc=$rc, out: $o)"

section_end egl328

# --- EGL-51: user manager before the account-side gateway build ------------
section_begin egl51 "EGL-51 user manager before build"
e51() { assert "$@"; }
e51d="$STATE/e51"
rm -rf "$e51d"; mkdir -p "$e51d/home/gacct/.config/egresslock"
printf 'profile p1 10.99.3.0/24\n    gateway 10.99.3.2 3128 p1-allowlist\n' > "$e51d/site.conf"
printf '# starter\n' > "$e51d/p1-allowlist"
printf 'profile p2 10.99.4.0/24\n' > "$e51d/plain.conf"
e51uid="$(id -u)"   # hook mode: the invoking process IS the account

# 1. --enable + gateway conf: linger BEFORE user@ start BEFORE the build;
#    the timer enable still happens; linger is not repeated (D2).
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
rm -f "$STATE/callorder.log" "$STATE/buildlog"
s_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e51d/home/gacct" \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e51a \
    $SKIT init --prefix "$SKITP" --account gacct --from "$e51d/site.conf" --enable 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 ]] && e51 pass || e51 fail "--enable gateway run (rc=$s_rc, out: $s_out)"
grep -q "loginctl enable-linger gacct" "$STATE/callorder.log" \
    && e51 pass || e51 fail "linger enabled during the same run (EGL-51-D2)"
grep -q "systemctl start user@$e51uid.service" "$STATE/callorder.log" \
    && e51 pass || e51 fail "user manager started for the account uid (EGL-51-D1)"
linger_i="$(grep -n 'loginctl enable-linger' "$STATE/callorder.log" | head -1 | cut -d: -f1)"
um_i="$(grep -n 'systemctl start user@' "$STATE/callorder.log" | head -1 | cut -d: -f1)"
build_i="$(grep -n 'podman build' "$STATE/callorder.log" | head -1 | cut -d: -f1)"
[[ -n "$linger_i" && -n "$um_i" && -n "$build_i" && "$linger_i" -lt "$um_i" && "$um_i" -lt "$build_i" ]] \
    && e51 pass || e51 fail "order linger < user@ start < podman build (got $linger_i/$um_i/$build_i)"
[[ "$(grep -c 'enable-linger' "$STATE/callorder.log")" == 1 ]] \
    && e51 pass || e51 fail "linger not repeated (EGL-51-D2)"
grep -q "enable --now egresslock-verify@gacct.timer" "$STATE/systemctl.log" \
    && e51 pass || e51 fail "--enable still arms the verify timer"

# EGL-52: the first-run build carries docker format too — one artifact
# shape across the three gateway-build surfaces (mirrors the egl38 pin;
# the WARN is gone because HEALTHCHECK becomes honored).
grep -q "build -t localhost/egresslock-gateway:e51a --format docker -f $SKITP/gateway/Containerfile $SKITP/gateway" "$STATE/buildlog" \
    && e51 pass || e51 fail "first-run build uses --format docker (EGL-52)"

# 2. No --enable + gateway conf: no loginctl at all (ARC-28-D3), the
#    user@ start still precedes the build, and the ARC-70-D2 skip hint
#    is still printed at the end.
: > "$STATE/loginctl.log"; rm -f "$STATE/callorder.log" "$STATE/buildlog"
s_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e51d/home/gacct" \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e51b \
    $SKIT init --prefix "$SKITP" --account gacct --from "$e51d/site.conf" 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 && ! -s "$STATE/loginctl.log" ]] \
    && e51 pass || e51 fail "no --enable: rc 0, no loginctl (ARC-28-D3; rc=$s_rc, out: $s_out)"
um_i="$(grep -n 'systemctl start user@' "$STATE/callorder.log" | head -1 | cut -d: -f1)"
build_i="$(grep -n 'podman build' "$STATE/callorder.log" | head -1 | cut -d: -f1)"
[[ -n "$um_i" && -n "$build_i" && "$um_i" -lt "$build_i" ]] \
    && e51 pass || e51 fail "user@ start before the build without --enable ($um_i/$build_i)"
[[ "$s_out" == *"timer NOT enabled"* ]] \
    && e51 pass || e51 fail "ARC-70-D2 skip hint still printed"

# 3. Conf with no gateway line is rejected at validation (EGL-366): rc 1
#    with the engine's named cause, and no user@ start happens.
rm -f "$STATE/callorder.log"
e51plain="$e51d/home/plain"
rm -rf "$e51plain"; mkdir -p "$e51plain"
e51ng_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e51plain" \
    $SKIT init --prefix "$SKITP" --account gacct --from "$e51d/plain.conf" 2>&1)"; e51ng_rc=$?
if [[ "$e51ng_rc" == 1 \
      && "$e51ng_out" == *"staged pair failed validation"* \
      && "$e51ng_out" == *"profile 'p2' has no 'gateway' directive"* ]] \
   && ! grep -s -q 'start user@' "$STATE/callorder.log"; then
    e51 pass
else
    e51 fail "no-gateway conf rejected named, no user@ start (rc=$e51ng_rc, out: $e51ng_out)"
fi

# 4. user manager not active: fail closed rc 1, stderr names the account,
#    user@ and the fix, and no podman build is attempted.
touch "$STATE/systemctl-usermgr-fails"
: > "$STATE/buildlog"; rm -f "$STATE/callorder.log"
f_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e51d/home/gacct" \
    $SKIT init --prefix "$SKITP" --account gacct --from "$e51d/site.conf" 2>&1)"; f_rc=$?
if [[ "$f_rc" == 1 && "$f_out" == *"no systemd user manager for 'gacct'"* \
      && "$f_out" == *"user@${e51uid}.service inactive"* \
      && "$f_out" == *"systemctl start user@${e51uid}.service"* ]]; then
    e51 pass
else
    e51 fail "usermgr inactive fails closed (rc=$f_rc, out: $f_out)"
fi
[[ ! -s "$STATE/buildlog" ]] \
    && e51 pass || e51 fail "no podman build attempted when user@ is inactive"
rm -f "$STATE/systemctl-usermgr-fails"
# 4b. Same failure with Linger=no: the enable-linger hint line is added.
touch "$STATE/systemctl-usermgr-fails"
f_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e51d/home/gacct" \
    ARCMOCK_LINGER_ANSWER=no \
    $SKIT init --prefix "$SKITP" --account gacct --from "$e51d/site.conf" 2>&1)"; f_rc=$?
if [[ "$f_rc" == 1 && "$f_out" == *"loginctl enable-linger gacct"* \
      && "$f_out" == *"or re-run setup with --enable"* ]]; then
    e51 pass
else
    e51 fail "usermgr failure + Linger=no names the linger fix (rc=$f_rc, out: $f_out)"
fi
rm -f "$STATE/systemctl-usermgr-fails"
section_end egl51

# --- ARC-19: setup-account --init-conf (sshd-style starter conf) ----------
section_begin arc19 "ARC-19 init-conf"
a19() { assert "$@"; }
a19p="$STATE/a19/prefix"        # fresh kit prefix with examples deployed
a19h="$STATE/a19/home/iacct"    # virtual account home
rm -rf "$STATE/a19"; mkdir -p "$a19p" "$a19h"

# 1. install-kit deploys examples/ into the prefix (D3), root-owned files.
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$a19p/wbin" EGRESSLOCK_PATH_SBINDIR="$a19p/wsbin" \
    "$KIT" --prefix "$a19p" >/dev/null 2>&1
[[ -f "$a19p/examples/main.conf" && -f "$a19p/examples/main-allowlist" ]] \
    && a19 pass || a19 fail "install-kit deploys examples/ (main.conf + main-allowlist)"
# The example itself must parse under the deployed engine and list 'main'.
a19_list="$(env ARCMOCK_PASSWD_HOME="$(conf_home_ro "$a19p/examples/main.conf")" \
    "$a19p/egresslock" list 2>&1)"
[[ "$a19_list" == *"main"* ]] \
    && a19 pass || a19 fail "shipped example conf parses and lists 'main'"

# 1b. EGL-408: --init-conf creates a fresh confdir leaf 0700 while a
#     missing ~/.config stays at the ambient umask; an existing 0755
#     confdir keeps its mode.
a408h="$STATE/a19/e408-fresh"
rm -rf "$a408h"
a19_out="$( ( umask 022; env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a408h" \
    $SKIT --prefix "$a19p" --account iacct --init-conf ) 2>&1 )"; a19_rc=$?
[[ "$a19_rc" == 0 \
      && "$(stat -c %a "$a408h/.config/egresslock" 2>/dev/null)" == 700 \
      && "$(stat -c %a "$a408h/.config" 2>/dev/null)" == 755 ]] \
    && a19 pass || a19 fail "--init-conf creates a fresh confdir 0700, ~/.config stays 0755 (rc=$a19_rc, out: $a19_out)"
a408e="$STATE/a19/e408-existing"
rm -rf "$a408e"; mkdir -p "$a408e/.config/egresslock"
chmod 755 "$a408e/.config/egresslock"
a19_out="$( ( umask 022; env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a408e" \
    $SKIT --prefix "$a19p" --account iacct --init-conf ) 2>&1 )"; a19_rc=$?
[[ "$a19_rc" == 0 \
      && "$(stat -c %a "$a408e/.config/egresslock")" == 755 ]] \
    && a19 pass || a19 fail "--init-conf leaves an existing 0755 confdir unchanged (rc=$a19_rc, out: $a19_out)"

# 2. --init-conf alone: writes the README well-known path + the
#    empty sibling allowlist, byte-compatible with the shipped pair.
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT --prefix "$a19p" --account iacct --init-conf 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 ]] && a19 pass || a19 fail "--init-conf run (rc=$a19_rc, out: $a19_out)"
a19_conf="$a19h/.config/egresslock/main.conf"
a19_al="$a19h/.config/egresslock/main-allowlist"
[[ -f "$a19_conf" && -f "$a19_al" ]] \
    && a19 pass || a19 fail "--init-conf creates conf + sibling allowlist"
cmp -s "$a19p/examples/main.conf" "$a19_conf" \
    && a19 pass || a19 fail "--init-conf conf is byte-identical to the shipped example"
cmp -s "$a19p/examples/main-allowlist" "$a19_al" \
    && a19 pass || a19 fail "--init-conf allowlist is byte-identical to the shipped example"
a19_list="$(env ARCMOCK_PASSWD_HOME="$a19h" "$a19p/egresslock" list 2>&1)"
[[ "$a19_list" == *"main"* ]] \
    && a19 pass || a19 fail "init'd conf parses and lists 'main'"
[[ ! -e "$a19h/.config/egresslock/unit.env" ]] \
    && a19 pass || a19 fail "--init-conf writes no unit.env (fixed confdir)"

# 2b. EGL-333-D9: --init-conf no longer accepts --profile (named mode is
#     gone). Both a non-main and `main` name hit the doctor-flag gate and
#     neither writes the starter.
a19f5h="$STATE/a19/f5home"
rm -rf "$a19f5h"; mkdir -p "$a19f5h"
for a19p_named in named main; do
    a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19f5h" \
        $SKIT --prefix "$a19p" --account iacct --init-conf --profile "$a19p_named" 2>&1)"; a19_rc=$?
    [[ "$a19_rc" == 2 \
        && "$a19_out" == *"--profile is a doctor flag only (inspection narrowing); the verify timer checks every profile"* ]] \
        && a19 pass || a19 fail "--init-conf --profile $a19p_named → D9 usage rc 2 (rc=$a19_rc, out: $a19_out)"
    [[ ! -e "$a19f5h/.config/egresslock/main.conf" && ! -e "$a19f5h/.config/egresslock/named.conf" ]] \
        && a19 pass || a19 fail "--init-conf --profile $a19p_named writes nothing"
done
rm -rf "$a19f5h"

# 3. Never overwrites: an existing conf keeps its content. A complete
#    pair re-run stays rc 0 (no refusal); a missing sibling allowlist
#    makes the pair torn and --init-conf REFUSES (EGL-100: rc 1, names
#    present + missing, never heals, never announces ready).
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT --prefix "$a19p" --account iacct --init-conf 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 && "$a19_out" != *"torn conf pair"* ]] \
    && a19 pass || a19 fail "complete pair re-run stays rc 0, no refusal (rc=$a19_rc, out: $a19_out)"
printf 'profile custom 10.198.0.0/24\n' > "$a19_conf"
rm -f "$a19_al"
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT --prefix "$a19p" --account iacct --init-conf 2>&1)"; a19_rc=$?
grep -qx "profile custom 10.198.0.0/24" "$a19_conf" \
    && a19 pass || a19 fail "--init-conf never overwrites an existing conf"
[[ ! -e "$a19_al" ]] \
    && a19 pass || a19 fail "--init-conf on existing conf does NOT create a missing sibling allowlist"
[[ "$a19_rc" == 1 ]] \
    && a19 pass || a19 fail "torn pair refused (rc=$a19_rc, out: $a19_out)"
[[ "$a19_out" == *"torn conf pair"* && "$a19_out" == *"present:"* && "$a19_out" == *"missing:"* ]] \
    && a19 pass || a19 fail "torn refusal names present + missing halves (out: $a19_out)"
[[ "$a19_out" != *"is ready"* ]] \
    && a19 pass || a19 fail "torn run never announces ready (out: $a19_out)"
rm -f "$a19_conf"

# 3b. EGL-433-D5: --init-conf classifies both halves with -L before -e.
#     A dangling link is false for -e, so the old code replaced the link
#     with the starter (link loss) or suggested `touch` on its missing
#     referent. Every dangling half is refused by name (conf first) before
#     any write; a live link or a directory keeps the existing
#     "exists / leave" branch (no write).
e433_init() { # <home>
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$1" \
        $SKIT --prefix "$a19p" --account iacct --init-conf
}
e433_real_cp="$(type -P cp)"
e433_real_mv="$(type -P mv)"
e433_real_ln="$(type -P ln)"
e433_dh="$STATE/a19/e433-dangling-conf"
rm -rf "$e433_dh"; mkdir -p "$e433_dh/.config/egresslock"
ln -s "$e433_dh/missing-conf" "$e433_dh/.config/egresslock/main.conf"
a19_out="$(e433_init "$e433_dh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: refusing: destination conf is a symbolic link to a missing file: $e433_dh/.config/egresslock/main.conf"* \
    && "$a19_out" == *"the starter is written only to a missing path; move the link aside (only the link moves) to a name that does not exist, then re-run:"* \
    && "$a19_out" == *"    mv -n -T -- $e433_dh/.config/egresslock/main.conf $e433_dh/.config/egresslock/main.conf.bak"* \
    && "$a19_out" == *"if that name already exists, nothing moves; pick another name. the conf pair was not changed."* \
    && -L "$e433_dh/.config/egresslock/main.conf" \
    && ! -e "$e433_dh/.config/egresslock/main.conf" \
    && ! -e "$e433_dh/.config/egresslock/main-allowlist" \
    && ! -L "$e433_dh/.config/egresslock/main-allowlist" ]] \
    && a19 pass || a19 fail "dangling init conf link refused by name, link intact (rc=$a19_rc, out: $a19_out)"

e433_alh="$STATE/a19/e433-dangling-al"
rm -rf "$e433_alh"; mkdir -p "$e433_alh/.config/egresslock"
ln -s "$e433_alh/missing-allowlist" "$e433_alh/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_alh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"refusing: destination allowlist is a symbolic link to a missing file: $e433_alh/.config/egresslock/main-allowlist"* \
    && "$a19_out" == *"    mv -n -T -- $e433_alh/.config/egresslock/main-allowlist $e433_alh/.config/egresslock/main-allowlist.bak"* \
    && -L "$e433_alh/.config/egresslock/main-allowlist" \
    && ! -e "$e433_alh/.config/egresslock/main-allowlist" \
    && ! -e "$e433_alh/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "dangling init allowlist link refused, no conf left behind (rc=$a19_rc, out: $a19_out)"

e433_th="$STATE/a19/e433-torn-dangling"
rm -rf "$e433_th"; mkdir -p "$e433_th/.config/egresslock"
printf 'profile custom 10.196.0.0/24\n' > "$e433_th/.config/egresslock/main.conf"
ln -s "$e433_th/missing-allowlist" "$e433_th/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_th" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"refusing: destination allowlist is a symbolic link to a missing file: $e433_th/.config/egresslock/main-allowlist"* \
    && "$a19_out" != *"torn conf pair"* \
    && "$a19_out" != *"touch"* \
    && -L "$e433_th/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_th/.config/egresslock/main.conf")" == "profile custom 10.196.0.0/24" ]] \
    && a19 pass || a19 fail "dangling allowlist in a torn pair refused without the touch hint (rc=$a19_rc, out: $a19_out)"
# Both dangling halves are named, conf first.
e433_bh="$STATE/a19/e433-both-dangling"
rm -rf "$e433_bh"; mkdir -p "$e433_bh/.config/egresslock"
ln -s "$e433_bh/missing-conf" "$e433_bh/.config/egresslock/main.conf"
ln -s "$e433_bh/missing-allowlist" "$e433_bh/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_bh" 2>&1)"; a19_rc=$?
conf_pos="${a19_out%%destination allowlist*}"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"destination conf is a symbolic link to a missing file: $e433_bh/.config/egresslock/main.conf"* \
    && "$a19_out" == *"destination allowlist is a symbolic link to a missing file: $e433_bh/.config/egresslock/main-allowlist"* \
    && "$conf_pos" == *"destination conf is a symbolic link"* \
    && -L "$e433_bh/.config/egresslock/main.conf" \
    && -L "$e433_bh/.config/egresslock/main-allowlist" ]] \
    && a19 pass || a19 fail "both dangling halves named, conf first (rc=$a19_rc, out: $a19_out)"

# Live-link / directory halves keep the existing "exists / leave" branch:
# nothing is written through the link, the link/directory stays.
e433_lh="$STATE/a19/e433-live-conf"
rm -rf "$e433_lh"; mkdir -p "$e433_lh/.config/egresslock"
ln -s "$a19p/examples/main.conf" "$e433_lh/.config/egresslock/main.conf"
: > "$e433_lh/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_lh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 \
    && "$a19_out" == *"conf exists ($e433_lh/.config/egresslock/main.conf); leaving conf and allowlist untouched"* \
    && -L "$e433_lh/.config/egresslock/main.conf" \
    && "$(cat "$e433_lh/.config/egresslock/main.conf")" == "$(cat "$a19p/examples/main.conf")" ]] \
    && a19 pass || a19 fail "live init conf link keeps the exists/leave branch (rc=$a19_rc, out: $a19_out)"
e433_dh2="$STATE/a19/e433-dir-conf"
rm -rf "$e433_dh2"; mkdir -p "$e433_dh2/.config/egresslock/main.conf"
printf 'conf-marker\n' > "$e433_dh2/.config/egresslock/main.conf/marker"
: > "$e433_dh2/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_dh2" 2>&1)"; a19_rc=$?
[[ "$a19_out" == *"conf exists ($e433_dh2/.config/egresslock/main.conf); leaving conf and allowlist untouched"* \
    && -d "$e433_dh2/.config/egresslock/main.conf" \
    && "$(cat "$e433_dh2/.config/egresslock/main.conf/marker")" == "conf-marker" ]] \
    && a19 pass || a19 fail "directory at the init conf path keeps the exists/leave branch (rc=$a19_rc, out: $a19_out)"
e433_lalh="$STATE/a19/e433-live-al"
rm -rf "$e433_lalh"; mkdir -p "$e433_lalh/.config/egresslock"
printf '# live allowlist\n.live.example.test\n' > "$e433_lalh/live-allowlist"
ln -s "$e433_lalh/live-allowlist" "$e433_lalh/.config/egresslock/main-allowlist"
a19_out="$(e433_init "$e433_lalh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 \
    && "$a19_out" == *"wrote starter $e433_lalh/.config/egresslock/main.conf"* \
    && -L "$e433_lalh/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_lalh/live-allowlist")" == $'# live allowlist\n.live.example.test' \
    && -f "$e433_lalh/.config/egresslock/main.conf" \
    && ! -L "$e433_lalh/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "live allowlist link is left in place when the conf is written (rc=$a19_rc, out: $a19_out)"
e433_dalh="$STATE/a19/e433-dir-al"
rm -rf "$e433_dalh"; mkdir -p "$e433_dalh/.config/egresslock/main-allowlist"
printf 'al-marker\n' > "$e433_dalh/.config/egresslock/main-allowlist/marker"
a19_out="$(e433_init "$e433_dalh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"wrote starter $e433_dalh/.config/egresslock/main.conf"* \
    && -d "$e433_dalh/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_dalh/.config/egresslock/main-allowlist/marker")" == "al-marker" \
    && -f "$e433_dalh/.config/egresslock/main.conf" \
    && ! -L "$e433_dalh/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "directory at the init allowlist path is left in place (conf written, validation fails) (rc=$a19_rc, out: $a19_out)"

# Positive control: an empty home still writes a regular 0600 pair.
e433_okh="$STATE/a19/e433-empty-home"
rm -rf "$e433_okh"; mkdir -p "$e433_okh"
a19_out="$(e433_init "$e433_okh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 \
    && -f "$e433_okh/.config/egresslock/main.conf" \
    && -f "$e433_okh/.config/egresslock/main-allowlist" \
    && ! -L "$e433_okh/.config/egresslock/main.conf" \
    && ! -L "$e433_okh/.config/egresslock/main-allowlist" \
    && "$(stat -c %a "$e433_okh/.config/egresslock/main.conf")" == 600 \
    && "$(stat -c %a "$e433_okh/.config/egresslock/main-allowlist")" == 600 ]] \
    && a19 pass || a19 fail "empty home still writes a regular 0600 starter pair (rc=$a19_rc, out: $a19_out)"

# 3c. EGL-433-D5: mv -T at both starter renames. A directory that races in
#     at the conf path during the rename is refused, not absorbed; the
#     published allowlist stays (never unlinked) and no temp file survives.
e433_mvshim="$STATE/a19/e433-mv-conf-dir"
rm -rf "$e433_mvshim"; mkdir -p "$e433_mvshim"
cat > "$e433_mvshim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    mkdir -p "\$dst"
    printf 'race-dir\n' > "\$dst/marker"
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_mvshim/mv"
force_mv_publish_fallback "$e433_mvshim"
e433_rh="$STATE/a19/e433-race-conf-dir"
rm -rf "$e433_rh"; mkdir -p "$e433_rh"
a19_out="$(PATH="$e433_mvshim:$PATH" e433_init "$e433_rh" 2>&1)"; a19_rc=$?
if [[ "$a19_rc" == 1 \
    && -d "$e433_rh/.config/egresslock/main.conf" \
    && "$(cat "$e433_rh/.config/egresslock/main.conf/marker")" == "race-dir" \
    && ! -e "$e433_rh/.config/egresslock/main.conf/main.conf" \
    && -f "$e433_rh/.config/egresslock/main-allowlist" \
    && -z "$(find "$e433_rh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main-allowlist" "$e433_rh/.config/egresslock/main-allowlist"; then
    a19 pass
else
    a19 fail "mv -T refuses a directory at the conf commit, allowlist left in place (rc=$a19_rc, out: $a19_out)"
fi

# The allowlist rename is -T too: a directory racing in at the allowlist
# path is refused, not entered; the conf is not written.
e433_mval_shim="$STATE/a19/e433-mv-allowlist-dir"
rm -rf "$e433_mval_shim"; mkdir -p "$e433_mval_shim"
cat > "$e433_mval_shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    mkdir -p "\$dst"
    printf 'race-al\n' > "\$dst/marker"
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_mval_shim/mv"
force_mv_publish_fallback "$e433_mval_shim"
e433_rah="$STATE/a19/e433-race-al-dir"
rm -rf "$e433_rah"; mkdir -p "$e433_rah"
a19_out="$(PATH="$e433_mval_shim:$PATH" e433_init "$e433_rah" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && -d "$e433_rah/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_rah/.config/egresslock/main-allowlist/marker")" == "race-al" \
    && ! -e "$e433_rah/.config/egresslock/main.conf" \
    && -z "$(find "$e433_rah/.config/egresslock/main-allowlist" -maxdepth 1 -name '.main-allowlist.init.*' -print -quit)" \
    && -z "$(find "$e433_rah/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "mv -T refuses a directory at the allowlist commit, no conf written (rc=$a19_rc, out: $a19_out)"

# 3d. EGL-433-D5 (defense in depth): the outer classification runs before
#     the account-side script, so a half that appears in between is caught
#     again inside init_conf_script. A dangling conf appearing after the
#     outer check is not replaced; a dangling allowlist appearing there is
#     refused by name before the conf is committed.
e433_cpshim="$STATE/a19/e433-cp-dangling-conf"
rm -rf "$e433_cpshim"; mkdir -p "$e433_cpshim"
cat > "$e433_cpshim/cp" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
dst="\${args[n-1]:-}"
if [[ "\$dst" == *"/.main.conf.init."* ]]; then
    ln -s "$STATE/a19/e433-race-conf-missing" "\$(dirname "\$dst")/main.conf"
fi
exec "$e433_real_cp" "\$@"
EOF
chmod +x "$e433_cpshim/cp"
e433_rch="$STATE/a19/e433-race-conf-link"
rm -rf "$e433_rch"; mkdir -p "$e433_rch"
a19_out="$(PATH="$e433_cpshim:$PATH" e433_init "$e433_rch" 2>&1)"; a19_rc=$?
if [[ "$a19_rc" == 1 \
    && -L "$e433_rch/.config/egresslock/main.conf" \
    && ! -e "$e433_rch/.config/egresslock/main.conf" \
    && -f "$e433_rch/.config/egresslock/main-allowlist" \
    && ! -L "$e433_rch/.config/egresslock/main-allowlist" \
    && -z "$(find "$e433_rch/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main-allowlist" "$e433_rch/.config/egresslock/main-allowlist"; then
    a19 pass
else
    a19 fail "inner guard refuses a conf link that appears after the outer check, allowlist left in place (rc=$a19_rc, out: $a19_out)"
fi

e433_cpalshim="$STATE/a19/e433-cp-dangling-al"
rm -rf "$e433_cpalshim"; mkdir -p "$e433_cpalshim"
cat > "$e433_cpalshim/cp" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
dst="\${args[n-1]:-}"
if [[ "\$dst" == *"/.main.conf.init."* ]]; then
    ln -s "$STATE/a19/e433-race-al-missing" "\$(dirname "\$dst")/main-allowlist"
fi
exec "$e433_real_cp" "\$@"
EOF
chmod +x "$e433_cpalshim/cp"
e433_ralh="$STATE/a19/e433-race-al-link"
rm -rf "$e433_ralh"; mkdir -p "$e433_ralh"
a19_out="$(PATH="$e433_cpalshim:$PATH" e433_init "$e433_ralh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"refusing: destination allowlist is a symbolic link to a missing file: $e433_ralh/.config/egresslock/main-allowlist"* \
    && -L "$e433_ralh/.config/egresslock/main-allowlist" \
    && ! -e "$e433_ralh/.config/egresslock/main-allowlist" \
    && ! -e "$e433_ralh/.config/egresslock/main.conf" \
    && ! -L "$e433_ralh/.config/egresslock/main.conf" \
    && -z "$(find "$e433_ralh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "inner guard refuses an allowlist link that appears after the outer check, no conf committed (rc=$a19_rc, out: $a19_out)"

# 3e. EGL-433-D7/B3: the S4 remedy is non-clobbering. An occupied
#     main.conf.bak survives the printed `mv -n -T --` line (the link
#     stays dangling); once the backup is gone, the same line moves only
#     the link.
e433_b3h="$STATE/a19/e433-bak-occupied"
rm -rf "$e433_b3h"; mkdir -p "$e433_b3h/.config/egresslock"
ln -s "$e433_b3h/.config/egresslock/missing-conf" "$e433_b3h/.config/egresslock/main.conf"
printf 'backup sentinel\n' > "$e433_b3h/.config/egresslock/main.conf.bak"
a19_out="$(e433_init "$e433_b3h" 2>&1)"; a19_rc=$?
e433_b3line="$(printf '%s\n' "$a19_out" | sed -n 's/^    \(mv -n -T -- .*\)$/\1/p' | head -n 1)"
( cd "$e433_b3h" && eval "$e433_b3line" )
[[ "$a19_rc" == 1 && -n "$e433_b3line" \
    && -L "$e433_b3h/.config/egresslock/main.conf" \
    && "$(cat "$e433_b3h/.config/egresslock/main.conf.bak")" == "backup sentinel" \
    && ! -L "$e433_b3h/.config/egresslock/main.conf.bak" ]] \
    && a19 pass || a19 fail "S4 remedy leaves an occupied .bak untouched (rc=$a19_rc, line: $e433_b3line)"
rm -f "$e433_b3h/.config/egresslock/main.conf.bak"
( cd "$e433_b3h" && eval "$e433_b3line" )
[[ -L "$e433_b3h/.config/egresslock/main.conf.bak" \
    && ! -e "$e433_b3h/.config/egresslock/main.conf" \
    && "$(readlink "$e433_b3h/.config/egresslock/main.conf.bak")" == "$e433_b3h/.config/egresslock/missing-conf" ]] \
    && a19 pass || a19 fail "S4 remedy moves only the link when the backup name is free"

# 3f. EGL-433-D7/B4: an apostrophe plus shell metacharacters in the
#     confdir are %q-rendered; executing the captured line in an inert
#     shell creates no canary and still moves only the link.
e433_b4h="$STATE/a19/e433-meta-apos'\$(touch\${IFS}CANARY)"
rm -rf "$e433_b4h"; mkdir -p "$e433_b4h/.config/egresslock"
ln -s "$e433_b4h/.config/egresslock/missing-conf" "$e433_b4h/.config/egresslock/main.conf"
a19_out="$(e433_init "$e433_b4h" 2>&1)"; a19_rc=$?
e433_b4line="$(printf '%s\n' "$a19_out" | sed -n 's/^    \(mv -n -T -- .*\)$/\1/p' | head -n 1)"
e433_b4cwd="$STATE/a19/e433-meta-cwd"; rm -rf "$e433_b4cwd"; mkdir -p "$e433_b4cwd"
( cd "$e433_b4cwd" && eval "$e433_b4line" )
[[ "$a19_rc" == 1 && -n "$e433_b4line" \
    && ! -e "$e433_b4cwd/CANARY" \
    && -L "$e433_b4h/.config/egresslock/main.conf.bak" \
    && ! -e "$e433_b4h/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "S4 %q path with apostrophe/metacharacters is inert when pasted (rc=$a19_rc, line: $e433_b4line)"

# 3g. EGL-433-D5/B2: a sibling initializer that completes the pair after
#     this run publishes the allowlist must not lose that allowlist. A
#     regular conf appears at the conf-rename point: S5 leaves both
#     halves in place, rc 1, one cause line (no generic wrapper).
e433_b2shim="$STATE/a19/e433-mv-sibling"
rm -rf "$e433_b2shim"; mkdir -p "$e433_b2shim"
cat > "$e433_b2shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e433_real_mv" "\$@"; st=\$?
if [[ \$st -eq 0 && "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    printf 'profile main 10.199.0.0/24\n    gateway 10.199.0.2 3128 main-allowlist\n' > "\$(dirname "\$dst")/main.conf"
fi
exit \$st
EOF
chmod +x "$e433_b2shim/mv"
force_mv_publish_fallback "$e433_b2shim"
e433_b2h="$STATE/a19/e433-sibling-pair"
rm -rf "$e433_b2h"; mkdir -p "$e433_b2h"
a19_out="$(PATH="$e433_b2shim:$PATH" e433_init "$e433_b2h" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: refusing: destination conf appeared while the starter pair was being written (another initializer may have completed it): $e433_b2h/.config/egresslock/main.conf"* \
    && "$a19_out" == *"the allowlist at $e433_b2h/.config/egresslock/main-allowlist was left in place and may have been changed or replaced since this run started; inspect it before reusing it:"* \
    && "$a19_out" == *"    cat -- $e433_b2h/.config/egresslock/main-allowlist"* \
    && "$a19_out" == *"    mv -n -T -- $e433_b2h/.config/egresslock/main-allowlist $e433_b2h/.config/egresslock/main-allowlist.bak"* \
    && "$a19_out" == *"if that name already exists, nothing moves; pick another name. re-run --init-conf to check the pair. this run did not write the conf."* \
    && "$a19_out" != *"the starter allowlist was left in place"* \
    && "$a19_out" != *"could not write the starter pair"* \
    && "$(grep -c 'destination conf appeared while the starter pair was being written' <<<"$a19_out")" == 1 \
    && -f "$e433_b2h/.config/egresslock/main.conf" && ! -L "$e433_b2h/.config/egresslock/main.conf" \
    && -f "$e433_b2h/.config/egresslock/main-allowlist" && ! -L "$e433_b2h/.config/egresslock/main-allowlist" \
    && "$(head -n 1 "$e433_b2h/.config/egresslock/main.conf")" == "profile main 10.199.0.0/24" ]] \
    && a19 pass || a19 fail "concurrent initializer (S5) leaves the completed pair intact, one cause line + guidance (rc=$a19_rc, out: $a19_out)"
a19_out="$(e433_init "$e433_b2h" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 \
    && -f "$e433_b2h/.config/egresslock/main.conf" \
    && -f "$e433_b2h/.config/egresslock/main-allowlist" \
    && "$(head -n 1 "$e433_b2h/.config/egresslock/main.conf")" == "profile main 10.199.0.0/24" ]] \
    && a19 pass || a19 fail "re-run after S5 leaves the completed pair and succeeds (rc=$a19_rc, out: $a19_out)"

# 3h. EGL-433-D5: a failed conf rename leaves the allowlist this run
#     published in place (no unlink — a deny-all starter is reused on
#     re-run). No conf is written; the re-run writes only the conf and
#     the pair completes.
e433_failshim="$STATE/a19/e433-mv-conffail"
rm -rf "$e433_failshim"; mkdir -p "$e433_failshim"
cat > "$e433_failshim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    exit 1
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_failshim/mv"
force_mv_publish_fallback "$e433_failshim"
e433_failh="$STATE/a19/e433-conffail"
rm -rf "$e433_failh"; mkdir -p "$e433_failh"
a19_out="$(PATH="$e433_failshim:$PATH" e433_init "$e433_failh" 2>&1)"; a19_rc=$?
if [[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: could not write the starter pair as iacct"* \
    && "$a19_out" == *"the allowlist at $e433_failh/.config/egresslock/main-allowlist was left in place and may have been changed or replaced since this run started; inspect it before reusing it:"* \
    && "$a19_out" == *"    cat -- $e433_failh/.config/egresslock/main-allowlist"* \
    && "$a19_out" == *"    mv -n -T -- $e433_failh/.config/egresslock/main-allowlist $e433_failh/.config/egresslock/main-allowlist.bak"* \
    && "$(grep -c 'could not write the starter pair' <<<"$a19_out")" == 1 \
    && -f "$e433_failh/.config/egresslock/main-allowlist" \
    && ! -L "$e433_failh/.config/egresslock/main-allowlist" \
    && ! -e "$e433_failh/.config/egresslock/main.conf" \
    && -z "$(find "$e433_failh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main-allowlist" "$e433_failh/.config/egresslock/main-allowlist"; then
    a19 pass
else
    a19 fail "failed conf rename leaves the published allowlist in place + guidance (rc=$a19_rc, out: $a19_out)"
fi
a19_out="$(e433_init "$e433_failh" 2>&1)"; a19_rc=$?
if [[ "$a19_rc" == 0 \
    && -f "$e433_failh/.config/egresslock/main.conf" \
    && -z "$(find "$e433_failh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main.conf" "$e433_failh/.config/egresslock/main.conf" \
      && cmp -s "$a19p/examples/main-allowlist" "$e433_failh/.config/egresslock/main-allowlist"; then
    a19 pass
else
    a19 fail "re-run after a failed conf rename writes only the conf (rc=$a19_rc, out: $a19_out)"
fi

# 3i. EGL-433-D5: a concurrent replacement of the allowlist (atomic
#     rename, as a real initializer does) plus a failed conf rename
#     survives: nothing unlinks the path after publish. The old
#     inode-owned rollback could not keep this promise on ext4 reuse.
e433_repshim="$STATE/a19/e433-mv-replace"
rm -rf "$e433_repshim"; mkdir -p "$e433_repshim"
cat > "$e433_repshim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    cfgdir="\$(dirname "\$dst")"
    printf 'foreign replacement\n' > "\$cfgdir/.main-allowlist.other.\$\$"
    "$e433_real_mv" -f -- "\$cfgdir/.main-allowlist.other.\$\$" "\$cfgdir/main-allowlist"
    stat -c '%d:%i' "\$cfgdir/main-allowlist" > "$STATE/a19/e433-replace-inode"
    exit 1
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_repshim/mv"
force_mv_publish_fallback "$e433_repshim"
e433_reph="$STATE/a19/e433-replace"
rm -rf "$e433_reph"; mkdir -p "$e433_reph"
rm -f "$STATE/a19/e433-replace-inode"
a19_out="$(PATH="$e433_repshim:$PATH" e433_init "$e433_reph" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && -f "$e433_reph/.config/egresslock/main-allowlist" \
    && ! -L "$e433_reph/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_reph/.config/egresslock/main-allowlist")" == "foreign replacement" \
    && "$(stat -c '%d:%i' "$e433_reph/.config/egresslock/main-allowlist")" == "$(cat "$STATE/a19/e433-replace-inode" 2>/dev/null)" \
    && ! -e "$e433_reph/.config/egresslock/main.conf" \
    && -z "$(find "$e433_reph/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "atomic allowlist replacement survives a failed conf rename (rc=$a19_rc, out: $a19_out)"

# 3j. EGL-433-D5: the delete+recreate replacement shape also survives,
#     because the product no longer unlinks a published allowlist at all.
#     This leg cannot observe ext4 inode reuse (TESTROOT is tmpfs): it
#     proves the replacement bytes and type survive after the failed conf
#     rename, and records the pre-delete vs replacement identity as
#     evidence only — equal identities on ext4 are not a product signal.
e433_rmshim="$STATE/a19/e433-mv-replace-rm"
rm -rf "$e433_rmshim"; mkdir -p "$e433_rmshim"
cat > "$e433_rmshim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    cfgdir="\$(dirname "\$dst")"
    stat -c '%d:%i' "\$cfgdir/main-allowlist" > "$STATE/a19/e433-rm-published-inode"
    rm -f -- "\$cfgdir/main-allowlist"
    printf 'foreign rm replacement\n' > "\$cfgdir/main-allowlist"
    stat -c '%d:%i' "\$cfgdir/main-allowlist" > "$STATE/a19/e433-rm-inode"
    exit 1
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_rmshim/mv"
force_mv_publish_fallback "$e433_rmshim"
e433_rmh="$STATE/a19/e433-replace-rm"
rm -rf "$e433_rmh"; mkdir -p "$e433_rmh"
rm -f "$STATE/a19/e433-rm-inode" "$STATE/a19/e433-rm-published-inode"
a19_out="$(PATH="$e433_rmshim:$PATH" e433_init "$e433_rmh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 \
    && -f "$e433_rmh/.config/egresslock/main-allowlist" \
    && ! -L "$e433_rmh/.config/egresslock/main-allowlist" \
    && "$(cat "$e433_rmh/.config/egresslock/main-allowlist")" == "foreign rm replacement" \
    && -s "$STATE/a19/e433-rm-published-inode" \
    && -s "$STATE/a19/e433-rm-inode" \
    && ! -e "$e433_rmh/.config/egresslock/main.conf" \
    && -z "$(find "$e433_rmh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "delete+recreate allowlist replacement survives a failed conf rename (rc=$a19_rc, out: $a19_out)"

# 3k. EGL-433-F4: the retained allowlist is described as possibly changed
#     (never as the starter or deny-all), with `cat --` inspect and a
#     non-clobbering `mv -n -T` move-aside. An occupied `.bak` (regular
#     file, directory, dangling symlink, live symlink) survives the printed
#     command; once the name is free, only the allowlist moves.
e433_f4shim="$STATE/a19/e433-f4-s5shim"
rm -rf "$e433_f4shim"; mkdir -p "$e433_f4shim"
cat > "$e433_f4shim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
"$e433_real_mv" "\$@"; st=\$?
if [[ \$st -eq 0 && "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    cfgdir="\$(dirname "\$dst")"
    printf 'allowed.example.test\n' > "\$cfgdir/.f4-other.\$\$"
    "$e433_real_mv" -f -- "\$cfgdir/.f4-other.\$\$" "\$cfgdir/main-allowlist"
    printf 'profile main 10.199.0.0/24\n    gateway 10.199.0.2 3128 main-allowlist\n' > "\$cfgdir/main.conf"
fi
exit \$st
EOF
chmod +x "$e433_f4shim/mv"
force_mv_publish_fallback "$e433_f4shim"
e433_f4h="$STATE/a19/e433-f4-s5"
rm -rf "$e433_f4h"; mkdir -p "$e433_f4h"
a19_out="$(PATH="$e433_f4shim:$PATH" e433_init "$e433_f4h" 2>&1)"; a19_rc=$?
e433_f4_al="$e433_f4h/.config/egresslock/main-allowlist"
e433_f4_bak="$e433_f4_al.bak"
printf -v e433_f4_qal '%q' "$e433_f4_al"
printf -v e433_f4_qbak '%q' "$e433_f4_bak"
e433_f4line="$(printf '%s\n' "$a19_out" | sed -n 's/^    \(mv -n -T -- .*\)$/\1/p' | head -n 1)"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"destination conf appeared while the starter pair was being written"* \
    && "$a19_out" == *"the allowlist at $e433_f4_qal was left in place and may have been changed or replaced since this run started; inspect it before reusing it:"* \
    && "$a19_out" == *"    cat -- $e433_f4_qal"* \
    && "$a19_out" == *"    mv -n -T -- $e433_f4_qal $e433_f4_qbak"* \
    && "$a19_out" != *"the starter allowlist was left in place"* \
    && "$a19_out" != *"deny-all"* \
    && "$(grep -c 'destination conf appeared while the starter pair was being written' <<<"$a19_out")" == 1 \
    && -n "$e433_f4line" \
    && "$(cat "$e433_f4_al")" == "allowed.example.test" \
    && -f "$e433_f4h/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "F4 S5 names the possibly-changed retained allowlist, one cause + guidance (rc=$a19_rc, out: $a19_out)"
printf 'bak sentinel\n' > "$e433_f4_bak"
( cd "$STATE/a19" && eval "$e433_f4line" )
[[ "$(cat "$e433_f4_bak")" == "bak sentinel" \
    && "$(cat "$e433_f4_al")" == "allowed.example.test" ]] \
    && a19 pass || a19 fail "F4 remedy leaves an occupied regular .bak untouched"
rm -f "$e433_f4_bak"; mkdir -p "$e433_f4_bak"; printf 'bak dir\n' > "$e433_f4_bak/marker"
( cd "$STATE/a19" && eval "$e433_f4line" )
[[ -d "$e433_f4_bak" && "$(cat "$e433_f4_bak/marker")" == "bak dir" \
    && "$(cat "$e433_f4_al")" == "allowed.example.test" ]] \
    && a19 pass || a19 fail "F4 remedy leaves an occupied directory .bak untouched"
rm -rf "$e433_f4_bak"; ln -s "$e433_f4h/missing-bak" "$e433_f4_bak"
( cd "$STATE/a19" && eval "$e433_f4line" )
[[ -L "$e433_f4_bak" && ! -e "$e433_f4_bak" \
    && "$(cat "$e433_f4_al")" == "allowed.example.test" ]] \
    && a19 pass || a19 fail "F4 remedy leaves an occupied dangling .bak untouched"
rm -f "$e433_f4_bak"; printf 'live bak\n' > "$e433_f4h/live-bak"
ln -s "$e433_f4h/live-bak" "$e433_f4_bak"
( cd "$STATE/a19" && eval "$e433_f4line" )
[[ -L "$e433_f4_bak" && "$(cat "$e433_f4h/live-bak")" == "live bak" \
    && "$(cat "$e433_f4_al")" == "allowed.example.test" ]] \
    && a19 pass || a19 fail "F4 remedy leaves an occupied live-symlink .bak untouched"
rm -f "$e433_f4_bak"
( cd "$STATE/a19" && eval "$e433_f4line" )
[[ -f "$e433_f4_bak" && ! -L "$e433_f4_bak" \
    && "$(cat "$e433_f4_bak")" == "allowed.example.test" \
    && ! -e "$e433_f4_al" ]] \
    && a19 pass || a19 fail "F4 remedy moves only the allowlist when the backup name is free"

# 3l. EGL-433-F4: the generic failed-conf-write case prints one cause line
#     and the same guidance; a concurrent replacement of the retained
#     allowlist keeps its bytes, and a re-run writes only the conf and
#     keeps that allowlist.
e433_f4gshim="$STATE/a19/e433-f4-failshim"
rm -rf "$e433_f4gshim"; mkdir -p "$e433_f4gshim"
cat > "$e433_f4gshim/mv" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    cfgdir="\$(dirname "\$dst")"
    printf 'allowed.example.test\n' > "\$cfgdir/.f4-other.\$\$"
    "$e433_real_mv" -f -- "\$cfgdir/.f4-other.\$\$" "\$cfgdir/main-allowlist"
    exit 1
fi
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e433_f4gshim/mv"
force_mv_publish_fallback "$e433_f4gshim"
e433_f4gh="$STATE/a19/e433-f4-generic"
rm -rf "$e433_f4gh"; mkdir -p "$e433_f4gh"
a19_out="$(PATH="$e433_f4gshim:$PATH" e433_init "$e433_f4gh" 2>&1)"; a19_rc=$?
e433_f4g_al="$e433_f4gh/.config/egresslock/main-allowlist"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: could not write the starter pair as iacct"* \
    && "$a19_out" == *"the allowlist at $e433_f4g_al was left in place and may have been changed or replaced since this run started; inspect it before reusing it:"* \
    && "$a19_out" == *"    cat -- $e433_f4g_al"* \
    && "$a19_out" == *"    mv -n -T -- $e433_f4g_al $e433_f4g_al.bak"* \
    && "$a19_out" != *"the starter allowlist was left in place"* \
    && "$a19_out" != *"deny-all"* \
    && "$(grep -c 'could not write the starter pair' <<<"$a19_out")" == 1 \
    && "$(cat "$e433_f4g_al")" == "allowed.example.test" \
    && ! -e "$e433_f4gh/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "F4 generic failed-conf-write prints one cause + guidance, allowlist bytes kept (rc=$a19_rc, out: $a19_out)"
a19_out="$(e433_init "$e433_f4gh" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 \
    && -f "$e433_f4gh/.config/egresslock/main.conf" \
    && "$(cat "$e433_f4g_al")" == "allowed.example.test" \
    && -z "$(find "$e433_f4gh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "F4 re-run after a failed conf write keeps the retained allowlist and writes the conf (rc=$a19_rc, out: $a19_out)"

# 3m. EGL-555-D3/P2: H4 publishes with `ln -T` (one link(2), dest is a
#     leaf). A regular allowlist that appears between the outer check and
#     the link is left in place; the conf is published, the pair completes
#     rc 0, and the success line does not claim this run wrote the
#     allowlist. A live link to a regular file is the same shape.
e555_alregshim="$STATE/a19/e555-ln-allowlist-regular"
rm -rf "$e555_alregshim"; mkdir -p "$e555_alregshim"
cat > "$e555_alregshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    printf '# racing allowlist\n.racing.example.test\n' > "\$dst"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_alregshim/ln"
e555_alregh="$STATE/a19/e555-allowlist-regular"
rm -rf "$e555_alregh"; mkdir -p "$e555_alregh"
a19_out="$(PATH="$e555_alregshim:$PATH" e433_init "$e555_alregh" 2>&1)"; a19_rc=$?
e555_alreg_al="$e555_alregh/.config/egresslock/main-allowlist"
e555_alreg_conf="$e555_alregh/.config/egresslock/main.conf"
if [[ "$a19_rc" == 0 \
    && "$a19_out" == *"egresslock-setup: --init-conf: wrote starter $e555_alreg_conf (the allowlist at $e555_alreg_al was already present and was left in place)"* \
    && "$a19_out" != *"wrote starter $e555_alreg_conf (+ "* \
    && "$(cat "$e555_alreg_al")" == $'# racing allowlist\n.racing.example.test' \
    && -f "$e555_alreg_conf" && ! -L "$e555_alreg_conf" \
    && -z "$(find "$e555_alregh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main.conf" "$e555_alreg_conf"; then
    a19 pass
else
    a19 fail "ln EEXIST on a racing regular allowlist completes the pair honestly (rc=$a19_rc, out: $a19_out)"
fi

e555_allnkshim="$STATE/a19/e555-ln-allowlist-live-link"
rm -rf "$e555_allnkshim"; mkdir -p "$e555_allnkshim"
e555_allnktarget="$STATE/a19/e555-allowlist-live-target"
printf '# live allowlist\n.live.example.test\n' > "$e555_allnktarget"
cat > "$e555_allnkshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    ln -s "$e555_allnktarget" "\$dst"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_allnkshim/ln"
e555_allnkh="$STATE/a19/e555-allowlist-live-link"
rm -rf "$e555_allnkh"; mkdir -p "$e555_allnkh"
a19_out="$(PATH="$e555_allnkshim:$PATH" e433_init "$e555_allnkh" 2>&1)"; a19_rc=$?
e555_allnk_al="$e555_allnkh/.config/egresslock/main-allowlist"
e555_allnk_conf="$e555_allnkh/.config/egresslock/main.conf"
if [[ "$a19_rc" == 0 \
    && "$a19_out" == *"egresslock-setup: --init-conf: wrote starter $e555_allnk_conf (the allowlist at $e555_allnk_al was already present and was left in place)"* \
    && "$a19_out" != *"wrote starter $e555_allnk_conf (+ "* \
    && -L "$e555_allnk_al" \
    && "$(cat "$e555_allnktarget")" == $'# live allowlist\n.live.example.test' \
    && -f "$e555_allnk_conf" && ! -L "$e555_allnk_conf" ]]; then
    a19 pass
else
    a19 fail "ln EEXIST on a racing live allowlist link leaves it and completes the pair (rc=$a19_rc, out: $a19_out)"
fi

# 3n. A dangling allowlist that appears at the link keeps S4: name the
#     link, write no conf, leave it intact, no generic wrapper.
e555_aldangshim="$STATE/a19/e555-ln-allowlist-dangling"
rm -rf "$e555_aldangshim"; mkdir -p "$e555_aldangshim"
cat > "$e555_aldangshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    ln -s "$STATE/a19/e555-racing-missing-allowlist" "\$dst"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_aldangshim/ln"
e555_aldangh="$STATE/a19/e555-allowlist-dangling"
rm -rf "$e555_aldangh"; mkdir -p "$e555_aldangh"
a19_out="$(PATH="$e555_aldangshim:$PATH" e433_init "$e555_aldangh" 2>&1)"; a19_rc=$?
e555_aldang_al="$e555_aldangh/.config/egresslock/main-allowlist"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: refusing: destination allowlist is a symbolic link to a missing file: $e555_aldang_al"* \
    && "$a19_out" != *"could not write the starter pair"* \
    && -L "$e555_aldang_al" && ! -e "$e555_aldang_al" \
    && ! -e "$e555_aldangh/.config/egresslock/main.conf" \
    && -z "$(find "$e555_aldangh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "ln EEXIST on a racing dangling allowlist keeps S4, no conf (rc=$a19_rc, out: $a19_out)"

# 3o. A directory, a live directory-symlink, or a special file that
#     appears at the link fails closed with the generic cause (never S4's
#     dangling wording, never a write through the shape).
e555_aldirshim="$STATE/a19/e555-ln-allowlist-dir"
rm -rf "$e555_aldirshim"; mkdir -p "$e555_aldirshim"
cat > "$e555_aldirshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    mkdir -p "\$dst"
    printf 'racing-dir\n' > "\$dst/marker"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_aldirshim/ln"
e555_aldirh="$STATE/a19/e555-allowlist-dir"
rm -rf "$e555_aldirh"; mkdir -p "$e555_aldirh"
a19_out="$(PATH="$e555_aldirshim:$PATH" e433_init "$e555_aldirh" 2>&1)"; a19_rc=$?
e555_aldir_al="$e555_aldirh/.config/egresslock/main-allowlist"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: could not write the starter pair as iacct"* \
    && "$a19_out" != *"symbolic link to a missing file"* \
    && "$(grep -c 'could not write the starter pair' <<<"$a19_out")" == 1 \
    && -d "$e555_aldir_al" \
    && "$(cat "$e555_aldir_al/marker")" == "racing-dir" \
    && ! -e "$e555_aldirh/.config/egresslock/main.conf" \
    && -z "$(find "$e555_aldirh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
    && a19 pass || a19 fail "ln EEXIST on a racing allowlist directory fails closed, not S4 (rc=$a19_rc, out: $a19_out)"

e555_allnkdshim="$STATE/a19/e555-ln-allowlist-dirlink"
rm -rf "$e555_allnkdshim"; mkdir -p "$e555_allnkdshim"
e555_allnkdtarget="$STATE/a19/e555-allowlist-dirlink-target"
rm -rf "$e555_allnkdtarget"; mkdir -p "$e555_allnkdtarget"
cat > "$e555_allnkdshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main-allowlist.init."* && "\$dst" == */main-allowlist ]]; then
    ln -s "$e555_allnkdtarget" "\$dst"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_allnkdshim/ln"
e555_allnkd_h="$STATE/a19/e555-allowlist-dirlink"
rm -rf "$e555_allnkd_h"; mkdir -p "$e555_allnkd_h"
a19_out="$(PATH="$e555_allnkdshim:$PATH" e433_init "$e555_allnkd_h" 2>&1)"; a19_rc=$?
e555_allnkd_al="$e555_allnkd_h/.config/egresslock/main-allowlist"
[[ "$a19_rc" == 1 \
    && "$a19_out" == *"could not write the starter pair as iacct"* \
    && "$a19_out" != *"symbolic link to a missing file"* \
    && -L "$e555_allnkd_al" \
    && -z "$(ls -A "$e555_allnkdtarget")" \
    && ! -e "$e555_allnkd_h/.config/egresslock/main.conf" ]] \
    && a19 pass || a19 fail "ln EEXIST on a racing live allowlist dir-link fails closed, no write-through (rc=$a19_rc, out: $a19_out)"

# 3p. A regular conf that appears at its link keeps S5: one cause line,
#     the allowlist this run published stays byte-identical, the racing
#     conf keeps its bytes, rc 1.
e555_confshim="$STATE/a19/e555-ln-conf-regular"
rm -rf "$e555_confshim"; mkdir -p "$e555_confshim"
cat > "$e555_confshim/ln" <<EOF
#!/usr/bin/env bash
args=("\$@")
n=\${#args[@]}
src="\${args[n-2]:-}"
dst="\${args[n-1]:-}"
if [[ "\$src" == *"/.main.conf.init."* && "\$dst" == */main.conf ]]; then
    printf 'foreign conf\n' > "\$dst"
fi
exec "$e433_real_ln" "\$@"
EOF
chmod +x "$e555_confshim/ln"
e555_confh="$STATE/a19/e555-conf-regular"
rm -rf "$e555_confh"; mkdir -p "$e555_confh"
a19_out="$(PATH="$e555_confshim:$PATH" e433_init "$e555_confh" 2>&1)"; a19_rc=$?
e555_conf_al="$e555_confh/.config/egresslock/main-allowlist"
e555_conf_conf="$e555_confh/.config/egresslock/main.conf"
if [[ "$a19_rc" == 1 \
    && "$a19_out" == *"egresslock-setup: --init-conf: refusing: destination conf appeared while the starter pair was being written (another initializer may have completed it): $e555_conf_conf"* \
    && "$a19_out" != *"could not write the starter pair"* \
    && "$(grep -c 'destination conf appeared while the starter pair was being written' <<<"$a19_out")" == 1 \
    && "$(cat "$e555_conf_conf")" == "foreign conf" \
    && -z "$(find "$e555_confh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main-allowlist" "$e555_conf_al"; then
    a19 pass
else
    a19 fail "ln EEXIST on a racing regular conf keeps S5, allowlist intact (rc=$a19_rc, out: $a19_out)"
fi

# 3q. The documented Q3 fallback: when `ln -T` fails for a non-EEXIST
#     reason (a filesystem without hard links), each half is published
#     with `mv -T` and the normal pair success line is printed.
e555_fbshim="$STATE/a19/e555-ln-fallback"
rm -rf "$e555_fbshim"; mkdir -p "$e555_fbshim"
force_mv_publish_fallback "$e555_fbshim"
e555_fbmark="$STATE/a19/e555-fallback-mv.log"
rm -f "$e555_fbmark"
cat > "$e555_fbshim/mv" <<EOF
#!/usr/bin/env bash
printf '%s\n' "\${@: -1}" >> "$e555_fbmark"
exec "$e433_real_mv" "\$@"
EOF
chmod +x "$e555_fbshim/mv"
e555_fbh="$STATE/a19/e555-fallback"
rm -rf "$e555_fbh"; mkdir -p "$e555_fbh"
a19_out="$(PATH="$e555_fbshim:$PATH" e433_init "$e555_fbh" 2>&1)"; a19_rc=$?
e555_fb_al="$e555_fbh/.config/egresslock/main-allowlist"
e555_fb_conf="$e555_fbh/.config/egresslock/main.conf"
if [[ "$a19_rc" == 0 \
    && "$a19_out" == *"egresslock-setup: --init-conf: wrote starter $e555_fb_conf (+ $e555_fb_al)"* \
    && "$a19_out" != *"was already present"* \
    && "$(grep -c -x -e "$e555_fb_conf" -e "$e555_fb_al" "$e555_fbmark")" == 2 \
    && -z "$(find "$e555_fbh/.config/egresslock" -maxdepth 1 -name '.main-*.init.*' -print -quit)" ]] \
      && cmp -s "$a19p/examples/main.conf" "$e555_fb_conf" \
      && cmp -s "$a19p/examples/main-allowlist" "$e555_fb_al"; then
    a19 pass
else
    a19 fail "non-EEXIST ln falls back to mv -T for both halves (rc=$a19_rc, out: $a19_out)"
fi

# 4. EGL-325: init --from is an install-time copy into the fixed confdir,
#    not a destination selector. The source is installed as
#    <profile>.conf (profile from the source's first `profile` line),
#    0600, and the source path is left untouched; no starter pair is
#    written next to the source.
a19_src="$STATE/a19/custom/site.conf"
mkdir -p "$STATE/a19/custom"
printf 'profile site 10.197.0.0/24\n    gateway 10.197.0.2 3128 site-allowlist\n' > "$a19_src"
printf '# starter\n' > "$STATE/a19/custom/site-allowlist"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT init --prefix "$a19p" --account iacct --from "$a19_src" >/dev/null 2>&1
[[ -f "$a19h/.config/egresslock/site.conf" && -f "$a19_src" ]] \
    && a19 pass || a19 fail "--from installs as <profile>.conf in the fixed confdir"
cmp -s "$a19_src" "$a19h/.config/egresslock/site.conf" \
    && a19 pass || a19 fail "--from install copies the source byte-identically"
[[ "$(stat -c %a "$a19h/.config/egresslock/site.conf" 2>/dev/null)" == "600" ]] \
    && a19 pass || a19 fail "--from install is 0600"
[[ ! -e "$STATE/a19/custom/main-allowlist" ]] \
    && a19 pass || a19 fail "--from install writes no starter pair next to the source"
rm -rf "$STATE/a19/custom"

# 5. Missing examples fail closed with a pointer at install-kit.
a19_nopref="$STATE/a19/noprefix"
mkdir -p "$a19_nopref"
cp "$a19p/egresslock" "$a19_nopref/egresslock"
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT --prefix "$a19_nopref" --account iacct --init-conf 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 && "$a19_out" == *"re-run install-kit.sh"* ]] \
    && a19 pass || a19 fail "missing examples → rc 1, points at install-kit (rc=$a19_rc, out: $a19_out)"

# 6. EGL-328: pathless init wires the on-disk confdir without a path;
#    an explicit missing --from still fails closed before wiring.
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT --prefix "$a19p" --account iacct 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 0 && "$a19_out" == *"1) validate conf … OK"* ]] \
    && a19 pass || a19 fail "pathless init wires an existing confdir (rc=$a19_rc, out: $a19_out)"
a19_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a19h" \
    $SKIT init --prefix "$a19p" --account iacct --from "$STATE/a19/nope.conf" 2>&1)"; a19_rc=$?
[[ "$a19_rc" == 1 && "$a19_out" == *"conf not found"* ]] \
    && a19 pass || a19 fail "missing --from still exits 1 fail-closed (rc=$a19_rc)"

# 7. On-host runuser/CWD finding: runuser inherits the caller's CWD and
#    chdir-fails when the account cannot traverse it (operator checkout
#    under a 0700 home → 'cannot chdir ...: Permission denied'). BOTH
#    root-mode runuser call sites must run from the account's own home.
#    (Static guard: the mock harness runs non-root hook mode and cannot
#    exercise runuser directly.)
[[ "$(grep -c 'cd "\$home" && runuser' "$SKIT")" == 2 ]] \
    && a19 pass || a19 fail "both runuser calls are home-CWD wrapped (on-host chdir finding)"
section_end arc19

# --- EGL-38: run map, --doctor, --build-gateway ------------------------------
section_begin egl38 "EGL-38 run map, doctor, build-gateway"
e38() { assert "$@"; }
e38p="$STATE/e38/prefix"   # fresh deployed kit prefix (engine + gateway + examples)
rm -rf "$STATE/e38"; mkdir -p "$e38p"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e38p/wbin" EGRESSLOCK_PATH_SBINDIR="$e38p/wsbin" \
    "$KIT" --prefix "$e38p" >/dev/null 2>&1
[[ -f "$e38p/egresslock" && -f "$e38p/gateway/Containerfile" && -f "$e38p/examples/main.conf" ]] \
    && e38 pass || e38 fail "e38 fixture: kit deployed to $e38p"
e38h="$STATE/e38/home/uctx"
mkdir -p "$e38h/.config/egresslock"
printf 'profile p1 10.99.5.0/24\n    gateway 10.99.5.2 3128 p1-allowlist\n' > "$STATE/e38/site.conf"
printf '# starter\n' > "$STATE/e38/p1-allowlist"
printf 'profile p2 10.99.6.0/24\n' > "$STATE/e38/plain.conf"
# Run-map extractor: the numbered lines only (D38-6 format).
e38_map() { grep -E '^[0-9]\) .* … (OK|SKIP|FAIL)$' <<<"$1"; }

# 1. Bundle --init-conf without --enable (starter conf has a gateway
#    line): full map in execution order, N from 1, linger/timer SKIP.
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"; : > "$STATE/buildlog"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38a \
    $SKIT --prefix "$e38p" --account uctx --init-conf 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 ]] && e38 pass || e38 fail "--init-conf bundle run (rc=$e38_rc, out: $e38o)"
[[ "$(e38_map "$e38o")" == $'1) validate conf … OK\n2) linger … SKIP\n3) user manager … OK\n4) gateway image … OK\n5) timer … SKIP' ]] \
    && e38 pass || e38 fail "init-conf map order/status (EGL-333-D2: 5 steps): $(e38_map "$e38o" | tr '\n' '|')"
# EGL-200 M1: the init-conf tail ends on the next-step block (starter
# conf first profile 'main').
[[ "$e38o" == *"next steps (as the account):"* \
    && "$e38o" == *"  sudo -iu uctx"* \
    && "$e38o" == *"  egresslock ensure main"* ]] \
    && e38 pass || e38 fail "EGL-200 M1: init-conf block names starter first profile (out: $e38o)"

# 2. Bundle --enable + gateway conf: linger OK < user manager OK <
#    gateway image OK < timer OK (D38-7 execution order).
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"; : > "$STATE/buildlog"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38b \
    $SKIT init --prefix "$e38p" --account uctx --from "$STATE/e38/site.conf" --enable 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 ]] && e38 pass || e38 fail "--enable bundle run (rc=$e38_rc, out: $e38o)"
li="$(grep -n '2) linger … OK' <<<"$e38o" | head -1 | cut -d: -f1)"
ui="$(grep -n '3) user manager … OK' <<<"$e38o" | head -1 | cut -d: -f1)"
gi="$(grep -n '4) gateway image … OK' <<<"$e38o" | head -1 | cut -d: -f1)"
ti="$(grep -n '5) timer … OK' <<<"$e38o" | head -1 | cut -d: -f1)"
[[ -n "$li" && -n "$ui" && -n "$gi" && -n "$ti" && "$li" -lt "$ui" && "$ui" -lt "$gi" && "$gi" -lt "$ti" ]] \
    && e38 pass || e38 fail "enable map order linger<usermgr<image<timer ($li/$ui/$gi/$ti)"

# 2b. FAIL is the last printed numbered step: linger Linger=no with
#     --enable stops the map at 2) linger … FAIL.
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    ARCMOCK_LINGER_ANSWER=no \
    $SKIT init --prefix "$e38p" --account uctx --from "$STATE/e38/site.conf" --enable 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 1 && "$(e38_map "$e38o" | tail -1)" == "2) linger … FAIL" ]] \
    && e38 pass || e38 fail "FAIL is the last numbered step (rc=$e38_rc, map: $(e38_map "$e38o" | tr '\n' '|'))"

# 3. Conf with no gateway line is refused at import validation (EGL-366):
#    rc 1 with the engine's named cause, and no numbered step runs (no
#    linger, no user@, no build).
e38plain="$STATE/e38/home/plain"
rm -rf "$e38plain"; mkdir -p "$e38plain"
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38plain" \
    $SKIT init --prefix "$e38p" --account uctx --from "$STATE/e38/plain.conf" --enable 2>&1)"; e38_rc=$?
if [[ "$e38_rc" == 1 \
      && -z "$(e38_map "$e38o")" \
      && "$e38o" == *"import: staged pair failed validation as uctx:"* \
      && "$e38o" == *"profile 'p2' has no 'gateway' directive"* ]] \
   && ! grep -s -q 'enable-linger' "$STATE/loginctl.log"; then
    e38 pass
else
    e38 fail "no-gateway conf refused at import validation, no step runs (rc=$e38_rc, out: $e38o)"
fi

# 4. --doctor with --account on a fresh home: rc 1 from the missing conf,
#    with the import fix (D38-2); there is no unit.env row to report
#    (EGL-333-D2).
e38h2="$STATE/e38/home/fresh"
mkdir -p "$e38h2"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h2" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account fresh --conf "$STATE/e38/site.conf" --doctor 2>&1)"; e38_rc=$?
if [[ "$e38_rc" == 1 && "$e38o" == *"PROBLEM: conf parse: FAIL (profile 'p1')"* \
      && "$e38o" == *"import fresh --from"* \
      && "$e38o" != *"unit.env"* ]]; then
    e38 pass
else
    e38 fail "doctor: missing conf, no unit.env row (rc=$e38_rc, out: $e38o)"
fi
# Host slice stays clean: engine + templates present.
[[ "$e38o" == *"OK: kit engine: present ($e38p)"* && "$e38o" == *"OK: unit templates: installed ($UNITS)"* ]] \
    && e38 pass || e38 fail "doctor: host slice rows (out: $e38o)"

# 5. --doctor with --account + gateway conf + inactive user manager:
#    rc 1, the fix names `systemctl start user@` (D38-7.2).
touch "$STATE/systemctl-usermgr-fails"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --doctor 2>&1)"; e38_rc=$?
if [[ "$e38_rc" == 1 && "$e38o" == *"PROBLEM: user manager: not active"* \
      && "$e38o" == *"fix: sudo systemctl start user@"* ]]; then
    e38 pass
else
    e38 fail "doctor: inactive user manager (rc=$e38_rc, out: $e38o)"
fi
rm -f "$STATE/systemctl-usermgr-fails"
# Healthy account slice (marker gone): rc 0, image + parse rows ok, and
# no unit.env row (EGL-333-D2). --profile p1 stays as inspection narrowing.
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    $SKIT init --prefix "$e38p" --account uctx --from "$STATE/e38/site.conf" >/dev/null 2>&1
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 && "$e38o" == *"OK: gateway image: present"* \
    && "$e38o" == *"OK: conf parse: ok (profile 'p1'"* \
    && "$e38o" == *"OK: timer: enabled"* && "$e38o" == *"OK: linger: on"* \
    && "$e38o" != *"unit.env"* ]] \
    && e38 pass || e38 fail "doctor: healthy account slice rc 0, no unit.env row (rc=$e38_rc, out: $e38o)"
# EGL-62 uniform-token pin: every non-indented output line of the
# healthy doctor capture carries the `OK:`/`PROBLEM:`/`NOTE:` tokens;
# continuation lines keep the two-space indent. Greps for any line
# matching neither.
printf '%s\n' "$e38o" | grep -qvE '^(OK|PROBLEM|NOTE): |^  ' \
    && e38 fail "doctor: non-token row or unindented continuation in output" \
    || e38 pass
# EGL-456-D6: setup's parse-time gw_img is test-mode only. Flag off -> a
# '-' value is ignored (no die; the account-less doctor is the one
# non-root setup run), flag on -> the flag-shape refusal still fires.
e38o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_GW_IMAGE='-privileged' \
    $SKIT --prefix "$e38p" --doctor 2>&1)"; e38_rc=$?
[[ "$e38_rc" != 2 && "$e38o" != *"must not start with '-'"* ]] \
    && e38 pass || e38 fail "flag-off gw_img is ignored, no die (rc=$e38_rc, out: $e38o)"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_GW_IMAGE='-privileged' \
    $SKIT --prefix "$e38p" --doctor 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 2 && "$e38o" == *"EGRESSLOCK_GW_IMAGE value must not start with '-'"* ]] \
    && e38 pass || e38 fail "flag-on gw_img '-' value still dies (rc=$e38_rc, out: $e38o)"
# EGL-333-D5: a legacy unit.env (with a conf path) is inert — the doctor
# output and rc are byte-identical to the run without it, and no row names
# the retired file.
e38uenv="$e38h/.config/egresslock/unit.env"
e38o_before="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e38_rc_before=$?
printf 'EGRESSLOCK_PROFILE=p1\nEGRESSLOCK_CONF=%s\n' "$e38h/.config/egresslock/p1.conf" > "$e38uenv"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e38_rc=$?
if [[ "$e38_rc" == "$e38_rc_before" && "$e38o" == "$e38o_before" \
      && "$e38o" != *"unit.env"* ]]; then
    e38 pass
else
    e38 fail "doctor: legacy unit.env is ignored (rc=$e38_rc/$e38_rc_before, out: $e38o)"
fi
rm -f "$e38uenv"
# Account-less doctor = host slice only, rc 0; and the EGL-24 pin: NOT
# rc 2 unknown-argument (D38-5). EGL-201: no fixtures -> the M8 NOTE.
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" $SKIT --doctor 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 && "$e38o" != *"unknown argument: --doctor"* && "$e38o" == *"OK: kit engine: present"* \
    && "$e38o" == *"NOTE: no accounts have egresslock-verify services on this host"* ]] \
    && e38 pass || e38 fail "EGL-24 pin: --doctor runs (rc=$e38_rc, out: $e38o)"
# Usage conflicts: --build-gateway x --account, --doctor x --apparmor-add.
e38o="$($SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --build-gateway 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 2 && "$e38o" == *"cannot be combined with --account"* ]] \
    && e38 pass || e38 fail "build-gateway x account is a usage error (rc=$e38_rc)"
e38o="$($SKIT --doctor --apparmor-add 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 2 && "$e38o" == *"cannot be combined"* ]] \
    && e38 pass || e38 fail "doctor x apparmor-add is a usage error (rc=$e38_rc)"

# 6. --build-gateway as non-root builds from the DEPLOYED prefix
#    (not the checkout CWD rules; D38-3). EGL-222: the standalone is now
#    an exec alias of the engine verb, so the build carries the engine's
#    `--format docker` between -t and -f (D5; -t stays first).
: > "$STATE/buildlog"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38c \
    $SKIT --prefix "$e38p" --build-gateway 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 ]] && e38 pass || e38 fail "build-gateway run (rc=$e38_rc, out: $e38o)"
grep -q "build -t localhost/egresslock-gateway:e38c --format docker -f $e38p/gateway/Containerfile $e38p/gateway" "$STATE/buildlog" \
    && e38 pass || e38 fail "build-gateway uses the deployed prefix context ($(cat "$STATE/buildlog"))"
grep -q "$TREE_ROOT/gateway" "$STATE/buildlog" \
    && e38 fail "build-gateway must not use checkout CWD rules" || e38 pass

# 7. --build-gateway when the user manager is inactive: rc 1, stderr
#    names user@, no podman build (D38-7.3; EGL-51 marker reused).
touch "$STATE/systemctl-usermgr-fails"
: > "$STATE/buildlog"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38d \
    $SKIT --prefix "$e38p" --build-gateway 2>&1)"; e38_rc=$?
if [[ "$e38_rc" == 1 && "$e38o" == *"no systemd user manager for"* && "$e38o" == *"user@"* ]]; then
    e38 pass
else
    e38 fail "build-gateway inactive user manager fails closed (rc=$e38_rc, out: $e38o)"
fi
[[ ! -s "$STATE/buildlog" ]] \
    && e38 pass || e38 fail "build-gateway: no podman build when user@ inactive"
rm -f "$STATE/systemctl-usermgr-fails"

# 8. EGL-222-D3/D9: the standalone is an exec ALIAS of the engine verb —
#    on an equal pin the "already built from deployed pin ..." line can
#    only come from `egresslock build-gateway`, and no second build runs.
e38pin="$(grep -oE 'sha256:[0-9a-f]{64}' "$e38p/gateway/Containerfile" | head -1)"
# R-EGL-487-2 F3: a from-now healthy date must not fall below the shipped
# floor when a release-day bump moves it (the up-to-date line would stop
# printing and this alias pin would red on an unrelated delta).
e38floor="$(awk '{ sub(/#.*/, ""); gsub(/[[:space:]]/, ""); if ($0 != "") { print; exit } }' \
    "$e38p/gateway/security-floor" 2>/dev/null || true)"
e38recent="$(date -u -d '2 days ago' '+%Y-%m-%d')"
[[ "$e38recent" < "$e38floor" ]] && e38recent="$e38floor"
printf '%s %sT00:00:00.000000000Z\n' "$e38pin" "$e38recent" \
    > "$STATE/image-inspect-localhost_egresslock-gateway_e38c"
: > "$STATE/buildlog"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38c \
    $SKIT --prefix "$e38p" --build-gateway 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 && "$e38o" == *"already built from deployed pin"* && ! -s "$STATE/buildlog" ]] \
    && e38 pass || e38 fail "build-gateway alias delegates to the engine verb (rc=$e38_rc, out: $e38o)"
# ... and --force forwards through the alias: an equal pin still rebuilds.
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e38c \
    $SKIT --prefix "$e38p" --build-gateway --force 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 0 && -s "$STATE/buildlog" ]] \
    && e38 pass || e38 fail "build-gateway alias forwards --force (rc=$e38_rc, out: $e38o)"
rm -f "$STATE/image-inspect-localhost_egresslock-gateway_e38c"

# 9. R-EGL-222-3 note: the alias with no engine at the prefix fails
#    closed with the remedy named (rc 1, not a bare exec 127).
e38neng="$STATE/e38/noeng"; mkdir -p "$e38neng"
e38o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 $SKIT --prefix "$e38neng" --build-gateway 2>&1)"; e38_rc=$?
[[ "$e38_rc" == 1 && "$e38o" == *"no engine at $e38neng/egresslock"* ]] \
    && e38 pass || e38 fail "alias without an engine fails closed named (rc=$e38_rc, out: $e38o)"
section_end egl38

# --- EGL-409: doctor reports non-0600 policy files --------------------------
# The account slice gains one read-only `PROBLEM: policy file modes` row per
# policy file whose exact mode is not 600 (the same class the engine's allow
# gate refuses), plus the confdir when the other-write bit is set. Missing
# files and the engine records (.pins/.revoke-pending/gateway-build.log) are
# skipped; symlinks are followed; a stat failure is an rc-neutral NOTE; rc 1
# on any PROBLEM. D9: unix modes only — no ACL/xattr tooling.
section_begin egl409 "EGL-409 doctor policy file modes"
e409() { assert "$@"; }
e409d="$STATE/e409"; rm -rf "$e409d"
e409h="$e409d/home/uctx"; e409cd="$e409h/.config/egresslock"
e409p="$e409d/prefix"; e409u="$e409d/units"
mkdir -p "$e409cd" "$e409p"
# Self-contained kit prefix + unit templates (no cross-section fixture
# coupling; a shard may run this section alone).
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e409u" \
    EGRESSLOCK_PATH_BINDIR="$e409p/wbin" EGRESSLOCK_PATH_SBINDIR="$e409p/wsbin" \
    "$KIT" --prefix "$e409p" >/dev/null 2>&1
[[ -f "$e409p/egresslock" && -f "$e409u/egresslock-verify@.service" ]] \
    && e409 pass || e409 fail "e409 fixture: kit deployed to $e409p with unit templates in $e409u"
printf 'profile p1 10.99.9.0/24\n    gateway 10.99.9.2 3128 p1-allowlist\n' > "$e409d/site.conf"
printf 'profile p2 10.99.10.0/24\n    gateway 10.99.10.2 3128 p2-allowlist\n' > "$e409d/site2.conf"
printf '# starter\n' > "$e409d/p1-allowlist"
printf '# starter\n' > "$e409d/p2-allowlist"

# Named fixture: the p1 pair, 0600; the confdir is the supported 0755
# default.
e409_stage() {
    rm -rf "$e409cd"; mkdir -p "$e409cd"; chmod 755 "$e409cd"
    cp "$e409d/site.conf" "$e409cd/p1.conf"
    cp "$e409d/p1-allowlist" "$e409cd/p1-allowlist"
    chmod 600 "$e409cd/p1.conf" "$e409cd/p1-allowlist"
}
# Aggregate fixture: two 0600 pairs.
e409_stage_aggregate() {
    rm -rf "$e409cd"; mkdir -p "$e409cd"; chmod 755 "$e409cd"
    cp "$e409d/site.conf" "$e409cd/p1.conf"
    cp "$e409d/p1-allowlist" "$e409cd/p1-allowlist"
    cp "$e409d/site2.conf" "$e409cd/p2.conf"
    cp "$e409d/p2-allowlist" "$e409cd/p2-allowlist"
    chmod 600 "$e409cd/p1.conf" "$e409cd/p1-allowlist" \
        "$e409cd/p2.conf" "$e409cd/p2-allowlist"
}
e409_run() {
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e409h" \
        EGRESSLOCK_UNIT_DIR="$e409u" \
        $SKIT --prefix "$e409p" --account u409 --doctor "$@" 2>&1
}
e409_modes() { stat -c '%a %n' "$e409cd/p1.conf" "$e409cd/p1-allowlist" "$e409cd" | sort; }

# 1. Healthy named install: one OK row with the checked-file count, rc 0;
#    the supported 0755 confdir is silent.
e409_stage
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 0 \
    && "$e409o" == *"OK: policy file modes: 0600 (2 files) — every checked policy file is owner-only"* \
    && "$e409o" != *"PROBLEM: policy file modes"* ]] \
    && e409 pass || e409 fail "healthy named install: one OK row (2 files), rc 0 (rc=$e409rc, out: $e409o)"

# 2. Legacy 0644 pair: 2 PROBLEM rows naming each path + its mode, each with
#    the account chmod fix, rc 1, no OK row; the run must not chmod anything.
e409_stage
chmod 644 "$e409cd/p1.conf" "$e409cd/p1-allowlist"
e409_before="$(e409_modes)"
e409o="$(e409_run --profile p1)"; e409rc=$?
e409_after="$(e409_modes)"
e409_n="$(printf '%s\n' "$e409o" | grep -c '^PROBLEM: policy file modes: ' || true)"
[[ "$e409rc" == 1 && "$e409_n" == 2 \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd/p1.conf is 644, not 0600 — the account's policy files are owner-only (0600), and proxy allow rewrites only a 0600 allowlist"* \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd/p1-allowlist is 644, not 0600"* \
    && "$e409o" == *"  fix: sudo -u u409 -- chmod 600 -- $e409cd/p1.conf"* \
    && "$e409o" == *"  fix: sudo -u u409 -- chmod 600 -- $e409cd/p1-allowlist"* \
    && "$e409o" != *"OK: policy file modes"* ]] \
    && e409 pass || e409 fail "legacy 0644 pair: 2 PROBLEM rows + fixes, rc 1, no OK (rc=$e409rc, n=$e409_n, out: $e409o)"
[[ "$e409_before" == "$e409_after" ]] \
    && e409 pass || e409 fail "doctor never chmods: modes unchanged (before: $(printf '%s' "$e409_before" | tr '\n' '|'), after: $(printf '%s' "$e409_after" | tr '\n' '|'))"

# 3. Mixed: one 0644 allowlist -> one PROBLEM naming only that file, and no
#    OK row while a PROBLEM stands.
e409_stage
chmod 644 "$e409cd/p1-allowlist"
e409o="$(e409_run --profile p1)"; e409rc=$?
e409_n="$(printf '%s\n' "$e409o" | grep -c '^PROBLEM: policy file modes: ' || true)"
[[ "$e409rc" == 1 && "$e409_n" == 1 \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd/p1-allowlist is 644"* \
    && "$e409o" != *"policy file modes: $e409cd/p1.conf"* \
    && "$e409o" != *"OK: policy file modes"* ]] \
    && e409 pass || e409 fail "mixed pair: only the bad file reports, no OK (rc=$e409rc, n=$e409_n, out: $e409o)"

# 4. Symlinks are followed to the mode that applies: a 0600 target is clean;
#    a 0644 target reports under the symlink path.
e409_stage
mv "$e409cd/p1-allowlist" "$e409d/al-0600"; chmod 600 "$e409d/al-0600"
ln -s "$e409d/al-0600" "$e409cd/p1-allowlist"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes: 0600 (2 files)"* ]] \
    && e409 pass || e409 fail "symlink to a 0600 target is clean (rc=$e409rc, out: $e409o)"
chmod 644 "$e409d/al-0600"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 1 \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd/p1-allowlist is 644"* \
    && "$e409o" != *"OK: policy file modes"* ]] \
    && e409 pass || e409 fail "symlink to a 0644 target reports the symlink path (rc=$e409rc, out: $e409o)"

# 5. A missing candidate adds no row (conf parse owns missing wiring);
#    the OK count covers only present files.
e409_stage
rm -f "$e409cd/p1-allowlist"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes: 0600 (1 files)"* \
    && "$(printf '%s\n' "$e409o" | grep -c 'policy file modes.*p1-allowlist' || true)" == 0 ]] \
    && e409 pass || e409 fail "missing allowlist: skipped, count 1 (rc=$e409rc, out: $e409o)"

# 6. Confdir: only other-write reports. 755/775/700 are supported and
#    silent; 777 (and sticky 1777) are PROBLEM; setgid 2775 is silent.
e409_stage
e409_ok=1
for e409_cm in 755 775 700; do
    chmod "$e409_cm" "$e409cd"
    e409o="$(e409_run --profile p1)"; e409rc=$?
    [[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes"* \
        && "$e409o" != *"policy file modes: $e409cd is"* ]] || e409_ok=0
done
(( e409_ok )) && e409 pass || e409 fail "confdir 755/775/700 stay silent (last rc=$e409rc, out: $e409o)"
chmod 777 "$e409cd"
e409_cbefore="$(stat -c %a "$e409cd")"
e409o="$(e409_run --profile p1)"; e409rc=$?
e409_cafter="$(stat -c %a "$e409cd")"
[[ "$e409rc" == 1 \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd is 777 (writable by other users) — any local user can replace the policy files in it"* \
    && "$e409o" == *"  fix: sudo -u u409 -- chmod o-w -- $e409cd"* \
    && "$e409o" != *"OK: policy file modes"* ]] \
    && e409 pass || e409 fail "world-writable confdir reports with the o-w fix (rc=$e409rc, out: $e409o)"
# F2: the confdir-branch read-only proof. Unlike the file branch, the printed
# o-w fix is a no-op on the 0755 fixtures, so the snapshot must run on a
# confdir where that fix would visibly change the mode.
[[ "$e409_cbefore" == "$e409_cafter" && "$e409_cafter" == 777 ]] \
    && e409 pass || e409 fail "doctor never chmods the confdir: 777 unchanged (before: $e409_cbefore, after: $e409_cafter)"
chmod 1777 "$e409cd"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 1 && "$e409o" == *"PROBLEM: policy file modes: $e409cd is 1777"* ]] \
    && e409 pass || e409 fail "sticky 1777 confdir reports through the mode mask (rc=$e409rc, out: $e409o)"
chmod 2775 "$e409cd"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes"* \
    && "$e409o" != *"policy file modes: $e409cd is"* ]] \
    && e409 pass || e409 fail "setgid/group-writable 2775 confdir stays silent (rc=$e409rc, out: $e409o)"

# 7. Excluded family: the engine records and the build log are never mode
#    rows, and an orphan *-allowlist with no conf is not checked.
e409_stage_aggregate
printf '# pins\n' > "$e409cd/p1.pins"; chmod 644 "$e409cd/p1.pins"
printf '# pending\n' > "$e409cd/p1.revoke-pending"; chmod 644 "$e409cd/p1.revoke-pending"
printf 'build log\n' > "$e409cd/gateway-build.log"; chmod 644 "$e409cd/gateway-build.log"
printf '# orphan\n' > "$e409cd/orphan-allowlist"; chmod 644 "$e409cd/orphan-allowlist"
e409o="$(e409_run)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes: 0600 (4 files)"* \
    && "$e409o" != *"p1.pins"* && "$e409o" != *"revoke-pending"* \
    && "$e409o" != *"gateway-build.log"* && "$e409o" != *"orphan-allowlist"* ]] \
    && e409 pass || e409 fail "excluded family + orphan allowlist produce no mode rows (rc=$e409rc, out: $e409o)"

# 8. Aggregate checks every *.conf pair; named checks only the selected
#    pair. A bad p2 is an aggregate PROBLEM but is invisible to the named
#    p1 run.
e409_stage_aggregate
e409o="$(e409_run)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes: 0600 (4 files)"* ]] \
    && e409 pass || e409 fail "aggregate healthy: 4 files OK, rc 0 (rc=$e409rc, out: $e409o)"
chmod 644 "$e409cd/p2.conf"
e409o="$(e409_run)"; e409rc=$?
e409_n="$(printf '%s\n' "$e409o" | grep -c '^PROBLEM: policy file modes: ' || true)"
[[ "$e409rc" == 1 && "$e409_n" == 1 \
    && "$e409o" == *"PROBLEM: policy file modes: $e409cd/p2.conf is 644"* \
    && "$e409o" != *"OK: policy file modes"* ]] \
    && e409 pass || e409 fail "aggregate reports the bad p2 only (rc=$e409rc, n=$e409_n, out: $e409o)"
e409o="$(e409_run --profile p1)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"OK: policy file modes: 0600 (2 files)"* \
    && "$e409o" != *"p2.conf"* ]] \
    && e409 pass || e409 fail "named p1 ignores the bad p2 (rc=$e409rc, out: $e409o)"

# 9. Account-less host slice stays mode-silent (the pointer NOTE names the
#    family as not examined, but no OK/PROBLEM mode row appears); help
#    names the new family.
e409o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e409u" \
    $SKIT --prefix "$e409p" --doctor 2>&1)"; e409rc=$?
[[ "$e409rc" == 0 \
    && "$e409o" != *"OK: policy file modes"* \
    && "$e409o" != *"PROBLEM: policy file modes"* \
    && "$e409o" == *"account wiring (conf, policy file modes, timer"* ]] \
    && e409 pass || e409 fail "account-less host slice is mode-silent (rc=$e409rc, out: $e409o)"
e409o="$($SKIT help doctor 2>&1)"; e409rc=$?
[[ "$e409rc" == 0 && "$e409o" == *"policy file modes"* ]] \
    && e409 pass || e409 fail "help doctor names the policy file modes row (rc=$e409rc)"

# 10. EGL-531-D4: both repair rows %q-quote their path, so a home/confdir
#     carrying a space and a quote still yields a paste-safe line. The
#     captured lines are re-parsed through a `sudo` stub that records its
#     argv; each path must arrive as one argv element.
e409q="$e409d/home u'q"; e409qcd="$e409q/.config/egresslock"
rm -rf "$e409q"; mkdir -p "$e409qcd"; chmod 777 "$e409qcd"
cp "$e409d/site.conf" "$e409qcd/p1.conf"
cp "$e409d/p1-allowlist" "$e409qcd/p1-allowlist"
chmod 644 "$e409qcd/p1.conf"; chmod 600 "$e409qcd/p1-allowlist"
e409qo="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e409q" \
    EGRESSLOCK_UNIT_DIR="$e409u" \
    $SKIT --prefix "$e409p" --account u409 --doctor --profile p1 2>&1)"; e409qrc=$?
printf -v e409q_qcf '%q' "$e409qcd/p1.conf"
printf -v e409q_qcd '%q' "$e409qcd"
e409qfix="$(printf '%s\n' "$e409qo" | grep '^  fix: ' || true)"
e409q_n="$(printf '%s\n' "$e409qfix" | grep -c . || true)"
e409qbin="$e409d/bin-fix"; mkdir -p "$e409qbin"
cat > "$e409qbin/sudo" <<'EOF'
#!/usr/bin/env bash
printf '%s\0' "$@" > "${FIX_ARGV_OUT:?}"
EOF
chmod +x "$e409qbin/sudo"
e409q_ok=1
[[ "$e409qrc" == 1 && "$e409q_n" == 2 ]] || e409q_ok=0
[[ "$e409qfix" == *"  fix: sudo -u u409 -- chmod 600 -- $e409q_qcf"* \
    && "$e409qfix" == *"  fix: sudo -u u409 -- chmod o-w -- $e409q_qcd"* ]] || e409q_ok=0
e409qi=0
while IFS= read -r e409qline; do
    [[ -n "$e409qline" ]] || continue
    e409qi=$((e409qi + 1))
    ( export PATH="$e409qbin:$PATH" FIX_ARGV_OUT="$e409d/argv-$e409qi"
      eval "${e409qline#  fix: }" ) || e409q_ok=0
done <<< "$e409qfix"
mapfile -d '' -t e409q_a1 < "$e409d/argv-1" 2>/dev/null || e409q_ok=0
mapfile -d '' -t e409q_a2 < "$e409d/argv-2" 2>/dev/null || e409q_ok=0
[[ "${#e409q_a1[@]}" == 7 \
    && "${e409q_a1[0]}" == "-u" && "${e409q_a1[1]}" == "u409" \
    && "${e409q_a1[2]}" == "--" && "${e409q_a1[3]}" == "chmod" \
    && "${e409q_a1[4]}" == "600" && "${e409q_a1[5]}" == "--" \
    && "${e409q_a1[6]}" == "$e409qcd/p1.conf" ]] || e409q_ok=0
[[ "${#e409q_a2[@]}" == 7 \
    && "${e409q_a2[0]}" == "-u" && "${e409q_a2[1]}" == "u409" \
    && "${e409q_a2[2]}" == "--" && "${e409q_a2[3]}" == "chmod" \
    && "${e409q_a2[4]}" == "o-w" && "${e409q_a2[5]}" == "--" \
    && "${e409q_a2[6]}" == "$e409qcd" ]] || e409q_ok=0
(( e409q_ok )) \
    && e409 pass || e409 fail "spaced/quoted home: both fix rows are %q and re-parse to one argv (rc=$e409qrc, n=$e409q_n, out: $e409qo)"
section_end egl409

# --- ARC-22: packaging (.deb + tar.gz) --------------------------------------
section_begin arc22 "ARC-22 packaging"
a22() { assert "$@"; }

DEBSH="$TREE_ROOT/packaging/build-deb.sh"
TARSH="$TREE_ROOT/packaging/build-tarball.sh"
p22="$STATE/a22"; rm -rf "$p22"; mkdir -p "$p22"

# D4: the tarball is the self-contained kit tree (incl. uninstall-kit.sh
# and the unit templates) + a README fragment.
# EGL-107-D1: the whole tarball flow (build, content asserts, extracted-
# tree install/uninstall) skips on the extracted kit — the producer and
# its artifacts are packaging/build-tarball.sh's; the f1*/AppArmor parts
# of this counter (no packaging deps) still run.
if [[ "$HAVE_BUILD_TARBALL" == 1 ]]; then
t_out="$(env EGRESSLOCK_TARBALL_OUT="$p22/k.tgz" "$TARSH" 2>&1)"; t_rc=$?
[[ "$t_rc" == 0 && -f "$p22/k.tgz" ]] \
    && a22 pass || a22 fail "tarball build (rc=$t_rc, out: $t_out)"
mkdir -p "$p22/x"; tar -xzf "$p22/k.tgz" -C "$p22/x"
for f in README.txt egresslock/install-kit.sh egresslock/uninstall-kit.sh \
         egresslock/egresslock egresslock/egresslock-setup \
         egresslock/gateway/Containerfile egresslock/gateway/security-floor \
         egresslock/examples/main.conf \
         egresslock/examples/egl-base/Containerfile \
         egresslock/examples/egl-base/build-egl-base \
         egresslock/examples/egl-base/security-floor \
         egresslock/docs/setup/uninstall.md egresslock/apparmor/usr.bin.pasta.local \
         egresslock/systemd/egresslock-verify@.service \
         egresslock/systemd/egresslock-verify@.timer; do
    [[ -e "$p22/x/$f" ]] && a22 pass || a22 fail "tarball contains $f"
done
# EGL-1 flatten: the kit root is now the repo root, so the tar sweep
# must keep shipping kit payload only — no git dir, no process files.
if tar -tzf "$p22/k.tgz" \
        | grep -qE '(^|/)\.git(/|$)|egresslock/(AGENTS\.md|\.gitignore|docs/(tickets|BOARD\.md))'; then
    a22 fail "tarball leaks repo-only process files"
else
    a22 pass
fi

# Tarball flow: install-kit.sh from the extracted tree deploys the full
# prefix set with the prefix-substituted ExecStart (in-kit templates).
# EGL-80-1-F1: explicit wrapper hooks (lib.sh defaults also exist; these
# make the tarball-flow call sites self-evidently non-host-writing).
u22="$p22/units"
i_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u22" \
    EGRESSLOCK_PATH_BINDIR="$p22/wbin" EGRESSLOCK_PATH_SBINDIR="$p22/wsbin" \
    bash "$p22/x/egresslock/install-kit.sh" --prefix "$p22/opt" 2>&1)"; i_rc=$?
for f in egresslock egresslock-start egresslock-verify egresslock-setup VERSION; do
    [[ -f "$p22/opt/$f" ]] && a22 pass || a22 fail "tarball install deployed $f (rc=$i_rc, out: $i_out)"
done
[[ -d "$p22/opt/gateway" && -f "$p22/opt/examples/main.conf" \
    && -f "$p22/opt/examples/egl-base/Containerfile" \
    && -x "$p22/opt/examples/egl-base/build-egl-base" \
    && -f "$p22/opt/docs/reference/operator-obligations.md" \
    && -f "$u22/egresslock-verify@.service" ]] \
    && a22 pass || a22 fail "tarball install deployed gateway/examples/egl-base/docs/units"
grep -q "ExecStart=$p22/opt/egresslock-verify" "$u22/egresslock-verify@.service" \
    && a22 pass || a22 fail "tarball install rewrote ExecStart with the prefix"

# EGL-72-D3: the extracted tree ships KIT_VERSION (the build version
# string); the install must stamp the deployed VERSION with it. Asserted
# here because the uninstall below removes the prefix wholesale.
[[ "$(tr -d ' \n' < "$p22/x/egresslock/KIT_VERSION")" == "$(sed -n 's/^version: //p' "$p22/opt/VERSION")" ]] \
    && a22 pass || a22 fail "EGL-72 tarball install uses KIT_VERSION as version:"

# ... and uninstall-kit.sh from the same tree removes it (same explicit
# wrapper hooks — EGL-80-1-F1).
u_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$u22" \
    EGRESSLOCK_PATH_BINDIR="$p22/wbin" EGRESSLOCK_PATH_SBINDIR="$p22/wsbin" \
    bash "$p22/x/egresslock/uninstall-kit.sh" --prefix "$p22/opt" 2>&1)"; u_rc=$?
[[ "$u_rc" == 0 && ! -d "$p22/opt" ]] \
    && a22 pass || a22 fail "tarball uninstall removes the prefix (rc=$u_rc, out: $u_out)"
else
    skip "$PKG_SKIP_TAG" "ARC-22 tarball flow (build + content asserts + extracted-tree install/uninstall) — packaging/build-tarball.sh is not on this tree (extracted kit)"
fi

# D1/D2: the staged .deb tree (file-set assert; dpkg optional below).
# EGL-107-D1: staging + every staged-tree assert skip with the producer.
if [[ "$HAVE_BUILD_DEB" == 1 ]]; then
s_out="$(env EGRESSLOCK_DEB_KEEP_STAGE="$p22/stage" \
    EGRESSLOCK_DEB_OUT="$p22/deb" "$DEBSH" 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 ]] && a22 pass || a22 fail "deb staging run (rc=$s_rc, out: $s_out)"
for f in DEBIAN/control DEBIAN/postinst DEBIAN/postrm \
         usr/bin/egresslock usr/sbin/egresslock-setup \
         usr/lib/egresslock/egresslock usr/lib/egresslock/egresslock-setup \
         usr/lib/egresslock/VERSION usr/lib/egresslock/gateway/Containerfile \
         usr/lib/egresslock/gateway/security-floor \
         usr/share/egresslock/examples/main.conf \
         usr/share/egresslock/examples/main-allowlist \
         usr/share/egresslock/examples/egl-base/Containerfile \
         usr/share/egresslock/examples/egl-base/README.md \
         usr/share/egresslock/examples/egl-base/build-egl-base \
         usr/share/egresslock/examples/egl-base/security-floor \
         usr/share/egresslock/doc/README.md \
         usr/share/egresslock/doc/docs/quickstart/allow-non-http.md \
         usr/share/egresslock/doc/docs/setup/install.md \
         usr/share/egresslock/apparmor/usr.bin.pasta.local \
         usr/lib/systemd/system/egresslock-verify@.service \
         usr/lib/systemd/system/egresslock-verify@.timer; do
    [[ -e "$p22/stage/$f" ]] && a22 pass || a22 fail "deb stage contains $f"
done
# EGL-1 flatten / EGL-550-D9: the generated ticket board is process
# material, not shipped; the package doc dir ships manuals only. The
# build-deb process filters are retired (the ticket flow now lives
# outside the shipped tree), so this file-set assert stays as the
# layout check on the staged artifact.
[[ ! -e "$p22/stage/usr/share/egresslock/doc/BOARD.md" ]] \
    && a22 pass || a22 fail "deb doc dir excludes BOARD.md (process file)"
# EGL-556-D3: one docs path on the deb layout. A relative `docs -> doc/docs`
# alias resolves the pages the messages name and apparmor/README.md's
# relative link, while every documented doc/ path stays in place.
if [[ -L "$p22/stage/usr/share/egresslock/docs" \
      && "$(readlink "$p22/stage/usr/share/egresslock/docs")" == "doc/docs" \
      && -f "$p22/stage/usr/share/egresslock/docs/reference/operator-obligations.md" \
      && -f "$p22/stage/usr/share/egresslock/docs/troubleshooting/pasta-apparmor.md" \
      && -f "$p22/stage/usr/share/egresslock/docs/troubleshooting/netns-inspection.md" \
      && -f "$p22/stage/usr/share/egresslock/docs/setup/upgrade.md" \
      && -f "$p22/stage/usr/share/egresslock/doc/README.md" \
      && -f "$p22/stage/usr/share/egresslock/doc/docs/setup/install.md" \
      && -e "$p22/stage/usr/share/egresslock/apparmor/../docs/troubleshooting/pasta-apparmor.md" ]]; then
    a22 pass
else
    a22 fail "deb docs alias is doc/docs and resolves the shipped pages + apparmor relative link"
fi
grep -q 'doc/upgrade.md' "$p22/stage/DEBIAN/postinst" \
    && a22 fail "deb postinst still names the nonexistent doc/upgrade.md" \
    || a22 pass
grep -q 'exec /usr/lib/egresslock/egresslock' "$p22/stage/usr/bin/egresslock" \
    && a22 pass || a22 fail "usr/bin wrapper targets libdir (D1)"
grep -q 'ExecStart=/usr/lib/egresslock/egresslock-verify' \
    "$p22/stage/usr/lib/systemd/system/egresslock-verify@.service" \
    && a22 pass || a22 fail "deb unit ExecStart uses libdir (D1)"
grep -qxF 'PartOf=egresslock-verify@%i.timer' \
    "$p22/stage/usr/lib/systemd/system/egresslock-verify@.service" \
    && a22 pass || a22 fail "deb unit stops the verify oneshot with its timer (PartOf=)"
# EGL-103-D1: the deb's unit copies keep the generated-file notice and
# stay ticket-ID-free.
if grep -q "do not edit" "$p22/stage/usr/lib/systemd/system/egresslock-verify@.service" \
   && grep -q "do not edit" "$p22/stage/usr/lib/systemd/system/egresslock-verify@.timer"; then
    a22 pass
else
    a22 fail "deb unit copies carry the generated-file notice (EGL-103)"
fi
if grep -qE 'EGL-|ARC-' "$p22/stage/usr/lib/systemd/system/egresslock-verify@.service" \
                        "$p22/stage/usr/lib/systemd/system/egresslock-verify@.timer"; then
    a22 fail "deb unit text leaks ticket IDs (EGL-103)"
else
    a22 pass
fi
grep -q '^Package: egresslock$' "$p22/stage/DEBIAN/control" \
    && grep -q '^Architecture: all$' "$p22/stage/DEBIAN/control" \
    && grep -q '^Depends:.*podman' "$p22/stage/DEBIAN/control" \
    && grep -q '^Depends:.*conntrack' "$p22/stage/DEBIAN/control" \
    && a22 pass || a22 fail "control: package/arch/depends (D2; conntrack is the revocation-flush prerequisite)"
# Verification gate: no site names anywhere in the package.
if grep -RIl 'home\.arpa' "$p22/stage" >/dev/null 2>&1; then
    a22 fail "deb stage leaks site names (arc22 verification)"
else
    a22 pass
fi
# D2: postinst never enables a timer or touches AppArmor; postrm never
# deletes account data, runs podman, or removes the pasta snippet.
if grep -vE '^\s*(#|$)' "$p22/stage/DEBIAN/postinst" | grep -qE 'systemctl enable|enable-linger|apparmor_parser|aa-complain'; then
    a22 fail "postinst enables a timer or touches AppArmor (D2/D3)"
else
    a22 pass
fi
if grep -vE '^\s*(#|$)' "$p22/stage/DEBIAN/postrm" | grep -qE 'rm -rf|rm -f|podman|config/egresslock|apparmor_parser'; then
    a22 fail "postrm deletes state or touches podman/AppArmor (D2/D3)"
else
    a22 pass
fi
# R-022-1 F2: the README's dual-install warning must be real — postinst
# actually checks for the prefix kit.
grep -q '/opt/egresslock/egresslock' "$p22/stage/DEBIAN/postinst" \
    && a22 pass || a22 fail "postinst warns on /opt dual install (R-022-1 F2)"

# EGL-433-D4: EGRESSLOCK_DEB_KEEP_STAGE may be absent or an empty real
# directory only. A caller's non-empty directory, a regular file, and a
# symlink are refused rc 2 before the staged tree is written; an empty
# real directory is removed with rmdir and becomes the staged tree's root
# (no <stage>/egresslock nesting), and an absent path is a plain copy.
k433="$p22/egl433"; rm -rf "$k433"; mkdir -p "$k433"
mkdir -p "$k433/nonempty"; printf 'thesis\n' > "$k433/nonempty/thesis.txt"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$k433/nonempty" EGRESSLOCK_DEB_OUT="$k433/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE must be absent or an empty real directory: $k433/nonempty"* \
    && "$o" == *"nothing was written to $k433/nonempty"* \
    && "$(cat "$k433/nonempty/thesis.txt")" == "thesis" \
    && ! -e "$k433/nonempty/DEBIAN" && ! -e "$k433/nonempty/usr" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a non-empty caller dir, contents intact (rc=$rc, out: $o)"
printf 'precious\n' > "$k433/regular-file"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$k433/regular-file" EGRESSLOCK_DEB_OUT="$k433/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"must be absent or an empty real directory: $k433/regular-file"* \
    && "$(cat "$k433/regular-file")" == "precious" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a regular file, bytes intact (rc=$rc, out: $o)"
mkdir -p "$k433/empty-target"
ln -s "$k433/empty-target" "$k433/link"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$k433/link" EGRESSLOCK_DEB_OUT="$k433/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE is a symbolic link: $k433/link"* \
    && "$o" == *"the link points to $k433/empty-target; nothing was written to $k433/link."* \
    && "$o" == *"EGRESSLOCK_DEB_KEEP_STAGE=<empty-dir> packaging/build-deb.sh"* \
    && -L "$k433/link" \
    && -z "$(ls -A "$k433/empty-target")" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a symlink to an empty dir, link intact (rc=$rc, out: $o)"
mkdir -p "$k433/good"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$k433/good" EGRESSLOCK_DEB_OUT="$k433/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$k433/good/DEBIAN/control" && ! -e "$k433/good/egresslock" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage accepts an empty real dir, stage root not nested (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$k433/fresh" EGRESSLOCK_DEB_OUT="$k433/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$k433/fresh/DEBIAN/control" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage still creates an absent stage (rc=$rc, out: $o)"
# EGL-433-D4/B1: classify the LEXICAL destination, never the literal
# spelling. `missing/../protected` is false for -e until mkdir creates
# `missing`; the pre-fix code then merged the staged tree into a
# non-empty `protected`. Now the lexical path is refused, `protected` is
# untouched, and `missing` is never created.
e433_lex_root="$k433/e433-lex"
rm -rf "$e433_lex_root"; mkdir -p "$e433_lex_root"
mkdir -p "$e433_lex_root/protected/egresslock/usr/lib/egresslock"
printf 'protected sentinel\n' > "$e433_lex_root/protected/egresslock/usr/lib/egresslock/egresslock"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_lex_root/missing/../protected" \
    EGRESSLOCK_DEB_OUT="$e433_lex_root/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE must be absent or an empty real directory: $e433_lex_root/missing/../protected"* \
    && "$o" == *"the value resolves to $e433_lex_root/protected;"* \
    && "$(cat "$e433_lex_root/protected/egresslock/usr/lib/egresslock/egresslock")" == "protected sentinel" \
    && ! -e "$e433_lex_root/protected/DEBIAN" \
    && ! -e "$e433_lex_root/missing" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a .. alias to a non-empty dir, no mkdir side effect (rc=$rc, out: $o)"
# A `..` alias to a regular file is refused too (never a copy into it).
printf 'regular sentinel\n' > "$e433_lex_root/prot-file"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_lex_root/absent-f/../prot-file" \
    EGRESSLOCK_DEB_OUT="$e433_lex_root/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"must be absent or an empty real directory: $e433_lex_root/absent-f/../prot-file"* \
    && "$(cat "$e433_lex_root/prot-file")" == "regular sentinel" \
    && ! -e "$e433_lex_root/absent-f" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a .. alias to a regular file (rc=$rc, out: $o)"
# A `..` alias that lexically names a symlink stays refused (S3-not-empty,
# not S3-link), and never rmdir's the referent: `realpath -s` keeps the
# final component a link, unlike `realpath`/`realpath -m`.
mkdir -p "$e433_lex_root/empty-target"
ln -s "$e433_lex_root/empty-target" "$e433_lex_root/empty-link"
out_ln="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_lex_root/missing/../empty-link" \
    EGRESSLOCK_DEB_OUT="$e433_lex_root/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$out_ln" == *"must be absent or an empty real directory: $e433_lex_root/missing/../empty-link"* \
    && "$out_ln" == *"the value resolves to $e433_lex_root/empty-link;"* \
    && ! -e "$e433_lex_root/empty-target/DEBIAN" \
    && -z "$(ls -A "$e433_lex_root/empty-target")" \
    && -L "$e433_lex_root/empty-link" \
    && ! -e "$e433_lex_root/missing" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage refuses a .. alias naming a symlink, referent untouched (rc=$rc, out: $out_ln)"
# `..` alias to an absent leaf: the tree lands at the lexical path and
# the literal alias component is never created.
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_lex_root/missing/../fresh" \
    EGRESSLOCK_DEB_OUT="$e433_lex_root/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e433_lex_root/fresh/DEBIAN/control" \
    && ! -e "$e433_lex_root/missing" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage creates only the lexical absent leaf (rc=$rc, out: $o)"
# The no-clobber leaf mkdir: a directory that appears just before the
# script creates the leaf reds S3-not-empty; no staged tree is merged in.
e433_mkshim="$k433/e433-mkdir-shim"
rm -rf "$e433_mkshim"; mkdir -p "$e433_mkshim"
e433_real_mkdir="$(type -P mkdir)"
cat > "$e433_mkshim/mkdir" <<EOF
#!/usr/bin/env bash
for a in "\$@"; do
    if [[ "\$a" == "$e433_lex_root/racer" ]]; then
        "$e433_real_mkdir" -p "\$a" && printf 'racing writer\n' > "\$a/racing.txt"
    fi
done
exec "$e433_real_mkdir" "\$@"
EOF
chmod +x "$e433_mkshim/mkdir"
o="$(PATH="$e433_mkshim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e433_lex_root/racer" \
    EGRESSLOCK_DEB_OUT="$e433_lex_root/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"must be absent or an empty real directory: $e433_lex_root/racer"* \
    && "$(cat "$e433_lex_root/racer/racing.txt")" == "racing writer" \
    && ! -e "$e433_lex_root/racer/DEBIAN" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage leaf mkdir refuses a racing creation, no merge (rc=$rc, out: $o)"
# EGL-433-D8/B5: a trailing newline is a real pathname byte. The old
# command-substitution capture classified `stage<newline>` as the
# sibling `stage`, removing/recreating it and copying the tree there.
# Now the newline stage is refused as the non-empty real directory it
# is; the empty sibling keeps its bytes and mode.
e433_nl="$k433/e433-nl"
rm -rf "$e433_nl"; mkdir -p "$e433_nl"
e433_nl_stage="$e433_nl/stage"$'\n'
e433_nl_sib="$e433_nl/stage"
mkdir -p "$e433_nl_stage" "$e433_nl_sib"
printf 'newline stage sentinel\n' > "$e433_nl_stage/thesis.txt"
chmod 700 "$e433_nl_sib"
printf -v e433_nl_qstage '%q' "$e433_nl_stage"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_nl_stage" \
    EGRESSLOCK_DEB_OUT="$e433_nl/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE must be absent or an empty real directory: $e433_nl_qstage"* \
    && "$(cat "$e433_nl_stage/thesis.txt")" == "newline stage sentinel" \
    && -z "$(ls -A "$e433_nl_sib")" \
    && "$(stat -c %a "$e433_nl_sib")" == 700 \
    && ! -e "$e433_nl_sib/DEBIAN" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage keeps a trailing-newline stage, sibling intact (rc=$rc, out: $o)"
# The parent capture had the same strip: `parent<newline>/fresh` used to
# classify the newline-free sibling `parent`. Now the tree lands under
# the newline parent and the sibling is untouched.
e433_nl_parent="$e433_nl/parent"$'\n'
e433_nl_psib="$e433_nl/parent"
mkdir -p "$e433_nl_psib"
printf 'parent sibling sentinel\n' > "$e433_nl_psib/keep.txt"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_nl_parent/fresh" \
    EGRESSLOCK_DEB_OUT="$e433_nl/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && -f "$e433_nl_parent/fresh/DEBIAN/control" \
    && ! -e "$e433_nl_psib/fresh" && ! -e "$e433_nl_psib/DEBIAN" \
    && "$(cat "$e433_nl_psib/keep.txt")" == "parent sibling sentinel" ]] \
    && a22 pass || a22 fail "EGL-433 keep-stage creates only the newline parent, sibling untouched (rc=$rc, out: $o)"
# F1 (D8): a producer that exits nonzero is unresolvable even when it
# printed a complete record. A realpath shim names a different empty real
# directory and exits 1: S3-not-empty, with nothing written to either the
# literal path or the emitted directory.
e433_f1p="$k433/e433-f1"
rm -rf "$e433_f1p"; mkdir -p "$e433_f1p"
mkdir -p "$e433_f1p/emitted-empty"; chmod 750 "$e433_f1p/emitted-empty"
mkdir -p "$e433_f1p/literal"
e433_f1pshim="$e433_f1p/realpath-shim"
mkdir -p "$e433_f1pshim"
cat > "$e433_f1pshim/realpath" <<EOF
#!/usr/bin/env bash
printf '%s\0' "$e433_f1p/emitted-empty"
exit 1
EOF
chmod +x "$e433_f1pshim/realpath"
o="$(PATH="$e433_f1pshim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e433_f1p/literal" \
    EGRESSLOCK_DEB_OUT="$e433_f1p/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE must be absent or an empty real directory: $e433_f1p/literal"* \
    && -z "$(ls -A "$e433_f1p/emitted-empty")" \
    && "$(stat -c %a "$e433_f1p/emitted-empty")" == 750 \
    && -z "$(ls -A "$e433_f1p/literal")" \
    && ! -e "$e433_f1p/literal/DEBIAN" ]] \
    && a22 pass || a22 fail "EGL-433 F1 failed realpath is unresolved, emitted dir untouched (rc=$rc, out: $o)"
# The dirname capture (the leaf's parent) gets the same status gate: a
# complete record from a failed dirname must not create the emitted parent
# (an absent child of an existing directory, so acceptance is observable)
# or the leaf.
e433_real_dirname="$(type -P dirname)"
e433_f1d="$e433_f1p/dirname"
mkdir -p "$e433_f1d/emitted-parent"
printf 'emitted parent sentinel\n' > "$e433_f1d/emitted-parent/sentinel"
e433_f1dshim="$e433_f1p/dirname-shim"
mkdir -p "$e433_f1dshim"
cat > "$e433_f1dshim/dirname" <<EOF
#!/usr/bin/env bash
if [[ "\${1:-}" == "-z" ]]; then
    printf '%s\0' "$e433_f1d/emitted-parent/new-child"
    exit 1
fi
exec "$e433_real_dirname" "\$@"
EOF
chmod +x "$e433_f1dshim/dirname"
o="$(PATH="$e433_f1dshim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e433_f1d/base/fresh" \
    EGRESSLOCK_DEB_OUT="$e433_f1d/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"must be absent or an empty real directory: $e433_f1d/base/fresh"* \
    && "$(cat "$e433_f1d/emitted-parent/sentinel")" == "emitted parent sentinel" \
    && ! -e "$e433_f1d/emitted-parent/new-child" \
    && ! -e "$e433_f1d/base" ]] \
    && a22 pass || a22 fail "EGL-433 F1 failed dirname is unresolved, no parent/leaf created (rc=$rc, out: $o)"
# S3-link's message-only readlink has the same gate: a complete wrong
# record from a failed producer keeps S3-link with the literal path and
# omits the `the link points to` line.
e433_f1l="$e433_f1p/s3-link"
mkdir -p "$e433_f1l/target" "$e433_f1l/emitted-target"
ln -s "$e433_f1l/target" "$e433_f1l/link"
e433_f1lshim="$e433_f1p/readlink-shim"
mkdir -p "$e433_f1lshim"
cat > "$e433_f1lshim/readlink" <<EOF
#!/usr/bin/env bash
printf '%s\0' "$e433_f1l/emitted-target"
exit 1
EOF
chmod +x "$e433_f1lshim/readlink"
o="$(PATH="$e433_f1lshim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e433_f1l/link" \
    EGRESSLOCK_DEB_OUT="$e433_f1l/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE is a symbolic link: $e433_f1l/link"* \
    && "$o" != *"the link points to"* \
    && -L "$e433_f1l/link" \
    && -z "$(ls -A "$e433_f1l/target")" \
    && -z "$(ls -A "$e433_f1l/emitted-target")" ]] \
    && a22 pass || a22 fail "EGL-433 F1 failed readlink keeps S3-link without a target line (rc=$rc, out: $o)"
# F5: the success line names the lexical destination D4 populated, never
# the input spelling. `lexical/link -> physical/child`: ordinary traversal
# of `link/../stage` lands in `physical/stage`; D4 writes `lexical/stage`.
e433_f5="$k433/e433-f5"
rm -rf "$e433_f5"; mkdir -p "$e433_f5/physical/child" \
    "$e433_f5/physical/stage" "$e433_f5/lexical/stage"
printf 'physical sentinel\n' > "$e433_f5/physical/stage/sentinel"
ln -s "$e433_f5/physical/child" "$e433_f5/lexical/link"
printf -v e433_f5_qlex '%q' "$e433_f5/lexical/stage"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_f5/lexical/link/../stage" \
    EGRESSLOCK_DEB_OUT="$e433_f5/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && -f "$e433_f5/lexical/stage/DEBIAN/control" \
    && "$(cat "$e433_f5/physical/stage/sentinel")" == "physical sentinel" \
    && "$o" == *"build-deb: staged tree copied to $e433_f5_qlex (not built)"* \
    && "$o" != *"link/../stage"* ]] \
    && a22 pass || a22 fail "EGL-433 F5 success line names the lexical destination (rc=$rc, out: $o)"
# A metacharacter-bearing lexical path stays one shell token in the line.
e433_f5m="$e433_f5/meta ap'stage"
mkdir -p "$e433_f5m"
printf -v e433_f5_qm '%q' "$e433_f5m"
o="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e433_f5m" \
    EGRESSLOCK_DEB_OUT="$e433_f5/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 && -f "$e433_f5m/DEBIAN/control" \
    && "$o" == *"build-deb: staged tree copied to $e433_f5_qm (not built)"* \
    && "$(printf '%s\n' "$o" | grep -c 'staged tree copied to')" == 1 ]] \
    && a22 pass || a22 fail "EGL-433 F5 metacharacter lexical path is one shell token (rc=$rc, out: $o)"

# EGL-555-D1/P3: the keep-stage copy is bound to the leaf this run
# created. A swap at the identity capture makes `stat .` mismatch and
# refuses rc 2 with nothing copied; a swap after the anchor cannot
# redirect the relative `cp -R`, so the referent stays untouched.
e555_ks1="$k433/e555-ks1"
rm -rf "$e555_ks1"; mkdir -p "$e555_ks1/victim" "$e555_ks1/shim"
printf 'ks1 sentinel\n' > "$e555_ks1/victim/sentinel"
e555_ks1_real_stat="$(type -P stat)"
cat > "$e555_ks1/shim/stat" <<EOF
#!/usr/bin/env bash
"$e555_ks1_real_stat" "\$@" > "$e555_ks1/shim/out" || exit \$?
if [[ "\${@: -1}" == "$e555_ks1/stage" && ! -e "$e555_ks1/shim/swapped" ]]; then
    : > "$e555_ks1/shim/swapped"
    mv -- "$e555_ks1/stage" "$e555_ks1/stage.real"
    ln -s "$e555_ks1/victim" "$e555_ks1/stage"
fi
cat "$e555_ks1/shim/out"
rm -f "$e555_ks1/shim/out"
EOF
chmod +x "$e555_ks1/shim/stat"
printf -v e555_ks1_qstage '%q' "$e555_ks1/stage"
o="$(PATH="$e555_ks1/shim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e555_ks1/stage" \
    EGRESSLOCK_DEB_OUT="$e555_ks1/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 2 \
    && "$o" == *"build-deb: refusing: EGRESSLOCK_DEB_KEEP_STAGE changed while the staged tree was checked: $e555_ks1_qstage"* \
    && "$o" == *"nothing was copied to $e555_ks1_qstage"* \
    && -L "$e555_ks1/stage" \
    && "$(cat "$e555_ks1/victim/sentinel")" == "ks1 sentinel" \
    && ! -e "$e555_ks1/victim/DEBIAN" && ! -e "$e555_ks1/victim/usr" \
    && -d "$e555_ks1/stage.real" \
    && -z "$(ls -A "$e555_ks1/stage.real")" ]] \
    && a22 pass || a22 fail "keep-stage refuses a leaf swapped after the mkdir (rc=$rc, out: $o)"

e555_ks2="$k433/e555-ks2"
rm -rf "$e555_ks2"; mkdir -p "$e555_ks2/victim" "$e555_ks2/shim"
printf 'ks2 sentinel\n' > "$e555_ks2/victim/sentinel"
e555_ks2_real_cp="$(type -P cp)"
cat > "$e555_ks2/shim/cp" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "-R" && "\$2" == "--" && "\$3" == */. && "\$4" == "." \
      && ! -e "$e555_ks2/shim/swapped" ]]; then
    : > "$e555_ks2/shim/swapped"
    mv -- "$e555_ks2/stage" "$e555_ks2/stage.moved"
    ln -s "$e555_ks2/victim" "$e555_ks2/stage"
fi
exec "$e555_ks2_real_cp" "\$@"
EOF
chmod +x "$e555_ks2/shim/cp"
printf -v e555_ks2_qstage '%q' "$e555_ks2/stage"
o="$(PATH="$e555_ks2/shim:$PATH" EGRESSLOCK_DEB_KEEP_STAGE="$e555_ks2/stage" \
    EGRESSLOCK_DEB_OUT="$e555_ks2/x.deb" "$DEBSH" 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$o" == *"build-deb: staged tree copied to $e555_ks2_qstage (not built)"* \
    && -L "$e555_ks2/stage" \
    && "$(cat "$e555_ks2/victim/sentinel")" == "ks2 sentinel" \
    && ! -e "$e555_ks2/victim/DEBIAN" && ! -e "$e555_ks2/victim/usr" \
    && -f "$e555_ks2/stage.moved/DEBIAN/control" \
    && -f "$e555_ks2/stage.moved/usr/lib/egresslock/egresslock" ]] \
    && a22 pass || a22 fail "keep-stage swap after the anchor cannot redirect the copy (rc=$rc, out: $o)"
else
    skip "$PKG_SKIP_TAG" "ARC-22 deb staging + staged-tree asserts — packaging/build-deb.sh is not on this tree (extracted kit)"
fi

# R-022-1 F1: a fresh .deb-only host — no /etc template, no --prefix —
# derives the prefix from the deb unit template (/usr/lib/systemd/system),
# so the postinst's printed command works out of the box.
f1="$p22/f1"; rm -rf "$f1"
mkdir -p "$f1/debunits" "$f1/libdir" "$f1/home/uacct/.config"
sed "s|__EGRESSLOCK_PREFIX__|$f1/libdir|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$f1/debunits/egresslock-verify@.service"
install -m 0755 "$TREE_ROOT/egresslock" "$f1/libdir/egresslock"
f1_out="$(env -u EGRESSLOCK_UNIT_DIR EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_DEB_UNIT_DIR="$f1/debunits" EGRESSLOCK_ACCOUNT_HOME="$f1/home/uacct" \
    "$SKIT" --account uacct --init-conf 2>&1)"; f1_rc=$?
if [[ "$f1_rc" == 0 && ! -e "$f1/home/uacct/.config/egresslock/unit.env" \
      && -f "$f1/home/uacct/.config/egresslock/main.conf" \
      && "$f1_out" != *"no engine at"* ]]; then
    a22 pass
else
    a22 fail "F1 deb-host setup derives the libdir prefix (rc=$f1_rc, out: $f1_out)"
fi

# R-EGL-37-1 D37-1: a stale /etc unit pointing at a dead prefix while the
# live kit is the .deb — setup must RETRY the deb unit dir and adopt the
# libdir prefix. EGRESSLOCK_DEFAULT_UNIT_DIR fakes the /etc probe without
# tripping explicit-hook suppression (EGRESSLOCK_UNIT_DIR would); a
# working /etc prefix still wins (f1w).
f1s="$p22/f1-stale"; rm -rf "$f1s"
mkdir -p "$f1s/etcunits" "$f1s/debunits" "$f1s/libdir" "$f1s/opt-dead" "$f1s/home/uacct/.config"
sed "s|__EGRESSLOCK_PREFIX__|$f1s/opt-dead|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$f1s/etcunits/egresslock-verify@.service"
sed "s|__EGRESSLOCK_PREFIX__|$f1s/libdir|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$f1s/debunits/egresslock-verify@.service"
install -m 0755 "$TREE_ROOT/egresslock" "$f1s/libdir/egresslock"
f1s_out="$(env -u EGRESSLOCK_UNIT_DIR EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_DEB_UNIT_DIR="$f1s/debunits" EGRESSLOCK_ACCOUNT_HOME="$f1s/home/uacct" \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$f1s/etcunits" \
    "$SKIT" --account uacct --init-conf 2>&1)"; f1s_rc=$?
[[ "$f1s_rc" == 0 && "$f1s_out" != *"no engine at"* ]] \
    && a22 pass || a22 fail "D37-1 stale-/etc retry adopts live deb prefix (rc=$f1s_rc, out: $f1s_out)"

# R-EGL-37-1 Finding 1a: BOTH probes miss (no units anywhere) -> rc 1
# with the two-shape error text (.deb hosts: / prefix installs:).
f1e="$p22/f1-errtext"; rm -rf "$f1e"
mkdir -p "$f1e/home/uacct/.config"
f1e_out="$(env -u EGRESSLOCK_UNIT_DIR EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_DEB_UNIT_DIR="$f1e/no-deb-units" EGRESSLOCK_DEFAULT_UNIT_DIR="$f1e/no-etc-units" \
    EGRESSLOCK_ACCOUNT_HOME="$f1e/home/uacct" \
    "$SKIT" --account uacct --init-conf 2>&1)"; f1e_rc=$?
[[ "$f1e_rc" == 1 \
    && "$f1e_out" == *"no engine at /opt/egresslock/egresslock"* \
    && "$f1e_out" == *".deb hosts: reinstall the current package, or pass --prefix /usr/lib/egresslock"* \
    && "$f1e_out" == *"prefix installs: run install-kit.sh first (or pass --prefix)"* ]] \
    && a22 pass || a22 fail "D37-1 both-probes-miss error names both shapes (rc=$f1e_rc, out: $f1e_out)"

# R-EGL-37-1 Finding 1b: EXPLICIT EGRESSLOCK_UNIT_DIR (stale, dead
# prefix) + a live deb available -> suppression must HOLD (the deb
# retry misfiring under an explicit hook would silently rewire hosts
# that asked to be pinned to a unit dir).
f1e_out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$f1s/etcunits" EGRESSLOCK_DEB_UNIT_DIR="$f1s/debunits" \
    EGRESSLOCK_ACCOUNT_HOME="$f1e/home/uacct" \
    "$SKIT" --account uacct --init-conf 2>&1)"; f1e_rc=$?
[[ "$f1e_rc" == 1 && "$f1e_out" == *"no engine at $f1s/opt-dead/egresslock"* \
    && "$f1e_out" == *".deb hosts:"* ]] \
    && a22 pass || a22 fail "D37-1 explicit hook suppresses the deb retry (rc=$f1e_rc, out: $f1e_out)"

# R-EGL-37-1 Note 3: a WORKING default-/etc prefix (no explicit hook)
# must win over a live deb — the retry must not fire when the first
# probe's engine exists.
f1w="$p22/f1-working"; rm -rf "$f1w"
mkdir -p "$f1w/etcunits" "$f1w/debunits" "$f1w/opt-live" "$f1w/libdir" "$f1w/home/uacct/.config"
sed "s|__EGRESSLOCK_PREFIX__|$f1w/opt-live|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$f1w/etcunits/egresslock-verify@.service"
sed "s|__EGRESSLOCK_PREFIX__|$f1w/libdir|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$f1w/debunits/egresslock-verify@.service"
install -m 0755 "$TREE_ROOT/egresslock" "$f1w/opt-live/egresslock"
install -m 0755 "$TREE_ROOT/egresslock" "$f1w/libdir/egresslock"
f1w_out="$(env -u EGRESSLOCK_UNIT_DIR EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_DEB_UNIT_DIR="$f1w/debunits" EGRESSLOCK_ACCOUNT_HOME="$f1w/home/uacct" \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$f1w/etcunits" \
    "$SKIT" --account uacct --init-conf 2>&1)"; f1w_rc=$?
# Prove the /opt engine (not the deb libdir) served the run: drop a
# marker the deb engine does not have.
printf 'opt-live\n' > "$f1w/opt-live/.engine-marker"
[[ "$f1w_rc" == 0 && "$f1w_out" != *"no engine at"* ]] \
    && a22 pass || a22 fail "D37-1 working default-/etc prefix wins over live deb (rc=$f1w_rc, out: $f1w_out)"

# dpkg-deb build smoke (when dpkg-deb exists and the producer is present;
# stage asserts already ran). EGL-372: the -I/-c/-f read-back trio is
# gone — it re-tested dpkg-deb's packaging contract, not product state;
# the staged-tree asserts + this build smoke own the evidence.
if command -v dpkg-deb >/dev/null 2>&1 && [[ "$HAVE_BUILD_DEB" == 1 ]]; then
    d_out="$(env EGRESSLOCK_DEB_OUT="$p22/egresslock_test_all.deb" "$DEBSH" 2>&1)"; d_rc=$?
    [[ "$d_rc" == 0 && -f "$p22/egresslock_test_all.deb" ]] \
        && a22 pass || a22 fail "dpkg-deb build smoke (rc=$d_rc, out: $d_out)"
elif [[ "$HAVE_BUILD_DEB" == 0 ]]; then
    skip "$PKG_SKIP_TAG" "ARC-22 dpkg-deb smoke — packaging/build-deb.sh is not on this tree (extracted kit)"
else
    echo "note: dpkg-deb not available; stage-only asserts ran (ARC-22)"
fi

# D3: egresslock-setup --apparmor-add (explicit activation, idempotent,
# hint-only without the flag, skip when pasta is not enforced).
aa22="$STATE/a22aa"; rm -rf "$aa22"
mkdir -p "$aa22/bin" "$aa22/aad/local" "$aa22/share/apparmor" "$aa22/nosnippet"
# EGL-22: enforce detection reads the KERNEL profiles listing, not
# aa-status prose. Fixtures mimic /sys/kernel/security/apparmor/profiles.
# EGL-39/D39-5: the default fixture is a LABELED-podman host (labeled
# host shape: `podman (unconfined)` — the flag occupies the mode column,
# EGL-39 ground truth); the unlabeled variant (stock Debian shape,
# pasta enforced, no podman profile) lives in profiles.nopodman.
printf '/usr/bin/pasta (enforce)\npodman (unconfined)\n' > "$aa22/profiles"
printf '/usr/bin/pasta (enforce)\n' > "$aa22/profiles.nopodman"
# EGL-39/D39-3: hat lines (podman//…) must never count as the main
# podman profile.
printf '/usr/bin/pasta (enforce)\npodman//null-/usr/bin/crun (complain)\npodman//null-/usr/bin/podman (complain)\n' > "$aa22/profiles.hats"
printf '/usr/bin/other (enforce)\n' > "$aa22/profiles.none"
cat > "$aa22/bin/aa-status" <<'EOF'
#!/usr/bin/env bash
[[ "${1:-}" == "--enabled" ]] && exit 0
exit 1
EOF
cat > "$aa22/bin/apparmor_parser" <<'EOF'
#!/usr/bin/env bash
# Mock: -r/-r -T log to the state file; -p/--preprocess flatten local
# includes onto stdout so the D2 load-check (egresslock-setup
# --apparmor-add) can see a rule that lives in a referenced local fragment
# (EGL-14-D2 / EGL-20-D1). No --print alias: the real parser has none.
# EGL-56: -p and --preprocess are the SAME action — given together the
# real AppArmor 5 parser aborts ("Too many actions"); the mock emulates
# that so a regression to the double flag cannot pass green.
if [[ "$1" == "-p" && "$2" == "--preprocess" ]]; then
    echo "apparmor_parser: Too many actions given on the command line." >&2
    exit 1
fi
if [[ "$1" == "-p" || "$1" == "--preprocess" ]]; then
    f="${@: -1}"
    if [[ "${ARCMOCK_CANONICAL_PARSER:-0}" == "1" ]]; then
        # EGL-30-D2 fixture: emit the REAL parser's canonicalized rule
        # form (parens dropped) — the literal-source grep used to
        # false-negative on exactly this output. Rules from the source
        # tree are rewritten to the canonical shape; everything else
        # passes through verbatim (structure lines still needed by the
        # callers).
        sed -E 's/signal[[:space:]]+\(receive\)([[:space:]]+set=\(term\))?/signal receive set=term/g; s/signal[[:space:]]+\(receive\)/signal receive/g' "$f"
        inc="$(sed -n 's/^[[:space:]]*#\{0,1\}include[[:space:]]*<local\/\(usr\.bin\.pasta\|pasta\)>.*/\1/p' "$f" | head -1)"
        if [[ -n "$inc" ]]; then
            sed -E 's/signal[[:space:]]+\(receive\)([[:space:]]+set=\(term\))?/signal receive set=term/g; s/signal[[:space:]]+\(receive\)/signal receive/g' "$(dirname "$f")/local/$inc" 2>/dev/null
        fi
        exit 0
    fi
    cat "$f"
    inc="$(sed -n 's/^[[:space:]]*#\{0,1\}include[[:space:]]*<local\/\(usr\.bin\.pasta\|pasta\)>.*/\1/p' "$f" | head -1)"
    if [[ -n "$inc" ]]; then
        cat "$(dirname "$f")/local/$inc" 2>/dev/null
    fi
else
    echo "apparmor_parser $*" >> "${ARCMOCK_STATE:?}/apparmor.log"
fi
EOF
chmod +x "$aa22/bin/aa-status" "$aa22/bin/apparmor_parser"
# EGL-80-L5: a FAILING aa-status stub — the deterministic stand-in for
# "AppArmor not enabled" (state 3 needs `aa-status --enabled` to fail or
# be missing; the real host binary may be present and succeed).
mkdir -p "$aa22/bin-noaa"
printf '#!/usr/bin/env bash\nexit 1\n' > "$aa22/bin-noaa/aa-status"
chmod +x "$aa22/bin-noaa/aa-status"
cp "$TREE_ROOT/apparmor/usr.bin.pasta.local" "$aa22/share/apparmor/"
# ARC-72-D1: the resolved profile file must mention /usr/bin/pasta.
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad/usr.bin.pasta"
run_aa() { env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="${AA_PROFILES:-$aa22/profiles}" "$SKIT" "$@"; }
: > "$STATE/apparmor.log"

# 1. --apparmor-add alone (no --account): applies the rule and reloads.
o="$(run_aa --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"updating pasta local profile"* \
      && "$o" == *"allow podman SIGTERM"* \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad/local/usr.bin.pasta")" -ge 1 \
      && "$(grep -cE 'signal \(receive\) set=\(term\) peer=podman' "$aa22/aad/local/usr.bin.pasta")" -ge 1 \
      && "$(grep -c '^# begin egresslock-setup --apparmor$' "$aa22/aad/local/usr.bin.pasta")" -ge 1 \
      && "$(grep -c '^# end egresslock-setup --apparmor$' "$aa22/aad/local/usr.bin.pasta")" -ge 1 \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]]; then
    a22 pass
else
    a22 fail "D3 --apparmor-add alone applies + reloads, marker-scoped (rc=$rc, out: $o)"
fi

# 2. Idempotent: the rule is already ours; no second parser run.
o="$(run_aa --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already allows"* && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a22 pass || a22 fail "D3 --apparmor-add idempotent (rc=$rc, out: $o)"

# 3. Without the flag: one stderr hint, no write, no parser run.
rm -rf "$aa22/aad/local"; mkdir -p "$aa22/aad/local"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"hint: the podman network helper (pasta) is confined by AppArmor"* \
    && "$o" == *"apparmor add"* \
    && ! -e "$aa22/aad/local/usr.bin.pasta" \
    && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a22 pass || a22 fail "D3 no-flag run: hint only, no write (rc=$rc, out: $o)"

# 4. pasta KNOWN not enforced (readable listing, no pasta): skip rc 0.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.none" "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"pasta not enforced; skipping"* ]] \
    && a22 pass || a22 fail "D3 known-not-enforced skip path (rc=$rc, out: $o)"

# 4b. AppArmor not enabled at all: skip rc 0 (no profiles, no aa-status).
#     EGL-80-L5: pin the profiles path to an absent file and shadow the
#     host's real aa-status (which may exist and succeed) with the
#     failing stub, so state 3 is deterministic on any host.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin-noaa:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/nosuchprofiles" "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"AppArmor: not enabled; skipping"* ]] \
    && a22 pass || a22 fail "D3 apparmor-not-enabled skip path (rc=$rc, out: $o)"

# 4c. EGL-22-D2: enforcement UNKNOWN (unreadable listing, aa-status on):
#     apply refuses rc 1 — never skip on unknown.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/nosuchprofiles" "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"cannot determine whether pasta is AppArmor-enforced"* \
    && "$o" == *"($aa22/nosuchprofiles unreadable by this user"* ]] \
    && a22 pass || a22 fail "D3 unknown-enforcement refuses rc 1 and names the listing (rc=$rc, out: $o)"

# 4d. EGL-22 finding (2026-09-09): the profiles path passes
#     `[[ -r ]]` (mode 0444) but open() still EACCES for non-root (grep
#     rc 2). grep failure must be UNKNOWN (state 2), never misread as
#     "no match" -> "NOT enforced". Simulate with a directory: grep on a
#     dir errors rc 2 while `-r` is true.
mkdir -p "$aa22/profiles-dir"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles-dir" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta enforcement: unknown"* && "$o" != *"NOT enforced"* ]] \
    && a22 pass || a22 fail "D3 grep-read-error -> unknown, not NOT enforced (rc=$rc, out: $o)"

# 4e. R-EGL-22-1 Finding 1 test gap: --apparmor-check on state 3
#     (AppArmor not enabled) must PRINT `AppArmor: not enabled` and the
#     rest, rc 1 — not abort silently under set -e.
#     EGL-80-L5: failing aa-status stub on PATH (the host's real
#     aa-status may exist and report enabled -> state 2, not 3).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin-noaa:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad-empty" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/nosuchprofiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"AppArmor: not enabled"* \
    && "$o" == *"pasta enforcement: n/a"* \
    && "$o" == *"pasta profile: missing file"* ]] \
    && a22 pass || a22 fail "R-EGL-22-1 F1 doctor state 3 prints, rc 1 (rc=$rc, out: $o)"

# 4f. R-EGL-22-1 Finding 1 test gap: --apparmor-check on state 2
#     (enforcement unknown) must PRINT `enforcement unknown`, rc 1.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/nosuchprofiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta enforcement: unknown"* ]] \
    && a22 pass || a22 fail "R-EGL-22-1 F1 doctor state 2 prints, rc 1 (rc=$rc, out: $o)"

# --- EGL-39: podman label tri-state + conditional amendment verdict -------
# Shared fresh fixture: profile WITH its local include, EMPTY local file
# (absent rule, healthy pasta side — the D39-4 rc-0 shape when the
# verdict is a KNOWN not-needed).
mkdir -p "$aa22/aad39/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad39/usr.bin.pasta"
: > "$aa22/aad39/local/usr.bin.pasta"
# 4g. Hat lines never count as the main podman profile (D39-3: anchored
#     ERE; labeled-host ground truth has podman//… hats). Pasta enforced + no
#     main podman line -> unlabeled -> not-needed verdict; aad39 is the
#     fresh healthy fixture (include present, local empty -> absent
#     rule) so D39-4 keeps rc 0.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.hats" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"podman label: unlabeled"* \
    && "$o" == *"pasta amendment: not required on this host (podman unlabeled)"* ]] \
    && a22 pass || a22 fail "EGL-39 hat lines do not count as labeled (rc=$rc, out: $o)"

# 4h. Labeled + enforced + absent rule: amendment needed, rc 1 (D39-4:
#     the rc-0 path is for KNOWN not-needed verdicts only).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"podman label: labeled"* \
    && "$o" == *"pasta amendment: required on this host"* \
    && "$o" == *"egresslock rule in local file: absent"* ]] \
    && a22 pass || a22 fail "EGL-39 labeled+enforced+absent rule -> needed, rc 1 (rc=$rc, out: $o)"

# 4i. Known-unlabeled (stock Debian shape: pasta enforced, no podman
#     profile) + healthy pasta side + absent rule: verdict not-needed,
#     rc 0 (D39-4 — the one intentional rc change).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"podman label: unlabeled"* \
    && "$o" == *"pasta amendment: not required on this host (podman unlabeled)"* \
    && "$o" == *"egresslock rule in local file: absent"* ]] \
    && a22 pass || a22 fail "EGL-39 unlabeled+healthy+absent rule -> rc 0 (rc=$rc, out: $o)"

# 4j. Same unlabeled verdict but MISSING extension (EGL-60 unlabeled-host
#     shape,
#     flipping the old D39-4 rc!=0 contract): stock unlabeled host, the
#     amendment is not required -> rc 0, Summary CHECK OK (not needed),
#     MISSING + amendment detail lines stay as evidence (EGL-60-D1).
mkdir -p "$aa22/aad39x/local"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad39x/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39x" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"podman label: unlabeled"* \
    && "$o" == *"pasta amendment: not required on this host (podman unlabeled)"* \
    && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"CHECK OK (AppArmor patch not needed)"* ]] \
    && a22 pass || a22 fail "EGL-60 unlabeled+missing extension -> OK not needed, rc 0 (rc=$rc, out: $o)"

# 4k. UNKNOWN listing (EACCES sim, profiles-dir): podman label unknown,
#     verdict condition unknown — NEVER a "not needed" claim (D39-3).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles-dir" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"podman label: unknown"* \
    && "$o" == *"pasta amendment: condition unknown"* \
    && "$o" != *"not needed"* ]] \
    && a22 pass || a22 fail "EGL-39 unknown listing -> no not-needed claim (rc=$rc, out: $o)"

# 4l. Unlabeled-listing doctor on a pasta-NOT-enforced host: verdict
#     not needed (pasta not enforced), rc 1 — the EGL-29-D1 pair's rc
#     table is frozen; only the absent-rule rc changed (D39-4).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.none" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta amendment: not required on this host (pasta not enforced)"* ]] \
    && a22 pass || a22 fail "EGL-39 pasta-not-enforced verdict, pair rc frozen (rc=$rc, out: $o)"

# 4m. Apply on a KNOWN-unlabeled host still applies (D39-1) and prints
#     the no-effect note (EGL-200 M5); the labeled path never does.
o="$(run_aa --apparmor-add 2>&1)"; rc=$?   # labeled default fixture
[[ "$rc" == 0 && "$o" != *"no effect on this host"* ]] \
    && a22 pass || a22 fail "EGL-39 labeled apply has no noop note (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"AppArmor: the egresslock rule is in place but has no effect on this host."* \
    && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad39/local/usr.bin.pasta")" -ge 1 ]] \
    && a22 pass || a22 fail "EGL-39 unlabeled apply: applies + noop note (rc=$rc, out: $o)"

# 4n. No-flag account run: hint on labeled (default fixture, D39-5),
#     suppressed + one-liner on unlabeled (D39-2 surface 1 / D39-5).
mkdir -p "$aa22/home39"
: > "$STATE/apparmor.log"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    EGRESSLOCK_ACCOUNT_HOME="$aa22/home39" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"hint: the podman network helper (pasta) is confined by AppArmor"* \
    && "$o" == *"is confined by AppArmor."* \
    && "$o" != *"(rule file:"* \
    && "$o" == *"'kill network process: permission denied', run: sudo egresslock-setup apparmor add"* \
    && "$o" != *"no effect on this host"* ]] \
    && a22 pass || a22 fail "EGL-39 labeled no-flag run keeps hint (rc=$rc, out: $o)"
: > "$STATE/apparmor.log"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" \
    EGRESSLOCK_ACCOUNT_HOME="$aa22/home39" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" != *"hint: the podman network helper"* \
    && "$o" == *"AppArmor: this host's podman is not confined by AppArmor, so no extra AppArmor rule is needed — no action needed."* ]] \
    && a22 pass || a22 fail "EGL-39 unlabeled no-flag run: no hint, one-liner (rc=$rc, out: $o)"

# EGL-301: the AppArmor preamble (hint + the unlabeled one-liner) prints
#     only on the account-setup path — doctor and build-gateway are
#     silent on both (the account-bundle run above keeps them). Both
#     profiles fixture: pasta enforced + podman unconfined, so the
#     pre-EGL-301 code printed here.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" doctor 2>&1)"; rc=$?
[[ "$o" != *"hint: the podman network helper"* \
    && "$o" != *"not confined by AppArmor"* \
    && "$o" == *"NOTE: AppArmor: see egresslock-setup apparmor check (pasta slice)"* ]] \
    && a22 pass || a22 fail "EGL-301 doctor is silent on the AppArmor preamble (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e301 \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --prefix "$e38p" --build-gateway 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" != *"hint: the podman network helper"* \
    && "$o" != *"not confined by AppArmor"* ]] \
    && a22 pass || a22 fail "EGL-301 build-gateway is silent on the AppArmor preamble (rc=$rc, out: $o)"

# 4o. Help text: no bare --apparmor flag anywhere (D39-8; EGL-29-D2
#     flags only — --apparmor-add/-remove/-check).
o="$("$SKIT" -h 2>&1)"; rc=$?
[[ "$rc" == 0 && "$(grep -cE '(^|[ (])--apparmor([^a-z-]|$)' <<< "$o")" -eq 0 ]] \
    && a22 pass || a22 fail "EGL-39/D39-8 help has no bare --apparmor (rc=$rc)"

# --- EGL-30 + EGL-32: canonical parser output + 2-line doctor scheme ------
# 4p. D30-2: with the CANONICAL preprocess fixture (real-parser shape,
#     parens stripped), a fresh apply must reach rc 0 with NO
#     "rule is NOT present" false-negative.
mkdir -p "$aa22/aad30/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad30/usr.bin.pasta"
: > "$aa22/aad30/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad30" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" ARCMOCK_CANONICAL_PARSER=1 \
    "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" != *"NOT present"* \
    && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad30/local/usr.bin.pasta")" -ge 1 ]] \
    && a22 pass || a22 fail "EGL-30 canonical parser output: apply rc 0, no false-negative (rc=$rc, out: $o)"

# 4q. D30-1: idempotent re-apply ALSO passes under the canonical fixture
#     (apply's `already` grep hits the local source file — source form).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad30" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" ARCMOCK_CANONICAL_PARSER=1 \
    "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already allows"* ]] \
    && a22 pass || a22 fail "EGL-30 canonical parser: re-apply idempotent (rc=$rc, out: $o)"

# 4r. D32-1: doctor lines — aad30 has a NATIVE include (stock wiring)
#     but OUR marker-scoped rule: extension `(stock)`, rule
#     `(egresslock)`; the compatibility-patch line is GONE. (4t/4u cover
#     the patched-extension variant via the aadp fixture in the EGL-21
#     block: present (egresslock) on the extension line.)
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad30" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$o" == *"pasta local extension: present (stock)"* \
    && "$o" == *"egresslock rule in local file: present (egresslock)"* \
    && "$o" != *"compatibility patch:"* ]] \
    && a22 pass || a22 fail "EGL-32 doctor: ownership lines, no patch line (rc=$rc, out: $o)"

# 4s. D32-1: stock include + stock (unmarked) operator rule -> `(stock)`
#     on both lines.
mkdir -p "$aa22/aad30s/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad30s/usr.bin.pasta"
printf '# operator rule (mine)\nsignal (receive) set=(term) peer=podman,\n' > "$aa22/aad30s/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad30s" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$o" == *"pasta local extension: present (stock)"* \
    && "$o" == *"egresslock rule in local file: present (stock)"* ]] \
    && a22 pass || a22 fail "EGL-32 doctor: stock ownership (rc=$rc, out: $o)"

# 4t. D32-1: MISSING extension + unmarked stock rule -> MISSING +
#     `present (stock)`, rc != 0 (EGL-14 unhealthy shape preserved).
mkdir -p "$aa22/aad30m/local"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad30m/usr.bin.pasta"
printf 'signal (receive) set=(term) peer=podman,\n' > "$aa22/aad30m/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad30m" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" != 0 && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"egresslock rule in local file: present (stock)"* ]] \
    && a22 pass || a22 fail "EGL-32 doctor: missing extension + stock rule (rc=$rc, out: $o)"

# 4u. D30-1: unapply still refuses on an unmarked rule (loosened ERE
#     must not widen the refusal logic).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_SHARE="$aa22/share" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad30s" PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"not guessing"* ]] \
    && a22 pass || a22 fail "EGL-30 unapply unmarked-rule refusal intact (rc=$rc, out: $o)"

# 5. Enforced but no snippet in the share: fail closed with a pointer.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/nosnippet" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"no pasta snippet"* ]] \
    && a22 pass || a22 fail "D3 missing snippet fails closed (rc=$rc, out: $o)"

# --- ARC-66: --apparmor-remove (unapply) ---------------------------------
# 6. EGL-29-D2: the old `--remove` flag is dropped (rc 2 unknown);
#    `--apparmor-add` + `--apparmor-remove` together is the rc 2 usage
#    error. R-EGL-29-1 minor (b): the Verification plan also lists bare
#    `--apparmor` and `--apparmor --remove` as rc-2 checks — assert all
#    three (same generic unknown-arg branch, but pin the plan).
o="$(run_aa --apparmor 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"unknown argument: --apparmor"* ]] \
    && a22 pass || a22 fail "D2 bare --apparmor dropped rc 2 (rc=$rc, out: $o)"
o="$(run_aa --apparmor --remove 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"unknown argument: --apparmor"* ]] \
    && a22 pass || a22 fail "D2 --apparmor --remove dropped rc 2 (rc=$rc, out: $o)"
o="$(run_aa --remove 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"unknown argument: --remove"* ]] \
    && a22 pass || a22 fail "D1 --remove dropped rc 2 (rc=$rc, out: $o)"
o="$(run_aa --apparmor-add --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"mutually exclusive"* ]] \
    && a22 pass || a22 fail "D1 add+remove usage error (rc=$rc, out: $o)"

# 7. Unapply strips ONLY the marker block: operator lines survive, file
#    survives, parser reloads. Idempotent second run.
mkdir -p "$aa22/aad2/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad2/usr.bin.pasta"
printf '# operator rule kept\n' > "$aa22/aad2/local/usr.bin.pasta"
{
    echo ""
    echo "# begin egresslock-setup --apparmor"
    echo "# added by egresslock-setup --apparmor (ARC-27 / ARC-22-D3):"
    cat "$aa22/share/apparmor/usr.bin.pasta.local"
    echo "# end egresslock-setup --apparmor"
} >> "$aa22/aad2/local/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad2" \
    "$SKIT" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"removed the egresslock pasta amendment"* \
      && -f "$aa22/aad2/local/usr.bin.pasta" \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad2/local/usr.bin.pasta")" == 0 \
      && "$(grep -c '# operator rule kept' "$aa22/aad2/local/usr.bin.pasta")" == 1 \
      && "$(grep -c 'egresslock-setup --apparmor' "$aa22/aad2/local/usr.bin.pasta")" == 0 \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]]; then
    a22 pass
else
    a22 fail "D1 unapply strips the block, keeps operator lines (rc=$rc, out: $o)"
fi
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad2" \
    "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already gone"* && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a22 pass || a22 fail "D1 unapply idempotent (rc=$rc, out: $o)"

# 8. Legacy lab shape (single start line through the signal rule) strips too.
mkdir -p "$aa22/aad3/local"
{
    echo '# operator line stays'
    echo ''
    echo '# added by egresslock-setup --apparmor (ARC-27 / ARC-22-D3):'
    echo '# snippet comment from the old append'
    echo 'signal (receive) peer=podman,'
} > "$aa22/aad3/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad3" \
    "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad3/local/usr.bin.pasta")" == 0 \
    && "$(grep -c '# operator line stays' "$aa22/aad3/local/usr.bin.pasta")" == 1 ]] \
    && a22 pass || a22 fail "D1 legacy-shape unapply (rc=$rc, out: $o)"

# 9. Unmarked signal rule (no kit marker): never guessed — rc 1, file
#    unchanged, no parser run.
mkdir -p "$aa22/aad4/local"
printf '# operator rule\nsignal (receive) peer=podman,\n' > "$aa22/aad4/local/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad4" \
    "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"unmarked"* \
    && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad4/local/usr.bin.pasta")" == 1 \
    && "$(wc -l < "$STATE/apparmor.log")" -eq 0 ]] \
    && a22 pass || a22 fail "D1 unmarked rule rc 1, untouched (rc=$rc, out: $o)"

# 10. Missing local file -> rc 0 already-gone; unapply works without
#     pasta enforcement (no aa-status stub in PATH).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_SHARE="$aa22/share" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad-empty" "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already gone"* ]] \
    && a22 pass || a22 fail "D1 missing file rc 0 (rc=$rc, out: $o)"
mkdir -p "$aa22/aad5/local"
{
    echo '# begin egresslock-setup --apparmor'
    echo 'signal (receive) peer=podman,'
    echo '# end egresslock-setup --apparmor'
} > "$aa22/aad5/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_SHARE="$aa22/share" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad5" "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && ! "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa22/aad5/local/usr.bin.pasta")" -ge 1 ]] \
    && a22 pass || a22 fail "D1 unapply without enforcement (rc=$rc, out: $o)"

# --- EGL-27: monotonic version stamps (dpkg ordering) ----------------------
# D1: version = <VERSION_BASE>+git<YYYYMMDDHHMMSS>.<12-char-sha> in BOTH
# build scripts; the second-resolution UTC stamp is the ordering key, the sha
# is identification only. EGL-107-D1: the script-shape greps skip on the
# extracted kit (scripts absent there); the dpkg-ordering pins below stay.
if [[ "$HAVE_BUILD_DEB" == 1 && "$HAVE_BUILD_TARBALL" == 1 ]]; then
grep -q "%Y%m%d%H%M%S" "$DEBSH" && grep -q "rev-parse --short=12" "$DEBSH" \
    && a22 pass || a22 fail "EGL-27 build-deb.sh stamps second-resolution + short12"
grep -q "%Y%m%d%H%M%S" "$TARSH" && grep -q "rev-parse --short=12" "$TARSH" \
    && a22 pass || a22 fail "EGL-27 build-tarball.sh stamps second-resolution + short12"
if ! grep -q "%Y%m%d')." "$DEBSH" && ! grep -q "%Y%m%d')." "$TARSH"; then
    a22 pass
else
    a22 fail "EGL-27 old date-only stamp still present"
fi
else
    skip "$PKG_SKIP_TAG" "EGL-27 build-script stamp-shape greps — packaging/build-*.sh are not on this tree (extracted kit)"
fi

# The point of the fix: two stamps from the NEW scheme, second timestamp
# later, must always compare lt — including the same-day rebuild case
# that DOWNGRADED under the old hex-suffix scheme. Synthetic shas are
# chosen so the OLD scheme's lexical order is inverted (2... < e...) to
# pin the regression. EGL-72-D4: both literals carry the 0.1.0 base
# (the synthetic pair pins same-base timestamp monotonicity).
v27_older="0.1.0+git20260911040000.2b6f0a1c9d3e"
v27_newer="0.1.0+git20260911045959.e05db24d86f0"
# EGL-342-D6: derive the previous release base from VERSION_BASE. The
# cycle marker `<X.Y.Z>-dev` (EGL-342-D1) is the ONLY accepted suffix and
# is stripped before the anchored N.N.N match; any other suffix (e.g.
# `-dirty`) or a below-floor base (0.0.x) returns nonzero (fail closed).
e273_prev_base() { # <base> -> previous base on stdout; rc 1 = cannot derive
    local raw="${1-}" core=""
    case "$raw" in
        *-dev) core="${raw%-dev}" ;;
        *)     core="$raw" ;;
    esac
    [[ "$core" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || return 1
    if (( BASH_REMATCH[2] > 0 )); then
        printf '%s\n' "${BASH_REMATCH[1]}.$((BASH_REMATCH[2]-1)).${BASH_REMATCH[3]}"
    elif (( BASH_REMATCH[1] > 0 )); then
        printf '%s\n' "$((BASH_REMATCH[1]-1)).0.0"
    else
        return 1
    fi
}
if command -v dpkg >/dev/null 2>&1; then
    if dpkg --compare-versions "$v27_older" lt "$v27_newer"; then
        a22 pass
    else
        a22 fail "EGL-27 new scheme not monotonic under dpkg ordering"
    fi
    # EGL-273: cross-base ordering derived from VERSION_BASE — a base
    # bump alone (same timestamp, same sha — worst case) must still
    # compare as an upgrade; a release bump needs no test edit
    # (replaces the per-release literal pairs, EGL-72-D4 .. EGL-242-D8).
    # EGL-342-D6: the cycle marker `-dev` is stripped before the anchored
    # N.N.N match; every other suffix still fails closed.
    e273_base="$(tr -d ' \t\n' < "$TREE_ROOT/VERSION_BASE" 2>/dev/null || true)"
    e273_prev="$(e273_prev_base "$e273_base" 2>/dev/null || true)"
    if [[ -z "$e273_prev" ]]; then
        a22 fail "EGL-273 cross-base check: cannot derive a previous base from VERSION_BASE '$e273_base' (EGL-164-D1 N.N.N shape, optional -dev marker)"
    elif dpkg --compare-versions "${e273_prev}+git20260924192516.76f1e51d345a" \
            lt "${e273_base}+git20260924192516.76f1e51d345a"; then
        a22 pass
    else
        a22 fail "EGL-273 derived cross-base stamp not an upgrade under dpkg ordering ($e273_prev -> $e273_base)"
    fi
    # EGL-342-D6: derivation accept/reject matrix — the bare base and the
    # chosen `-dev` marker derive minor-1; `-dirty`/unknown suffixes and a
    # below-floor base (no previous base exists) fail closed.
    for e273_case in \
        '0.9.0|0.8.0|bare N.N.N accepted' \
        '0.9.0-dev|0.8.0|-dev marker stripped' \
        '0.8.0-dirty||-dirty fails closed' \
        '0.9.0-rc1||unknown suffix fails closed' \
        '0.0.1||prev floor fails closed'
    do
        IFS='|' read -r e273_in e273_want e273_desc <<< "$e273_case"
        if e273_got="$(e273_prev_base "$e273_in")"; then
            [[ -n "$e273_want" && "$e273_got" == "$e273_want" ]] \
                && a22 pass \
                || a22 fail "EGL-342 derivation: $e273_desc ('$e273_in' -> '$e273_got', want '${e273_want:-failure}')"
        else
            [[ -z "$e273_want" ]] && a22 pass \
                || a22 fail "EGL-342 derivation: $e273_desc ('$e273_in' failed, want '$e273_want')"
        fi
    done
else
    skip "dpkg absent" "EGL-27 dpkg not available; skipping compare-versions assert"
fi

# A real build stamps the artifact with the new scheme (the output name is
# fixed, so the stamp is read from the build-log line). EGL-164: the
# live-base pin derives from VERSION_BASE (shape B). EGL-273: the cross-base
# dpkg-ordering check also derives its previous base from VERSION_BASE,
# replacing the per-release literal pairs (EGL-72-D4, EGL-82-D4, EGL-88-D8,
# EGL-118-D8, EGL-135-D8, EGL-188-D8, EGL-204-D8, EGL-242-D8).
# EGL-80-L8: the stamp embeds the git commit; without .git (exported
# snapshot) build-tarball falls back to 'unknown' (named SKIP, EGL-74).
# Full assert runs in the private tree and public git clones.
b27="$p22/egl27"; rm -rf "$b27"; mkdir -p "$b27"
if [[ "$HAVE_BUILD_TARBALL" == 0 ]]; then
    # EGL-107-D1: the producer is absent (extracted kit) — the shape
    # cause names the real reason; .git shape is irrelevant here.
    skip "$PKG_SKIP_TAG" "EGL-27 tarball stamp assert — packaging/build-tarball.sh is not on this tree (extracted kit)"
elif [[ ! -d "$TREE_ROOT/.git" ]]; then
    skip "git-metadata absent" "EGL-27 tarball stamp assert needs .git metadata (absent in exported/staged trees); build-tarball falls back to 'unknown' by design"
else
    t27_rc=0
    env EGRESSLOCK_TARBALL_OUT="$b27/k.tgz" "$TARSH" >"$b27/log" 2>&1 || t27_rc=$?
    # EGL-164: the live-base pin derives from VERSION_BASE — a bump
    # needs no test edit here.
    base164="$(tr -d ' \t\n' < "$TREE_ROOT/VERSION_BASE" 2>/dev/null || true)"
    if [[ -z "$base164" ]]; then
        a22 fail "EGL-164 VERSION_BASE missing/empty at $TREE_ROOT/VERSION_BASE — derived live-base pin cannot run"
        base164="IMPOSSIBLE_BASE_EGL_164"   # never matches; downstream assert stays fail-closed
    fi
    # EGL-164-D1 / EGL-342-D7: the base is N.N.N, optionally carrying the
    # `-dev` cycle marker — escape only '.'. Inside double quotes
    # \\+ / \\. yield \+ / \. in the ERE — byte-identical to the old
    # hardcoded literal (the EGL-188-D8 shape); a maintainer-written base
    # could only widen the match (in-repo, reviewed file; accepted,
    # EGL-164-D1). The derived regex already matches a marked base
    # (e.g. `0.9.0-dev\+git…`), so no code change is needed here.
    re164="$(printf '%s' "$base164" | sed 's/\./\\./g')\\+git[0-9]{14}\\.[0-9a-f]{12}(-dirty)?"
    v27_real="$(grep -oE "$re164" "$b27/log" | head -1)"
    [[ "$t27_rc" == 0 && -f "$b27/k.tgz" && -n "$v27_real" ]] \
        && a22 pass || a22 fail "EGL-27 tarball build stamps new scheme (rc=$t27_rc, log: $(cat "$b27/log"))"
fi

# D2: the warn is warn-only — build-deb.sh must print the version and
# must not gate on dpkg-query (builds succeed without it). The compare
# path only fires when an installed package exists; here assert the
# code shape (echo + dpkg-query + --compare-versions ... ge + stderr
# WARNING) rather than an installed package in the test container.
if [[ "$HAVE_BUILD_DEB" == 1 ]]; then
grep -q 'build-deb: version \$version' "$DEBSH" \
    && grep -q "dpkg-query -W -f='\${Version}' egresslock" "$DEBSH" \
    && grep -q 'dpkg --compare-versions "\$installed" ge "\$version"' "$DEBSH" \
    && grep -q 'WARNING - installed egresslock' "$DEBSH" \
    && a22 pass || a22 fail "EGL-27 build-deb.sh prints version + downgrade warn (D2)"
else
    skip "$PKG_SKIP_TAG" "EGL-27 build-deb warn-shape grep — packaging/build-deb.sh is not on this tree (extracted kit)"
fi

# --- EGL-72: VERSION_BASE 0.1.0 + release-aware stamps ---------------------
# D1: one VERSION_BASE at the repo root, fail-closed in all three
# scripts. D3: both VERSION stamps carry a `version:` line; the tarball
# ships VERSION_BASE + stage-only KIT_VERSION (the KIT_VERSION→version:
# assert lives in the tarball-install section above, before the
# uninstall removes the prefix). D4: the base asserts + pins.
[[ -s "$TREE_ROOT/VERSION_BASE" ]] \
    && a22 pass || a22 fail "EGL-72 VERSION_BASE exists at the repo root"
# EGL-72-D3 stage/tarball VERSION consumers (EGL-107-D1: skip with the
# producers on the extracted kit; the install-kit stamp assert stays).
if [[ "$HAVE_BUILD_DEB" == 1 ]]; then
grep -q '^version: ' "$p22/stage/usr/lib/egresslock/VERSION" \
    && a22 pass || a22 fail "EGL-72 deb VERSION stamp has a version: line"
else
    skip "$PKG_SKIP_TAG" "EGL-72 deb-stage VERSION stamp assert — packaging/build-deb.sh is not on this tree (extracted kit)"
fi
grep -q '^version: ' "$OPT/VERSION" \
    && a22 pass || a22 fail "EGL-72 install-kit VERSION stamp has a version: line"
if [[ "$HAVE_BUILD_TARBALL" == 1 ]]; then
[[ -f "$p22/x/egresslock/VERSION_BASE" && -f "$p22/x/egresslock/KIT_VERSION" ]] \
    && a22 pass || a22 fail "EGL-72 tarball ships VERSION_BASE + KIT_VERSION"
else
    skip "$PKG_SKIP_TAG" "EGL-72 tarball VERSION_BASE/KIT_VERSION assert — packaging/build-tarball.sh is not on this tree (extracted kit)"
fi

# EGL-382: the AppArmor profile-dir hook is test-only. Without the flag
# the production /etc/apparmor.d is read, so the sentinel fixture path
# is never named. EGL-390: the profiles-listing hook is different — a
# non-root run without the flag still honors the copied listing, so pin
# the fixture-derived enforcement and label rows (not only the profile
# file name).
mkdir -p "$aa22/neg-aad/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/neg-aad/usr.bin.pasta"
: > "$aa22/neg-aad/local/usr.bin.pasta"
o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/neg-aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$o" == *"pasta profile:"* && "$o" != *"$aa22/neg-aad"* \
    && "$o" == *"pasta enforcement: enforced"* \
    && "$o" == *"podman label: labeled"* ]] \
    && a22 pass || a22 fail "apparmor dir hook ignored without the test flag; profiles listing honored non-root (rc=$rc, out: $o)"

# EGL-390: EGRESSLOCK_APPARMOR_PROFILES is honored only for non-root or
# test mode; a production root run reads the kernel listing. Fake root
# (`id -u` -> 0) with isolated fixtures, compared against an unset
# control so a host-dependent live listing cannot decide the result.
aa390="$aa22/bin390"
mkdir -p "$aa390" "$aa22/home390"
cat > "$aa390/id" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "-u" ]]; then
    echo 0
    exit 0
fi
if [[ "${1:-}" == "cacct" ]]; then
    exit 0
fi
exec /usr/bin/id "$@"
EOF
cat > "$aa390/getent" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "passwd" && "\$2" == "cacct" ]]; then
    printf 'cacct:x:1000:1000::%s:/bin/sh\n' "$aa22/home390"
    exit 0
fi
exec /usr/bin/getent "\$@"
EOF
chmod +x "$aa390/id" "$aa390/getent"
# Root check: fixture must not steer; the output matches the unset control.
o390_ctl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_APPARMOR_PROFILES \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" "$SKIT" --apparmor-check 2>&1)"; rc390_ctl=$?
o390_neg="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc390_neg=$?
# EGL-491-D7: equal modulo the ignored-hook warnings, which are pinned.
o390_ctls="$(printf '%s\n' "$o390_ctl" | strip_egl491_warnings)"
o390_negs="$(printf '%s\n' "$o390_neg" | strip_egl491_warnings)"
[[ "$rc390_neg" == "$rc390_ctl" && "$o390_negs" == "$o390_ctls" \
    && "$o390_neg" == *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored: it is a test-harness override and requires EGRESSLOCK_KIT_ALLOW_NON_ROOT=1; the production default applies."* \
    && "$o390_ctl" == *"EGRESSLOCK_APPARMOR_D is set but ignored"* \
    && "$o390_ctl" != *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored"* ]] \
    && a22 pass || a22 fail "EGL-390 profiles hook ignored on a root check without the test flag (rc=$rc390_neg, out: $o390_neg)"
# Test mode honors the same fixture (the positive control for the row above).
o390_pos="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    PATH="$aa390:$aa22/bin:$PATH" EGRESSLOCK_SHARE="$aa22/share" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc390_pos=$?
[[ "$o390_pos" == *"pasta enforcement: enforced"* \
    && "$o390_pos" == *"podman label: labeled"* ]] \
    && a22 pass || a22 fail "EGL-390 profiles hook honored with the test flag (rc=$rc390_pos, out: $o390_pos)"
# Root add: a `profiles.none` fixture (would skip) must not steer the
# decision; the no-snippet share keeps a broken gate write-free.
o390_actl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_APPARMOR_PROFILES \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" "$SKIT" --prefix "$aa22/nosnippet" --apparmor-add 2>&1)"; rc390_actl=$?
o390_aneg="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.none" "$SKIT" --prefix "$aa22/nosnippet" --apparmor-add 2>&1)"; rc390_aneg=$?
# EGL-491-D7: equal modulo the ignored-hook warnings, which are pinned.
o390_actls="$(printf '%s\n' "$o390_actl" | strip_egl491_warnings)"
o390_anegs="$(printf '%s\n' "$o390_aneg" | strip_egl491_warnings)"
[[ "$rc390_aneg" == "$rc390_actl" && "$o390_anegs" == "$o390_actls" \
    && "$o390_aneg" == *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored: it is a test-harness override and requires EGRESSLOCK_KIT_ALLOW_NON_ROOT=1; the production default applies."* \
    && "$o390_actl" == *"EGRESSLOCK_APPARMOR_D is set but ignored"* \
    && "$o390_actl" != *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored"* ]] \
    && a22 pass || a22 fail "EGL-390 profiles hook does not steer a root add without the test flag (rc=$rc390_aneg, out: $o390_aneg)"
# R-EGL-390-2 F3: the unknown-listing refuse names the RESOLVED listing,
# not a fresh env expansion. Fake root plus a grep stub that reproduces
# the documented EACCES on the kernel listing (the suite's directory
# fixture does the same for a copied listing): a fixture directory that
# would itself be unreadable must not be named — the line carries the
# kernel path the resolver chose.
aa390p="$aa22/bin390p"
mkdir -p "$aa390p"
cat > "$aa390p/id" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "-u" ]]; then
    echo 0
    exit 0
fi
exec /usr/bin/id "$@"
EOF
cat > "$aa390p/grep" <<'EOF'
#!/usr/bin/env bash
# Force only the kernel listing read to look like EACCES (grep rc 2);
# every other grep is the real binary.
for a in "$@"; do
    if [[ "$a" == "/sys/kernel/security/apparmor/profiles" ]]; then
        exit 2
    fi
done
exec /usr/bin/grep "$@"
EOF
chmod +x "$aa390p/id" "$aa390p/grep"
o390_ref="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    PATH="$aa390p:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles-dir" "$SKIT" --apparmor-add 2>&1)"; rc390_ref=$?
[[ "$rc390_ref" == 1 \
    && "$o390_ref" == *"(/sys/kernel/security/apparmor/profiles unreadable by this user"* \
    && "$o390_ref" != *"$aa22/profiles-dir"* ]] \
    && a22 pass || a22 fail "EGL-390 unknown-listing refuse names the resolved kernel path, never the fixture (rc=$rc390_ref, out: $o390_ref)"
# Root account preamble: same rule (the hint is driven by the listing read).
o390_pctl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_APPARMOR_PROFILES \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc390_pctl=$?
o390_pneg="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    PATH="$aa390:$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc390_pneg=$?
# EGL-491-D7: equal modulo the ignored-hook warnings, which are pinned.
# The preamble reads the profiles listing (not the profile dir), so the
# PROFILES warning is the one it must add.
o390_pctls="$(printf '%s\n' "$o390_pctl" | strip_egl491_warnings)"
o390_pnegs="$(printf '%s\n' "$o390_pneg" | strip_egl491_warnings)"
[[ "$rc390_pneg" == "$rc390_pctl" && "$o390_pnegs" == "$o390_pctls" \
    && "$o390_pneg" == *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored: it is a test-harness override and requires EGRESSLOCK_KIT_ALLOW_NON_ROOT=1; the production default applies."* \
    && "$o390_pctl" != *"EGRESSLOCK_APPARMOR_PROFILES is set but ignored"* ]] \
    && a22 pass || a22 fail "EGL-390 profiles hook does not steer a root account preamble (rc=$rc390_pneg, out: $o390_pneg)"
# Test mode honors the fixture on the preamble (positive control).
o390_ppos="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    PATH="$aa390:$aa22/bin:$PATH" EGRESSLOCK_SHARE="$aa22/share" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" init --prefix "$SKITP" --account cacct --from "$a18d/plain.conf" 2>&1)"; rc390_ppos=$?
[[ "$o390_ppos" == *"hint: the podman network helper (pasta) is confined by AppArmor"* ]] \
    && a22 pass || a22 fail "EGL-390 profiles hook honored by the account preamble with the test flag (rc=$rc390_ppos, out: $o390_ppos)"

section_end arc22

# --- EGL-39: install-kit.sh AppArmor advisory one-liner (D39-2) -----------
# Separate prefix/unit dirs so the a16 state asserts stay untouched.
section_begin a39 "EGL-39 install-kit advisory"
a39() { assert "$@"; }
ik39="$STATE/ik39"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$ik39/units" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" EGRESSLOCK_PATH_BINDIR="$ik39/wbin" EGRESSLOCK_PATH_SBINDIR="$ik39/wbin" \
    "$KIT" --prefix "$ik39/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"AppArmor: podman labeled; confirm pasta compatibility: sudo $ik39/opt/egresslock-setup apparmor check"* ]] \
    && a39 pass || a39 fail "EGL-39 install-kit labeled advisory (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$ik39/units" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" EGRESSLOCK_PATH_BINDIR="$ik39/wbin" EGRESSLOCK_PATH_SBINDIR="$ik39/wbin" \
    "$KIT" --prefix "$ik39/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"AppArmor: this host's podman is not confined by AppArmor, so no extra AppArmor rule is needed — no action needed."* ]] \
    && a39 pass || a39 fail "EGL-39 install-kit unlabeled advisory (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$ik39/units" \
    EGRESSLOCK_APPARMOR_PROFILES="$ik39/no-such-profiles" EGRESSLOCK_PATH_BINDIR="$ik39/wbin" EGRESSLOCK_PATH_SBINDIR="$ik39/wbin" \
    "$KIT" --prefix "$ik39/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" != *"AppArmor:"* ]] \
    && a39 pass || a39 fail "EGL-39 install-kit silent on UNKNOWN (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$ik39/units" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.hats" EGRESSLOCK_PATH_BINDIR="$ik39/wbin" EGRESSLOCK_PATH_SBINDIR="$ik39/wbin" \
    "$KIT" --prefix "$ik39/opt" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"AppArmor: this host's podman is not confined by AppArmor, so no extra AppArmor rule is needed — no action needed."* ]] \
    && a39 pass || a39 fail "EGL-39 install-kit hats do not count as labeled (rc=$rc, out: $o)"
# EGL-390: the installer's advisory read is test-mode only. That leg —
# fake root, flag off, hooks set, byte-compared against an unset control —
# cannot run hermetically on the non-root host battery once EGL-434 gates
# the unit/PATH hooks (the ignored hooks would target the real /etc and
# /usr/local). It moved to the VM fault case A-kit-path-hooks-root (real
# root in the guest), together with the EGL-434 default-target pin.
section_end a39

# --- EGL-434: the kit unit/PATH hooks are test-mode only -------------------
# D1/D3: with EGRESSLOCK_KIT_ALLOW_NON_ROOT unset (or not exactly 1), an
# inherited EGRESSLOCK_UNIT_DIR / EGRESSLOCK_PATH_BINDIR /
# EGRESSLOCK_PATH_SBINDIR is ignored and the production paths are used
# exactly as if the variables were unset. The negative legs below run as
# fake root on the host (the uninstall/install root guards read `id -u`),
# with a selective rm shim so the real defaults are never touched; the
# successful-root default-target install lives in VM case
# A-kit-path-hooks-root.
section_begin egl434 "EGL-434 kit path hooks are test-mode only"
e434() { assert "$@"; }
e434d="$STATE/egl434"; rm -rf "$e434d"; mkdir -p "$e434d"

# 0. F1 (R-EGL-434-3; reopened R-EGL-434-6, R-EGL-434-8): the direct
#    root refusals — this file's and tests/run.sh's — must read the
#    kernel's effective UID (/proc/self/status), never a caller-controlled
#    source, and run before any side effect. Two bypasses were real: a
#    PATH `id` shim reporting a non-root uid (R-EGL-434-6) and an
#    environment-supplied `EUID` (R-EGL-434-8) — bash imports it at
#    startup. Pins: actual uid 0 (user namespace) with an inherited `id`
#    reporting a non-root uid, with a failing `id`, and with a forged
#    `EUID=<nonzero>` must all refuse; an ordinary non-root run with an
#    `id` reporting 0/failing or a forged `EUID=0` must not be refused
#    (an `id -u`/`EUID` guard would wrongly refuse). EGL434_ROOT_GUARD_PROBE
#    =1 bounds every probe: the child stops right after the guard, before
#    `source lib.sh` or any HOME side effect, and prints
#    `guard-pass euid=<n>`, so a refusal prints neither the marker nor
#    creates `$HOME/.config`. `env -u EUID` is carried into every other
#    probe child so those pins do not depend on the caller's EUID.
#    Mutation-red: restore `$(id -u)` -> the uid-0 id probes stop refusing
#    (and the non-root id=0 probe starts); restore `$EUID` -> the uid-0
#    forged-EUID probes stop refusing (and the non-root EUID=0 probe
#    starts); delete the guard -> probe children print the marker.
e434g="$e434d/root-guard"
rm -rf "$e434g"
mkdir -p "$e434g/home" "$e434g/id-nonroot" "$e434g/id-root" "$e434g/id-fail"
printf '#!/usr/bin/env bash\nif [[ "${1:-}" == "-u" ]]; then echo 1002; exit 0; fi\nexec /usr/bin/id "$@"\n' \
    > "$e434g/id-nonroot/id"
printf '#!/usr/bin/env bash\nif [[ "${1:-}" == "-u" ]]; then echo 0; exit 0; fi\nexec /usr/bin/id "$@"\n' \
    > "$e434g/id-root/id"
printf '#!/usr/bin/env bash\necho "id: simulated failure" >&2\nexit 1\n' \
    > "$e434g/id-fail/id"
chmod +x "$e434g"/id-*/id

# Expected uid for the guard-pass markers: the kernel's effective UID
# (the guard source), not this shell's `EUID`, which is forged if the
# battery itself was launched with one.
e434_uid=""
while IFS=$' \t' read -r e434_k e434_r e434_e e434_s e434_f; do
    if [[ "$e434_k" == "Uid:" ]]; then e434_uid="$e434_e"; break; fi
done < /proc/self/status

# Ordinary non-root execution: a lying or failing `id` must not change
# the guard's decision (the kernel uid is the real caller's uid).
e434o="$(env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" PATH="$e434g/id-root:$PATH" \
    bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "non-root run is not refused by an id shim reporting uid 0 (rc=$e434rc, out: $e434o)"
e434o="$(env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" PATH="$e434g/id-fail:$PATH" \
    bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "non-root run is not refused by a failing id command (rc=$e434rc, out: $e434o)"
e434o="$(env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" PATH="$e434g/id-root:$PATH" \
    bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"run.sh guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "run.sh is not refused by an id shim reporting uid 0 (rc=$e434rc, out: $e434o)"
e434o="$(env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" PATH="$e434g/id-fail:$PATH" \
    bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"run.sh guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "run.sh is not refused by a failing id command (rc=$e434rc, out: $e434o)"

# R-EGL-434-8: an environment-supplied EUID is not a UID source either.
# On an ordinary non-root run, a forged `EUID=0` must not cause a refusal
# (an EUID guard over-refused here).
e434o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EUID=0 EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" \
    bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "non-root run is refused by a forged EUID=0 (rc=$e434rc, out: $e434o)"
e434o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EUID=0 EGL434_ROOT_GUARD_PROBE=1 \
    HOME="$e434g/home" \
    bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && "$e434o" == *"run.sh guard-pass euid=$e434_uid"* \
    && "$e434o" != *"FAIL run tests as an unprivileged account"* \
    && ! -e "$e434g/home/.config" ]] \
    && e434 pass || e434 fail "run.sh is refused by a forged EUID=0 (rc=$e434rc, out: $e434o)"

# Actual uid 0: user-namespace root is the kernel's uid 0 for the guard.
# The namespace root maps to this unprivileged caller, so even a regressed
# guard cannot write host root-owned paths; the probe seam stops it
# before lib.sh. The inherited `id` lies in the id cases and the EUID
# cases forge the environment value, so a PATH- or env-sourced guard
# would pass these.
if command -v unshare >/dev/null 2>&1 && unshare -r true 2>/dev/null; then
    e434o="$(unshare -r env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" PATH="$e434g/id-nonroot:$PATH" \
        bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"test-kit.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "test-kit.sh: actual uid 0 is refused despite an id shim reporting uid 1002 (rc=$e434rc, out: $e434o)"
    e434o="$(unshare -r env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" PATH="$e434g/id-fail:$PATH" \
        bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"test-kit.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "test-kit.sh: actual uid 0 is refused when id fails (rc=$e434rc, out: $e434o)"
    e434o="$(unshare -r env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" PATH="$e434g/id-nonroot:$PATH" \
        bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"run.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "run.sh: actual uid 0 is refused despite an id shim reporting uid 1002 (rc=$e434rc, out: $e434o)"
    e434o="$(unshare -r env -u EUID -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" PATH="$e434g/id-fail:$PATH" \
        bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"run.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "run.sh: actual uid 0 is refused when id fails (rc=$e434rc, out: $e434o)"
    # R-EGL-434-8: a forged environment EUID must not mask actual uid 0.
    e434o="$(unshare -r env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EUID=1002 EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" \
        bash "$TREE_ROOT/tests/test-kit.sh" 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"test-kit.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "test-kit.sh: actual uid 0 is refused despite a forged EUID=1002 (rc=$e434rc, out: $e434o)"
    e434o="$(unshare -r env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EUID=1002 EGL434_ROOT_GUARD_PROBE=1 \
        HOME="$e434g/home" \
        bash "$TREE_ROOT/tests/run.sh" --harness docs 2>&1)"; e434rc=$?
    [[ "$e434rc" == 2 \
        && "$e434o" == *"run.sh: FAIL run tests as an unprivileged account"* \
        && "$e434o" != *"guard-pass"* \
        && ! -e "$e434g/home/.config" ]] \
        && e434 pass || e434 fail "run.sh: actual uid 0 is refused despite a forged EUID=1002 (rc=$e434rc, out: $e434o)"
else
    skip "namespace-unavailable" "actual uid-0 root-guard negatives skipped: unshare -r unavailable"
fi

# Fake root: every command but `id` is the real one. The test process is
# still unprivileged, so the gated default targets (/etc, /usr/local) are
# not writable even though the scripts' root guard sees uid 0.
e434_fakeroot="$e434d/fakeroot"
mkdir -p "$e434_fakeroot"
cat > "$e434_fakeroot/id" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "-u" ]]; then
    echo 0
    exit 0
fi
if [[ "${1:-}" == "uacct" ]]; then
    exit 0
fi
exec /usr/bin/id "$@"
EOF
chmod +x "$e434_fakeroot/id"

# A real-kit prefix (the four markers) the uninstall/install runs may
# remove/deploy; never the shared $OPT/$UNITS fixtures.
e434_mkprefix() { # <dir>
    local p="$1"
    mkdir -p "$p/gateway"
    install -m 0755 "$TREE_ROOT/egresslock" "$p/egresslock"
    : > "$p/egresslock-verify"
    : > "$p/VERSION"
    : > "$p/gateway/Containerfile"
}

# 1. Uninstall negative: fake root, hooks set, no flag. The selective rm
#    shim logs every removal target and runs the real rm only when every
#    operand is under $STATE, so the default /etc target is logged but
#    never touched and the fixture hook sentinels can prove the gate.
e434u="$e434d/uninstall"
e434_mkprefix "$e434u/prefix"
mkdir -p "$e434u/bin" "$e434u/units" "$e434u/wbin" "$e434u/wsbin"
cat > "$e434u/bin/rm" <<EOF
#!/usr/bin/env bash
printf 'rm %s\n' "\$*" >> "$e434u/rm.log"
for _a in "\$@"; do
    case "\$_a" in
        -*) continue ;;
        "$STATE"/*|./*) ;;
        *) exit 0 ;;
    esac
done
exec /bin/rm "\$@"
EOF
chmod +x "$e434u/bin/rm"
: > "$e434u/units/egresslock-verify@.service"
: > "$e434u/units/egresslock-verify@.timer"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec true\n' "$e434u/prefix" \
    > "$e434u/wbin/egresslock"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec true\n' "$e434u/prefix" \
    > "$e434u/wsbin/egresslock-setup"
: > "$e434u/rm.log"
e434o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT PATH="$e434u/bin:$e434_fakeroot:$PATH" \
    EGRESSLOCK_UNIT_DIR="$e434u/units" \
    EGRESSLOCK_PATH_BINDIR="$e434u/wbin" EGRESSLOCK_PATH_SBINDIR="$e434u/wsbin" \
    "$UKIT" --prefix "$e434u/prefix" 2>&1)"; e434rc=$?
e434log="$(cat "$e434u/rm.log" 2>/dev/null || true)"
[[ "$e434rc" == 0 && ! -e "$e434u/prefix" \
    && -e "$e434u/units/egresslock-verify@.service" \
    && -e "$e434u/units/egresslock-verify@.timer" \
    && -e "$e434u/wbin/egresslock" && -e "$e434u/wsbin/egresslock-setup" \
    && "$e434log" == *"/etc/systemd/system/egresslock-verify@.service"* \
    && "$e434log" == *"/etc/systemd/system/egresslock-verify@.timer"* \
    && "$e434log" != *"$e434u/units"* \
    && "$e434log" != *"$e434u/wbin"* && "$e434log" != *"$e434u/wsbin"* ]] \
    && e434 pass || e434 fail "uninstall ignores the unit/PATH hooks without the flag (rc=$e434rc, out: $e434o, rm log: $e434log)"
# Positive control: the same hooks are live with the flag (the harness
# contract), so the sentinels are the ones removed.
e434_mkprefix "$e434u/prefix"
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$e434u/bin:$PATH" \
    EGRESSLOCK_UNIT_DIR="$e434u/units" \
    EGRESSLOCK_PATH_BINDIR="$e434u/wbin" EGRESSLOCK_PATH_SBINDIR="$e434u/wsbin" \
    "$UKIT" --prefix "$e434u/prefix" 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && ! -e "$e434u/prefix" \
    && ! -e "$e434u/units/egresslock-verify@.service" \
    && ! -e "$e434u/units/egresslock-verify@.timer" \
    && ! -e "$e434u/wbin/egresslock" && ! -e "$e434u/wsbin/egresslock-setup" ]] \
    && e434 pass || e434 fail "uninstall honors the unit/PATH hooks with the flag (rc=$e434rc, out: $e434o)"

# 2. Installer negative (F3, R-EGL-434-3): fake namespace root, no flag,
#    hooks set. The run happens in a private mount namespace whose
#    "production" destinations (/etc/systemd/system, /usr/local/{bin,sbin})
#    are writable fixture dirs, so it can COMPLETE: asserting a finished
#    install that wrote only the defaults and left the hook dirs empty
#    cannot go vacuous behind an earlier co-install/foreign-wrapper guard
#    (the R-EGL-434-3 F3 failure mode). Host product leftovers are
#    neutralized inside the namespace (dpkg-query shim; overmounts for a
#    host /usr/lib/egresslock and /usr/bin/egresslock) so a developer
#    host with the .deb installed runs the same leg.
#    Mutation-red (each gate isolated, verified): drop only the unit gate
#    -> the unit templates land in hook-units and default-units stays
#    empty; drop only the bin or sbin gate -> that wrapper lands in its
#    hook dir and the matching default wrapper is missing.
e434i="$e434d/install-ns"; rm -rf "$e434i"
mkdir -p "$e434i/default-units" "$e434i/default-bin" "$e434i/default-sbin" \
         "$e434i/hook-units" "$e434i/hook-bin" "$e434i/hook-sbin" \
         "$e434i/opt" "$e434i/shim" "$e434i/empty-lib"
printf '#!/usr/bin/env bash\n# the namespace leg pins destinations, not co-install policy\nexit 1\n' \
    > "$e434i/shim/dpkg-query"
chmod +x "$e434i/shim/dpkg-query"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=/host-foreign\nexec true\n' \
    > "$e434i/ub-marker"
cat > "$e434i/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: uid 0 with fixture bind mounts over the three
# production destinations. $1 = fixture root, $2 = install-kit.sh.
set -euo pipefail
d=$1; kit=$2
mkdir -p /etc/systemd/system /usr/local/bin /usr/local/sbin
mount --bind "$d/default-units" /etc/systemd/system
mount --bind "$d/default-bin" /usr/local/bin
mount --bind "$d/default-sbin" /usr/local/sbin
if [[ -e /usr/lib/egresslock ]]; then
    mount --bind "$d/empty-lib" /usr/lib/egresslock
fi
if [[ -e /usr/bin/egresslock ]]; then
    mount --bind "$d/ub-marker" /usr/bin/egresslock
fi
export PATH="$d/shim:$PATH"
exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    EGRESSLOCK_UNIT_DIR="$d/hook-units" \
    EGRESSLOCK_PATH_BINDIR="$d/hook-bin" \
    EGRESSLOCK_PATH_SBINDIR="$d/hook-sbin" \
    "$kit" --prefix "$d/opt"
EOF
chmod +x "$e434i/run.sh"
if command -v unshare >/dev/null 2>&1 && unshare -rm true 2>/dev/null; then
    e434o="$(unshare -rm bash "$e434i/run.sh" "$e434i" "$KIT" 2>&1)"; e434rc=$?
    [[ "$e434rc" == 0 \
        && "$e434o" == *"successfully installed! kit is at: $e434i/opt"* \
        && -f "$e434i/default-units/egresslock-verify@.service" \
        && -f "$e434i/default-units/egresslock-verify@.timer" \
        && -f "$e434i/default-bin/egresslock" \
        && -f "$e434i/default-sbin/egresslock-setup" \
        && "$(grep -c "^ExecStart=$e434i/opt/egresslock-verify$" \
              "$e434i/default-units/egresslock-verify@.service")" == 1 \
        && "$(sed -n 2p "$e434i/default-bin/egresslock")" \
           == "# egresslock-path-wrapper prefix=$e434i/opt" \
        && -z "$(ls -A "$e434i/hook-units")" \
        && -z "$(ls -A "$e434i/hook-bin")" \
        && -z "$(ls -A "$e434i/hook-sbin")" ]] \
        && e434 pass || e434 fail "no-flag install writes only the production targets, never the ignored hooks (rc=$e434rc, out: $e434o)"
else
    skip "namespace-unavailable" "installer default-target negative skipped: unshare -rm unavailable"
fi
# Positive control (test mode): the very same hooks are the write targets.
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$e434i/hook-units" \
    EGRESSLOCK_PATH_BINDIR="$e434i/hook-bin" EGRESSLOCK_PATH_SBINDIR="$e434i/hook-sbin" \
    "$KIT" --prefix "$e434i/opt" 2>&1)"; e434rc=$?
[[ "$e434rc" == 0 && -f "$e434i/hook-units/egresslock-verify@.service" \
    && -f "$e434i/hook-units/egresslock-verify@.timer" \
    && -f "$e434i/hook-bin/egresslock" && -f "$e434i/hook-sbin/egresslock-setup" ]] \
    && e434 pass || e434 fail "install honors the unit/PATH hooks with the flag (rc=$e434rc, out: $e434o)"

# 3. Setup negative (read-only doctor, no account): the gated overrides
#    must not steer prefix derivation or the unit-template row. Flag off
#    -> DEFAULT/DEB/UNIT are all ignored: the production /etc probe
#    misses, no hook dir is named and no fixture engine is adopted. Flag
#    on -> the default/deb hooks are live (deb fallback runs), and the
#    explicit UNIT_DIR hook suppresses the fallback.
e434s="$e434d/setup"; rm -rf "$e434s"
mkdir -p "$e434s/hookunits" "$e434s/debunits" "$e434s/hookdead" "$e434s/libdir"
sed "s|__EGRESSLOCK_PREFIX__|$e434s/hookdead|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e434s/hookunits/egresslock-verify@.service"
sed "s|__EGRESSLOCK_PREFIX__|$e434s/libdir|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e434s/debunits/egresslock-verify@.service"
: > "$e434s/hookunits/egresslock-verify@.timer"
: > "$e434s/debunits/egresslock-verify@.timer"
install -m 0755 "$TREE_ROOT/egresslock" "$e434s/libdir/egresslock"
e434o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_ACCOUNT_HOME \
    EGRESSLOCK_UNIT_DIR="$e434s/hookunits" \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$e434s/no-etc-units" \
    EGRESSLOCK_DEB_UNIT_DIR="$e434s/debunits" \
    "$SKIT" --doctor 2>&1)"; e434rc=$?
[[ "$e434o" != *"$e434s/hookunits"* && "$e434o" != *"$e434s/hookdead"* \
    && "$e434o" != *"$e434s/debunits"* ]] \
    && e434 pass || e434 fail "setup ignores the unit/default hooks without the flag (rc=$e434rc, out: $e434o)"
# EGL-456-D6: the DEFAULT/DEB hooks are live with the flag. The DEFAULT
# probe misses and the DEB hook supplies the live template, so the deb
# fallback runs and names the fixture (the no-flag leg above has no
# fixture seam; the root heuristics evidence is VM A-kit-path-hooks-root).
e434o="$(env -u EGRESSLOCK_ACCOUNT_HOME EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$e434s/no-etc-units" \
    EGRESSLOCK_DEB_UNIT_DIR="$e434s/debunits" \
    "$SKIT" --doctor 2>&1)"; e434rc=$?
[[ "$e434o" == *"OK: kit engine: present ($e434s/libdir)"* \
    && "$e434o" == *"OK: unit templates: installed ($e434s/debunits)"* ]] \
    && e434 pass || e434 fail "setup honors the default/deb hooks with the flag (rc=$e434rc, out: $e434o)"
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_UNIT_DIR="$e434s/hookunits" \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$e434s/no-etc-units" \
    EGRESSLOCK_DEB_UNIT_DIR="$e434s/debunits" \
    "$SKIT" --doctor 2>&1)"; e434rc=$?
[[ "$e434o" == *"OK: unit templates: installed ($e434s/hookunits)"* \
    && "$e434o" != *"$e434s/debunits"* && "$e434o" != *"OK: kit engine: present ($e434s/libdir)"* ]] \
    && e434 pass || e434 fail "setup honors the unit hook with the flag (deb fallback suppressed; rc=$e434rc, out: $e434o)"

# 3b. F2 (R-EGL-434-3): the stale-/etc deb-fallback retry must run when
#     the explicit EGRESSLOCK_UNIT_DIR hook is inherited but IGNORED
#     (flag off). Production defaults are fixture-bound in a private
#     mount namespace: /etc is stale (dead prefix), /usr/lib is live.
#     off must equal the hook-unset control (the live deb prefix is
#     adopted); flag-on explicit hook suppresses the retry (the hook's
#     dead prefix is kept). Mutation-red (isolated, R-EGL-434-3 F2):
#     change the retry predicate -z "$unit_dir_override" to
#     -z "${EGRESSLOCK_UNIT_DIR:-}" -> the off row becomes MISSING at the
#     stale prefix and this leg reds.
e434rt="$e434s/retry-ns"; rm -rf "$e434rt"
mkdir -p "$e434rt/stale-units" "$e434rt/deb-units" "$e434rt/hook-units" \
         "$e434rt/dead" "$e434rt/hookdead" "$e434rt/live"
sed "s|__EGRESSLOCK_PREFIX__|$e434rt/dead|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e434rt/stale-units/egresslock-verify@.service"
sed "s|__EGRESSLOCK_PREFIX__|$e434rt/live|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e434rt/deb-units/egresslock-verify@.service"
sed "s|__EGRESSLOCK_PREFIX__|$e434rt/hookdead|g" \
    "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e434rt/hook-units/egresslock-verify@.service"
: > "$e434rt/stale-units/egresslock-verify@.timer"
: > "$e434rt/deb-units/egresslock-verify@.timer"
: > "$e434rt/hook-units/egresslock-verify@.timer"
install -m 0755 "$TREE_ROOT/egresslock" "$e434rt/live/egresslock"
cat > "$e434rt/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: $1 = fixture root, $2 = egresslock-setup, $3 = mode.
set -euo pipefail
d=$1; skit=$2; mode=$3
mkdir -p /etc/systemd/system /usr/lib/systemd/system
mount --bind "$d/stale-units" /etc/systemd/system
mount --bind "$d/deb-units" /usr/lib/systemd/system
case "$mode" in
    unset) exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_UNIT_DIR \
        "$skit" --account root --doctor ;;
    off)   exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
        EGRESSLOCK_UNIT_DIR="$d/hook-units" \
        "$skit" --account root --doctor ;;
    on)    exec env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
        EGRESSLOCK_UNIT_DIR="$d/hook-units" \
        "$skit" --account root --doctor ;;
esac
EOF
chmod +x "$e434rt/run.sh"
if command -v unshare >/dev/null 2>&1 && unshare -rm true 2>/dev/null; then
    e434_rtrows() { grep -E '^(OK|PROBLEM): (kit engine|unit templates):' <<<"$1" || true; }
    e434unset="$(unshare -rm bash "$e434rt/run.sh" "$e434rt" "$SKIT" unset 2>&1)"
    e434off="$(unshare -rm bash "$e434rt/run.sh" "$e434rt" "$SKIT" off 2>&1)"
    e434on="$(unshare -rm bash "$e434rt/run.sh" "$e434rt" "$SKIT" on 2>&1)"
    [[ "$(e434_rtrows "$e434off")" == "$(e434_rtrows "$e434unset")" \
        && "$e434off" == *"OK: kit engine: present ($e434rt/live)"* \
        && "$e434off" != *"$e434rt/hook-units"* \
        && "$e434off" != *"$e434rt/stale-units"* ]] \
        && e434 pass || e434 fail "ignored UNIT_DIR does not suppress the stale-/etc deb retry (unset: $(e434_rtrows "$e434unset"), off: $(e434_rtrows "$e434off"))"
    [[ "$e434on" == *"PROBLEM: kit engine: MISSING ($e434rt/hookdead/egresslock)"* \
        && "$e434on" == *"OK: unit templates: installed ($e434rt/hook-units)"* ]] \
        && e434 pass || e434 fail "flag-on explicit UNIT_DIR still suppresses the retry (out: $e434on)"
else
    skip "namespace-unavailable" "stale-/etc retry negative skipped: unshare -rm unavailable"
fi

# EGL-524-D3: run a no-flag selector leg in a fresh private mount
# namespace modeled on e434i. The production destinations are fixture
# binds, a dpkg-query shim reports "not installed", and a host
# /usr/lib/egresslock or non-wrapper /usr/bin/egresslock is overmounted
# with a benign fixture — so the ignored-hook proof does not depend on
# the host being deb-free. e434_sel_ns_prepare writes the per-leg root
# and its run.sh; e434_sel_ns_run executes it (0 = namespace available).
# The availability probe must cover bind capability, not just user
# namespaces: on a host where `unshare -rm` works but `mount --bind` is
# blocked (seccomp/AppArmor/container policy), the leg would otherwise
# red mid-run instead of taking the named namespace-unavailable skip.
e434_sel_ns_available() {
    command -v unshare >/dev/null 2>&1 || return 1
    unshare -rm bash -c '
        set -e
        d=$(mktemp -d)
        mkdir -p "$d/src" "$d/dst"
        mount --bind "$d/src" "$d/dst"
        umount "$d/dst" 2>/dev/null || true
        rm -rf "$d"
    ' 2>/dev/null
}
e434_sel_ns_prepare() { # <root> <prefix>
    local root="$1" prefix="$2"
    rm -rf "$root" "$prefix"
    mkdir -p "$root/default-units" "$root/default-bin" "$root/default-sbin" \
             "$root/shim" "$root/empty-lib"
    printf '#!/usr/bin/env bash\n# the namespace leg pins destinations, not co-install policy\nexit 1\n' \
        > "$root/shim/dpkg-query"
    chmod +x "$root/shim/dpkg-query"
    printf '#!/bin/sh\n# egresslock-path-wrapper prefix=/host-foreign\nexec true\n' \
        > "$root/ub-marker"
    cat > "$root/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: uid 0 with fixture bind mounts over the production
# destinations. $1 = root, $2 = install-kit.sh, $3 = hook variable,
# $4 = hook value, $5 = prefix.
set -euo pipefail
d=$1; kit=$2; hookvar=$3; hookval=$4; prefix=$5
mkdir -p /etc/systemd/system /usr/local/bin /usr/local/sbin
mount --bind "$d/default-units" /etc/systemd/system
mount --bind "$d/default-bin" /usr/local/bin
mount --bind "$d/default-sbin" /usr/local/sbin
if [[ -e /usr/lib/egresslock ]]; then
    mount --bind "$d/empty-lib" /usr/lib/egresslock
fi
if [[ -e /usr/bin/egresslock ]]; then
    mount --bind "$d/ub-marker" /usr/bin/egresslock
fi
export PATH="$d/shim:$PATH"
exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$hookvar=$hookval" \
    "$kit" --prefix "$prefix"
EOF
    chmod +x "$root/run.sh"
}
e434_sel_ns_run() { # <root> <hook-var> <hook-value> <prefix>
    e434_sel_out="$(unshare -rm bash "$1/run.sh" "$1" "$KIT" "$2" "$3" "$4" 2>&1)"; e434_sel_rc=$?
}

# 4. Install selectors (EGL-456-D4): UNIT_SRC / UB_BIN / DEB_LIBDIR are
#    test-only hooks. Each no-flag leg proves the hook is ignored (the
#    run reaches the prefix copy using the production path); each flag-on
#    leg proves the hook is live (the completeness check or a host-leftover
#    refusal fires). The real-root success path is VM
#    A-kit-path-hooks-root.
e434sel="$e434d/selectors"; rm -rf "$e434sel"
mkdir -p "$e434sel/decoy-systemd" "$e434sel/ub" "$e434sel/libdir"
mkdir -p "$e434sel/opt-src-neg" "$e434sel/opt-src-pos" \
         "$e434sel/opt-ub-neg" "$e434sel/opt-ub-pos" \
         "$e434sel/opt-deb-neg" "$e434sel/opt-deb-pos"
# Decoy UNIT_SRC: service only, no timer -> incomplete tree.
: > "$e434sel/decoy-systemd/egresslock-verify@.service"
e434o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT PATH="$e434_fakeroot:$PATH" \
    EGRESSLOCK_UNIT_SRC="$e434sel/decoy-systemd" \
    "$KIT" --prefix "$e434sel/opt-src-neg" 2>&1)"; e434rc=$?
[[ -f "$e434sel/opt-src-neg/egresslock" && "$e434o" != *"incomplete kit tree"* \
    && "$e434o" != *"$e434sel/decoy-systemd"* ]] \
    && e434 pass || e434 fail "install ignores UNIT_SRC without the flag (rc=$e434rc, out: $e434o)"
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$e434_fakeroot:$PATH" \
    EGRESSLOCK_UNIT_SRC="$e434sel/decoy-systemd" \
    "$KIT" --prefix "$e434sel/opt-src-pos" 2>&1)"; e434rc=$?
[[ "$e434rc" == 1 && "$e434o" == *"incomplete kit tree"* \
    && "$e434o" == *"(missing: systemd/egresslock-verify@.timer)"* \
    && ! -e "$e434sel/opt-src-pos/egresslock" ]] \
    && e434 pass || e434 fail "install honors UNIT_SRC with the flag (pre-copy gap; rc=$e434rc, out: $e434o)"
# UB_BIN: a non-wrapper file at the probe path refuses with the flag.
# The no-flag leg runs namespace-bound (EGL-524-D3): its proof is that the
# production default is probed while the hook is ignored, so a host
# /usr/bin/egresslock must not turn a correct production refusal into a red.
printf '#!/bin/sh\n# the deb engine, not a kit PATH wrapper\n' > "$e434sel/ub/egresslock"
chmod 0755 "$e434sel/ub/egresslock"
if e434_sel_ns_available; then
    e434_sel_ns_prepare "$e434sel/ns-ub" "$e434sel/opt-ub-neg"
    e434_sel_ns_run "$e434sel/ns-ub" EGRESSLOCK_UB_BIN "$e434sel/ub/egresslock" "$e434sel/opt-ub-neg"
    [[ -f "$e434sel/opt-ub-neg/egresslock" \
        && "$e434_sel_out" != *"exists and is not an egresslock kit PATH"* \
        && "$e434_sel_out" != *"$e434sel/ub/egresslock"* ]] \
        && e434 pass || e434 fail "install ignores UB_BIN without the flag (rc=$e434_sel_rc, out: $e434_sel_out)"
else
    skip "namespace-unavailable" "UB_BIN no-flag selector leg skipped: unshare -rm or bind mount unavailable"
fi
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$e434_fakeroot:$PATH" \
    EGRESSLOCK_UB_BIN="$e434sel/ub/egresslock" \
    "$KIT" --prefix "$e434sel/opt-ub-pos" 2>&1)"; e434rc=$?
[[ "$e434rc" == 1 \
    && "$e434o" == *"$e434sel/ub/egresslock exists and is not an egresslock kit PATH"* ]] \
    && e434 pass || e434 fail "install honors UB_BIN with the flag (deb-shape refusal; rc=$e434rc, out: $e434o)"
# DEB_LIBDIR: a VERSION marker at the probe path refuses with the flag.
# Same namespace-bound no-flag leg (EGL-524-D3): a production libdir
# leftover is a legitimate host shape, not a hook leak.
: > "$e434sel/libdir/VERSION"
if e434_sel_ns_available; then
    e434_sel_ns_prepare "$e434sel/ns-deb" "$e434sel/opt-deb-neg"
    e434_sel_ns_run "$e434sel/ns-deb" EGRESSLOCK_DEB_LIBDIR "$e434sel/libdir" "$e434sel/opt-deb-neg"
    [[ -f "$e434sel/opt-deb-neg/egresslock" \
        && "$e434_sel_out" != *"an egresslock .deb kit exists"* \
        && "$e434_sel_out" != *"$e434sel/libdir"* ]] \
        && e434 pass || e434 fail "install ignores DEB_LIBDIR without the flag (rc=$e434_sel_rc, out: $e434_sel_out)"
else
    skip "namespace-unavailable" "DEB_LIBDIR no-flag selector leg skipped: unshare -rm or bind mount unavailable"
fi
e434o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$e434_fakeroot:$PATH" \
    EGRESSLOCK_DEB_LIBDIR="$e434sel/libdir" \
    "$KIT" --prefix "$e434sel/opt-deb-pos" 2>&1)"; e434rc=$?
[[ "$e434rc" == 1 \
    && "$e434o" == *"an egresslock .deb kit exists at $e434sel/libdir"* ]] \
    && e434 pass || e434 fail "install honors DEB_LIBDIR with the flag (libdir refusal; rc=$e434rc, out: $e434o)"
section_end egl434

# --- ARC-72: pasta profile resolution (distro-dependent names) -------------
section_begin arc72 "ARC-72 apparmor resolution"
a72() { assert "$@"; }
# Fixtures: the same aa-status/apparmor_parser stubs from the ARC-22 block.
# D1: candidates are usr.bin.pasta then pasta; a "pasta" file that does not
# mention /usr/bin/pasta is skipped; the write target is the local include
# the profile itself names. D2: resolve before any write. D3: after a
# successful reload, point the operator at the account-side netns probe.
# D4: apply refuses (rc 1, no write) with the force-confmiss recovery;
# --remove is file cleanup and stays rc 0 when the profile is missing.
aa72="$STATE/a22aa72"; rm -rf "$aa72"
mkdir -p "$aa72/aad/local" "$aa72/share/apparmor"
cp "$TREE_ROOT/apparmor/usr.bin.pasta.local" "$aa72/share/apparmor/"
run_aa72() { env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa72/share" EGRESSLOCK_APPARMOR_D="$1" \
    EGRESSLOCK_APPARMOR_PROFILES="${AA_PROFILES:-$aa22/profiles}" "$SKIT" "${@:2}"; }

# 11. Only the alt name exists (profile "pasta" incl. <local/pasta>):
#     writes local/pasta, reloads THAT file, prints the D3 confirm line.
printf '/usr/bin/pasta {\n  include <local/pasta>\n}\n' > "$aa72/aad/pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aad" --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aad/local/pasta")" -ge 1 \
      && ! -e "$aa72/aad/local/usr.bin.pasta" \
      && "$(grep -c "$aa72/aad/pasta" "$STATE/apparmor.log")" -eq 1 \
      && "$o" == *"sudo egresslock-setup apparmor check"* ]]; then
    a72 pass
else
    a72 fail "D1 alt profile name resolves + D3 confirm line (rc=$rc, out: $o)"
fi

# 12. A file named "pasta" without /usr/bin/pasta is skipped; the real
#     usr.bin.pasta profile wins.
mkdir -p "$aa72/aadb/local"
printf '# some other pasta thing\n' > "$aa72/aadb/pasta"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa72/aadb/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadb" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aadb/local/usr.bin.pasta")" -ge 1 \
    && "$(grep -c "$aa72/aadb/usr.bin.pasta" "$STATE/apparmor.log")" -eq 1 ]] \
    && a72 pass || a72 fail "D1 unrelated pasta file skipped (rc=$rc, out: $o)"

# 13. Idempotence keys off the RESOLVED local file (alt name, already
#     applied): no second parser run.
o="$(run_aa72 "$aa72/aad" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already allows"* && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a72 pass || a72 fail "D1 idempotence on resolved file (rc=$rc, out: $o)"

# 14. No candidate profile: refuse BEFORE writing anything; the recovery
#     message names the force-confmiss reinstall (D4).
mkdir -p "$aa72/aadc/local"
o="$(run_aa72 "$aa72/aadc" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 1 && ! -e "$aa72/aadc/local/usr.bin.pasta" && ! -e "$aa72/aadc/local/pasta" \
    && "$o" == *"--force-confmiss"* ]] \
    && a72 pass || a72 fail "D4 no profile -> rc 1, no write, recovery named (rc=$rc, out: $o)"

# 15. Profile exists but has no local include: EGL-14-D1 installs a
#     marked compatibility include (backed up), writes the rule into the
#     canonical fragment, reloads, and verifies the rule is loaded
#     (D2). Never appends the rule to the distro profile body directly.
mkdir -p "$aa72/aadd/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadd/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadd" --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aadd/local/usr.bin.pasta")" -ge 1 \
      && "$(grep -c '# begin egresslock-setup --apparmor compatibility patch' "$aa72/aadd/usr.bin.pasta")" == 1 \
      && "$(grep -c '#include <local/usr.bin.pasta>' "$aa72/aadd/usr.bin.pasta")" -ge 1 \
      && -f "$aa72/aadd/.usr.bin.pasta.egresslock-bak" \
      && ! -e "$aa72/aadd/usr.bin.pasta.egresslock-bak" \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]]; then
    a72 pass
else
    a72 fail "D1 no local include -> compat patch + rule + verified reload (rc=$rc, out: $o)"
fi

# 16. Remove when the resolved include differs from the legacy path:
#     BOTH files get stripped; profile present so the reload runs.
mkdir -p "$aa72/aade/local"
printf '/usr/bin/pasta {\n  include <local/pasta>\n}\n' > "$aa72/aade/pasta"
printf '# operator line alt\n' > "$aa72/aade/local/pasta"
{
    echo '# begin egresslock-setup --apparmor'
    echo 'signal (receive) peer=podman,'
    echo '# end egresslock-setup --apparmor'
} >> "$aa72/aade/local/pasta"
printf '# operator line legacy\n' > "$aa72/aade/local/usr.bin.pasta"
{
    echo '# begin egresslock-setup --apparmor'
    echo 'signal (receive) peer=podman,'
    echo '# end egresslock-setup --apparmor'
} >> "$aa72/aade/local/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aade" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aade/local/pasta")" == 0 \
      && "$(grep -c 'operator line alt' "$aa72/aade/local/pasta")" == 1 \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aade/local/usr.bin.pasta")" == 0 \
      && "$(grep -c 'operator line legacy' "$aa72/aade/local/usr.bin.pasta")" == 1 \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]]; then
    a72 pass
else
    a72 fail "D1 unapply covers resolved + legacy include (rc=$rc, out: $o)"
fi

# 17. Remove with the distro profile missing: file cleanup still rc 0
#     (warn "NOT reloaded"), no parser run (D4).
mkdir -p "$aa72/aadf/local"
{
    echo '# begin egresslock-setup --apparmor'
    echo 'signal (receive) peer=podman,'
    echo '# end egresslock-setup --apparmor'
} > "$aa72/aadf/local/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadf" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"NOT reloaded"* \
    && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aadf/local/usr.bin.pasta")" == 0 \
    && "$(wc -l < "$STATE/apparmor.log")" -eq 0 ]] \
    && a72 pass || a72 fail "D4 unapply rc 0 without profile (rc=$rc, out: $o)"

section_end arc72

# --- EGL-14: compatibility include + doctor -------------------------------
# D1: apply on a profile with no local include installs a marked,
# backed-up compatibility include; --remove strips exactly it. D3: the
# --apparmor-check report reflects the amendment state and exits nonzero when a
# required element is missing.
section_begin arc14 "EGL-14 apparmor compat include + doctor"
a14() { assert "$@"; }

# 1. Re-apply after --remove: the include-less profile gets the patch,
#    the rule loads, and a re-run is idempotent (no second patch, no
#    second reload).
mkdir -p "$aa72/aadg/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadg/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadg" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aadg/local/usr.bin.pasta")" -ge 1 \
    && "$(grep -c '# begin egresslock-setup --apparmor compatibility patch' "$aa72/aadg/usr.bin.pasta")" == 1 \
    && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a14 pass || a14 fail "EGL-14 apply on include-less profile (rc=$rc, out: $o)"
o="$(run_aa72 "$aa72/aadg" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"already allows"* \
    && "$(grep -c '# begin egresslock-setup --apparmor compatibility patch' "$aa72/aadg/usr.bin.pasta")" == 1 \
    && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]] \
    && a14 pass || a14 fail "EGL-14 re-apply idempotent with patch (rc=$rc, out: $o)"

# 2. --remove on that host: strips the local block AND the compat include,
#    removes the backup, reloads; the profile returns to no-include.
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadg" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"removed the egresslock pasta amendment"* \
      && "$(grep -cE 'signal \(receive\)( set=\(term\))? peer=podman' "$aa72/aadg/local/usr.bin.pasta")" == 0 \
      && "$(grep -c '# begin egresslock-setup --apparmor compatibility patch' "$aa72/aadg/usr.bin.pasta")" == 0 \
      && "$(grep -c '#include <local/usr.bin.pasta>' "$aa72/aadg/usr.bin.pasta")" == 0 \
      && ! -e "$aa72/aadg/.usr.bin.pasta.egresslock-bak" \
      && ! -e "$aa72/aadg/usr.bin.pasta.egresslock-bak" \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 1 ]]; then
    a14 pass
else
    a14 fail "EGL-14 remove strips compat patch + backup (rc=$rc, out: $o)"
fi

# 3. --apparmor-check reflects a healthy applied state and exits 0.
mkdir -p "$aa72/aadh/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa72/aadh/usr.bin.pasta"
o="$(run_aa72 "$aa72/aadh" --apparmor-add 2>&1)"; rc=$?   # apply (native include present)
: > "$STATE/apparmor.log"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa72/aadh" EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-check 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$o" == *"AppArmor: enabled"* \
      && "$o" == *"pasta enforcement: enforced"* \
      && "$o" == *"pasta profile: found"* \
      && "$o" == *"pasta local extension: present (stock)"* \
      && "$o" == *"egresslock rule in local file: present (egresslock)"* \
      && "$o" != *"compatibility patch:"* ]]; then
    a14 pass
else
    a14 fail "EGL-14 --apparmor-check healthy rc 0 (rc=$rc, out: $o)"
fi

# 3b. --apparmor-check on a PATCHED include-less host (EGL-21-D1): shows the
#     patch line, not a false native-extension claim.
mkdir -p "$aa72/aadp/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadp/usr.bin.pasta"
run_aa72 "$aa72/aadp" --apparmor-add >/dev/null 2>&1
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa72/aadp" EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$o" == *"pasta local extension: present (egresslock)"* \
    && "$o" != *"compatibility patch:"* ]] \
    && a14 pass || a14 fail "EGL-21 --apparmor-check patched host shows egresslock extension (rc=$rc, out: $o)"

# 4. --apparmor-check reports MISSING extension + absent rule and exits nonzero.
mkdir -p "$aa72/aadi/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadi/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa72/aadi" EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" != 0 \
    && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"egresslock rule in local file: absent"* ]] \
    && a14 pass || a14 fail "EGL-14 --apparmor-check unhealthy rc!=0 (rc=$rc, out: $o)"

section_end arc14

# --- EGL-20: parser-reality fixes (preprocess, dot backup, no-truncate) ---
# D1: load-check uses a SINGLE -p action; EGL-56: `-p --preprocess` is
#     "Too many actions" on AppArmor 5, so the source pin keeps the pair out.
# D2: backup is a leading-dot file; an old non-dot backup migrates on apply.
# D3: strip never truncates the distro profile (rc 1, file + backup intact).
# D4: the patch lands after the pasta header's brace, not the first `{`.
section_begin arc20 "EGL-20 parser-reality fixes"
a20() { assert "$@"; }

# 0. EGL-56: the double-flag invocation must not exist in the source.
grep -q -- '-p --preprocess' "$SKIT" \
    && a20 fail "pasta_rule_loaded still passes both -p and --preprocess (AppArmor 5: Too many actions)" \
    || a20 pass

# 1. EGL-26-D1: a preamble comment containing `{` must not capture the
#    patch, and the marked include must land BEFORE the closing `}` of
#    the pasta body (after the body rule), not after the opening `{`.
mkdir -p "$aa72/aadj/local"
printf '# sample preamble { not a profile brace }\n/usr/bin/pasta {\n  /usr/bin/foo r,\n}\n' > "$aa72/aadj/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadj" --apparmor-add 2>&1)"; rc=$?
# header line 2, opening `{` line 3, body rule line 4, marker block must
# start on line 5 (immediately before the closing `}` on line 6).
patch_line="$(grep -n '# begin egresslock-setup --apparmor compatibility patch' "$aa72/aadj/usr.bin.pasta" | cut -d: -f1)"
close_line="$(grep -n '^}' "$aa72/aadj/usr.bin.pasta" | cut -d: -f1)"
[[ "$rc" == 0 && "$patch_line" == 4 && "$close_line" == 7 ]] \
    && a20 pass || a20 fail "EGL-26 D1 patch before closing brace (rc=$rc, line=$patch_line, close=$close_line, out: $o)"

# 2. D2: a leftover non-dot backup from a pre-EGL-20 apply is migrated
#    to the dot name on the next apply (never left loadable).
mkdir -p "$aa72/aadk/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadk/usr.bin.pasta"
cp -a "$aa72/aadk/usr.bin.pasta" "$aa72/aadk/usr.bin.pasta.egresslock-bak"
o="$(run_aa72 "$aa72/aadk" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && -f "$aa72/aadk/.usr.bin.pasta.egresslock-bak" \
    && ! -e "$aa72/aadk/usr.bin.pasta.egresslock-bak" ]] \
    && a20 pass || a20 fail "EGL-20 D2 non-dot backup migrated (rc=$rc, out: $o)"

# 2b. R-EGL-20-1 finding 1 (apply path): a LEGACY EGL-14-patched host —
#     marker include already present + non-dot backup on disk. Apply must
#     migrate the backup even though install_compat_include is not called
#     (pasta_had_include=1). The rule is already applied, so rc 0 with
#     only the backup migrated and no second reload.
mkdir -p "$aa72/aadn/local"
{
    printf '/usr/bin/pasta {\n'
    echo '# begin egresslock-setup --apparmor compatibility patch'
    echo '  #include <local/usr.bin.pasta>'
    echo '# end egresslock-setup --apparmor compatibility patch'
    printf '}\n'
} > "$aa72/aadn/usr.bin.pasta"
{
    echo '# begin egresslock-setup --apparmor'
    echo '# added by egresslock-setup --apparmor'
    echo 'signal (receive) set=(term) peer=podman,'
    echo '# end egresslock-setup --apparmor'
} > "$aa72/aadn/local/usr.bin.pasta"
cp -a "$aa72/aadn/usr.bin.pasta" "$aa72/aadn/usr.bin.pasta.egresslock-bak"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadn" --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"already allows"* \
      && -f "$aa72/aadn/.usr.bin.pasta.egresslock-bak" \
      && ! -e "$aa72/aadn/usr.bin.pasta.egresslock-bak" \
      && "$(wc -l < "$STATE/apparmor.log")" -eq 0 ]]; then
    a20 pass
else
    a20 fail "EGL-20 D2 legacy patched host: apply migrates non-dot backup (rc=$rc, out: $o)"
fi

# 2c. R-EGL-20-1 finding 1 (remove path): --remove on that legacy host
#     also removes the non-dot backup (never leaves it loadable).
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadn" --apparmor-remove 2>&1)"; rc=$?
gone=0; grep -q 'egresslock-setup --apparmor compatibility patch' "$aa72/aadn/usr.bin.pasta" || gone=1
if [[ "$rc" == 0 && "$o" == *"removed the egresslock pasta amendment"* \
      && ! -e "$aa72/aadn/.usr.bin.pasta.egresslock-bak" \
      && ! -e "$aa72/aadn/usr.bin.pasta.egresslock-bak" \
      && "$gone" == 1 ]]; then
    a20 pass
else
    a20 fail "EGL-20 D2 legacy patched host: --remove drops non-dot backup (rc=$rc, out: $o)"
fi

# 3. D3: a profile whose marked block contains the header/brace — the
#    strip would destroy it, so --remove refuses rc 1 and leaves the
#    live file + backup untouched.
mkdir -p "$aa72/aadl/local"
{
    echo '# begin egresslock-setup --apparmor compatibility patch'
    echo '/usr/bin/pasta {'
    echo '  #include <local/usr.bin.pasta>'
    echo '# end egresslock-setup --apparmor compatibility patch'
    echo '}'
} > "$aa72/aadl/usr.bin.pasta"
cp -a "$aa72/aadl/usr.bin.pasta" "$aa72/aadl/.usr.bin.pasta.egresslock-bak"
cp -a "$aa72/aadl/usr.bin.pasta" "$aa72/aadl/before"
o="$(run_aa72 "$aa72/aadl" --apparmor-remove 2>&1)"; rc=$?
same=0; cmp -s "$aa72/aadl/usr.bin.pasta" "$aa72/aadl/before" && same=1
if [[ "$rc" == 1 && "$o" == *"refusing to strip"* \
      && -f "$aa72/aadl/.usr.bin.pasta.egresslock-bak" \
      && "$same" == 1 ]]; then
    a20 pass
else
    a20 fail "EGL-20 D3 strip refuses to destroy profile (rc=$rc, out: $o)"
fi

section_end arc20

# --- EGL-23: remove-path verification (parser rc surfaced, -T, negative) --
# D1: a failing reload on remove is rc 1 (never a silent success). D2:
# the remove reload is `apparmor_parser -r -T -- <profile>`. D3: after a
# successful strip+reload the signal rule is ABSENT from the flattened
# profile; a still-present rule is rc 1 loud.
section_begin arc23 "EGL-23 remove verification"
a23() { assert "$@"; }

# 1. D2: remove of an applied amendment reloads with -r -T; the negative
#    load-check (rule absent) passes and rc 0.
mkdir -p "$aa72/aadr/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aadr/usr.bin.pasta"
o="$(run_aa72 "$aa72/aadr" --apparmor-add 2>&1)"; rc=$?   # apply first (compat patch + rule)
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa72/aadr" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 && "$o" == *"removed the egresslock pasta amendment"* \
      && "$(grep -c -- '-r -T' "$STATE/apparmor.log")" -ge 1 \
      && "$o" == *"pasta profile reloaded"* ]]; then
    a23 pass
else
    a23 fail "EGL-23 D2 remove reloads with -r -T, negative check passes (rc=$rc, out: $o, log: $(cat "$STATE/apparmor.log"))"
fi

# 2. D1: mock parser fails on the remove reload -> unapply rc 1, loud.
mkdir -p "$aa72/aads/bin"
cat > "$aa72/aads/bin/apparmor_parser" <<'EOF'
#!/usr/bin/env bash
if [[ "$1" == "-r" ]]; then
    echo "mock parser failure" >&2
    exit 1
fi
exit 0
EOF
chmod +x "$aa72/aads/bin/apparmor_parser"
mkdir -p "$aa72/aads/local"
printf '/usr/bin/pasta {\n}\n' > "$aa72/aads/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa72/share" EGRESSLOCK_APPARMOR_D="$aa72/aads" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-add 2>&1)"; rc=$?   # apply (uses aa22 mock -> ok)
# now --remove with the failing parser
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa72/aads/bin:$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa72/share" EGRESSLOCK_APPARMOR_D="$aa72/aads" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"apparmor_parser failed"* ]] \
    && a23 pass || a23 fail "EGL-23 D1 parser failure on remove -> rc 1 (rc=$rc, out: $o)"

section_end arc23


# --- ARC-70: drift-signal visibility (setup hint) ---------------------------
# D1: --enable stays explicit. D2: account setup without --enable prints a
# loud stdout hint naming the re-run; with --enable there is no hint; an
# --apparmor-alone run (no account processed) never hints. D3: the engine
# never queries systemctl/linger (asserted in the engine harness instead).
section_begin arc70 "ARC-70 drift-signal hint"
a70() { assert "$@"; }

# 1. Account setup without --enable: the re-run line is runnable and
#    named with the account's own paths (EGL-102-F1/R4; EGL-333-D7: plain
#    pathless init — no --profile). EGL-270 P3 (candidate 5): the bare
#    "timer NOT enabled" clause was trimmed — egl51 #2 pins the hint
#    line's presence; the ("did not arm drift checks" + re-arm) bits
#    below are its only home.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" 2>&1)"
[[ "$o" == *"this run did not arm drift checks"* \
    && "$o" == *"sudo egresslock-setup init cacct --enable"* ]] \
    && a70 pass || a70 fail "no --enable -> loud hint with runnable re-run line (out: $o)"

# 2. With --enable: no hint (the enable commands already ran), and the
#    system changes are announced before they happen (post-R-070-2).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$a18d/home/cacct" \
    $SKIT init --prefix "$SKITP" --account cacct --from "$a18d/site.conf" --enable 2>&1)"
[[ "$o" != *"timer NOT enabled"* \
    && "$o" == *"enabling verify timer for cacct"* \
    && "$o" == *"enabling linger for cacct"* ]] \
    && a70 pass || a70 fail "--enable -> no hint, actions announced (out: $o)"

# 3. --apparmor-add alone: no account processed -> never hints, never
#    announces timer/linger actions.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-add 2>&1)"
[[ "$o" != *"timer NOT enabled"* && "$o" != *"enabling linger"* \
    && "$o" != *"enabling verify timer"* ]] \
    && a70 pass || a70 fail "apparmor-alone -> no hint, no announcements (out: $o)"

# 4. EGL-25-D1: --apparmor-add / --apparmor-remove alone (no --account)
#    do NOT print the account closer ("no account setup requested");
#    they already printed their outcome. Old wording gone.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-add 2>&1)"
[[ "$o" != *"no account setup requested"* \
    && "$o" != *"--apparmor-add done"* \
    && "$o" != *"no account steps requested"* ]] \
    && a70 pass || a70 fail "EGL-25 D1 apply-alone: no account closer (out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-remove 2>&1)"
[[ "$o" != *"no account setup requested"* \
    && "$o" != *"--apparmor-add done"* \
    && "$o" != *"no account steps requested"* ]] \
    && a70 pass || a70 fail "EGL-25 D1 remove-alone: no account closer (out: $o)"

section_end arc70

# --- ARC-69 D5: --apparmor-add file handling (mode/inode/blank lines) ----------
# Apply inserts the blank separator only after existing non-empty
# content; --remove strips a blank before the marker, writes INTO the
# file (inode + mode + owner survive; mv would clobber a conffile), and
# truncates whitespace-only residue to 0 bytes.
section_begin arc69s "ARC-69 apparmor file handling"
a69s() { assert "$@"; }

aa69="$STATE/a22aa69"; rm -rf "$aa69"
mkdir -p "$aa69/aad/local" "$aa69/share/apparmor"
cp "$TREE_ROOT/apparmor/usr.bin.pasta.local" "$aa69/share/apparmor/"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa69/aad/usr.bin.pasta"
run_aa69() { env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa69/share" EGRESSLOCK_APPARMOR_D="$aa69/aad" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" "${@:2}"; }

# 1. 0644 EMPTY local file: apply adds NO leading blank line; mode
#    survives the apply.
: > "$aa69/aad/local/usr.bin.pasta"
chmod 0644 "$aa69/aad/local/usr.bin.pasta"
o="$(run_aa69 "$aa69/aad" --apparmor-add 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$(head -1 "$aa69/aad/local/usr.bin.pasta")" == "# begin egresslock-setup --apparmor" \
    && "$(stat -c %a "$aa69/aad/local/usr.bin.pasta")" == "644" ]] \
    && a69s pass || a69s fail "D5 empty-file apply: no leading blank, mode kept (rc=$rc, out: $o)"

# 2. The ticket's exact case: 0644 empty -> apply + remove -> still 0644
#    and 0 bytes.
o="$(run_aa69 "$aa69/aad" --apparmor-remove 2>&1)"; rc=$?
[[ "$rc" == 0 && ! -s "$aa69/aad/local/usr.bin.pasta" \
    && "$(stat -c %a "$aa69/aad/local/usr.bin.pasta")" == "644" ]] \
    && a69s pass || a69s fail "D5 apply+remove over empty file: 0644, 0 bytes (rc=$rc, out: $o)"

# 3. Operator content: apply adds the blank separator; remove strips the
#    block AND the separator, and the inode + mode survive (no mv).
printf '# operator rule\n' > "$aa69/aad/local/usr.bin.pasta"
chmod 0640 "$aa69/aad/local/usr.bin.pasta"
o="$(run_aa69 "$aa69/aad" --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$(sed -n '2p' "$aa69/aad/local/usr.bin.pasta")" == "" \
      && "$(sed -n '3p' "$aa69/aad/local/usr.bin.pasta")" == "# begin egresslock-setup --apparmor" ]]; then
    a69s pass
else
    a69s fail "D5 non-empty apply: blank separator present (rc=$rc, out: $o)"
fi
a69s_ino="$(stat -c %i "$aa69/aad/local/usr.bin.pasta")"
o="$(run_aa69 "$aa69/aad" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$(cat "$aa69/aad/local/usr.bin.pasta")" == "# operator rule" \
      && "$(stat -c %a "$aa69/aad/local/usr.bin.pasta")" == "640" \
      && "$(stat -c %i "$aa69/aad/local/usr.bin.pasta")" == "$a69s_ino" ]]; then
    a69s pass
else
    a69s fail "D5 remove: inode+mode kept, separator gone (rc=$rc, out: $o)"
fi

section_end arc69s

# --- EGL-50: doctor Summary + verdict reword, report-only remove, hygiene --
# D50-2: `pasta amendment: required on this host` vocabulary. D50-3:
# one final `Summary:` line on --apparmor-check; rc agrees (OK 0,
# FAILED 1, UNKNOWN 1 — never rc 2, never green from unknown). D50-6.1:
# the apply confirm line points at --apparmor-check. D50-7: remove is
# report-only — no ritual, no probe command. D50-4/D50-5: no `[--enable]`
# and no internal ticket IDs in shipped output.
section_begin egl50 "EGL-50 doctor summary + message hygiene"
e50() { assert "$@"; }

# 1. Unknown listing (EGL-39 4k shape): Summary CHECK UNKNOWN, rc 1
#    (not 2), never a "not needed" claim.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles-dir" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"Summary: CHECK UNKNOWN (run as root if apparmor policy not visible to current user)"* \
    && "$o" != *"not needed"* && "$o" != *"not required"* ]] \
    && e50 pass || e50 fail "D50-3 unknown listing -> Summary UNKNOWN rc 1 (rc=$rc, out: $o)"

# 2. Labeled+enforced+applied (EGL-14 aadh fixture, amendment applied):
#    Summary CHECK OK (AppArmor patch applied), rc 0.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa72/aadh" EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"Summary: CHECK OK (AppArmor patch applied)"* ]] \
    && e50 pass || e50 fail "D50-3 applied -> Summary OK rc 0 (rc=$rc, out: $o)"

# 3. Unlabeled + healthy pasta side (aad39): Summary CHECK OK (AppArmor
#    patch not needed), rc 0.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"Summary: CHECK OK (AppArmor patch not needed)"* ]] \
    && e50 pass || e50 fail "D50-3 not-needed -> Summary OK rc 0 (rc=$rc, out: $o)"

# 4. Labeled+enforced+ext MISSING+rule absent: Summary CHECK FAILED
#    (AppArmor patch needed), rc 1 (the fix is --apparmor-add's patch).
mkdir -p "$aa22/aad50n"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad50n/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_APPARMOR_D="$aa22/aad50n" EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" \
    "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta amendment: required on this host"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch needed)"* ]] \
    && e50 pass || e50 fail "D50-3 needed -> Summary FAILED rc 1 (rc=$rc, out: $o)"

# 5. Labeled+enforced+extension present but rule absent: the
#    applied/missing dimensions disagree -> CHECK FAILED (incomplete), rc 1.
#    Fresh fixture (aad39's local file is filled by an EGL-39 apply test).
mkdir -p "$aa22/aad50x/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad50x/usr.bin.pasta"
: > "$aa22/aad50x/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad50x" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta local extension: present (stock)"* \
    && "$o" == *"egresslock rule in local file: absent"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch incomplete)"* ]] \
    && e50 pass || e50 fail "D50-3 incomplete (ext present, rule absent) -> Summary FAILED rc 1 (rc=$rc, out: $o)"

# 6. --apparmor-remove success is report-only (D50-7): the two facts,
#    no ritual, no probe command, no confirm pointer.
mkdir -p "$aa22/aad50r/local"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad50r/usr.bin.pasta"
run_aa72 "$aa22/aad50r" --apparmor-add >/dev/null 2>&1
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa22/aad50r" --apparmor-remove 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$o" == *"removed the egresslock pasta amendment"* \
      && "$o" == *"pasta profile reloaded"* \
      && "$o" != *"must now FAIL"* \
      && "$o" != *"tear down"* \
      && "$o" != *"terminate-user"* \
      && "$o" != *"podman unshare"* \
      && "$o" != *"--apparmor-check"* ]]; then
    e50 pass
else
    e50 fail "D50-7 remove success is report-only (rc=$rc, out: $o)"
fi

# 7. --apparmor-add success confirms via --apparmor-check (D50-6.1),
#    no probe ritual.
mkdir -p "$aa22/aad50a/local"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad50a/usr.bin.pasta"
: > "$STATE/apparmor.log"
o="$(run_aa72 "$aa22/aad50a" --apparmor-add 2>&1)"; rc=$?
if [[ "$rc" == 0 \
      && "$o" == *"pasta profile reloaded"* \
      && "$o" == *"Confirm with: sudo egresslock-setup apparmor check"* \
      && "$o" != *"must now FAIL"* \
      && "$o" != *"podman unshare"* ]]; then
    e50 pass
else
    e50 fail "D50-6.1 apply confirm points at apparmor check (rc=$rc, out: $o)"
fi

# 8. D50-4: no `[--enable]` bracket presentation anywhere operator-facing.
#    EGL-107-D1: packaging files skip per-file on the extracted kit; the
#    shipped kit scripts always assert (an absent file must not turn
#    the grep into a vacuous pass).
for f in "$TREE_ROOT/egresslock-setup" "$TREE_ROOT/install-kit.sh" \
         "$TREE_ROOT/packaging/build-deb.sh" "$TREE_ROOT/packaging/build-tarball.sh" \
         "$TREE_ROOT/packaging/README.md"; do
    if [[ ! -f "$f" ]]; then
        skip "$PKG_SKIP_TAG" "D50-4 [--enable] sweep — $f is not on this tree (extracted kit)"
    elif grep -qF -- '[--enable]' "$f"; then
        e50 fail "D50-4 [--enable] bracket in $f"
    else
        e50 pass
    fi
done

# 9. D50-5: shipped install output speaks product — the generated
#    postinst and the tarball README fragment carry no internal ticket
#    IDs and point at apparmor check; no [--enable] either.
#    EGL-107-D1: both artifacts are packaging producers' outputs; skip
#    with them on the extracted kit.
if [[ "$HAVE_BUILD_DEB" == 1 ]]; then
if grep -qF 'ARC-22-D3' "$p22/stage/DEBIAN/postinst"; then
    e50 fail "D50-5 postinst leaks ARC-22-D3"
else
    e50 pass
fi
grep -q 'apparmor check' "$p22/stage/DEBIAN/postinst" \
    && e50 pass || e50 fail "postinst points at apparmor check"
grep -qF -- '[--enable]' "$p22/stage/DEBIAN/postinst" \
    && e50 fail "postinst still shows [--enable]" || e50 pass
# EGL-517 F8: the shipped next-step line is paste-inert — no `<...>`
# placeholder (a pasted `<acct>` redirects before command lookup).
grep -qE '<[A-Za-z][^<>]*>' "$p22/stage/DEBIAN/postinst" \
    && e50 fail "postinst still carries an angle-bracket placeholder" || e50 pass
else
    skip "$PKG_SKIP_TAG" "D50-5 postinst hygiene greps — packaging/build-deb.sh is not on this tree (extracted kit)"
fi
if [[ "$HAVE_BUILD_TARBALL" == 1 ]]; then
if grep -qF 'ARC-22-D3' "$p22/x/README.txt"; then
    e50 fail "tarball README fragment carries ARC-22-D3"
else
    e50 pass
fi
grep -q 'apparmor check' "$p22/x/README.txt" \
    && e50 pass || e50 fail "tarball README fragment points at apparmor check"
grep -qF -- '[--enable]' "$p22/x/README.txt" \
    && e50 fail "tarball README still shows [--enable]" || e50 pass
# EGL-517 F8: the tarball README next-step line is paste-inert too.
grep -qE '<[A-Za-z][^<>]*>' "$p22/x/README.txt" \
    && e50 fail "tarball README still carries an angle-bracket placeholder" || e50 pass
else
    skip "$PKG_SKIP_TAG" "D50-5 tarball README hygiene greps — packaging/build-tarball.sh is not on this tree (extracted kit)"
fi

section_end egl50

# --- EGL-55: doctor profile-networks row (advisory) -----------------------
# D55-1: with --account + a parsed conf, one rc-neutral row after the
# gateway image lines: present (all), missing (names) — run: egresslock
# ensure <name>..., or unknown when `podman network ls` fails. The row
# never fails the doctor and never runs ensure.
section_begin egl55 "EGL-55 doctor profile-networks row"
e55() { assert "$@"; }
mkdir -p "$STATE/e55"

# 1. Healthy account slice, no networks yet: advisory missing row, rc 0.
rm -f "$STATE/networks"/*
e55o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e55rc=$?
[[ "$e55rc" == 0 && "$e55o" == *"NOTE: profile networks: missing (p1) — run as the account: egresslock ensure p1"* ]] \
    && e55 pass || e55 fail "D55-1 missing row, rc stays 0 (rc=$e55rc, out: $e55o)"

# 2. Network present in the account store: present (p1), still rc 0.
printf 'driver=bridge\nsubnet=10.99.5.0/24\ngateway=10.99.5.1\nipv6_enabled=false\n' \
    > "$STATE/networks/egresslock-p1"
e55o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e55rc=$?
[[ "$e55rc" == 0 && "$e55o" == *"OK: profile networks: present (p1)"* ]] \
    && e55 pass || e55 fail "D55-1 present row (rc=$e55rc, out: $e55o)"

# 3. EGL-323: a conf with a second `profile` block is refused at load
#    (one profile per conf file). The walked path shows the engine error
#    under the parse FAIL row and the row's named skip; doctor rc 1.
#    EGL-325: doctor reads the account's fixed confdir, so stage the
#    fixture as <profile>.conf there before the read-only run.
printf 'profile pa 10.99.7.0/24\nprofile pb 10.99.8.0/24\n' \
    > "$STATE/e55/two.conf"
cp "$STATE/e55/two.conf" "$e38h/.config/egresslock/pa.conf"
e55o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e55/two.conf" --profile pa --doctor 2>&1)"; e55rc=$?
[[ "$e55rc" == 1 && "$e55o" == *"PROBLEM: conf parse: FAIL"* \
    && "$e55o" == *"$e38h/.config/egresslock/pa.conf:2: one profile per conf file: 'pa' is already defined at line 1; put each profile in its own conf file"* \
    && "$e55o" == *"NOTE: profile networks: skipped (conf parse failed above)"* ]] \
    && e55 pass || e55 fail "D55-1 two-profile conf rejected at load, row skipped (rc=$e55rc, out: $e55o)"
rm -f "$e38h/.config/egresslock/pa.conf"

# 4. `podman network ls` fails (no session): the row says unknown, does
#    not fail the doctor, does not start user@ (rc 0 when else healthy).
mkdir -p "$STATE/e55/bin"
cat > "$STATE/e55/bin/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == network && "\$2" == ls ]]; then echo "mock: ls denied" >&2; exit 1; fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$STATE/e55/bin/podman"
e55o="$(env PATH="$STATE/e55/bin:$PATH" EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_ACCOUNT_HOME="$e38h" EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e55rc=$?
[[ "$e55rc" == 0 && "$e55o" == *"NOTE: profile networks: unknown"* \
    && "$e55o" == *"OK: gateway image: present"* ]] \
    && e55 pass || e55 fail "D55-1 ls-failure -> unknown, rc-neutral (rc=$e55rc, out: $e55o)"
rm -f "$STATE/e55/bin/podman"

# 5. Conf parse already failed: the row is a NAMED skip with the cause
#    (EGL-102-D6-R2: disclose why, never silently absent); doctor still
#    rc 1 from the parse row.
printf 'profile bad 10.99.8.0/24\n    rule nonsense\n' > "$STATE/e55/bad.conf"
cp "$STATE/e55/bad.conf" "$e38h/.config/egresslock/bad.conf"
e55o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e55/bad.conf" --profile bad --doctor 2>&1)"; e55rc=$?
[[ "$e55rc" == 1 && "$e55o" == *"PROBLEM: conf parse: FAIL"* \
    && "$e55o" == *"NOTE: profile networks: skipped (conf parse failed above)"* ]] \
    && e55 pass || e55 fail "D55-1 row skipped when conf parse failed (rc=$e55rc, out: $e55o)"
rm -f "$e38h/.config/egresslock/bad.conf"

section_end egl55

# --- EGL-203: doctor gateway-image staleness row (advisory) --------------
# The present branch peeks at the image's base label and compares it with
# the deployed Containerfile pin, read from the engine's NEIGHBOR gateway/
# (build-gateway's context; R-EGL-222-3 F2, share override never feeds it).
# Advisory/rc-neutral (the EGL-55 precedent). Fixture: mock podman
# image-inspect ($D/image-inspect-<img>); default empty => "base unknown".
section_begin egl203 "EGL-203 doctor gateway-image staleness row"
e203() { assert "$@"; }
e203img="localhost/egresslock-gateway:latest"
e203fix="$STATE/image-inspect-$(echo "$e203img" | tr '/:' '__')"
e203dig="$(grep '^FROM ' "$e38p/gateway/Containerfile" | grep -oE 'sha256:[0-9a-f]{64}' | head -1)"
e203short="${e203dig#sha256:}"; e203short="${e203short:0:12}"   # the row prints the short digest
e203share="$STATE/e203/share"
mkdir -p "$e203share/gateway"
# EGL-487: computed healthy dates (a fixed old date trips the age line)
# never below the deployed floor (R-EGL-487-2 F3): the floor is bumped
# on release day (D6), so a plain now-relative date can fall below it
# and red a healthy leg. Floor-based cases use the deployed floor ±
# offsets.
e203_floor="$(awk '{ sub(/#.*/, ""); gsub(/[[:space:]]/, ""); if ($0 != "") { print; exit } }' \
    "$e38p/gateway/security-floor")"
e203_egl_floor="$(awk '{ sub(/#.*/, ""); gsub(/[[:space:]]/, ""); if ($0 != "") { print; exit } }' \
    "$e38p/examples/egl-base/security-floor")"
e203_recent="$(date -u -d '2 days ago' '+%Y-%m-%d')"
[[ "$e203_recent" < "$e203_floor" ]] && e203_recent="$e203_floor"
e203_egl_recent="$(date -u -d '2 days ago' '+%Y-%m-%d')"
[[ "$e203_egl_recent" < "$e203_egl_floor" ]] && e203_egl_recent="$e203_egl_floor"
e203_before_floor="$(date -u -d "$e203_floor - 5 days" '+%Y-%m-%d')"
e203_over_age="$(date -u -d "$e203_floor - 60 days" '+%Y-%m-%d')"
e203_egl_before="$(date -u -d "$e203_egl_floor - 5 days" '+%Y-%m-%d')"

# EGL-487-D6: the shipped floor records parse as ISO dates, are not in
# the future, and are never older than the seed recorded here (a bump is
# expected; a regression below the seed is not).
for e203_floor_pair in "gateway:2026-11-04" "examples/egl-base:2026-10-20"; do
    e203_floor_dir="${e203_floor_pair%%:*}"
    e203_floor_seed="${e203_floor_pair#*:}"
    e203_floor_file="$TREE_ROOT/$e203_floor_dir/security-floor"
    e203_floor_value="$(awk '{ sub(/#.*/, ""); gsub(/[[:space:]]/, ""); if ($0 != "") { print; exit } }' \
        "$e203_floor_file" 2>/dev/null || true)"
    if [[ -f "$e203_floor_file" \
          && "$e203_floor_value" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ \
          && "$(date -u -d "$e203_floor_value" '+%Y-%m-%d' 2>/dev/null || true)" == "$e203_floor_value" \
          && ! "$e203_floor_value" > "$(date -u '+%Y-%m-%d')" ]] \
       && { [[ "$e203_floor_value" == "$e203_floor_seed" ]] \
            || [[ "$e203_floor_value" > "$e203_floor_seed" ]]; }; then
        e203 pass
    else
        e203 fail "floor record $e203_floor_dir/security-floor is a valid ISO date, not future, not below seed $e203_floor_seed (got: '${e203_floor_value:-missing}')"
    fi
    # R-EGL-487-2 F4: the parsers take the first non-comment line, so an
    # appended "bump" would silently keep the old floor. Pin the shipped
    # one-line format so an append reds here instead.
    e203_floor_lines="$(awk '{ sub(/#.*/, ""); gsub(/^[[:space:]]+/, ""); gsub(/[[:space:]]+$/, ""); if ($0 != "") c++ } END { print c+0 }' \
        "$e203_floor_file" 2>/dev/null || true)"
    if [[ "$e203_floor_lines" == 1 ]]; then
        e203 pass
    else
        e203 fail "floor record $e203_floor_dir/security-floor has exactly one non-comment line (got: ${e203_floor_lines:-read-failed})"
    fi
done

# 1. Label matches the deployed pin: the row shows the base (short
#    digest) + built date, no staleness or rebuild line, doctor rc 0.
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_recent" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"OK: gateway image: present ($e203img) — base $e203short"* \
    && "$e203o" == *", built $e203_recent"* && "$e203o" != *"stale:"* \
    && "$e203o" != *"rebuild:"* ]] \
    && e203 pass || e203 fail "D203-3 match row: base + built, rc-neutral (rc=$e203rc, out: $e203o)"
rm -f "$e203fix"

# 2. Divergent-pin round trip (R-EGL-222-3 F2): the share override does
#    NOT feed the doctor's pin. Share carries pin B (all-zero digest),
#    the engine neighbor carries pin A, the image is A-labelled: the
#    doctor must report NO stale row (its pin source = the remedy's
#    context), and the doctor's recommended remedy must agree — the
#    alias execs the engine verb, which reports up-to-date and builds
#    nothing.
printf 'FROM docker.io/library/debian:13-slim@sha256:%064d\n' 0 > "$e203share/gateway/Containerfile"
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_recent" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_SHARE="$e203share" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"OK: gateway image: present ($e203img) — base $e203short"* \
    && "$e203o" != *"stale:"* ]] \
    && e203 pass || e203 fail "D203-3 F2: share pin ignored, neighbor pin matches (rc=$e203rc, out: $e203o)"
: > "$STATE/buildlog"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_SHARE="$e203share" \
    $SKIT --prefix "$e38p" --build-gateway 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"already built from deployed pin $e203short"* && ! -s "$STATE/buildlog" ]] \
    && e203 pass || e203 fail "D203-3 F2: the doctor's remedy agrees with the doctor (rc=$e203rc, out: $e203o)"

# 2b. Pin moved in the NEIGHBOR (the canonical pin source): the stale
#     row still fires with both sides named and the account-shell
#     rebuild pointer; still advisory (rc 0).
printf 'FROM docker.io/library/debian:13-slim@sha256:%064d\n' 0 > "$e38p/gateway/Containerfile"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"stale: base pin moved (image base $e203short != deployed pin 000000000000)"* \
    && "$e203o" == *"rebuild in the account shell: egresslock build-gateway && egresslock ensure --replace-gateway PROFILE per affected profile (see \"The gateway image\" reference page)"* ]] \
    && e203 pass || e203 fail "D203-3 neighbor-pin-moved stale row with pointer, rc-neutral (rc=$e203rc, out: $e203o)"
cp -f "$TREE_ROOT/gateway/Containerfile" "$e38p/gateway/Containerfile"   # restore the fixture prefix
rm -f "$e203fix" "$e203share/gateway/Containerfile"

# 3. Pre-label image (inspect succeeds, label empty): "base unknown
#    (pre-label image)" + the same rebuild pointer, rc-neutral.
printf ' 2026-08-01T00:00:00.000000000Z\n' > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"OK: gateway image: present ($e203img) — base unknown (pre-label image), built 2026-08-01"* \
    && "$e203o" == *"stale: base unknown (pre-label image) — rebuild in the account shell: egresslock build-gateway && egresslock ensure --replace-gateway PROFILE per affected profile (see \"The gateway image\" reference page)"* ]] \
    && e203 pass || e203 fail "D203-3 pre-label row with pointer, rc-neutral (rc=$e203rc, out: $e203o)"
rm -f "$e203fix"

# 3b. EGL-254: Podman's literal "<no value>" marker for a missing label
#     key (a space inside) must classify exactly like the empty label —
#     pre-label row + pre-label stale pointer, never a "base <no" or
#     "base pin moved" claim.
printf '<no value> 2026-08-01T00:00:00.000000000Z\n' > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"OK: gateway image: present ($e203img) — base unknown (pre-label image), built 2026-08-01"* \
    && "$e203o" == *"stale: base unknown (pre-label image)"* \
    && "$e203o" != *"base pin moved"* && "$e203o" != *"<no value>"* ]] \
    && e203 pass || e203 fail "D203-3 literal <no value> pre-label row, rc-neutral (rc=$e203rc, out: $e203o)"
rm -f "$e203fix"

# 4. Inspect fails (no session/old podman): degrades to a bare "base
#    unknown" — no staleness claim, no pre-label guess, doctor rc 0.
mkdir -p "$STATE/e203/bin"
cat > "$STATE/e203/bin/podman" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == image && "\$2" == inspect ]]; then echo "mock: inspect denied" >&2; exit 1; fi
exec "$TESTROOT/bin/podman" "\$@"
EOF
chmod +x "$STATE/e203/bin/podman"
e203o="$(env PATH="$STATE/e203/bin:$PATH" EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
    EGRESSLOCK_ACCOUNT_HOME="$e38h" EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"OK: gateway image: present ($e203img) — base unknown"* \
    && "$e203o" != *"pre-label"* && "$e203o" != *"stale:"* ]] \
    && e203 pass || e203 fail "D203-3 inspect failure degrades to base unknown, rc-neutral (rc=$e203rc, out: $e203o)"
rm -f "$STATE/e203/bin/podman"

# 5. EGL-487-D2: below the deployed gateway floor -> one rc-neutral
#    `rebuild:` line naming the floor, the --force remedy and the
#    reference pointer; `stale:` keeps its moved-pin meaning only.
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_before_floor" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"rebuild: gateway image built $e203_before_floor is older than the kit's security rebuild floor $e203_floor"* \
    && "$e203o" == *"egresslock build-gateway --force && egresslock ensure --replace-gateway PROFILE per affected profile"* \
    && "$e203o" != *"stale:"* && "$e203o" != *"days old"* ]] \
    && e203 pass || e203 fail "EGL-487 below-floor gateway rebuild line + --force remedy, rc-neutral (rc=$e203rc, out: $e203o)"

# 5b. The floor line wins when the image is also over age.
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_over_age" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"security rebuild floor $e203_floor"* \
    && "$e203o" != *"days old"* ]] \
    && e203 pass || e203 fail "EGL-487 gateway floor line wins over age (rc=$e203rc, out: $e203o)"

# 5c. Above the floor but over the 30-day backstop: the age line names
#     --force and the newer-kit action. Plant an old floor for this case.
printf '2000-01-01\n' > "$e38p/gateway/security-floor"
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$(date -u -d '45 days ago' '+%Y-%m-%d')" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"is more than 30 days old — refresh it in the account shell:"* \
    && "$e203o" == *"check for a newer egresslock release"* \
    && "$e203o" != *"security rebuild floor"* ]] \
    && e203 pass || e203 fail "EGL-487 over-age gateway rebuild line + newer-kit action (rc=$e203rc, out: $e203o)"

# 5d. Missing or unparseable floor degrades silently: the age backstop
#     still fires and no floor claim is invented.
for e203_nofloor in absent garbage; do
    rm -f "$e38p/gateway/security-floor"
    [[ "$e203_nofloor" == garbage ]] && printf 'not-a-date\n' > "$e38p/gateway/security-floor"
    printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$(date -u -d '45 days ago' '+%Y-%m-%d')" > "$e203fix"
    e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
        EGRESSLOCK_UNIT_DIR="$UNITS" \
        $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
    [[ "$e203rc" == 0 && "$e203o" == *"is more than 30 days old"* \
        && "$e203o" != *"security rebuild floor"* ]] \
        && e203 pass || e203 fail "EGL-487 missing/unparseable floor ($e203_nofloor) degrades to age only (rc=$e203rc, out: $e203o)"
done
cp -f "$TREE_ROOT/gateway/security-floor" "$e38p/gateway/security-floor"

# 5e. Missing .Created (base label only): no floor/age guess.
printf '%s\n' "$e203dig" > "$e203fix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" == *"OK: gateway image: present ($e203img) — base $e203short"* \
    && "$e203o" != *"rebuild:"* && "$e203o" != *"stale:"* ]] \
    && e203 pass || e203 fail "EGL-487 missing .Created degrades silently (rc=$e203rc, out: $e203o)"
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_recent" > "$e203fix"

# 5f. EGL-487-D5: the optional egl-base image row. Absent = no row;
#     present = mirror row; stale and below-floor carry their own
#     reasons and the helper path from the prefix's share tree. The
#     gateway fixture stays healthy throughout.
e203eglimg="localhost/egl-base:latest"
e203eglfix="$STATE/image-inspect-$(echo "$e203eglimg" | tr '/:' '__')"
rm -f "$STATE/images/localhost_egl-base_latest" "$e203eglfix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 && "$e203o" != *"egl-base image:"* ]] \
    && e203 pass || e203 fail "EGL-487 absent egl-base image prints no row (rc=$e203rc, out: $e203o)"

: > "$STATE/images/localhost_egl-base_latest"
printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_egl_recent" > "$e203eglfix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"OK: egl-base image: present (localhost/egl-base:latest) — base $e203short, built $e203_egl_recent"* \
    && "$e203o" != *"rebuild:"* ]] \
    && e203 pass || e203 fail "EGL-487 healthy egl-base image row (rc=$e203rc, out: $e203o)"

printf '%s %sT00:00:00.000000000Z\n' "$e203dig" "$e203_egl_before" > "$e203eglfix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"rebuild: egl-base image built $e203_egl_before is older than the kit's security rebuild floor $e203_egl_floor"* \
    && "$e203o" == *"$e38p/examples/egl-base/build-egl-base --force"* ]] \
    && e203 pass || e203 fail "EGL-487 below-floor egl-base rebuild line + helper remedy (rc=$e203rc, out: $e203o)"

printf 'sha256:%064d %sT00:00:00.000000000Z\n' 0 "$e203_egl_recent" > "$e203eglfix"
e203o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e203rc=$?
[[ "$e203rc" == 0 \
    && "$e203o" == *"stale: base pin moved (image base 000000000000 != deployed pin $e203short)"* \
    && "$e203o" == *"$e38p/examples/egl-base/build-egl-base"* && "$e203o" != *"rebuild:"* ]] \
    && e203 pass || e203 fail "EGL-487 moved-pin egl-base stale line (rc=$e203rc, out: $e203o)"
rm -f "$STATE/images/localhost_egl-base_latest" "$e203eglfix"
rm -f "$e203fix"

section_end egl203

# --- EGL-59: kit --help is operator UI — no ticket/process citations -----
# Same rule as the engine (EGL-59-D1/D2/D3): kit help headers must not leak
# ticket/decision IDs or paths. A ticket tree whose path contains the
# `docs/tickets/` substring still matches the D3 regex
# `docs/tickets/[A-Za-z0-9]`. R-EGL-69-1 finding 3's build-gateway
# entry is retired with the script (EGL-253).
section_begin egl59 "EGL-59 kit help operator-UI"
e59() { assert "$@"; }
k59_id_re='ARC-[0-9]|EGL-[0-9]|docs/tickets/[A-Za-z0-9]'
entries59=("egresslock-setup:-h" "egresslock-verify:-h" \
           "install-kit.sh:-h" "uninstall-kit.sh:-h" \
           "egresslock-setup:help")
for entry in "${entries59[@]}"; do
    f="${entry%%:*}"; flag="${entry##*:}"
    o="$(bash "$TREE_ROOT/$f" "$flag" 2>&1)"; rc=$?
    if [[ "$rc" == 0 ]] && ! grep -qE "$k59_id_re" <<<"$o"; then
        e59 pass
    else
        e59 fail "$f $flag leaks ticket/process refs or rc=$rc"
    fi
done

section_end egl59

# --- EGL-60: unlabeled-not-required matrix + out-of-scope guards ----------
# D60-1: on a KNOWN-unlabeled host with the pasta profile found, the verdict
# is `not required on this host (podman unlabeled)` and the check ends
# `Summary: CHECK OK (AppArmor patch not needed)`, rc 0, for every
# extension/rule combination; detail lines stay as evidence.
# D60-2 amends D39-4: missing extension is rc 1 only when `required` or
# `condition unknown` (labeled hosts keep FAILED — e50 #4/#5, 4t, EGL-14 #4).
section_begin egl60 "EGL-60 unlabeled-not-required doctor verdict"
e60() { assert "$@"; }

# 1. The unlabeled-host reproduction (D60-1 matrix cell: MISSING + absent):
#    unlabeled + no include + empty local file -> rc 0, OK (not needed),
#    MISSING + not-required detail lines still printed.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39x" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 \
    && "$o" == *"pasta profile: found"* \
    && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"egresslock rule in local file: absent"* \
    && "$o" == *"pasta amendment: not required on this host (podman unlabeled)"* \
    && "$o" == *"CHECK OK (AppArmor patch not needed)"* ]] \
    && e60 pass || e60 fail "D60-1 unlabeled MISSING+absent -> OK not needed rc 0 (rc=$rc, out: $o)"

# 2. Matrix cell MISSING + rule present (stock operator rule): still
#    rc 0, OK (not needed), MISSING line stays.
mkdir -p "$aa22/aad60m/local"
printf '/usr/bin/pasta {\n}\n' > "$aa22/aad60m/usr.bin.pasta"
printf 'signal (receive) set=(term) peer=podman,\n' > "$aa22/aad60m/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad60m" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"egresslock rule in local file: present (stock)"* \
    && "$o" == *"CHECK OK (AppArmor patch not needed)"* ]] \
    && e60 pass || e60 fail "D60-1 unlabeled MISSING+present rule -> OK not needed rc 0 (rc=$rc, out: $o)"

# 3. Matrix cells with the extension present: present+absent (fresh
#    fixture — aad39's local file was filled by the EGL-39 4m apply) and
#    present+present (aad60p) both rc 0, OK (not needed), on the
#    unlabeled host.
mkdir -p "$aa22/aad60i/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad60i/usr.bin.pasta"
: > "$aa22/aad60i/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad60i" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"pasta local extension: present (stock)"* \
    && "$o" == *"egresslock rule in local file: absent"* \
    && "$o" == *"CHECK OK (AppArmor patch not needed)"* ]] \
    && e60 pass || e60 fail "D60-1 unlabeled present+absent -> OK not needed rc 0 (rc=$rc, out: $o)"
mkdir -p "$aa22/aad60p/local"
printf '/usr/bin/pasta {\n  #include <local/usr.bin.pasta>\n}\n' > "$aa22/aad60p/usr.bin.pasta"
printf 'signal (receive) set=(term) peer=podman,\n' > "$aa22/aad60p/local/usr.bin.pasta"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad60p" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"pasta local extension: present (stock)"* \
    && "$o" == *"egresslock rule in local file: present (stock)"* \
    && "$o" == *"CHECK OK (AppArmor patch not needed)"* ]] \
    && e60 pass || e60 fail "D60-1 unlabeled present+present -> OK not needed rc 0 (rc=$rc, out: $o)"

# 4. Out-of-scope guards stay frozen (D60-2): missing pasta profile file
#    even unlabeled -> rc 1 / FAILED incomplete; pasta-not-enforced
#    unlabeled verdict -> rc 1 (EGL-29-D1 4l); labeled+MISSING+absent ->
#    FAILED (patch needed) rc 1 (e50 #4); labeled+MISSING+present rule
#    -> FAILED incomplete rc 1 (4t).
mkdir -p "$aa22/aad60x"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad60x" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.nopodman" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta profile: missing file"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch incomplete)"* ]] \
    && e60 pass || e60 fail "D60-2 missing profile file stays FAILED rc 1 (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles.none" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta amendment: not required on this host (pasta not enforced)"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch incomplete)"* ]] \
    && e60 pass || e60 fail "D60-2 pasta-not-enforced stays FAILED rc 1 (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad39x" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch needed)"* ]] \
    && e60 pass || e60 fail "D60-2 labeled MISSING+absent stays FAILED needed rc 1 (rc=$rc, out: $o)"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 PATH="$aa22/bin:$PATH" \
    EGRESSLOCK_SHARE="$aa22/share" EGRESSLOCK_APPARMOR_D="$aa22/aad60m" \
    EGRESSLOCK_APPARMOR_PROFILES="$aa22/profiles" "$SKIT" --apparmor-check 2>&1)"; rc=$?
[[ "$rc" == 1 && "$o" == *"pasta local extension: MISSING"* \
    && "$o" == *"Summary: CHECK FAILED (AppArmor patch incomplete)"* ]] \
    && e60 pass || e60 fail "D60-2 labeled MISSING+present rule stays FAILED incomplete rc 1 (rc=$rc, out: $o)"

section_end egl60

# --- EGL-68/EGL-69: install-kit foreign-prefix guard; apparmor/ ships
#     with the prefix ----------------------------------------------------
section_begin egl68 "EGL-68/69 install-kit guard + apparmor prefix"
e68() { assert "$@"; }

# EGL-68-D1: a non-kit prefix with a foreign gateway/ is refused rc 1,
# and the guard runs BEFORE any write: no engine binary smeared into
# the tree, the foreign gateway/ byte-identical.
e68p="$STATE/e68/foreign"; rm -rf "$STATE/e68"; mkdir -p "$e68p/gateway"
printf 'not a kit\n' > "$e68p/gateway/Makefile"
e68o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68p/wbin" EGRESSLOCK_PATH_SBINDIR="$e68p/wsbin" \
    "$KIT" --prefix "$e68p" 2>&1)"; e68_rc=$?
[[ "$e68_rc" == 1 && "$e68o" == *"refusing to delete $e68p/gateway"* ]] \
    && e68 pass || e68 fail "foreign gateway/ refused rc 1 (rc=$e68_rc, out: $e68o)"
[[ -f "$e68p/gateway/Makefile" && ! -e "$e68p/egresslock" && ! -e "$e68p/VERSION" \
    && ! -e "$e68p/gateway.tmp" ]] \
    && e68 pass || e68 fail "foreign tree untouched (guard precedes all writes)"
# The same guard covers examples/recipes: no markers, foreign tree, refused.
e68r="$STATE/e68/foreign-recipes"; mkdir -p "$e68r/examples/recipes"
printf 'keep\n' > "$e68r/examples/recipes/keep.txt"
e68o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68r/wbin" EGRESSLOCK_PATH_SBINDIR="$e68r/wsbin" \
    "$KIT" --prefix "$e68r" 2>&1)"; e68_rc=$?
[[ "$e68_rc" == 1 && -f "$e68r/examples/recipes/keep.txt" && ! -e "$e68r/egresslock" ]] \
    && e68 pass || e68 fail "foreign recipes/ refused, untouched (rc=$e68_rc, out: $e68o)"
# EGL-232: the same guard covers examples/egl-base (foreign tree refused
# rc 1, never deleted).
e68b="$STATE/e68/foreign-egl-base"; mkdir -p "$e68b/examples/egl-base"
printf 'keep\n' > "$e68b/examples/egl-base/keep.txt"
e68o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68b/wbin" EGRESSLOCK_PATH_SBINDIR="$e68b/wsbin" \
    "$KIT" --prefix "$e68b" 2>&1)"; e68_rc=$?
[[ "$e68_rc" == 1 && -f "$e68b/examples/egl-base/keep.txt" && ! -e "$e68b/egresslock" ]] \
    && e68 pass || e68 fail "foreign egl-base/ refused, untouched (rc=$e68_rc, out: $e68o)"
# Kit-shaped tree (gateway/Containerfile present, no other markers):
# the rm paths are kit-shaped, the install proceeds.
e68k="$STATE/e68/kitshaped"; mkdir -p "$e68k/gateway"
: > "$e68k/gateway/Containerfile"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68k/wbin" EGRESSLOCK_PATH_SBINDIR="$e68k/wsbin" \
    "$KIT" --prefix "$e68k" >/dev/null 2>&1; e68_rc=$?
[[ "$e68_rc" == 0 && -f "$e68k/egresslock" && -f "$e68k/gateway/Containerfile" ]] \
    && e68 pass || e68 fail "kit-shaped tree (gateway/Containerfile) installs (rc=$e68_rc)"
# A marked prefix reinstalls and still replaces gateway/ wholesale
# (the rm path is taken; stale files do not survive an upgrade).
e68m="$STATE/e68/marked"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68m/wbin" EGRESSLOCK_PATH_SBINDIR="$e68m/wsbin" \
    "$KIT" --prefix "$e68m" >/dev/null 2>&1
[[ -f "$e68m/VERSION" ]] \
    && e68 pass || e68 fail "marked prefix fixture (VERSION present)"
printf 'stale\n' > "$e68m/gateway/Containerfile.stale"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68m/wbin" EGRESSLOCK_PATH_SBINDIR="$e68m/wsbin" \
    "$KIT" --prefix "$e68m" >/dev/null 2>&1; e68_rc=$?
[[ "$e68_rc" == 0 && -f "$e68m/gateway/Containerfile" \
    && ! -e "$e68m/gateway/Containerfile.stale" ]] \
    && e68 pass || e68 fail "reinstall on marked prefix replaces gateway/ (rc=$e68_rc)"
# EGL-531-D1: a leftover `.tmp` staging path used to receive `cp -R` INTO
# it, so the later `mv` deployed gateway/gateway/… — pre-clean each of the
# four staging paths and pin the shipped tree shape.
e68t="$STATE/e68/stale-tmp"; rm -rf "$e68t"
mkdir -p "$e68t/gateway.tmp/stale" "$e68t/apparmor.tmp/stale" \
    "$e68t/examples/recipes.tmp/stale" "$e68t/examples/egl-base.tmp/stale"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68t/wbin" EGRESSLOCK_PATH_SBINDIR="$e68t/wsbin" \
    "$KIT" --prefix "$e68t" >/dev/null 2>&1; e68_rc=$?
[[ "$e68_rc" == 0 \
    && -f "$e68t/gateway/Containerfile" && ! -e "$e68t/gateway/gateway" \
    && -f "$e68t/apparmor/usr.bin.pasta.local" && ! -e "$e68t/apparmor/apparmor" \
    && -f "$e68t/examples/recipes/github.md" && ! -e "$e68t/examples/recipes/recipes" \
    && -f "$e68t/examples/egl-base/Containerfile" \
    && ! -e "$e68t/examples/egl-base/egl-base" \
    && ! -e "$e68t/gateway.tmp" && ! -e "$e68t/apparmor.tmp" ]] \
    && e68 pass || e68 fail "stale .tmp staging paths are pre-cleaned, no nested deploy (rc=$e68_rc)"
# EGL-69-D2: a fresh prefix ships apparmor/usr.bin.pasta.local.
e68a="$STATE/e68/aaprefix"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e68a/wbin" EGRESSLOCK_PATH_SBINDIR="$e68a/wsbin" \
    "$KIT" --prefix "$e68a" >/dev/null 2>&1; e68_rc=$?
[[ "$e68_rc" == 0 && -f "$e68a/apparmor/usr.bin.pasta.local" ]] \
    && e68 pass || e68 fail "install-kit prefix ships apparmor/usr.bin.pasta.local (rc=$e68_rc)"

section_end egl68

# --- EGL-90: strict --prefix charset (audit I-02/I-03), quoted PATH
#     wrapper exec, EGL-68 guard extended to apparmor/ -------------------
section_begin egl90 "EGL-90 prefix charset + quoted wrapper + apparmor guard"
e90() { assert "$@"; }
e90d="$STATE/e90"; rm -rf "$e90d"; mkdir -p "$e90d/units" "$e90d/wbin" "$e90d/wsbin"
# e90run: install-kit with the mock dirs; captures output, leaves rc.
e90run() {
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e90d/units" \
        EGRESSLOCK_PATH_BINDIR="$e90d/wbin" EGRESSLOCK_PATH_SBINDIR="$e90d/wsbin" \
        "$KIT" --prefix "$1" 2>&1
}
# 1. (D2.1) '/tmp/eg;id' -> rc 2; NOTHING written: no wrapper, no unit
#    template, no prefix dir (the check runs at parse).
e90o="$(e90run '/tmp/eg;id')"; e90_rc=$?
[[ "$e90_rc" == 2 && "$e90o" == *"must be an absolute kit path"* \
    && ! -e "$e90d/wbin/egresslock" && ! -e "$e90d/wsbin/egresslock-setup" \
    && ! -e "$e90d/units/egresslock-verify@.service" && ! -e "/tmp/eg;id" ]] \
    && e90 pass || e90 fail "metachar --prefix rejected rc 2, nothing written (rc=$e90_rc, out: $e90o)"
# 2. (D2.2) |, $( ), and whitespace -> rc 2 (the sed-delimiter and
#    shell-metachar classes).
for e90_p in '/tmp/a|b' '/tmp/$(id)' '/tmp/a b'; do
    e90o="$(e90run "$e90_p")"; e90_rc=$?
    if [[ "$e90_rc" == 2 && "$e90o" == *"must be an absolute kit path"* ]]; then
        e90 pass
    else
        e90 fail "illegal --prefix '$e90_p' rejected rc 2 (rc=$e90_rc, out: $e90o)"
    fi
done
# 3. (D2.3) a legal absolute prefix (dots allowed) still installs; the
#    wrapper exec is QUOTED, the marker comment stays unquoted, and the
#    unit template carries the substituted ExecStart.
e90ok="$e90d/ok.prefix"
e90o="$(e90run "$e90ok")"; e90_rc=$?
[[ "$e90_rc" == 0 && -f "$e90ok/egresslock" ]] \
    && e90 pass || e90 fail "legal dotted prefix installs (rc=$e90_rc, out: $e90o)"
[[ "$(sed -n '2p' "$e90d/wbin/egresslock")" == "# egresslock-path-wrapper prefix=$e90ok" ]] \
    && e90 pass || e90 fail "wrapper marker line 2 stays unquoted (EGL-43 matching)"
grep -qF "exec \"$e90ok/egresslock\" \"\$@\"" "$e90d/wbin/egresslock" \
    && e90 pass || e90 fail "wrapper exec is quoted (I-03 defense in depth)"
grep -qF "exec \"$e90ok/egresslock-setup\" \"\$@\"" "$e90d/wsbin/egresslock-setup" \
    && e90 pass || e90 fail "setup wrapper exec is quoted"
grep -qF "ExecStart=$e90ok/egresslock-verify" "$e90d/units/egresslock-verify@.service" \
    && e90 pass || e90 fail "unit template ExecStart carries the legal prefix"
# 4. (EGL-90-D3) the EGL-68 guard now also covers $prefix/apparmor: a
#    foreign apparmor/ tree with no kit markers anywhere is refused rc 1
#    and left byte-identical, BEFORE any copy.
e90aa="$e90d/foreign-aa"; mkdir -p "$e90aa/apparmor"
printf 'keep\n' > "$e90aa/apparmor/keep.conf"
e90o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e90d/units" \
    EGRESSLOCK_PATH_BINDIR="$e90aa/wbin" EGRESSLOCK_PATH_SBINDIR="$e90aa/wsbin" \
    "$KIT" --prefix "$e90aa" 2>&1)"; e90_rc=$?
[[ "$e90_rc" == 1 && -f "$e90aa/apparmor/keep.conf" \
    && "$e90o" == *"refusing to delete $e90aa/apparmor"* && ! -e "$e90aa/egresslock" ]] \
    && e90 pass || e90 fail "foreign apparmor/ refused rc 1, untouched (rc=$e90_rc, out: $e90o)"

section_end egl90

# --- EGL-83: co-install guard — postinst /etc shadow handling (D1) +
#     install-kit deb-libdir refuse (D2) ---------------------------------
section_begin egl83 "EGL-83 co-install guard: postinst /etc shadow + deb-libdir refuse"
e83() { assert "$@"; }
e83="$STATE/e83"; rm -rf "$e83"; mkdir -p "$e83"

# D3: the staged (not built) postinst carries the shadow guard.
# EGL-107-D1: staging + the staged-text asserts skip with the producer
# on the extracted kit; the deb-libdir refusal assert below is
# packaging-independent and still runs.
if [[ "$HAVE_BUILD_DEB" == 1 ]]; then
s_out="$(env EGRESSLOCK_DEB_KEEP_STAGE="$e83/stage" \
    EGRESSLOCK_DEB_OUT="$e83/deb" "$DEBSH" 2>&1)"; s_rc=$?
[[ "$s_rc" == 0 && -f "$e83/stage/DEBIAN/postinst" ]] \
    && e83 pass || e83 fail "deb staging run (rc=$s_rc, out: $s_out)"
e83pi="$e83/stage/DEBIAN/postinst"
grep -q '/etc/systemd/system/egresslock-verify@.service' "$e83pi" \
    && e83 pass || e83 fail "postinst checks the /etc shadow template (D1)"
grep -qF 'uninstall-kit.sh --prefix $live_prefix' "$e83pi" \
    && e83 pass || e83 fail "postinst fail-branch names the uninstall remediation (D1)"
grep -q 'dpkg --configure egresslock' "$e83pi" \
    && e83 pass || e83 fail "postinst fail-branch names the configure finisher (D1)"
grep -q 'removed stale prefix-install unit shadowing' "$e83pi" \
    && e83 pass || e83 fail "postinst remove-stale branch named (D1)"
# EGL-102-D6-R5: the /etc classification (R5 table on the postinst card)
# is staged-text asserted; the mock battery cannot run dpkg/postinst.
grep -q 'cmp -s' "$e83pi" \
    && e83 pass || e83 fail "postinst classifies the /etc timer against the package copy (R5)"
grep -q 'stale-product' "$e83pi" \
    && e83 pass || e83 fail "postinst product-shaped stale class (R5)"
grep -q 'kept $etc_svc — not recognizable' "$e83pi" \
    && e83 pass || e83 fail "unknown-shape service kept with disclosure (R5)"
grep -q 'kept $etc_tmr' "$e83pi" \
    && e83 pass || e83 fail "unknown-shape timer kept with disclosure (R5)"
grep -q 'prefix-live' "$e83pi" \
    && e83 pass || e83 fail "live custom-prefix detection via ExecStart markers (R1/R5)"
grep -q 'reset-failed' "$e83pi" \
    && e83 pass || e83 fail "postinst resets failed instances (D1)"
# EGL-531-D2: the /opt-only co-install shape (a live prefix engine with
# no /etc template to shadow the deb units) hard-fails instead of
# completing warn-only, with the uninstall remediation + configure finisher.
e83opt="$(awk '/^if \[ -e \/opt\/egresslock\/egresslock \]; then$/{f=1} f{print} f&&/^fi$/{exit}' "$e83pi")"
[[ -n "$e83opt" && "$e83opt" == *"exit 1"* \
    && "$e83opt" == *"The two install channels must never"* \
    && "$e83opt" == *"uninstall-kit.sh --prefix /opt/egresslock"* \
    && "$e83opt" == *"dpkg --configure egresslock"* \
    && "$e83opt" != *"WARNING: a prefix kit also exists"* ]] \
    && e83 pass || e83 fail "postinst /opt-only co-install shape hard-fails (block: $e83opt)"
if grep -vE '^\s*(#|$)' "$e83pi" | grep -qE 'systemctl enable|apparmor_parser'; then
    e83 fail "postinst enables a timer or applies AppArmor (D1 boundary)"
else
    e83 pass
fi
# EGL-270 P3 (candidate 6): egl103 folded into this block. It consumed this
# staged deb tree and re-grepped boundaries already pinned above; the folded
# asserts are the ones with no home here — one postinst/postrm disclosure
# line per unit mutate (R2 bounded to unit mutates; the mock cannot run
# dpkg/postinst). The duplicate stale-prefix-unit re-grep was dropped.
e83prm="$e83/stage/DEBIAN/postrm"
# The always-run reload discloses exactly once (dedupe: the shadow-rm
# branch must not print a second daemon-reload line).
[[ "$(grep -cF 'postinst: systemd daemon-reload' "$e83pi")" == 1 ]] \
    && e83 pass || e83 fail "postinst prints the daemon-reload line exactly once"
grep -qF 'postrm: systemd daemon-reload' "$e83prm" \
    && e83 pass || e83 fail "postrm prints the daemon-reload line"
# postrm stays a reload-only script (ARC-22-D2 boundary re-check).
if grep -vE '^\s*(#|$)' "$e83prm" | grep -qE 'rm -rf|rm -f|podman|config/egresslock|apparmor_parser'; then
    e83 fail "postrm deletes state or touches podman/AppArmor"
else
    e83 pass
fi
else
    skip "$PKG_SKIP_TAG" "EGL-83 staged-postinst asserts — packaging/build-deb.sh is not on this tree (extracted kit)"
fi

# D3: install-kit refuses a deb-libdir kit (EGRESSLOCK_DEB_LIBDIR/VERSION
# present, no dpkg-query needed) rc 1, and writes NO units and NO PATH
# wrappers (the refusal sits in the wrapper stage, before section 2).
e83d="$e83/libdir"; mkdir -p "$e83d/libdir" "$e83d/units" "$e83d/wbin" "$e83d/wsbin"
: > "$e83d/libdir/VERSION"
e83o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e83d/units" \
    EGRESSLOCK_PATH_BINDIR="$e83d/wbin" EGRESSLOCK_PATH_SBINDIR="$e83d/wsbin" \
    EGRESSLOCK_DEB_LIBDIR="$e83d/libdir" \
    "$KIT" --prefix "$e83d/opt" 2>&1)"; e83_rc=$?
[[ "$e83_rc" == 1 && "$e83o" == *'apt remove egresslock'* \
    && "$e83o" == *'rm -r'* \
    && ! -e "$e83d/units/egresslock-verify@.service" \
    && ! -e "$e83d/wbin/egresslock" && ! -e "$e83d/wsbin/egresslock-setup" ]] \
    && e83 pass || e83 fail "deb-libdir kit refuses install-kit rc 1 (rc=$e83_rc, out: $e83o)"

section_end egl83

# --- EGL-103-D3: postinst/postrm print one line per unit mutate ---------
# Removed per EGL-270 P3 (candidate 6): the section consumed the EGL-83
# staged deb tree and re-grepped boundaries pinned at stage-build time;
# its unique disclosure-time asserts now run inside egl83's staged block
# (same fixture, one skip cover — the EGL-107-D1 skip reason stands).

# --- EGL-102-D6-R2: install-kit source-completeness preflight -----------
# An incomplete kit tree fails closed BEFORE any copy (nothing written,
# named missing files + next action) instead of a mid-deploy
# `install: cannot stat` partial prefix.
section_begin egl102r2 "EGL-102-R2 install-kit source-completeness preflight (excluded-silent — no RESULTS line, not in TOTAL; declared gap, EGL-184-D2)" excluded-silent
e102r2() { assert "$@"; }
e102d="$STATE/e102r2"; rm -rf "$e102d"; mkdir -p "$e102d/sparse" "$e102d/dest"
cp "$TREE_ROOT/install-kit.sh" "$e102d/sparse/"
printf '0.2.0\n' > "$e102d/sparse/VERSION_BASE"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102d/sparse/install-kit.sh" --prefix "$e102d/dest" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102d/sparse"* \
    && "$e102o" == *"missing: "* && "$e102o" == *"restore the full checkout"* \
    && ! -e "$e102d/dest/egresslock" && ! -e "$e102d/units/egresslock-verify@.service" ]] \
    && e102r2 pass || e102r2 fail "incomplete tree fails closed, nothing written (rc=$e102_rc, out: $e102o)"

# EGL-270 P3 (candidate 12, generated-glue refactor — excluded-silent, no
# counted delta): the kit manifest is enumerated once; each partial case
# stages the full tree minus its own exclusion instead of three
# hand-maintained copies that grew one entry per release.
e102_manifest=(
    install-kit.sh egresslock egresslock-start egresslock-verify egresslock-setup
    gateway/Containerfile gateway/entrypoint.sh gateway/squid.conf
    gateway/security-floor
    apparmor/usr.bin.pasta.local apparmor/README.md
    examples/main.conf examples/main-allowlist examples/recipes
    examples/egl-base/Containerfile examples/egl-base/README.md
    examples/egl-base/build-egl-base examples/egl-base/security-floor
    docs
    systemd/egresslock-verify@.service systemd/egresslock-verify@.timer
)
e102_stage_tree() { # e102_stage_tree <dest> [missing...] — manifest minus exclusions, VERSION_BASE seeded
    local d="$1"; shift
    local f skip
    for f in "${e102_manifest[@]}"; do
        for skip in "$@"; do
            [[ "$f" == "$skip" ]] && continue 2
        done
        mkdir -p "$d/$(dirname "$f")"
        cp -R "$TREE_ROOT/$f" "$d/$f"
    done
    printf '0.2.0\n' > "$d/VERSION_BASE"
}

# Partial case (EGL-102-D6-F3): every enumerated item present EXCEPT
# examples/recipes — the preflight must still fail closed BEFORE any
# copy (the copy list copies recipes unconditionally; without this, the
# gate passes and a bare `cp: cannot stat ... recipes` kills a partial
# deploy mid-way). EGL-549: the widened manifest names the tree root and
# its leaves, so the refusal names the missing recipes set (root first).
e102p="$e102d/partial"; mkdir -p "$e102p"
e102_stage_tree "$e102p" examples/recipes
e102d2="$e102d/dest2"; mkdir -p "$e102d2"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102p/install-kit.sh" --prefix "$e102d2" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102p"* \
    && "$e102o" == *"(missing: examples/recipes "* \
    && "$e102o" == *"examples/recipes/github.md"* \
    && "$e102o" == *"examples/recipes/agent-container-example/Containerfile"* \
    && ! -e "$e102d2/egresslock" && ! -e "$e102d2/gateway" && ! -e "$e102d2/examples" ]] \
    && e102r2 pass || e102r2 fail "recipes-only gap fails closed pre-copy (rc=$e102_rc, out: $e102o)"

# EGL-232: the enumeration covers egl-base too — everything present EXCEPT
# examples/egl-base/Containerfile must fail closed BEFORE any copy.
e102b="$e102d/partial-eglbase"; mkdir -p "$e102b"
e102_stage_tree "$e102b" examples/egl-base/Containerfile
e102d3="$e102d/dest3"; mkdir -p "$e102d3"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102b/install-kit.sh" --prefix "$e102d3" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102b"* \
    && "$e102o" == *"(missing: examples/egl-base/Containerfile)"* \
    && ! -e "$e102d3/egresslock" && ! -e "$e102d3/gateway" && ! -e "$e102d3/examples" ]] \
    && e102r2 pass || e102r2 fail "egl-base-only gap fails closed pre-copy (rc=$e102_rc, out: $e102o)"

# EGL-240: the manifest lists the helper (already pinned), so the full tree
# minus the helper reports exactly that one path; nothing copied.
e102h="$e102d/partial-helper"; mkdir -p "$e102h"
e102_stage_tree "$e102h" examples/egl-base/build-egl-base
e102d4="$e102d/dest4"; mkdir -p "$e102d4"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102h/install-kit.sh" --prefix "$e102d4" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102h"* \
    && "$e102o" == *"(missing: examples/egl-base/build-egl-base)"* \
    && ! -e "$e102d4/egresslock" && ! -e "$e102d4/gateway" && ! -e "$e102d4/examples" ]] \
    && e102r2 pass || e102r2 fail "helper-absent gap fails closed pre-copy (rc=$e102_rc, out: $e102o)"

# EGL-253: the README is copied by `cp -R` and required by build-deb, so a
# README-only source gap must fail closed pre-copy naming exactly that path.
e102rm="$e102d/partial-readme"; mkdir -p "$e102rm"
e102_stage_tree "$e102rm" examples/egl-base/README.md
e102d5="$e102d/dest5"; mkdir -p "$e102d5"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102rm/install-kit.sh" --prefix "$e102d5" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102rm"* \
    && "$e102o" == *"(missing: examples/egl-base/README.md)"* \
    && ! -e "$e102d5/egresslock" && ! -e "$e102d5/gateway" && ! -e "$e102d5/examples" ]] \
    && e102r2 pass || e102r2 fail "README-only gap fails closed pre-copy (rc=$e102_rc, out: $e102o)"

# EGL-556-D2: the docs tree is part of the gate. Missing and symlinked
# trees both fail closed naming exactly `docs`, before any copy.
e102doc="$e102d/partial-docs"; mkdir -p "$e102doc"
e102_stage_tree "$e102doc" docs
e102d6="$e102d/dest6"; mkdir -p "$e102d6"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102doc/install-kit.sh" --prefix "$e102d6" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102doc"* \
    && "$e102o" == *"(missing: docs)"* \
    && ! -e "$e102d6/egresslock" && ! -e "$e102d6/gateway" ]] \
    && e102r2 pass || e102r2 fail "docs-only gap fails closed pre-copy (rc=$e102_rc, out: $e102o)"
e102sym="$e102d/partial-docs-link"; mkdir -p "$e102sym"
e102_stage_tree "$e102sym" docs
ln -s "$TREE_ROOT/docs" "$e102sym/docs"
e102d7="$e102d/dest7"; mkdir -p "$e102d7"
e102o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e102d/units" \
    EGRESSLOCK_PATH_BINDIR="$e102d/wbin" EGRESSLOCK_PATH_SBINDIR="$e102d/wsbin" \
    "$e102sym/install-kit.sh" --prefix "$e102d7" 2>&1)"; e102_rc=$?
[[ "$e102_rc" == 1 && "$e102o" == *"incomplete kit tree at $e102sym"* \
    && "$e102o" == *"(missing: docs)"* \
    && ! -e "$e102d7/egresslock" && ! -e "$e102d7/docs" ]] \
    && e102r2 pass || e102r2 fail "symlinked docs/ fails closed pre-copy (rc=$e102_rc, out: $e102o)"
section_end egl102r2

# --- EGL-240: build-egl-base helper (mock podman) ------------------------
# The example-image helper checks/builds localhost/egl-base:latest next
# to its Containerfile. Fixture: helper + Containerfile in a temp dir;
# the shared mock (lib.sh) answers podman image exists/inspect via
# $STATE/image-inspect-… (catted verbatim) and records `podman build`
# into $STATE/buildlog (build -t also makes the image exist). Never
# runs a container; never calls egresslock.
section_begin egl240 "EGL-240 build-egl-base"
e240() { assert "$@"; }
EGLIMG="localhost/egl-base:latest"
EGLSTATE_KEY="$(echo "$EGLIMG" | tr '/:' '__')"
EGLINS="$STATE/image-inspect-$EGLSTATE_KEY"
EGLSRV="$STATE/egl240-srv"
rm -rf "$EGLSRV"; mkdir -p "$EGLSRV"
cp "$TREE_ROOT/examples/egl-base/build-egl-base" "$EGLSRV/build-egl-base"
cp "$TREE_ROOT/examples/egl-base/Containerfile" "$EGLSRV/Containerfile"
chmod +x "$EGLSRV/build-egl-base"
EGLPIN="$(grep -oE 'sha256:[0-9a-f]{64}' "$EGLSRV/Containerfile" | head -1)"
EGLPIN12="${EGLPIN#sha256:}"; EGLPIN12="${EGLPIN12:0:12}"
egl_saved_wd="$(pwd)"

# 1. Foreign cwd: invoke by path; context/flag from the helper's OWN dir.
cd /tmp
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$(cat "$STATE/buildlog")" == *"-f $EGLSRV/Containerfile $EGLSRV"* ]]; then
    e240 pass
else
    e240 fail "case 1 foreign cwd: helper-dir context, not caller cwd (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi
cd "$egl_saved_wd"

# 2. Missing image → builds.
: > "$STATE/buildlog"
rm -f "$STATE/images/$EGLSTATE_KEY"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"egl-base image: missing (localhost/egl-base:latest)"* \
      && "$e_out" == *"Building localhost/egl-base:latest FROM $EGLPIN12"* \
      && "$e_out" == *"Done: localhost/egl-base:latest"* \
      && -s "$STATE/buildlog" && "$(cat "$STATE/buildlog")" != *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 2 missing → build (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi
assert_kit_lines_paste_safe "egl-base build banner" "$e_out" '^Building'
assert_kit_lines_paste_safe "egl-base done line" "$e_out" '^Done:'

# 3. Current image (label pin == deployed pin) → exact up-to-date line.
printf '%s\n' "$EGLPIN" > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"already built from deployed pin $EGLPIN12"* \
      && ! -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 3 current → exact up-to-date line, no build (rc=$e_rc, out: $e_out)"
fi

# 4. Stale (label pin != deployed pin) → stale + rebuild.
printf 'sha256:deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef\n' > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"egl-base image: stale: base pin moved (image deadbeefdead != deployed pin $EGLPIN12)"* \
      && -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 4 stale pin → rebuild (rc=$e_rc, out: $e_out)"
fi

# 5a. Pre-label: empty inspect fixture.
: > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"egl-base image: stale: base unknown (pre-label image)"* \
      && -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 5a pre-label empty fixture → rebuild (rc=$e_rc, out: $e_out)"
fi
# 5b. Pre-label: the literal <no value> (missing Go-template key).
printf '<no value>\n' > "$EGLINS"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"egl-base image: stale: base unknown (pre-label image)"* \
      && -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 5b pre-label <no value> → rebuild (rc=$e_rc, out: $e_out)"
fi

# 6. --force on a current image → rebuild with --no-cache, no state line.
printf '%s\n' "$EGLPIN" > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" --force 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"Building"* && "$e_out" != *"egl-base image:"* \
      && "$(cat "$STATE/buildlog")" == *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6 --force rebuilds (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi

# 6b. EGL-487-D4: below the recorded floor at pin equality is a real
#     refresh (--no-cache) and names the floor; age alone never builds.
e240_floor="$(awk '{ sub(/#.*/, ""); gsub(/[[:space:]]/, ""); if ($0 != "") { print; exit } }' \
    "$TREE_ROOT/examples/egl-base/security-floor")"
e240_below="$(date -u -d "$e240_floor - 5 days" '+%Y-%m-%d')"
printf '%s\n' "$e240_floor" > "$EGLSRV/security-floor"
printf '%s %sT00:00:00.000000000Z\n' "$EGLPIN" "$e240_below" > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"egl-base image: built $e240_below predates the recorded rebuild floor $e240_floor — rebuilding with --no-cache"* \
      && "$(cat "$STATE/buildlog")" == *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6b below-floor equal-pin rebuild (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi

# 6c. Above the floor at pin equality → the exact up-to-date line, no
#     build. R-EGL-487-2 F3: never below the floor (a release-day bump
#     would otherwise red this healthy leg).
e240_above="$(date -u -d '2 days ago' '+%Y-%m-%d')"
[[ "$e240_above" < "$e240_floor" ]] && e240_above="$e240_floor"
printf '%s %sT00:00:00.000000000Z\n' "$EGLPIN" "$e240_above" > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == "already built from deployed pin $EGLPIN12 — use --force to rebuild" \
      && ! -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 6c above-floor equal-pin is up-to-date (rc=$e_rc, out: $e_out)"
fi

# 6d. Over age but above the floor → still up-to-date; age is the
#     doctor's advisory, never a build trigger.
rm -f "$EGLSRV/security-floor"
printf '%s %sT00:00:00.000000000Z\n' "$EGLPIN" "$(date -u -d '90 days ago' '+%Y-%m-%d')" > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == "already built from deployed pin $EGLPIN12 — use --force to rebuild" \
      && ! -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 6d over-age above-floor still up-to-date, no build (rc=$e_rc, out: $e_out)"
fi

# 6e. Missing or unparseable floor: no floor claim, still up-to-date.
for e240_nofloor in absent garbage; do
    rm -f "$EGLSRV/security-floor"
    [[ "$e240_nofloor" == garbage ]] && printf 'not-a-date\n' > "$EGLSRV/security-floor"
    printf '%s %sT00:00:00.000000000Z\n' "$EGLPIN" "$e240_below" > "$EGLINS"
    : > "$STATE/buildlog"
    e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
    if [[ "$e_rc" == 0 \
          && "$e_out" == "already built from deployed pin $EGLPIN12 — use --force to rebuild" \
          && ! -s "$STATE/buildlog" ]]; then
        e240 pass
    else
        e240 fail "case 6e missing/unparseable floor ($e240_nofloor) does not claim a floor (rc=$e_rc, out: $e_out)"
    fi
done
rm -f "$EGLSRV/security-floor"

# 6f. R-EGL-487-2 F2: only an image whose build date is at or after the
#     floor proves the floor is satisfied. A missing image, a pre-label
#     image, and a missing .Created all rebuild with --no-cache too — a
#     surviving pre-floor apt layer must not be reused and then read as
#     fresh. A moved pin needs no flag (the FROM digest invalidated it).
printf '%s\n' "$e240_floor" > "$EGLSRV/security-floor"
rm -f "$STATE/images/$EGLSTATE_KEY" "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 && -s "$STATE/buildlog" \
      && "$(cat "$STATE/buildlog")" == *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6f missing image + floor uses --no-cache (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi

: > "$STATE/images/$EGLSTATE_KEY"
printf ' 2026-08-01T00:00:00.000000000Z\n' > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 && -s "$STATE/buildlog" \
      && "$(cat "$STATE/buildlog")" == *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6g pre-label image + floor uses --no-cache (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi

printf '%s\n' "$EGLPIN" > "$EGLINS"   # base label matches, no .Created
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 && -s "$STATE/buildlog" \
      && "$(cat "$STATE/buildlog")" == *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6h missing .Created + floor uses --no-cache (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi

printf 'sha256:deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef 2026-08-01T00:00:00.000000000Z\n' > "$EGLINS"
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 && -s "$STATE/buildlog" \
      && "$(cat "$STATE/buildlog")" != *'--no-cache'* ]]; then
    e240 pass
else
    e240 fail "case 6i moved pin + floor still has no --no-cache (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi
rm -f "$EGLSRV/security-floor"

# 7. Podman absent → rc 1, exact error, no build attempted.
egl_emptybin="$STATE/egl240-emptybin"; rm -rf "$egl_emptybin"; mkdir -p "$egl_emptybin"
ln -s "$(command -v bash || echo /usr/bin/bash)" "$egl_emptybin/bash"
ln -s "$(command -v dirname || echo "$(command -v dirname)")" "$egl_emptybin/dirname"
: > "$STATE/buildlog"
e_out="$(PATH="$egl_emptybin" "$EGLSRV/build-egl-base" 2>&1)" && e_rc=0 || e_rc=$?
if [[ "$e_rc" == 1 \
      && "$e_out" == *"Error: podman not found on PATH (required to build localhost/egl-base:latest)"* \
      && ! -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 7 podman absent (rc=$e_rc, out: $e_out)"
fi

# 8. Bad argument → rc 2 usage.
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" foo 2>&1)" && e_rc=0 || e_rc=$?
if [[ "$e_rc" == 2 \
      && "$e_out" == *"Error: build-egl-base takes no arguments other than --force."* ]]; then
    e240 pass
else
    e240 fail "case 8 bad arg rc 2 (rc=$e_rc, out: $e_out)"
fi

# 9. --help prints the header; nothing runs.
: > "$STATE/buildlog"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" --help 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$e_out" == *"build-egl-base — build the shared example image"* \
      && ! -s "$STATE/buildlog" ]]; then
    e240 pass
else
    e240 fail "case 9 --help (rc=$e_rc, out: $e_out)"
fi

# 10. Build failure → rc 1, exact retry line, no --force when plain.
rm -f "$STATE/images/$EGLSTATE_KEY" "$EGLINS"
: > "$STATE/build-fails"
: > "$STATE/buildlog"
egl_noP="$(PATH="$TESTROOT/bin:$PATH" "$EGLSRV/build-egl-base" 2>&1)" && e_rc=0 || e_rc=$?
egl_q="$(printf '%q' "$EGLSRV/build-egl-base")"
if [[ "$e_rc" == 1 \
      && "$egl_noP" == *"Error: egl-base image build failed for localhost/egl-base:latest (build output above); fix the cause and re-run: $egl_q"* \
      && "$egl_noP" != *"--force"* ]]; then
    e240 pass
else
    e240 fail "case 10 build failure retry (rc=$e_rc, out: $egl_noP, expect retry: $egl_q)"
fi
rm -f "$STATE/build-fails"

# 11. Missing Containerfile → rc 1 exact error.
egl_nocf="$STATE/egl240-nocf"; rm -rf "$egl_nocf"; mkdir -p "$egl_nocf"
cp "$TREE_ROOT/examples/egl-base/build-egl-base" "$egl_nocf/build-egl-base"
chmod +x "$egl_nocf/build-egl-base"
e_out="$(PATH="$TESTROOT/bin:$PATH" "$egl_nocf/build-egl-base" 2>&1)" && e_rc=0 || e_rc=$?
if [[ "$e_rc" == 1 \
      && "$e_out" == *"Error: no Containerfile at $egl_nocf/Containerfile"* ]]; then
    e240 pass
else
    e240 fail "case 11 missing Containerfile (rc=$e_rc, out: $e_out)"
fi
# 12. Exported CDPATH must not change the helper's own-directory
#     canonicalization (R-EGL-378-12): a non-`./` relative invocation
#     (`egl-base/build-egl-base`) must resolve the context next to the
#     script, never a foreign CDPATH hit. Without `CDPATH=` on the
#     script's own `cd`, bash lands in the foreign egl-base/ and the
#     helper dies on a false missing-Containerfile error before any
#     build. Mutation: drop the guard -> rc 1, no build -> reds.
egl_cd="$STATE/egl240-cd"; rm -rf "$egl_cd"; mkdir -p "$egl_cd/egl-base"
cp "$TREE_ROOT/examples/egl-base/build-egl-base" "$egl_cd/egl-base/build-egl-base"
cp "$TREE_ROOT/examples/egl-base/Containerfile" "$egl_cd/egl-base/Containerfile"
chmod +x "$egl_cd/egl-base/build-egl-base"
egl_cd_foreign="$STATE/egl240-cd-foreign"; rm -rf "$egl_cd_foreign"; mkdir -p "$egl_cd_foreign/egl-base"
rm -f "$STATE/images/$EGLSTATE_KEY"
: > "$STATE/buildlog"
e_out="$(cd "$egl_cd" && PATH="$TESTROOT/bin:$PATH" CDPATH="$egl_cd_foreign" \
    egl-base/build-egl-base 2>&1)"; e_rc=$?
if [[ "$e_rc" == 0 \
      && "$(cat "$STATE/buildlog")" == *"-f $egl_cd/egl-base/Containerfile $egl_cd/egl-base"* \
      && "$e_out" != *"$egl_cd_foreign"* ]]; then
    e240 pass
else
    e240 fail "case 12 CDPATH exported, non-./ relative invocation still resolves the helper context (rc=$e_rc, out: $e_out, bl: $(cat "$STATE/buildlog" 2>/dev/null))"
fi
rm -f "$EGLINS"
# 13. Untraversable CWD (R-EGL-378-15): every podman call in the helper
#     runs from / (in_root), so the headline failure does not persist on
#     this shipped account helper. The CWD log proves the start
#     directory; the build log proves the helper-local context.
#     Mutation: drop an `in_root` prefix -> the mock's startup chdir
#     fails (rc 125) -> reds.
egl_blocked="$STATE/egl240-blocked"; rm -rf "$egl_blocked"; mkdir -p "$egl_blocked"
egl_cwdlog="$STATE/egl240-cwd.log"; : > "$egl_cwdlog"
rm -f "$STATE/images/$EGLSTATE_KEY"
: > "$STATE/buildlog"
( cd "$egl_blocked" && chmod 000 . \
    && env PATH="$TESTROOT/bin:$PATH" ARCMOCK_PODMAN_CWD_LOG="$egl_cwdlog" \
        "$EGLSRV/build-egl-base" ) > "$STATE/egl240-blocked.out" 2>&1; e_rc=$?
chmod 755 "$egl_blocked"
egl_cwdseen="$(sort -u "$egl_cwdlog")"
if [[ "$e_rc" == 0 && "$egl_cwdseen" == "/" \
      && "$(cat "$STATE/buildlog")" == *"-f $EGLSRV/Containerfile $EGLSRV"* \
      && "$(cat "$STATE/egl240-blocked.out")" != *"cannot chdir"* ]]; then
    e240 pass
else
    e240 fail "case 13 untraversable CWD: helper runs podman from / (rc=$e_rc, cwd-log: $(printf '%s' "$egl_cwdseen" | tr '\n' '|'), bl: $(cat "$STATE/buildlog" 2>/dev/null), out: $(cat "$STATE/egl240-blocked.out"))"
fi

# 14. Relative Podman path settings keep their invocation-directory
#     meaning across the helper's cd / (R-EGL-378-15, same class as the
#     engine's egl378 leg 10): a caller-exported relative
#     CONTAINERS_CONF must still open. Mutation: drop the absolutization
#     loop from in_root -> the mock resolves /podman.conf and exits 125
#     -> reds.
egl_envdir="$STATE/egl240-env"; rm -rf "$egl_envdir"; mkdir -p "$egl_envdir"
printf '[engine]\n' > "$egl_envdir/podman.conf"
egl_cfglog="$STATE/egl240-config.log"; : > "$egl_cfglog"
rm -f "$STATE/images/$EGLSTATE_KEY"
: > "$STATE/buildlog"
( cd "$egl_envdir" && env PATH="$TESTROOT/bin:$PATH" \
    ARCMOCK_PODMAN_CONFIG_VARS="CONTAINERS_CONF" \
    ARCMOCK_PODMAN_CONFIG_LOG="$egl_cfglog" \
    CONTAINERS_CONF=./podman.conf \
    "$EGLSRV/build-egl-base" ) > "$STATE/egl240-env.out" 2>&1; e_rc=$?
egl_cfgseen="$(sort -u "$egl_cfglog")"
if [[ "$e_rc" == 0 \
      && "$egl_cfgseen" == "CONTAINERS_CONF=$egl_envdir/./podman.conf" \
      && -s "$STATE/buildlog" \
      && "$(cat "$STATE/egl240-env.out")" != *"no such file"* ]]; then
    e240 pass
else
    e240 fail "case 14 relative Podman settings preserved (rc=$e_rc, config: $(printf '%s' "$egl_cfgseen" | tr '\n' '|'), out: $(cat "$STATE/egl240-env.out"))"
fi
section_end egl240

# --- EGL-84: --doctor verify-unit health rows (hermetic systemctl) ----
section_begin egl84 "EGL-84 doctor verify-unit health"
e84() { assert "$@"; }
e84d="$STATE/e84"; rm -rf "$e84d"; mkdir -p "$e84d/units" "$e84d/prefix" "$e84d/emptydeb"
: > "$e84d/prefix/egresslock"
# Mock unit templates for the doctor rows (ExecStart present, target exec).
sed "s|__EGRESSLOCK_PREFIX__|$e84d/prefix|g" "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e84d/units/egresslock-verify@.service"
: > "$e84d/units/egresslock-verify@.timer"
chmod +x "$e84d/prefix/egresslock"
# e84run: account-less doctor (host slice) unless --account given.
e84run() {
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" \
        "$SKIT" --prefix "$e84d/prefix" "$@" 2>&1
}
# e84clean: remove the systemctl mock fixtures between cases.
e84clean() {
    rm -f "$STATE/systemctl-fragpath" "$STATE/systemctl-fragpath-timer" \
          "$STATE/systemctl-mainstatus" "$STATE/systemctl-is-enabled" \
          "$STATE"/systemctl-show-* \
          "$STATE/systemctl-list-units" "$STATE/systemctl-list-units-failed" \
          "$STATE/systemctl-health-failed"
}

# 1. Healthy default (no fixtures): rc 0; the fragment is not resolved
#    by the mock (no fixture) and that is a NAMED neutral row, not a
#    failure, with a next check (reload) — no PROBLEM rows. R1: the
#    host slice names what it did not examine (account wiring pointer).
#    EGL-201: no fixtures = no enumerated accounts -> the M8 NOTE row
#    (no M7 inventory, no M9 summary).
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 0 && "$e84o" == *"NOTE: verify unit fragment: not resolved by systemctl"* \
    && "$e84o" == *"daemon-reload"* \
    && "$e84o" == *"not examined (no account operand)"* \
    && "$e84o" == *"sudo egresslock-setup doctor ACCOUNT"* \
    && "$e84o" == *"NOTE: no accounts have egresslock-verify services on this host"* \
    && "$e84o" != *"services healthy"* && "$e84o" != *"egresslock-verify services:"* \
    && "$e84o" != *"are set up for"* \
    && "$e84o" != *"FAILED"* && "$e84o" != *"SHADOWED"* && "$e84o" != *"DANGLING"* \
    && "$e84o" != *"PROBLEM: "* ]] \
    && e84 pass || e84 fail "healthy doctor stays rc 0 (rc=$e84_rc, out: $e84o)"

# 1b. EGL-201 P4/P5 healthy multi-account host: --all lists two
#     accounts' instances (alice service+timer pair, svc service), the
#     split --failed fixture is EMPTY -> M9 healthy row (2/2, the
#     service+timer pair counted once), M7 plural inventory, rc 0, no
#     PROBLEM. Both fixture files are set explicitly.
printf 'egresslock-verify@alice.service loaded active running\negresslock-verify@alice.timer loaded active waiting\negresslock-verify@svc.service loaded active running\n' > "$STATE/systemctl-list-units"
: > "$STATE/systemctl-list-units-failed"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 0 && "$e84o" == *"OK: all egresslock-verify services healthy (2/2)"* \
    && "$e84o" == *"NOTE: egresslock-verify services are set up for 2 accounts: alice, svc — to check an account: sudo egresslock-setup doctor ACCOUNT"* \
    && "$e84o" != *"PROBLEM: "* ]] \
    && e84 pass || e84 fail "healthy 2-account host: M9 (2/2) + M7 plural (rc=$e84_rc, out: $e84o)"

# 1c. EGL-201 partial + ghost: alice active + a dangling ghost
#     (`not-found` — excluded from M7/M9) + a failed svc timer
#     (timer shape: ExecMainStatus 0 -> the M3 timer copy, never
#     "exit status"); M9 partial row with the ghost out of both counts.
printf 'egresslock-verify@alice.service loaded active running\negresslock-verify@ghost.timer not-found not-found not-found\negresslock-verify@svc.timer loaded failed failed Periodic network policy verification for svc (drift signal)\n' > "$STATE/systemctl-list-units"
printf '● egresslock-verify@svc.timer loaded failed failed Periodic network policy verification for svc (drift signal)\n' > "$STATE/systemctl-list-units-failed"
printf '0\n' > "$STATE/systemctl-mainstatus"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: egresslock-verify@svc.timer: FAILED — the timer is enabled but not running (the start result is unknown); the verify service did not run"* \
    && "$e84o" != *"exit status"* \
    && "$e84o" == *"PROBLEM: egresslock-verify services: 1 of 2 failed"* \
    && "$e84o" == *"NOTE: egresslock-verify services are set up for 2 accounts: alice, svc"* \
    && "$e84o" != *"ghost"* \
    && "$e84o" == *"inspect: sudo journalctl -u egresslock-verify@svc.timer -n 20"* \
    && "$e84o" != *"last:"* && "$e84o" != *"next:"* ]] \
    && e84 pass || e84 fail "failed timer: armed-state row + M9 partial 1 of 2, ghost excluded, no recency (rc=$e84_rc, out: $e84o)"
e84clean

# 2. Failed-instance sweep: 203/EXEC start failure classified. The fixture
#    carries the REAL systemd column shape (a `●` state-marker glyph
#    `--no-legend` does not strip — EGL-201-P1): the unit name is field 2.
#    EGL-345: no verify-unit row names the cause (no fragment resolved
#    here), so the row stays a PROBLEM with the service journal as the
#    lead evidence and carries last/next (never / not scheduled).
printf '● egresslock-verify@uacct.service loaded failed running\n' > "$STATE/systemctl-list-units"
printf '203\n' > "$STATE/systemctl-mainstatus"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@uacct.service: FAILED — the verify program could not start (203/EXEC); systemd never ran it"* \
    && "$e84o" == *"  last: never"* && "$e84o" == *"  next: not scheduled"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@uacct.service -n 20"* \
    && "$e84o" != *"NOTE: egresslock-verify@uacct.service: failed (203/EXEC)"* \
    && "$e84o" != *"●"* \
    && "$e84o" == *"NOTE: egresslock-verify services are set up for 1 account: uacct"* ]] \
    && e84 pass || e84 fail "203 start failure row rc 1 (rc=$e84_rc, out: $e84o)"
# 2b. EGL-201-P1: the newer-systemd marker shape (`×`, v253+) parses to
#     the same row + inspect line — the token scan is marker-agnostic.
printf '× egresslock-verify@uacct.service loaded failed running\n' > "$STATE/systemctl-list-units"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@uacct.service: FAILED — the verify program could not start (203/EXEC); systemd never ran it"* \
    && "$e84o" == *"inspect: sudo journalctl -u egresslock-verify@uacct.service -n 20"* \
    && "$e84o" != *"×"* ]] \
    && e84 pass || e84 fail "×-marked failed row parses to the real unit (rc=$e84_rc, out: $e84o)"
# 3. Exit-1 instance: the row names the verify-run failure, shows the
#    never/not-scheduled recency, and prints the re-run as reset-failed +
#    systemctl start (the unit's own User=/EnvironmentFile= apply; no
#    opaque bash -c), with the service journal secondary. No named profile
#    is known here, so no scoped ensure repair is printed.
printf '1\n' > "$STATE/systemctl-mainstatus"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: egresslock-verify@uacct.service: FAILED — the verify run failed (exit 1)"* \
    && "$e84o" == *"  last: never"* && "$e84o" == *"  next: not scheduled"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@uacct.service"* \
    && "$e84o" == *"  fix: sudo systemctl start egresslock-verify@uacct.service"* \
    && "$e84o" != *"bash -c"* && "$e84o" != *"manually as uacct"* \
    && "$e84o" != *"sudo -iu uacct -- egresslock ensure"* \
    && "$e84o" == *"inspect: sudo journalctl -u egresslock-verify@uacct.service -n 20"* \
    && "$e84o" == *"check: sudo egresslock-setup doctor uacct"* ]] \
    && e84 pass || e84 fail "exit-1 row text + recency + systemctl re-run rc 1 (rc=$e84_rc, out: $e84o)"
e84clean

# 3a. EGL-345: disabled + failed timer (the live-repro shape) — the state
#     names the cause, so no journal dead end; the row prints the clear +
#     re-arm + check, and kit_check_timer never contradicts it with an OK.
printf 'disabled\n' > "$STATE/systemctl-is-enabled"
printf 'resources\n' > "$STATE/systemctl-show-Result"
printf 'egresslock-verify@dtmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account dtmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@dtmr.timer: FAILED and not enabled — the drift-check timer is disarmed; no verify run is scheduled"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@dtmr.timer"* \
    && "$e84o" == *"  fix: sudo egresslock-setup init dtmr --enable"* \
    && "$e84o" == *"  check: sudo egresslock-setup doctor dtmr"* \
    && "$e84o" != *"inspect:"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "disabled+failed timer: state row, no inspect, no OK (rc=$e84_rc, out: $e84o)"
e84clean

# 3b. EGL-345: enabled + failed timer with Result=resources — timer-start
#     language (not the enum), the bounded timer journal secondary with
#     the rotated-out caveat, reset-failed -> restart -> is-active check.
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf 'resources\n' > "$STATE/systemctl-show-Result"
printf 'egresslock-verify@etmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account etmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@etmr.timer: FAILED — the timer is enabled but not running (systemd reported a resource failure); the verify service did not run"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@etmr.timer"* \
    && "$e84o" == *"  fix: sudo systemctl restart egresslock-verify@etmr.timer"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@etmr.timer -n 20"* \
    && "$e84o" == *"an empty journal means the start error was rotated out"* \
    && "$e84o" == *"  check: sudo systemctl is-active egresslock-verify@etmr.timer"* \
    && "$e84o" != *"Result=resources"* && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "enabled+failed timer: timer-start row + inspect + clear (rc=$e84_rc, out: $e84o)"
e84clean

# 3c. EGL-345/EGL-346: armed + failed service (exit 1) — service
#     last/next (next is the timer's NextElapse), the re-run as
#     reset-failed + systemctl start (systemd applies the unit's own
#     User=/EnvironmentFile=), and the bounded service journal secondary.
printf '#!/usr/bin/env bash\nExecStart=%s/prefix/egresslock-verify\n' "$e84d" > "$e84d/faketmpl-svc"
: > "$e84d/prefix/egresslock-verify"; chmod +x "$e84d/prefix/egresslock-verify"
printf '%s\n' "$e84d/faketmpl-svc" > "$STATE/systemctl-fragpath"
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'Thu 2026-10-22 05:59:00 UTC\n' > "$STATE/systemctl-show-ExecMainStartTimestamp"
printf 'Thu 2026-10-22 06:00:00 UTC\n' > "$STATE/systemctl-show-ExecMainExitTimestamp"
printf 'Thu 2026-10-22 06:15:00 UTC\n' > "$STATE/systemctl-show-NextElapseUSecRealtime"
printf 'egresslock-verify@svcrun.service\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account svcrun --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@svcrun.service: FAILED — the verify run failed (exit 1)"* \
    && "$e84o" == *"  last: Thu 2026-10-22 06:00:00 UTC"* \
    && "$e84o" == *"  next: Thu 2026-10-22 06:15:00 UTC"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@svcrun.service"* \
    && "$e84o" == *"  fix: sudo systemctl start egresslock-verify@svcrun.service"* \
    && "$e84o" != *"bash -c"* && "$e84o" != *"manually as svcrun"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@svcrun.service -n 20"* \
    && "$e84o" == *"  check: sudo egresslock-setup doctor svcrun"* \
    && "$e84o" != *"journalctl -u egresslock-verify@svcrun.timer"* ]] \
    && e84 pass || e84 fail "armed+failed service: last/next + systemctl re-run + service journal (rc=$e84_rc, out: $e84o)"
e84clean

# 3c-1. EGL-346/EGL-333-D8: the scoped `ensure <profile>` repair prints
#     only for an explicit `doctor --profile`. A unit.env profile is inert
#     (D5): with no --profile the first fix is the reset-failed re-run and
#     no ensure line prints.
mkdir -p "$e84d/home/.config/egresslock"
printf 'EGRESSLOCK_PROFILE=namedprof\n' > "$e84d/home/.config/egresslock/unit.env"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@svcprof.service\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account svcprof --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
e84_svcblock="$(printf '%s\n' "$e84o" | sed -n '/PROBLEM: egresslock-verify@svcprof.service/,/^[^ ]/p')"
e84_first_fix="$(grep -m1 '^  fix:' <<<"$e84_svcblock")"
[[ "$e84_rc" == 1 \
    && "$e84_first_fix" == "  fix: sudo systemctl reset-failed egresslock-verify@svcprof.service" \
    && "$e84o" != *"egresslock ensure"* \
    && "$e84o" == *"  fix: sudo systemctl start egresslock-verify@svcprof.service"* ]] \
    && e84 pass || e84 fail "exit-1 + inert unit.env: no scoped ensure repair (rc=$e84_rc, first='$e84_first_fix', out: $e84o)"
# An explicit --profile seeds the scoped repair; unit.env still does not.
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account svcprof --profile flagprof --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"  fix: sudo -iu svcprof -- egresslock ensure flagprof"* \
    && "$e84o" != *"egresslock ensure namedprof"* ]] \
    && e84 pass || e84 fail "--profile seeds the scoped ensure repair (rc=$e84_rc, out: $e84o)"
# Non-exit-1: no ensure repair even with a named profile on disk.
printf '2\n' > "$STATE/systemctl-mainstatus"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account svcprof --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"the verify run failed (exited with status 2)"* \
    && "$e84o" != *"sudo -iu svcprof -- egresslock ensure"* ]] \
    && e84 pass || e84 fail "non-exit-1 row omits the scoped ensure repair (rc=$e84_rc, out: $e84o)"
# Host sweep: the account guard suppresses another account's repair.
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@sweepacct.service loaded failed failed\n' > "$STATE/systemctl-list-units-failed"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@sweepacct.service: FAILED — the verify run failed (exit 1)"* \
    && "$e84o" != *"sudo -iu"* && "$e84o" != *"egresslock ensure"* ]] \
    && e84 pass || e84 fail "host-sweep row omits the scoped ensure repair (rc=$e84_rc, out: $e84o)"
rm -rf "$e84d/home/.config"
e84clean

# 3d. EGL-345: 203/EXEC already explained by the verify-unit
#     ExecStart/target row -> a NOTE (no second PROBLEM, no inspect, no
#     repeated target/reinstall text). The actionable row above keeps
#     rc/grep intact.
printf '#!/usr/bin/env bash\nExecStart=/opt/egresslock/egresslock-verify\n' > "$e84d/faketmpl-203"
printf '%s\n' "$e84d/faketmpl-203" > "$STATE/systemctl-fragpath"
printf '203\n' > "$STATE/systemctl-mainstatus"
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@noteacct.service\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account noteacct --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: verify unit: ExecStart target missing/not executable: /opt/egresslock/egresslock-verify"* \
    && "$e84o" == *"NOTE: egresslock-verify@noteacct.service: failed (203/EXEC) — explained by the verify-unit row above"* \
    && "$e84o" != *"PROBLEM: egresslock-verify@noteacct.service: FAILED"* \
    && "$e84o" != *"inspect:"* \
    && "$(grep -c 'the unit points at an uninstalled/renamed kit' <<<"$e84o")" == 1 ]] \
    && e84 pass || e84 fail "203 explained: NOTE, no problem/inspect/duplicate (rc=$e84_rc, out: $e84o)"
e84clean

# 3e. EGL-345: 203/EXEC the verify-unit row does NOT explain (target
#     present/executable, e.g. a missing ELF interpreter) -> stays a
#     PROBLEM with the service journal as the lead evidence.
printf '#!/usr/bin/env bash\nExecStart=%s/prefix/egresslock-verify\n' "$e84d" > "$e84d/faketmpl-203b"
printf '%s\n' "$e84d/faketmpl-203b" > "$STATE/systemctl-fragpath"
printf '203\n' > "$STATE/systemctl-mainstatus"
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@noteacct2.service\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account noteacct2 --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@noteacct2.service: FAILED — the verify program could not start (203/EXEC); systemd never ran it"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@noteacct2.service -n 20"* \
    && "$e84o" != *"NOTE: egresslock-verify@noteacct2.service: failed"* \
    && "$e84o" != *"ExecStart target missing"* ]] \
    && e84 pass || e84 fail "unexplained 203: PROBLEM + service journal (rc=$e84_rc, out: $e84o)"
e84clean

# 3f. EGL-345: masked / static / not-found timers — the state names the
#     cause, the remedy is state-specific, and there is no timer journal
#     line (no dead end, and not-found has no journal stream at all).
printf 'masked\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@mtmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account mtmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@mtmr.timer: FAILED and masked — systemd will not start it until it is unmasked"* \
    && "$e84o" == *"  fix: sudo systemctl unmask egresslock-verify@mtmr.timer"* \
    && "$e84o" == *"  fix: sudo egresslock-setup init mtmr --enable"* \
    && "$e84o" != *"inspect:"* ]] \
    && e84 pass || e84 fail "masked timer: state remedy, no inspect (rc=$e84_rc, out: $e84o)"
e84clean
printf 'static\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@stmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account stmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@stmr.timer: FAILED and not enableable (static) — the unit template is missing or corrupt"* \
    && "$e84o" == *"  fix: reinstall the channel that owns the verify unit templates"* \
    && "$e84o" == *"  fix: sudo systemctl daemon-reload"* \
    && "$e84o" != *"inspect:"* ]] \
    && e84 pass || e84 fail "static timer: reinstall remedy, no inspect (rc=$e84_rc, out: $e84o)"
e84clean
printf 'not-found\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@ntmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account ntmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@ntmr.timer: FAILED and not found — the unit template is missing or corrupt"* \
    && "$e84o" == *"  fix: reinstall the channel that owns the verify unit templates"* \
    && "$e84o" != *"inspect:"* ]] \
    && e84 pass || e84 fail "not-found timer: reinstall remedy, no inspect (rc=$e84_rc, out: $e84o)"
e84clean

# 3g. EGL-345: service failed + timer disabled — both rows reconcile, the
#     timer row owns the re-arm (one copy), and the service row keeps the
#     verify journal (useful regardless of timer state).
printf 'disabled\n' > "$STATE/systemctl-is-enabled"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@rectmr.service\negresslock-verify@rectmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account rectmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
e84_svcblock="$(printf '%s\n' "$e84o" | sed -n '/PROBLEM: egresslock-verify@rectmr.service: FAILED/,/^[^ ]/p')"
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@rectmr.timer: FAILED and not enabled"* \
    && "$e84o" == *"PROBLEM: egresslock-verify@rectmr.service: FAILED — the verify run failed (exit 1); the timer is not enabled, so no further checks are scheduled"* \
    && "$e84o" == *"  fix: re-arm the timer — see its FAILED row above for the exact command"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@rectmr.service -n 20"* \
    && "$e84_svcblock" != *"egresslock-setup init rectmr"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "service+timer reconcile: one re-arm, service journal (rc=$e84_rc, out: $e84o)"
e84clean

# 3h. EGL-345 (R2): the armed-state probe did not answer (empty
#     is-enabled) -> the service row must NOT assert "the timer is not
#     enabled"; it names the unknown and the re-arm is conditional on
#     the operator's own state read. kit_check_timer names the same
#     unknown instead of a false "not enabled".
: > "$STATE/systemctl-is-enabled"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@unkacct.service\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account unkacct --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@unkacct.service: FAILED — the verify run failed (exit 1); the timer's armed state could not be determined, so whether further checks are scheduled is unknown"* \
    && "$e84o" == *"  fix: check whether the timer is enabled: systemctl is-enabled egresslock-verify@unkacct.timer"* \
    && "$e84o" == *"  fix: if it is not enabled, re-arm: sudo egresslock-setup init unkacct --enable"* \
    && "$e84o" == *"PROBLEM: timer: armed state unknown (egresslock-verify@unkacct.timer)"* \
    && "$e84o" != *"the timer is not enabled"* \
    && "$e84o" != *"timer: not enabled"* ]] \
    && e84 pass || e84 fail "unanswered armed-state probe is a named unknown, never not-enabled (rc=$e84_rc, out: $e84o)"
e84clean

# 3i. EGL-345 (R2): is-enabled answers `enabled` but the ActiveState
#     lookup fails -> never the armed OK; the row names the unknown
#     running state and gives the status/check path.
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
: > "$STATE/systemctl-show-fail-ActiveState"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: timer: enabled but its running state is unknown (egresslock-verify@uctx.timer)"* \
    && "$e84o" == *"  fix: sudo systemctl status egresslock-verify@uctx.timer"* \
    && "$e84o" == *"  check: sudo egresslock-setup doctor uctx"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "failed ActiveState probe is a named unknown, never armed OK (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-is-enabled" "$STATE/systemctl-show-fail-ActiveState"

# 3i-b. EGL-345 (R4): the ActiveState lookup ANSWERS but prints nothing.
#     ActiveState has no valid empty value, so rc 0 + empty output is a
#     probe that did not establish the state — never the armed OK. The
#     mock defaults ActiveState to `active`; this fixture is explicitly
#     empty to pin the empty-answer degrade.
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
: > "$STATE/systemctl-show-ActiveState.egresslock-verify@uctx.timer"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: timer: enabled but its running state is unknown (egresslock-verify@uctx.timer)"* \
    && "$e84o" == *"  fix: sudo systemctl status egresslock-verify@uctx.timer"* \
    && "$e84o" == *"  check: sudo egresslock-setup doctor uctx"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "empty ActiveState answer is a named unknown, never armed OK (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-is-enabled" "$STATE/systemctl-show-ActiveState.egresslock-verify@uctx.timer"

# 3j. EGL-345 (R2 minor, R4): an `indirect` timer (enabled only
#     through another unit's Also=/alias) is deliberately NOT the
#     not-enableable template-missing class — the template is present.
#     It is a named unknown armed state (the raw state is shown) with
#     the clear/restart path, no journal, never a template claim.
printf 'indirect\n' > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@itmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account itmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@itmr.timer: FAILED — the timer is in a failed state (armed state unknown: indirect)"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@itmr.timer"* \
    && "$e84o" == *"  fix: sudo systemctl restart egresslock-verify@itmr.timer"* \
    && "$e84o" != *"the unit template is missing or corrupt"* \
    && "$e84o" != *"reinstall the channel that owns the verify unit templates"* \
    && "$e84o" != *"inspect:"* && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "indirect timer: named unknown, never a template claim (rc=$e84_rc, out: $e84o)"
e84clean

# 3j-b. EGL-345 (R4): a failed service whose timer is `indirect` must
#     not assert "the timer is not enabled" — the armed state was not
#     established. Same named-unknown service row as the empty answer;
#     the timer's failed row owns the clear + restart, and the pointer
#     names those commands (EGL-356 D3), never a re-arm.
printf 'indirect\n' > "$STATE/systemctl-is-enabled"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@itmr2.service\negresslock-verify@itmr2.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account itmr2 --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@itmr2.timer: FAILED — the timer is in a failed state (armed state unknown: indirect)"* \
    && "$e84o" == *"PROBLEM: egresslock-verify@itmr2.service: FAILED — the verify run failed (exit 1); the timer's armed state could not be determined, so whether further checks are scheduled is unknown"* \
    && "$e84o" == *"  fix: the timer is failed too — see its FAILED row above for the reset-failed and restart commands"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@itmr2.service -n 20"* \
    && "$e84o" != *"the timer is not enabled"* \
    && "$e84o" != *"for the exact command"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "service + indirect timer: named unknown, never not-enabled (rc=$e84_rc, out: $e84o)"
e84clean

# 3j-c. EGL-345 (R4): kit_check_timer for an `indirect` timer names the
#     unknown armed state with a check — never "not enabled", never the
#     armed OK, and no reinstall claim.
printf 'indirect\n' > "$STATE/systemctl-is-enabled"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account itmr3 --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: timer: armed state unknown (egresslock-verify@itmr3.timer)"* \
    && "$e84o" == *"  fix: check the timer state: systemctl is-enabled egresslock-verify@itmr3.timer"* \
    && "$e84o" != *"PROBLEM: timer: not enabled"* \
    && "$e84o" != *"reinstall the channel that owns the verify unit templates"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "kit_check_timer indirect: named unknown, never not-enabled/OK (rc=$e84_rc, out: $e84o)"
e84clean

# 3j-d. EGL-356 (D2/D3): an unrecognized raw is-enabled answer (`linked`)
#     is not a classified disarmed state. Both units failed: the timer row
#     names the raw unknown, the service row names the unknown armed state
#     (never "not enabled"), and the pointer names the clear + restart the
#     timer row actually prints — not a re-arm command it never printed.
printf 'linked\n' > "$STATE/systemctl-is-enabled"
printf '1\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@lnktmr.service\negresslock-verify@lnktmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account lnktmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@lnktmr.timer: FAILED — the timer is in a failed state (armed state unknown: linked)"* \
    && "$e84o" == *"PROBLEM: egresslock-verify@lnktmr.service: FAILED — the verify run failed (exit 1); the timer's armed state could not be determined, so whether further checks are scheduled is unknown"* \
    && "$e84o" == *"  fix: the timer is failed too — see its FAILED row above for the reset-failed and restart commands"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@lnktmr.timer"* \
    && "$e84o" == *"  fix: sudo systemctl restart egresslock-verify@lnktmr.timer"* \
    && "$e84o" == *"  inspect: sudo journalctl -u egresslock-verify@lnktmr.service -n 20"* \
    && "$e84o" != *"the timer is not enabled"* \
    && "$e84o" != *"for the exact command"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "service + raw linked timer: named unknown, real pointer (rc=$e84_rc, out: $e84o)"
e84clean

# 3k. EGL-345 (R2): a failed timer whose armed-state probe did not
#     answer names the unknown state, not enabled/disabled, and prints
#     only the generic clear/restart path (no journal claim).
: > "$STATE/systemctl-is-enabled"
printf 'egresslock-verify@unktmr.timer\n' > "$STATE/systemctl-health-failed"
: > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account unktmr --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 \
    && "$e84o" == *"PROBLEM: egresslock-verify@unktmr.timer: FAILED — the timer is in a failed state (armed state unknown)"* \
    && "$e84o" == *"  fix: sudo systemctl reset-failed egresslock-verify@unktmr.timer"* \
    && "$e84o" == *"  fix: sudo systemctl restart egresslock-verify@unktmr.timer"* \
    && "$e84o" != *"FAILED and not enabled"* && "$e84o" != *"FAILED and masked"* ]] \
    && e84 pass || e84 fail "unanswered timer armed state is a named unknown (rc=$e84_rc, out: $e84o)"
e84clean

# 4. Shadow: an /etc fragment overriding the deb's /usr/lib unit — both
#    paths named, rc 1 (EGL-83 incident shape; the deb copy is a fixture
#    via EGRESSLOCK_DEB_UNIT_DIR, the /etc path is only a mock answer).
mkdir -p "$e84d/debunits"
: > "$e84d/debunits/egresslock-verify@.service"
printf '/etc/systemd/system/egresslock-verify@.service\n' > "$STATE/systemctl-fragpath"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: SHADOWED — systemd loads /etc/systemd/system/egresslock-verify@.service, not the deb's $e84d/debunits/egresslock-verify@.service"* \
    && "$e84o" != *"ExecStart missing"* ]] \
    && e84 pass || e84 fail "shadow row names both paths rc 1 (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-fragpath"

# 4a. Shadow fix, state-aware (prefix kit LIVE): the /etc fragment's
#     ExecStart dir carries kit markers and is not the deb libdir -> the
#     fix names removing the prefix kit (no .deb reinstall), not a
#     blanket "uninstall + reinstall". EGRESSLOCK_ETC_UNIT_DIR mocks the
#     /etc load-precedence path so the shadow gate is reachable
#     hermetically (no real /etc write).
mkdir -p "$e84d/etcmock"
printf '#!/usr/bin/env bash\nExecStart=%s/egresslock-verify\n' "$e84d/prefix" > "$e84d/etcmock/egresslock-verify@.service"
printf '%s\n' "$e84d/etcmock/egresslock-verify@.service" > "$STATE/systemctl-fragpath"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: SHADOWED"* \
    && "$e84o" == *"uninstall-kit.sh --prefix $e84d/prefix"* \
    && "$e84o" == *"no reinstall"* ]] \
    && e84 pass || e84 fail "shadow fix (prefix kit live) names uninstall-kit, no reinstall (rc=$e84_rc, out: $e84o)"
# 4b. Shadow fix, deb-copy edge: the /etc fragment's ExecStart lives in
#     the deb libdir itself (an /etc copy of the deb unit). Markers
#     exist there, but it IS the deb libdir -> must take the stale-rm
#     branch, never "remove the prefix kit at <deb libdir>".
mkdir -p "$e84d/egresslock"; : > "$e84d/egresslock/VERSION"
printf '#!/usr/bin/env bash\nExecStart=%s/egresslock/egresslock-verify\n' "$e84d" > "$e84d/etcmock/egresslock-verify@.service"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: SHADOWED"* \
    && "$e84o" == *"stale /etc templates"* \
    && "$e84o" != *"uninstall-kit.sh --prefix $e84d/egresslock"* ]] \
    && e84 pass || e84 fail "shadow fix (deb-libdir ExecStart) takes the stale-rm branch (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-fragpath"

# 5. ExecStart target missing/not executable (the uninstalled-prefix
#    case): the mock resolves the fragment to a fixture file whose
#    ExecStart points at a nonexistent binary.
printf '#!/usr/bin/env bash\nExecStart=/opt/egresslock/egresslock-verify\n' > "$e84d/faketmpl"
printf '%s\n' "$e84d/faketmpl" > "$STATE/systemctl-fragpath"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: ExecStart target missing/not executable: /opt/egresslock/egresslock-verify"* ]] \
    && e84 pass || e84 fail "missing ExecStart target row rc 1 (rc=$e84_rc, out: $e84o)"
# ... and a template with no ExecStart at all: the fix is channel-aware
#     (R4: names the reinstall for the channel that owns the file).
printf '#!/usr/bin/env bash\nDescription=no exec\n' > "$e84d/faketmpl2"
printf '%s\n' "$e84d/faketmpl2" > "$STATE/systemctl-fragpath"
e84o="$(e84run --doctor)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: ExecStart missing in $e84d/faketmpl2"* \
    && "$e84o" == *"reinstall the channel that owns it"* ]] \
    && e84 pass || e84 fail "ExecStart-less template row rc 1 (rc=$e84_rc, out: $e84o)"
e84clean

# 6. Account instance probed even when the listing is empty: the
#    is-failed fixture marks every probed unit failed (203 status).
#    EGL-201: the sweep is empty -> M8 speaks (no accounts enumerated);
#    the probe row drops the `verify unit` head (M1).
printf '203\n' > "$STATE/systemctl-mainstatus"
printf 'failed\n' > /dev/null   # (marker below drives is-failed)
: > "$STATE/systemctl-health-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account e84acct --conf "$e84d/nosuch.conf" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: egresslock-verify@e84acct.service: FAILED"* \
    && "$e84o" != *"PROBLEM: verify unit"* \
    && "$e84o" == *"inspect: sudo journalctl -u egresslock-verify@e84acct.service -n 20"* ]] \
    && e84 pass || e84 fail "account instance is-failed row rc 1 (rc=$e84_rc, out: $e84o)"
# 6b. Dedup: a unit already reported by the sweep is not reported twice
#     by the account probe.
printf 'egresslock-verify@e84acct.service loaded failed running\n' > "$STATE/systemctl-list-units"
printf '● egresslock-verify@e84acct.service loaded failed running\n' > "$STATE/systemctl-list-units-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e84d/home" \
    EGRESSLOCK_UNIT_DIR="$e84d/units" \
    "$SKIT" --prefix "$e84d/prefix" --account e84acct --conf "$e84d/nosuch.conf" --doctor 2>&1)"
[[ "$(grep -c 'PROBLEM: egresslock-verify@e84acct.service: FAILED' <<<"$e84o")" == 1 ]] \
    && e84 pass || e84 fail "sweep+account dedup (out: $e84o)"
e84clean

# 7. Dangling timer enablement: a wants symlink whose template is gone
#    -> rc 1. Clean sweep fixture -> the run must produce EXACTLY one
#    PROBLEM row, and the row must name the path: an unrelated failure
#    cannot satisfy this check for the wrong reason.
mkdir -p "$e84d/units/timers.target.wants"
ln -s "$e84d/units/egresslock-verify@ghost.timer" "$e84d/units/timers.target.wants/egresslock-verify@ghost.timer"
e84o="$(e84run --doctor)"; e84_rc=$?
e84prob="$(printf '%s\n' "$e84o" | grep -c '^PROBLEM: ' || :)"
[[ "$e84_rc" == 1 && "$e84prob" == 1 \
    && "$e84o" == *"PROBLEM: verify timer: DANGLING enablement — $e84d/units/timers.target.wants/egresslock-verify@ghost.timer"* ]] \
    && e84 pass || e84 fail "dangling wants row rc 1, exactly one PROBLEM (rc=$e84_rc, problems=$e84prob, out: $e84o)"
rm -rf "$e84d/units/timers.target.wants"

# 8. No usable systemctl -> named skip, rc-neutral (D5). EGL-201:
#    the enumeration/summary are silent too (the named skip spoke; no
#    M7 inventory, no M9 summary).
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_SYSTEMCTL=/nonexistent/systemctl \
    EGRESSLOCK_UNIT_DIR="$e84d/units" "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 0 && "$e84o" == *"NOTE: verify units: skipped (systemctl not found)"* \
    && "$e84o" != *"no accounts have"* && "$e84o" != *"are set up for"* \
    && "$e84o" != *"services healthy"* ]] \
    && e84 pass || e84 fail "no-systemctl named skip rc-neutral (rc=$e84_rc, out: $e84o)"

# 8b. EGL-382: the systemctl hook is test-only — without the flag it is
#     ignored, so the production `systemctl` on PATH is used and the
#     marker hook is never invoked. The mock's call log plus rc/output
#     liveness (R-EGL-382-2 F2) keep an early --doctor exit from passing
#     on marker-absence alone.
e84_marker="$e84d/neg-systemctl-marker"
cat > "$e84d/neg-systemctl" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "${EGRESSLOCK_MARKER_FILE:?}"
exit 0
EOF
chmod +x "$e84d/neg-systemctl"
rm -f "$e84_marker"
: > "$STATE/systemctl.log"
# F4 (R-EGL-456-3): compare to a hook-unset control instead of pinning a
# host-dependent MISSING row. On a host with legitimate production
# templates the ignored-hook run must still equal the unset run; if a
# gate were live, the fixture dirs would change the row (or the systemctl
# shim would be invoked). Assert the named hook paths are absent too, so
# the pin does not rest on host state.
e84base="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_SYSTEMCTL \
    -u EGRESSLOCK_MARKER_FILE -u EGRESSLOCK_DEFAULT_UNIT_DIR \
    -u EGRESSLOCK_DEB_UNIT_DIR \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84base_rc=$?
e84o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_SYSTEMCTL="$e84d/neg-systemctl" \
    EGRESSLOCK_MARKER_FILE="$e84_marker" EGRESSLOCK_DEFAULT_UNIT_DIR="$e84d/units" \
    EGRESSLOCK_DEB_UNIT_DIR="$e84d/emptydeb" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
# EGL-491-D7: equal modulo the ignored-hook warnings, which are pinned.
e84base_s="$(printf '%s\n' "$e84base" | strip_egl491_warnings)"
e84o_s="$(printf '%s\n' "$e84o" | strip_egl491_warnings)"
[[ "$e84_rc" == "$e84base_rc" && "$e84o_s" == "$e84base_s" \
    && "$e84o" == *"EGRESSLOCK_SYSTEMCTL is set but ignored"* \
    && "$e84o" == *"EGRESSLOCK_DEFAULT_UNIT_DIR is set but ignored"* \
    && "$e84o" == *"EGRESSLOCK_DEB_UNIT_DIR is set but ignored"* \
    && "$e84o" != *"$e84d/units"* && "$e84o" != *"$e84d/emptydeb"* \
    && ! -e "$e84_marker" \
    && "$(grep -c '^systemctl ' "$STATE/systemctl.log")" -gt 0 ]] \
    && e84 pass || e84 fail "systemctl/default-dir hooks ignored without the test flag (control rc=$e84base_rc, rc=$e84_rc, out: $e84o)"

# 9. Templates missing from BOTH unit dirs (explicit empty hooks): the
#    fix line must name both channels — a deb-only host must not be
#    sent to install-kit.sh alone, which refuses on a co-installed deb.
e84nounits="$e84d/nounits"; mkdir -p "$e84nounits/deb"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84nounits" EGRESSLOCK_DEB_UNIT_DIR="$e84nounits/deb" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: unit templates: MISSING"* \
    && "$e84o" == *".deb hosts: reinstall the package"* \
    && "$e84o" == *"re-run install-kit.sh"* ]] \
    && e84 pass || e84 fail "missing templates fix names both channels (rc=$e84_rc, out: $e84o)"

# 9b. (R3 partial shape) only the service template present: a PARTIAL
#     row naming both names, rc 1 — not the blanket MISSING text.
e84partial="$e84d/partial"; mkdir -p "$e84partial"
sed "s|__EGRESSLOCK_PREFIX__|$e84d/prefix|g" "$TREE_ROOT/systemd/egresslock-verify@.service" \
    > "$e84partial/egresslock-verify@.service"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84partial" "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: unit templates: PARTIAL"* \
    && "$e84o" == *"service: $e84partial"* && "$e84o" == *"timer: MISSING"* \
    && "$e84o" == *"installs both"* ]] \
    && e84 pass || e84 fail "partial template row rc 1 (rc=$e84_rc, out: $e84o)"

# 10. (EGL-302-D2) healthy account slice + ANOTHER account's failed unit:
#     the unit is NOT printed — out-of-slice units are suppressed under
#     --account and rc stays neutral (driven only by the invoked slice).
#     Fixtures come from the e38/e55 block ($e38p engine, $UNITS). The plain
#     host sweep is the reporting surface for these units.
printf '● egresslock-verify@otheracct.service loaded failed running\n' > "$STATE/systemctl-list-units"
printf '203\n' > "$STATE/systemctl-mainstatus"
printf 'egresslock-verify@other*\n' > "$STATE/systemctl-health-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 0 && "$e84o" != *"out-of-account"* \
    && "$e84o" != *"egresslock-verify@otheracct"* \
    && "$e84o" != *"rc unaffected"* ]] \
    && e84 pass || e84 fail "out-of-slice unit suppressed under --account, rc-neutral (rc=$e84_rc, out: $e84o)"
# 10b. The account's OWN failed unit still drives rc 1 (its row is the
#      plain in-slice M1 form, not the out-of-account label).
printf 'egresslock-verify@uctx*\n' > "$STATE/systemctl-health-failed"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
own_row="$(grep 'PROBLEM: egresslock-verify@uctx.service: FAILED' <<<"$e84o" | head -1)"
[[ "$e84_rc" == 1 && "$own_row" == *"egresslock-verify@uctx.service: FAILED"* \
    && "$own_row" != *"out-of-account"* ]] \
    && e84 pass || e84 fail "own-account failed unit keeps rc 1 (rc=$e84_rc, out: $e84o)"
e84clean

# 11. (R3 sibling + R5) timer-template shadow: an /etc timer template
#     whose content differs from the deb's timer is a SHADOWED row, rc 1,
#     disclosed inspect-first (never a blind rm); an IDENTICAL copy is
#     benign — no row, rc 0 (postinst cleans identical copies).
: > "$e84d/debunits/egresslock-verify@.timer"
printf 'OnCalendar=hourly\n' > "$e84d/etcmock/egresslock-verify@.timer"
printf '%s\n' "$e84d/etcmock/egresslock-verify@.timer" > "$STATE/systemctl-fragpath-timer"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify timer template: SHADOWED — systemd loads $e84d/etcmock/egresslock-verify@.timer"* \
    && "$e84o" == *"inspect it before removing anything"* ]] \
    && e84 pass || e84 fail "timer-template shadow row rc 1 (rc=$e84_rc, out: $e84o)"
# EGL-456-D6: the ETC hook is test-mode only. Flag off -> the doctor reads
# the production /etc path, so the decoy shadow row must not fire and the
# decoy path must not be named (the flag-on leg above is the control; the
# fragpath fixture still points at the decoy).
e84o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_UNIT_DIR="$e84d/units" \
    EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84o" != *"timer template: SHADOWED"* && "$e84o" != *"$e84d/etcmock"* ]] \
    && e84 pass || e84 fail "ETC unit-dir hook ignored without the test flag (rc=$e84_rc, out: $e84o)"
# F2 (R-EGL-456-3): the leg above is vacuous on a host without the
# production deb timer: the shadow check cannot fire even if only the ETC
# gate is removed. Run the same negative in a private mount namespace
# with a synthetic production deb timer present, so the ETC gate is the
# only thing keeping the shadow row suppressed. Unset/off must be
# byte-identical; the flag-on control must fire. Mutation: move only the
# ETC assignment outside the kit_test_mode branch -> the off run differs
# from the unset control (SHADOWED row).
if command -v unshare >/dev/null 2>&1 && unshare -rm true 2>/dev/null; then
    e84nsd="$e84d/ns"; e84nsprod="$e84nsd/prod-systemd"; e84nsetc="$e84nsd/prod-etc"
    rm -rf "$e84nsd"; mkdir -p "$e84nsprod" "$e84nsetc" "$e84nsd/bin"
    printf 'OnCalendar=daily\n' > "$e84nsprod/egresslock-verify@.timer"
    printf 'OnCalendar=hourly\n' > "$e84d/etcmock/egresslock-verify@.timer"
    printf '%s\n' "$e84d/etcmock/egresslock-verify@.timer" > "$STATE/systemctl-fragpath-timer"
    cat > "$e84nsd/bin/id" <<'EOF'
#!/usr/bin/env bash
# The namespace root is still the unprivileged harness account; report it
# so egresslock-setup takes its non-root test shape with the flag off.
if [[ "${1:-}" == "-u" ]]; then echo 1000; exit 0; fi
exec /usr/bin/id "$@"
EOF
    chmod +x "$e84nsd/bin/id"
    e84nsrun() { # e84nsrun <env-prefix args...> — mount production dirs, then exec
        E84NS_STATE="$STATE" E84NS_TESTBIN="$TESTROOT/bin" \
        unshare -rm bash -c '
            set -e
            d="$1"; shift
            mkdir -p /usr/lib/systemd/system /etc/systemd/system
            mount --bind "$d/prod-systemd" /usr/lib/systemd/system
            mount --bind "$d/prod-etc" /etc/systemd/system
            export PATH="$d/bin:$E84NS_TESTBIN:$PATH" ARCMOCK_STATE="$E84NS_STATE"
            exec env "$@"
        ' _ "$e84nsd" "$@"
    }
    e84ns_unset="$(e84nsrun -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_ETC_UNIT_DIR \
        "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84ns_unset_rc=$?
    e84ns_off="$(e84nsrun -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
        EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
        "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84ns_off_rc=$?
    e84ns_on="$(e84nsrun EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 \
        EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
        "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84ns_on_rc=$?
    # EGL-491-D7: equal modulo the ignored-hook warning, which is pinned.
    e84ns_unset_s="$(printf '%s\n' "$e84ns_unset" | strip_egl491_warnings)"
    e84ns_off_s="$(printf '%s\n' "$e84ns_off" | strip_egl491_warnings)"
    [[ "$e84ns_off_rc" == "$e84ns_unset_rc" && "$e84ns_off_s" == "$e84ns_unset_s" \
        && "$e84ns_off" == *"EGRESSLOCK_ETC_UNIT_DIR is set but ignored"* \
        && "$e84ns_unset" != *"EGRESSLOCK_ETC_UNIT_DIR is set but ignored"* \
        && "$e84ns_off" != *"timer template: SHADOWED"* \
        && "$e84ns_off" != *"$e84d/etcmock"* ]] \
        && e84 pass || e84 fail "ETC hook ignored with a production deb timer present (unset rc=$e84ns_unset_rc, off rc=$e84ns_off_rc, out: $e84ns_off)"
    [[ "$e84ns_on_rc" == 1 \
        && "$e84ns_on" == *"PROBLEM: verify timer template: SHADOWED — systemd loads $e84d/etcmock/egresslock-verify@.timer, not the deb's /usr/lib/systemd/system/egresslock-verify@.timer"* ]] \
        && e84 pass || e84 fail "ETC hook live with the flag (production deb timer shadow row; rc=$e84ns_on_rc, out: $e84ns_on)"
else
    skip "namespace-unavailable" "ETC production-deb-timer negative skipped: unshare -rm unavailable"
fi
# 11b. Identical copy of the deb timer: stale product copy — benign, no row.
: > "$e84d/etcmock/egresslock-verify@.timer"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 0 && "$e84o" != *"timer template: SHADOWED"* ]] \
    && e84 pass || e84 fail "identical /etc timer copy is benign (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-fragpath-timer"

# 12. (R5) unknown-shape /etc service shadow: ExecStart outside any kit
#     dir, no markers -> the fix discloses and has the operator inspect;
#     it must NOT prescribe the marker-shaped routes (no prefix-kit
#     removal, no blanket stale-rm).
printf '#!/usr/bin/env bash\nExecStart=/usr/local/bin/not-ours-verify\n' > "$e84d/etcmock/egresslock-verify@foreign.service"
printf '%s\n' "$e84d/etcmock/egresslock-verify@foreign.service" > "$STATE/systemctl-fragpath"
e84o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e84d/units" EGRESSLOCK_DEB_UNIT_DIR="$e84d/debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e84d/etcmock" \
    "$SKIT" --prefix "$e84d/prefix" --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: verify unit: SHADOWED — systemd loads $e84d/etcmock/egresslock-verify@foreign.service"* \
    && "$e84o" == *"does not look like an egresslock product template"* \
    && "$e84o" != *"uninstall-kit.sh --prefix"* && "$e84o" != *"stale /etc templates only"* ]] \
    && e84 pass || e84 fail "unknown-shape shadow keeps the file, discloses (rc=$e84_rc, out: $e84o)"
e84clean

# 12b. (R2 armed-but-stopped) is-enabled says `enabled` but the timer is
#      not active: that is not an armed timer — PROBLEM + the one start
#      command, never a contradicting OK row.
printf 'enabled\n' > "$STATE/systemctl-is-enabled"
printf 'inactive\n' > "$STATE/systemctl-show-ActiveState.egresslock-verify@uctx.timer"
e84o="$(env ARCMOCK_LINGER_ANSWER=no EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: timer: enabled but not running (egresslock-verify@uctx.timer)"* \
    && "$e84o" == *"fix: sudo systemctl start egresslock-verify@uctx.timer"* \
    && "$e84o" != *"OK: timer: enabled"* ]] \
    && e84 pass || e84 fail "enabled-but-stopped timer is a PROBLEM, not OK (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-is-enabled" "$STATE/systemctl-show-ActiveState.egresslock-verify@uctx.timer"

# 13. (R4 runnable fix) the timer-not-enabled arm command is the plain
#     pathless init (EGL-333-D7: the timer verifies every profile, so the
#     fix carries no --profile). EGL-201: the timer/linger PROBLEM rows
#     name the unit/account (M10/M11).
: > "$STATE/systemctl-timer-off"
e84o="$(env ARCMOCK_LINGER_ANSWER=no EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e38h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    "$SKIT" --prefix "$e38p" --account uctx --conf "$STATE/e38/site.conf" --profile p1 --doctor 2>&1)"; e84_rc=$?
[[ "$e84_rc" == 1 && "$e84o" == *"PROBLEM: timer: not enabled (egresslock-verify@uctx.timer)"* \
    && "$e84o" == *"fix: sudo egresslock-setup init uctx --enable"* \
    && "$e84o" != *"init uctx --profile"* \
    && "$e84o" == *"PROBLEM: linger: off (account uctx)"* ]] \
    && e84 pass || e84 fail "timer fix line is the plain pathless init; M10/M11 rows (rc=$e84_rc, out: $e84o)"
rm -f "$STATE/systemctl-timer-off"

# 14. (R1 named skip) DELETED per EGL-270 P3 (candidate 1): the
#     conf-parse-failed named-skip row was verbatim-duplicated by
#     egl55 #5 (same bad.conf fixture shape, same rc/message asserts) —
#     egl55 owns the row; no count-enabled property was unique here.

section_end egl84


# --- EGL-287: setup verb grammar — summary/pages, aliases, conflicts -----
# P1/P2: the four summary surfaces (-h, --help, bare, help) are byte-equal,
# rc 0, <= 40 lines, ID-free, and bare of unadorned --apparmor (EGL-39);
# every help topic renders rc 0 and equals `<verb> --help` (apparmor too —
# help wins); error edges (unknown topic, extra token, help help, bare
# apparmor) are rc 2 with the named message + summary on stderr; help is
# rootless/config-free. D2 aliases are the legacy code: --doctor == doctor,
# legacy flag bundle == init (same rc/output); a legacy mode flag beside a
# verb is a named rc 2 usage error.
section_begin egl287 "EGL-287 setup verb grammar"
eg287() { assert "$@"; }

# 1. Summary surfaces.
s287_summary="$("$SKIT" -h 2>/dev/null)"; s287_rc=$?
[[ "$s287_rc" == 0 ]] \
    && eg287 pass || eg287 fail "-h rc 0 (rc=$s287_rc)"
[[ "$(wc -l <<<"$s287_summary")" -le 40 ]] \
    && eg287 pass || eg287 fail "summary <= 40 lines (got $(wc -l <<<"$s287_summary"))"
for s287_a in --help help; do
    o="$("$SKIT" "$s287_a" 2>/dev/null)"; rc=$?
    [[ "$rc" == 0 && "$o" == "$s287_summary" ]] \
        && eg287 pass || eg287 fail "$s287_a == -h byte-equal rc 0 (rc=$rc)"
done
o="$("$SKIT" 2>/dev/null)"; rc=$?
[[ "$rc" == 0 && "$o" == "$s287_summary" ]] \
    && eg287 pass || eg287 fail "bare invocation = the summary, rc 0 (rc=$rc)"
if grep -qE "$k59_id_re" <<<"$s287_summary"; then
    eg287 fail "summary leaks ticket/process refs"
else
    eg287 pass
fi
if grep -qE '(^|[ (])--apparmor([^a-z-]|$)' <<<"$s287_summary"; then
    eg287 fail "summary carries a bare --apparmor"
else
    eg287 pass
fi

# 1b. EGL-517: setup help/usage is paste-inert — no unquoted `<`, `>`,
#     `|`, `&`, `;`, or backtick on a command-shaped line.
#     EGL-517-F2: derive the verb list from the live summary index, never a
#     literal here, so a verb added later cannot silently escape the scan.
verbs517=()
while IFS= read -r v517; do
    [[ -n "$v517" ]] && verbs517+=( "$v517" )
done < <("$SKIT" -h 2>&1 | awk '
    /^Verbs:$/ { inb = 1; next }
    inb && /^[[:space:]]*$/ { exit }
    inb {
        line = $0
        sub(/^[[:space:]]*egresslock-setup[[:space:]]+/, "", line)
        if (line == $0) next
        split(line, a, /[[:space:]]+/)
        if (a[1] == "help") next
        if (a[1] ~ /^[a-z][a-z-]*$/) print a[1]
    }')
(( ${#verbs517[@]} > 0 )) \
    && eg287 pass || eg287 fail "derived verbs: summary index not parsed"
assert_setup_help_lines_paste_safe "summary" "$("$SKIT" -h 2>&1)"
assert_setup_help_page_no_angles "summary" "$("$SKIT" -h 2>&1)"
for t287 in "${verbs517[@]}"; do
    o287="$("$SKIT" help "$t287" 2>&1)"; r287=$?
    [[ "$r287" == 0 ]] && eg287 pass || eg287 fail "derived verb help $t287 (rc=$r287)"
    assert_setup_help_lines_paste_safe "help $t287" "$o287"
    assert_setup_help_page_no_angles "help $t287" "$o287"
done
for t287 in env "env test"; do
    assert_setup_help_page_no_angles "help $t287" "$("$SKIT" help $t287 2>&1)"
done
# EGL-517-D3: the setup/kit non-help emitted text (Error/NOTE/fix/usage) is
# swept too; the source scan keeps a new site from escaping. install-kit.sh
# and uninstall-kit.sh are absent from an extracted kit, so scan when present.
assert_setup_source_clean "$TREE_ROOT/egresslock-setup" "egresslock-setup"
for f517 in install-kit.sh uninstall-kit.sh; do
    [[ -f "$TREE_ROOT/$f517" ]] && assert_setup_source_clean "$TREE_ROOT/$f517" "$f517"
done

# 2. Verb/topic pages. EGL-372: pin each page's named property — the five
#    verb pages open with their usage synopsis; `env` is a reference page
#    (no synopsis) and opens with its title + Environment block.
for t287 in init import doctor build-gateway apparmor env; do
    o="$("$SKIT" help "$t287" 2>/dev/null)"; rc=$?
    case "$t287" in
        init) want287='egresslock-setup init ACCOUNT [--from CONF] [--init-conf] [--prefix PATH]' ;;
        import) want287='egresslock-setup import ACCOUNT --from CONF [--allowlist PATH] [--force] [--prefix PATH]' ;;
        doctor) want287='egresslock-setup doctor [ACCOUNT] [--profile PROFILE] [--prefix PATH]' ;;
        build-gateway) want287='egresslock-setup build-gateway [--force] [--prefix PATH]' ;;
        apparmor) want287='egresslock-setup apparmor add, remove, or check' ;;
    esac
    if [[ "$t287" == env ]]; then
        [[ "$rc" == 0 \
           && "$o" == *"Kit data locations, environment overrides, and defaults for the"$'\n'"setup tool."* \
           && "$o" == *"Environment:"* ]] \
            && eg287 pass || eg287 fail "help env reference title + Environment block (rc=$rc)"
    else
        [[ "$rc" == 0 && "$(head -n1 <<<"$o")" == "$want287" ]] \
            && eg287 pass || eg287 fail "help $t287 usage synopsis first line (rc=$rc)"
    fi
    if grep -qE "$k59_id_re" <<<"$o"; then
        eg287 fail "help $t287 leaks ticket/process refs"
    else
        eg287 pass
    fi
    if grep -qE '(^|[ (])--apparmor([^a-z-]|$)' <<<"$o"; then
        eg287 fail "help $t287 carries a bare --apparmor"
    else
        eg287 pass
    fi
done
for t287 in init import doctor build-gateway apparmor; do
    o="$("$SKIT" "$t287" --help 2>/dev/null)"; rc=$?
    [[ "$rc" == 0 && "$o" == "$("$SKIT" help "$t287" 2>/dev/null)" ]] \
        && eg287 pass || eg287 fail "$t287 --help == help $t287 (rc=$rc)"
done
o="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$SKIT" apparmor --help 2>/dev/null)"; rc=$?
[[ "$rc" == 0 && "$o" == "$("$SKIT" help apparmor 2>/dev/null)" ]] \
    && eg287 pass || eg287 fail "apparmor --help = the apparmor page, rc 0, rootless (rc=$rc)"

# EGL-410: `help env test` is the hidden harness-hook census. The default
# `help env` page carries none of the moved names (and keeps the operator
# `EGRESSLOCK_APPARMOR_PROFILES` row); the hidden page lists every one.
s287_env="$("$SKIT" help env 2>/dev/null)"; s287_env_rc=$?
s287_test="$("$SKIT" help env test 2>/dev/null)"; s287_test_rc=$?
s287_ok=1
for s287_v in EGRESSLOCK_SHARE EGRESSLOCK_GW_IMAGE EGRESSLOCK_KIT_ALLOW_NON_ROOT \
             EGRESSLOCK_UNIT_DIR EGRESSLOCK_DEFAULT_UNIT_DIR EGRESSLOCK_ETC_UNIT_DIR \
             EGRESSLOCK_DEB_UNIT_DIR EGRESSLOCK_APPARMOR_D EGRESSLOCK_SYSTEMCTL \
             EGRESSLOCK_ACCOUNT_HOME; do
    [[ "$s287_env" != *"$s287_v"* ]] || s287_ok=0
    [[ "$s287_test" == *"$s287_v"* ]] || s287_ok=0
done
[[ "$s287_env" == *"EGRESSLOCK_APPARMOR_PROFILES"* ]] || s287_ok=0
[[ "$s287_env" == *"help env test"* ]] || s287_ok=0
[[ "$s287_env_rc" == 0 && "$s287_test_rc" == 0 && "$s287_ok" == 1 ]] \
    && eg287 pass || eg287 fail "EGL-410 env/test split (rc=$s287_env_rc/$s287_test_rc)"
# EGL-531-D3: the SHARE row carries the same test-mode marker as its
# siblings now that the hook is gated.
s287_share="$(printf '%s\n' "$s287_test" | grep -A4 '^  EGRESSLOCK_SHARE=')"
[[ "$s287_share" == *"requires"* \
    && "$s287_share" == *"EGRESSLOCK_KIT_ALLOW_NON_ROOT=1"* ]] \
    && eg287 pass || eg287 fail "help env test SHARE row carries the test-mode marker"
if grep -qE "$k59_id_re" <<<"$s287_test"; then
    eg287 fail "help env test leaks ticket/process refs"
else
    eg287 pass
fi

# 3. Typed edges: summary on stderr, named messages, rc 2.
o="$("$SKIT" help bogus 2>/dev/null)"; rc=$?
o2="$("$SKIT" help bogus 2>&1 1>/dev/null)"
[[ "$rc" == 2 && -z "$o" && "$o2" == *"Error: unknown help topic 'bogus'."* && "$o2" == *"Usage:"* ]] \
    && eg287 pass || eg287 fail "help bogus rc 2 named + summary on stderr (rc=$rc, out: $o2)"
o="$("$SKIT" help a b 2>/dev/null)"; rc=$?
o2="$("$SKIT" help a b 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"Error: egresslock-setup help takes at most one topic."* && "$o2" == *"Usage:"* ]] \
    && eg287 pass || eg287 fail "help a b rc 2 takes-at-most-one (rc=$rc, out: $o2)"
# EGL-410: only the exact `env test` pair is special; `env <bogus>` keeps
# the same message.
o="$("$SKIT" help env bogus 2>/dev/null)"; rc=$?
o2="$("$SKIT" help env bogus 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"Error: egresslock-setup help takes at most one topic."* && "$o2" == *"Usage:"* ]] \
    && eg287 pass || eg287 fail "help env bogus rc 2 takes-at-most-one (rc=$rc, out: $o2)"
o="$("$SKIT" help help 2>/dev/null)"; rc=$?
o2="$("$SKIT" help help 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"Error: unknown help topic 'help'."* ]] \
    && eg287 pass || eg287 fail "help help rc 2 unknown topic (rc=$rc, out: $o2)"
o="$("$SKIT" help --help 2>/dev/null)"; rc=$?
o2="$("$SKIT" help --help 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"Error: unknown help topic '--help'."* ]] \
    && eg287 pass || eg287 fail "help --help rc 2 unknown topic (rc=$rc, out: $o2)"
o="$("$SKIT" apparmor 2>/dev/null)"; rc=$?
o2="$("$SKIT" apparmor 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"apparmor needs a sub-verb: add, remove, or check"* && "$o2" == *"Usage:"* ]] \
    && eg287 pass || eg287 fail "bare apparmor rc 2 named sub-verb list (rc=$rc, out: $o2)"

# 4. Alias equivalence (D2): the verbs run the same code path.
# 4a. doctor: same rc + output on a fixed fixture (host slice, mock
#     unit dir).
s287_doc="$STATE/egl287/docx"; rm -rf "$s287_doc"; mkdir -p "$s287_doc/units"
o1="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$s287_doc/units" "$SKIT" --doctor --prefix "$SKITP" 2>&1)"; r1=$?
o2="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$s287_doc/units" "$SKIT" doctor --prefix "$SKITP" 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" ]] \
    && eg287 pass || eg287 fail "--doctor == doctor (rc $r1/$r2)"
# 4b. build-gateway (no engine at prefix): byte-equal failure shape.
s287_neng="$STATE/egl287/noeng"; mkdir -p "$s287_neng"
o1="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 "$SKIT" --build-gateway --prefix "$s287_neng" 2>&1)"; r1=$?
o2="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 "$SKIT" build-gateway --prefix "$s287_neng" 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" ]] \
    && eg287 pass || eg287 fail "--build-gateway == build-gateway (rc $r1/$r2)"
# 4c. apparmor check (read-only host probe on the real container): the
#     verb form runs the same checker.
o1="$("$SKIT" --apparmor-check 2>&1)"; r1=$?
o2="$("$SKIT" apparmor check 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" ]] \
    && eg287 pass || eg287 fail "--apparmor-check == apparmor check (rc $r1/$r2)"
# 4d. init: the verb wires the same account state as the legacy bundle,
#     byte-equal output, and neither writes a unit.env (EGL-333-D2).
s287_i="$STATE/egl287/init"; rm -rf "$s287_i"
mkdir -p "$s287_i/prefix" "$s287_i/home/u287/.config/egresslock"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$s287_i/prefix/wbin" EGRESSLOCK_PATH_SBINDIR="$s287_i/prefix/wsbin" \
    "$KIT" --prefix "$s287_i/prefix" >/dev/null 2>&1
s287_legen() { # <legacy|verb> <image-tag>
    local form="$1" tag="$2"
    rm -f "$s287_i/home/u287/.config/egresslock/main.conf" \
          "$s287_i/home/u287/.config/egresslock/main-allowlist"
    if [[ "$form" == legacy ]]; then
        env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$s287_i/home/u287" \
            EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE="localhost/egresslock-gateway:$tag" \
            "$SKIT" --prefix "$s287_i/prefix" --account u287 --init-conf 2>&1
    else
        env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$s287_i/home/u287" \
            EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE="localhost/egresslock-gateway:$tag" \
            "$SKIT" init --prefix "$s287_i/prefix" --account u287 --init-conf 2>&1
    fi
}
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"; : > "$STATE/buildlog"
o1="$(s287_legen legacy e287a)"; r1=$?
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"; : > "$STATE/buildlog"
o2="$(s287_legen verb e287b)"; r2=$?
[[ ! -e "$s287_i/home/u287/.config/egresslock/unit.env" ]] \
    && eg287 pass || eg287 fail "init verb writes no unit.env (got: $(cat "$s287_i/home/u287/.config/egresslock/unit.env" 2>/dev/null))"
[[ "$r1" == "$r2" && "$o1" == "$o2" ]] \
    && eg287 pass || eg287 fail "init verb == legacy bundle (rc $r1/$r2; diff: $(diff <(printf '%s' "$o1") <(printf '%s' "$o2") >/dev/null 2>&1 || diff <(printf '%s' "$o1") <(printf '%s' "$o2") 2>&1 | head -3))"

# 5. Conflict refusal: a legacy mode flag beside a verb (rc 2, named).
o="$("$SKIT" init --doctor 2>/dev/null)"; rc=$?
o2="$("$SKIT" init --doctor 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"egresslock-setup: --doctor is a verb: run 'egresslock-setup doctor'"* ]] \
    && eg287 pass || eg287 fail "init --doctor rc 2 named (rc=$rc, out: $o2)"
o="$("$SKIT" doctor --apparmor-check 2>/dev/null)"; rc=$?
o2="$("$SKIT" doctor --apparmor-check 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"egresslock-setup: --apparmor-check is a verb: run 'egresslock-setup apparmor check'"* ]] \
    && eg287 pass || eg287 fail "doctor --apparmor-check rc 2 named (rc=$rc, out: $o2)"
o="$("$SKIT" apparmor add --apparmor-check 2>/dev/null)"; rc=$?
[[ "$rc" == 2 ]] \
    && eg287 pass || eg287 fail "apparmor add + legacy --apparmor-check refused (rc=$rc)"
o="$("$SKIT" build-gateway --build-gateway 2>/dev/null)"; rc=$?
o2="$("$SKIT" build-gateway --build-gateway 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"egresslock-setup: --build-gateway is a verb: run 'egresslock-setup build-gateway'"* ]] \
    && eg287 pass || eg287 fail "build-gateway + legacy flag refused (rc=$rc, out: $o2)"
o="$("$SKIT" init --build-gateway 2>/dev/null)"; rc=$?
o2="$("$SKIT" init --build-gateway 2>&1 1>/dev/null)"
[[ "$rc" == 2 && "$o2" == *"egresslock-setup: --build-gateway is a verb: run 'egresslock-setup build-gateway'"* ]] \
    && eg287 pass || eg287 fail "init --build-gateway refused (rc=$rc, out: $o2)"

# 6. EGL-517: seeded-sandbox paste — a swept setup synopsis line performs
#    no file operation. Seed the placeholder names and the old lowercase
#    trigger words; paste each command-shaped line; assert rc 2 and a
#    byte-identical file set (no truncation, no junk).
s517="$TESTROOT/s517"; rm -rf "$s517"; mkdir -p "$s517"
for w in profile print apply list p PROFILE NAME ACCOUNT CONF PATH COMMAND CIDR HOST PORT HOST:PORT VERB UID PROFILE.conf .pins .conf .revoke-pending; do
    printf 'seed:%s\n' "$w" > "$s517/$w"
done
# EGL-517-F2: one single-char file per kept bracket class, derived from the
# same emitted lines (a pasted `[--flag]` group is a bash character class).
s517_cls=()
while IFS= read -r b517; do
    [[ -n "$b517" ]] && s517_cls+=( "$b517" )
done < <(
    { "$SKIT" -h 2>&1
      for t287 in "${verbs517[@]}"; do "$SKIT" help "$t287" 2>&1; done
    } | grep -oE '\[[^]]*\]' | sed -E 's/^\[//; s/\]$//' \
      | awk 'match($0, /[A-Za-z0-9]/) { print substr($0, RSTART, 1) }' | sort -u)
(( ${#s517_cls[@]} > 0 )) \
    && eg287 pass || eg287 fail "seeded paste: no bracket class derived"
for b517 in "${s517_cls[@]}"; do
    printf 'seed:%s\n' "$b517" > "$s517/$b517"
done
# R-EGL-517-5 F12: hash dotfiles too — `<profile>.pins` pastes as an
# output redirect to a dot-named target, which `sha256sum -- *` cannot see.
s517_snap() { ( cd "$s517" && ls -A && sha256sum -- * .[!.]* 2>/dev/null ) | sort; }
s517_before="$(s517_snap)"
s517_bad=""
paste517s() { # paste517s <line>
    local rc=0 out after
    out="$( cd "$s517" && eval "$1" 2>&1 )" || rc=$?
    after="$(s517_snap)"
    if [[ "$1" == 'egresslock-setup doctor [ACCOUNT]' ]]; then
        # EGL-581/EGL-600: the account is a real optional operand, so the
        # seeded bracket-class file makes this synopsis paste as a
        # one-character account name — a valid read-only account-slice
        # request that must refuse as non-root, not a usage error. Keep the
        # file-op guard; require the root refusal.
        if [[ "$rc" != 1 || "$out" != *"must run as root"* ]]; then
            s517_bad="rc=$rc line=$1 out=$out"
        elif [[ "$after" != "$s517_before" ]]; then
            s517_bad="file change line=$1"
        fi
        return
    fi
    if [[ "$rc" != 2 ]]; then
        s517_bad="rc=$rc line=$1 out=$out"
    elif [[ "$after" != "$s517_before" ]]; then
        s517_bad="file change line=$1"
    fi
}
paste517s_any() { # paste517s_any <line> — file-op check only (rc may vary)
    local after
    ( cd "$s517" && eval "$1" ) >/dev/null 2>&1 || true
    after="$(s517_snap)"
    if [[ "$after" != "$s517_before" ]]; then
        s517_bad="file change line=$1"
    fi
}
while IFS= read -r l; do
    paste517s "$l"
done < <("$SKIT" -h 2>&1 \
    | awk '/^  egresslock-setup / { sub(/^  /, ""); split($0, a, /  +/); print a[1] }' \
    | grep -E '[A-Z]{2}|\[[^]]|apparmor add, remove, or check')
while IFS= read -r l; do
    paste517s "$l"
done < <(for t287 in "${verbs517[@]}"; do
              "$SKIT" help "$t287" 2>&1 | grep -E '^egresslock-setup '
          done | grep -E '[A-Z]{2}|\[[^]]|apparmor add, remove, or check')
# Full index lines (description included): file-op check only.
while IFS= read -r l; do
    paste517s_any "$l"
done < <("$SKIT" -h 2>&1 | grep -E '^  egresslock-setup ')
[[ -z "$s517_bad" ]] && eg287 pass || eg287 fail "seeded paste: $s517_bad"

section_end egl287

# --- EGL-200: setup console output ------------------------------------------
section_begin egl200 "EGL-200 setup console output"
e200() { assert "$@"; }
# Self-contained fixture: deployed prefix, gateway conf + allowlist,
# single-profile no-gateway conf, one account home (e38 shape).
e200p="$STATE/egl200/prefix"
rm -rf "$STATE/egl200"; mkdir -p "$e200p"
env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$UNITS" \
    EGRESSLOCK_PATH_BINDIR="$e200p/wbin" EGRESSLOCK_PATH_SBINDIR="$e200p/wsbin" \
    "$KIT" --prefix "$e200p" >/dev/null 2>&1
[[ -f "$e200p/egresslock" && -f "$e200p/gateway/Containerfile" && -f "$e200p/examples/main.conf" ]] \
    && e200 pass || e200 fail "egl200 fixture: kit deployed to $e200p"
e200h="$STATE/egl200/home/actx"
mkdir -p "$e200h/.config/egresslock"
printf 'profile p1 10.99.7.0/24\n    gateway 10.99.7.2 3128 p1-allowlist\n' \
    > "$STATE/egl200/gw.conf"
printf '# starter\n' > "$STATE/egl200/p1-allowlist"
printf 'profile pa 10.99.8.0/24\n    gateway 10.99.8.2 3128 pa-allowlist\n' > "$STATE/egl200/pa.conf"
printf '# starter\n' > "$STATE/egl200/pa-allowlist"
e200_map() { grep -E '^[0-9]\) .* … (OK|SKIP|FAIL)$' <<<"$1"; }

# 1. First run, image missing, noisy stream enabled: the terminal shows
#    M8 and never the build stream; the stream lands in the build log.
: > "$STATE/build-noisy"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e200gw \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/gw.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"egresslock-setup: building the gateway image — first run downloads the base image and packages; a few minutes. Build log: $e200h/.config/egresslock/gateway-build.log"* \
    && "$o" != *"MOCK-BUILD-OUTPUT"* ]] \
    && e200 pass || e200 fail "EGL-200 P3-C quiet build: M8 only, stream not on terminal (rc=$rc, out: $o)"
grep -q "MOCK-BUILD-OUTPUT" "$e200h/.config/egresslock/gateway-build.log" \
    && e200 pass || e200 fail "EGL-200 P3-C build stream captured in gateway-build.log (log: $(cat "$e200h/.config/egresslock/gateway-build.log" 2>/dev/null))"
# EGL-328 D8: --from imports p1 but does NOT choose named mode; a pathless
# init wires aggregate and names the first conf profile in the next block.
[[ "$o" == *"next steps (as the account):"* \
    && "$o" == *"  sudo -iu actx"* \
    && "$o" == *"  egresslock ensure p1"* \
    && "$o" != *"the scheduled check"* ]] \
    && e200 pass || e200 fail "EGL-200 M1(c)/EGL-600 P3: block + no claim without --enable (out: $o)"
rm -f "$STATE/build-noisy"

# 2. Image present re-run: the quiet path is skipped entirely.
: > "$STATE/buildlog"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e200gw \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/gw.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"gateway image present"* && "$o" != *"building the gateway image"* ]] \
    && e200 pass || e200 fail "EGL-200 P3-C re-run: image present, no build line (rc=$rc, out: $o)"

# 3. Failing build: rc 1, step 4 FAIL, M9 names the log and its last
#    lines are shown (noisy marker feeds the log the tail prints).
: > "$STATE/build-noisy"; : > "$STATE/build-fails"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e200gw2 \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/gw.conf" 2>&1)"; rc=$?
rm -f "$STATE/build-fails"; rm -f "$STATE/build-noisy"
[[ "$rc" == 1 && "$(e200_map "$o" | tail -1)" == "4) gateway image … FAIL" \
    && "$o" == *"egresslock-setup: gateway image build failed; last lines of the build log ($e200h/.config/egresslock/gateway-build.log):"* \
    && "$o" == *"MOCK-BUILD-OUTPUT"* ]] \
    && e200 pass || e200 fail "EGL-200 P3-C build failure: M9 + tail shown (rc=$rc, map: $(e200_map "$o" | tr '\n' '|'))"

# 4. EGL-200 M2/EGL-333: a second profile is wired aggregate — no
#    'named mode' or 'verify mode:' wording survives, and without
#    --enable no scheduled-check claim prints (EGL-600 P3). EGL-333-F5:
#    the next-step block names the profile THIS run imported (pa), not
#    the aggregate list's first entry (p1), so the freshly imported
#    profile is the one the operator is told to ensure.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/pa.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" != *"the scheduled check"* \
    && "$o" != *"only profile"* && "$o" != *"verify mode:"* \
    && "$o" == *"  egresslock ensure pa"* && "$o" == *"  egresslock verify pa"* ]] \
    && e200 pass || e200 fail "EGL-200 M2/F5 + EGL-600 P3: no claim without --enable (rc=$rc, out: $o)"

# 4b. EGL-333-F5: an unchanged import stages nothing ("import:
#     unchanged"), so the next-step block must name the profile --from
#     named (pa), not the aggregate list's first entry (p1). The pair
#     imported by leg 4 already matches, so this takes the unchanged
#     branch.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/pa.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"egresslock-setup: import: unchanged"* \
    && "$o" == *"  egresslock ensure pa"* && "$o" == *"  egresslock verify pa"* ]] \
    && e200 pass || e200 fail "EGL-333-F5: unchanged pair import names the imported profile (rc=$rc, out: $o)"

# 4c. EGL-333-F5, the source-is-destination unchanged return: --from
#     naming the live destination pair validates in place — the block
#     still names the imported profile.
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT init --prefix "$e200p" --account actx --from "$e200h/.config/egresslock/pa.conf" 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"egresslock-setup: import: unchanged"* \
    && "$o" == *"  egresslock ensure pa"* ]] \
    && e200 pass || e200 fail "EGL-333-F5: source-is-destination import names the imported profile (rc=$rc, out: $o)"

# 5. EGL-200 M1(c): a sweep-mode setup (--init-conf only: no --from, so
#    no profile is derived) names the first profile from the step-1
#    list capture for the ensure hint.
e200h5="$STATE/egl200/home/sweep"
rm -rf "$e200h5"; mkdir -p "$e200h5"
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h5" \
    EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:e200gw \
    $SKIT --prefix "$e200p" --account actx --init-conf 2>&1)"; rc=$?
[[ "$rc" == 0 && "$o" == *"  egresslock ensure main"* \
    && "$o" != *"the scheduled check"* ]] \
    && e200 pass || e200 fail "EGL-200 M1(c)/EGL-600 P3: first-profile fallback, no claim (rc=$rc, out: $o)"

# 6. EGL-333-D9: init rejects --profile with the doctor-flag usage error
#    before anything is installed (no stray conf).
o="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e200h" \
    EGRESSLOCK_UNIT_DIR="$UNITS" \
    $SKIT init --prefix "$e200p" --account actx --from "$STATE/egl200/pa.conf" --profile nope 2>&1)"; rc=$?
[[ "$rc" == 2 && "$o" == *"--profile is a doctor flag only (inspection narrowing)"* \
    && ! -e "$e200h/.config/egresslock/nope.conf" ]] \
    && e200 pass || e200 fail "EGL-333-D9: init --profile refused rc 2 (rc=$rc, out: $o)"

section_end egl200

# --- EGL-581: positional ACCOUNT on init/import/doctor; reserved 'all' ----
section_begin egl581 "EGL-581 positional ACCOUNT + reserved all"
e581() { assert "$@"; }
e581d="$STATE/egl581"; rm -rf "$e581d"
mkdir -p "$e581d/home/u581" "$e581d/home/u582"
e581_run() { # <home> <setup args...>
    local h="$1"; shift
    env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$h" \
        EGRESSLOCK_UNIT_DIR="$UNITS" EGRESSLOCK_GW_IMAGE=localhost/egresslock-gateway:latest \
        "$SKIT" "$@" --prefix "$SKITP"
}
e581_ng() { env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$SKIT" "$@" 2>&1; }

# 1. Parse equivalence, root-gate witness (hook off, non-root): the
#    positional, the flags-before-operand spelling, and the legacy
#    --account alias all reach the same gate with the same bytes. A
#    parser miss would be rc 2 `unknown argument` instead.
for e581_v in init import doctor; do
    case "$e581_v" in
        init)   e581_tail=(--from /nonexistent/none.conf) ;;
        import) e581_tail=(--from /nonexistent/none.conf) ;;
        doctor) e581_tail=() ;;
    esac
    o1="$(e581_ng "$e581_v" u581 "${e581_tail[@]}")"; r1=$?
    o2="$(e581_ng "$e581_v" "${e581_tail[@]}" u581)"; r2=$?
    o3="$(e581_ng "$e581_v" --account u581 "${e581_tail[@]}")"; r3=$?
    if [[ "$r1" == 1 && "$r2" == 1 && "$r3" == 1 \
          && "$o1" == "$o2" && "$o1" == "$o3" \
          && "$o1" == *"must run as root"* && "$o1" != *"unknown argument"* ]]; then
        e581 pass
    else
        e581 fail "$e581_v positional/flags/alias root-gate parity (rc $r1/$r2/$r3, out: $o1)"
    fi
done

# 2. Accepted forms in kit-test mode (account slice reached): the
#    positional and the alias run the same code path, flags may sit
#    before or after the operand, and the same value in both forms is
#    accepted.
o1="$(e581_run "$e581d/home/u581" init u581 2>&1)"; r1=$?
o2="$(e581_run "$e581d/home/u581" init --account u581 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" && "$o1" == *"no profile configs in"* ]] \
    && e581 pass || e581 fail "init positional == --account (rc $r1/$r2, out: $o1)"
o1="$(e581_run "$e581d/home/u581" import u581 --from /nonexistent/none.conf 2>&1)"; r1=$?
o2="$(e581_run "$e581d/home/u581" import --account u581 --from /nonexistent/none.conf 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" && "$o1" == *"conf not found"* ]] \
    && e581 pass || e581 fail "import positional == --account (rc $r1/$r2, out: $o1)"
o1="$(e581_run "$e581d/home/u581" init u581 --from /nonexistent/none.conf 2>&1)"; r1=$?
o2="$(e581_run "$e581d/home/u581" init --from /nonexistent/none.conf u581 2>&1)"; r2=$?
o3="$(e581_run "$e581d/home/u581" init u581 --account u581 --from /nonexistent/none.conf 2>&1)"; r3=$?
[[ "$r1" == "$r2" && "$r2" == "$r3" && "$o1" == "$o2" && "$o2" == "$o3" ]] \
    && e581 pass || e581 fail "init operand before/after flags + same value both forms (rc $r1/$r2/$r3)"

# 3. Both forms with different values is rc 2 before any account read;
#    the message names both values and the one-form rule.
o1="$(e581_run "$e581d/home/u581" init u581 --account u582 2>&1)"; r1=$?
[[ "$r1" == 2 \
    && "$o1" == *"egresslock-setup: account names differ: --account 'u582' and positional 'u581' (pass one form, or the same value in both)"* \
    && "$o1" != *"no profile configs"* ]] \
    && e581 pass || e581 fail "different --account/positional values rc 2 named (rc=$r1, out: $o1)"

# 4. One positional max: a second one rides the existing unknown-argument
#    arm for the three account verbs; the other verbs take no operand.
for e581_case in "init u581 u582" "import u581 u582 --from /nonexistent/none.conf" "doctor u581 u582"; do
    read -r -a e581_argv <<<"$e581_case"
    o="$(e581_ng "${e581_argv[@]}")"; rc=$?
    [[ "$rc" == 2 && "$o" == *"unknown argument: u582"* ]] \
        && e581 pass || e581 fail "second positional refused: $e581_case (rc=$rc, out: $o)"
done
for e581_case in "apparmor add u581" "build-gateway u581"; do
    read -r -a e581_argv <<<"$e581_case"
    o="$(e581_ng "${e581_argv[@]}")"; rc=$?
    [[ "$rc" == 2 && "$o" == *"unknown argument: u581"* ]] \
        && e581 pass || e581 fail "non-account verb rejects operand: $e581_case (rc=$rc, out: $o)"
done

# 5. Bare doctor stays the host slice; doctor ACCOUNT adds the account
#    slice; --profile narrows the positional form identically.
o1="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$SKIT" doctor --prefix "$SKITP" 2>&1)"; r1=$?
o2="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$SKIT" --doctor --prefix "$SKITP" 2>&1)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" \
    && "$o1" == *"not examined (no account operand)"* \
    && "$o1" == *"sudo egresslock-setup doctor ACCOUNT"* ]] \
    && e581 pass || e581 fail "bare doctor host slice + pointer (rc $r1/$r2, out: $o1)"
o1="$(e581_run "$e581d/home/u581" doctor u581)"; r1=$?
o2="$(e581_run "$e581d/home/u581" doctor --account u581)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" && "$o1" == *"conf parse: FAIL"* ]] \
    && e581 pass || e581 fail "doctor ACCOUNT == doctor --account ACCOUNT (rc $r1/$r2, out: $o1)"
o1="$(e581_run "$e581d/home/u581" doctor u581 --profile main)"; r1=$?
o2="$(e581_run "$e581d/home/u581" doctor --account u581 --profile main)"; r2=$?
[[ "$r1" == "$r2" && "$o1" == "$o2" ]] \
    && e581 pass || e581 fail "doctor ACCOUNT --profile == alias form (rc $r1/$r2)"

# 6. Required-account usage names the positional spelling per verb; the
#    verb-less bundle keeps the legacy flag spelling.
o="$(e581_ng init)"; rc=$?
[[ "$rc" == 2 && "$o" == *"egresslock-setup: init requires an account: egresslock-setup init ACCOUNT [--from CONF or --init-conf]"* ]] \
    && e581 pass || e581 fail "init missing account names init ACCOUNT (rc=$rc, out: $o)"
o="$(e581_ng import --from /nonexistent/none.conf)"; rc=$?
[[ "$rc" == 2 && "$o" == *"egresslock-setup: import requires an account: egresslock-setup import ACCOUNT --from CONF"* ]] \
    && e581 pass || e581 fail "import missing account names import ACCOUNT (rc=$rc, out: $o)"
o="$(e581_ng --init-conf)"; rc=$?
[[ "$rc" == 2 && "$o" == *"egresslock-setup: --account is required (or a verb: doctor, build-gateway, apparmor add, remove, or check)"* ]] \
    && e581 pass || e581 fail "legacy bundle keeps the --account-required wording (rc=$rc, out: $o)"

# 7. 'all' is reserved on every setup path that resolves an account name:
#    one message, rc 2, before root/id/account-home, and it fires in
#    kit-test mode too (no hook bypass). The fix line points at the
#    shipped reference note.
e581_reserved="egresslock-setup: account name 'all' is reserved (it means every account in setup commands); use a different account name"
e581_fix="  fix: if this is your runner account, rename it and re-run setup (steps: docs/reference/scripts-and-environment.md)"
e581_hall="$e581d/home/all-never"
: > "$STATE/systemctl.log"; : > "$STATE/loginctl.log"; : > "$STATE/buildlog"
e581_allcheck() { # <label> <setup args...>
    local label="$1"; shift
    local err="$e581d/all.err" out rc
    out="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_ACCOUNT_HOME="$e581_hall" \
        EGRESSLOCK_UNIT_DIR="$UNITS" "$SKIT" "$@" --prefix "$SKITP" 2>"$err")"; rc=$?
    if [[ "$rc" == 2 && -z "$out" \
          && "$(sed -n '1p' "$err")" == "$e581_reserved" \
          && "$(sed -n '2p' "$err")" == "$e581_fix" \
          && "$(sed -n '3p' "$err")" == "Usage:" \
          && "$(grep -cF -- "$e581_reserved" "$err")" == 1 \
          && "$(grep -cF 'must run as root' "$err")" == 0 \
          && "$(grep -cF 'no such account' "$err")" == 0 ]]; then
        e581 pass
    else
        e581 fail "reserved all ($label): rc=$rc out=$out err=$(head -3 "$err" | tr '\n' '|')"
    fi
}
e581_allcheck "init" init all
e581_allcheck "import" import all --from /nonexistent/none.conf
e581_allcheck "doctor" doctor all
e581_allcheck "legacy bundle" --account all --init-conf
e581_allcheck "init --account" init --account all
e581_allcheck "import --account" import --account all --from /nonexistent/none.conf
e581_allcheck "doctor --account" doctor --account all
e581_allcheck "both forms same value" init all --account all
[[ ! -e "$e581_hall" ]] \
    && e581 pass || e581 fail "reserved all never resolves the account home"
[[ ! -s "$STATE/systemctl.log" && ! -s "$STATE/loginctl.log" && ! -s "$STATE/buildlog" ]] \
    && e581 pass || e581 fail "reserved all has no systemd/linger/build side effect"
# Case-sensitive: ALL is a different OS name and stays legal.
o="$(e581_ng init ALL --from /nonexistent/none.conf)"; rc=$?
[[ "$rc" == 1 && "$o" == *"must run as root"* && "$o" != *"is reserved"* ]] \
    && e581 pass || e581 fail "ALL is not reserved (rc=$rc, out: $o)"
o="$(e581_run "$e581d/home/u581" doctor ALL)"; rc=$?
[[ "$rc" == 1 && "$o" == *"conf parse: FAIL"* && "$o" != *"is reserved"* ]] \
    && e581 pass || e581 fail "doctor ALL reaches the account slice (rc=$rc, out: $o)"

# 8. Help surfaces: the canonical synopses are positional (pinned above in
#    egl287), the summary and reference page keep the alias discoverable,
#    and no verb page teaches the old required flag form.
e581_sum="$("$SKIT" -h 2>&1)"
[[ "$e581_sum" == *"accepted as a hidden alias of the positional ACCOUNT on init, import,"* ]] \
    && e581 pass || e581 fail "summary keeps the --account hidden-alias line"
for e581_t in init import doctor; do
    o="$("$SKIT" help "$e581_t" 2>/dev/null)"; rc=$?
    [[ "$rc" == 0 ]] || e581 fail "help $e581_t rc 0 (rc=$rc)"
    if grep -qE "^egresslock-setup $e581_t --account" <<<"$o"; then
        e581 fail "help $e581_t still opens with the flag form"
    else
        e581 pass
    fi
done
o="$("$SKIT" help init 2>/dev/null)"
[[ "$o" == *"--account NAME"* && "$o" == *"legacy alias of ACCOUNT"* ]] \
    && e581 pass || e581 fail "help init documents --account as the hidden alias"
o="$("$SKIT" help import 2>/dev/null)"
[[ "$(head -n1 <<<"$o")" == 'egresslock-setup import ACCOUNT --from CONF [--allowlist PATH] [--force] [--prefix PATH]' ]] \
    && e581 pass || e581 fail "help import synopsis is positional (got: $(head -n1 <<<"$o"))"

# 9. Emitted next-step producers teach the positional form (the installed
#    kit and both packaging channels). The files are absent on an
#    extracted kit, so skip with a named cause there.
for e581_f in install-kit.sh packaging/build-deb.sh packaging/build-tarball.sh; do
    [[ -f "$TREE_ROOT/$e581_f" ]] || continue
    if grep -qF 'egresslock-setup init ACCT --init-conf --enable' "$TREE_ROOT/$e581_f" \
       && ! grep -qF 'egresslock-setup init --account' "$TREE_ROOT/$e581_f"; then
        e581 pass
    else
        e581 fail "$e581_f next step is not the positional form"
    fi
done

section_end egl581

# --- EGL-491: ignored test-hook warnings on the kit entry points ----------
# D1/D2: every recognized gated hook set without the test flag warns once
# per name per invocation, stderr-only, at its discard branch; D4: a flag
# set to anything but exactly `1` warns once. rc, stdout, and the
# production fallback stay the flag-off-equals-unset shape, and the value
# is never echoed.
section_begin egl491 "EGL-491 ignored test-hook warnings (kit)"
e491() { assert "$@"; }
e491d="$STATE/egl491"; rm -rf "$e491d"; mkdir -p "$e491d"
e491_hsent='is set but ignored: it is a test-harness override and requires EGRESSLOCK_KIT_ALLOW_NON_ROOT=1; the production default applies.'
e491_fsent='is set but is not the exact value 1, so test mode is off; test-harness overrides are ignored.'
e491_count() { printf '%s\n' "$1" | grep -cF -- "$2 is set but ignored" || true; }
e491_named_warning() { # e491_named_warning <out> <prefix> <var>
    printf '%s' "$1" | grep -qF -- "$2$3 $e491_hsent"
}

# 1. Setup host doctor, flag off: every gated setup hook is discarded with
#    one named stderr line and the production fallback, while stdout and
#    rc equal the hook-unset control. UNIT_DIR rows are read more than
#    once (top-level resolution plus both doctor paths for SYSTEMCTL), so
#    the exact-one count is the D2 dedupe pin. Decoy values are never
#    echoed.
mkdir -p "$e491d/prefix" "$e491d/hook-units" "$e491d/hook-defunits" \
         "$e491d/hook-debunits" "$e491d/hook-etcunits"
ln -s "$TREE_ROOT/egresslock" "$e491d/prefix/egresslock"
e491_ctl_out="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_UNIT_DIR \
    -u EGRESSLOCK_DEFAULT_UNIT_DIR -u EGRESSLOCK_DEB_UNIT_DIR \
    -u EGRESSLOCK_ETC_UNIT_DIR -u EGRESSLOCK_GW_IMAGE -u EGRESSLOCK_SYSTEMCTL \
    "$SKIT" --prefix "$e491d/prefix" --doctor 2>"$e491d/doctor-ctl.err")"; e491_ctl_rc=$?
e491_out="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    EGRESSLOCK_UNIT_DIR="$e491d/hook-units" \
    EGRESSLOCK_DEFAULT_UNIT_DIR="$e491d/hook-defunits" \
    EGRESSLOCK_DEB_UNIT_DIR="$e491d/hook-debunits" \
    EGRESSLOCK_ETC_UNIT_DIR="$e491d/hook-etcunits" \
    EGRESSLOCK_GW_IMAGE='localhost/egl491-decoy:latest' \
    EGRESSLOCK_SYSTEMCTL="$e491d/decoy-systemctl" \
    "$SKIT" --prefix "$e491d/prefix" --doctor 2>"$e491d/doctor-hook.err")"; e491_rc=$?
e491_err="$(cat "$e491d/doctor-hook.err")"
e491_ctlerr="$(cat "$e491d/doctor-ctl.err")"
e491_ok=1
for e491_v in UNIT_DIR DEFAULT_UNIT_DIR DEB_UNIT_DIR ETC_UNIT_DIR GW_IMAGE SYSTEMCTL; do
    e491_named_warning "$e491_err" "egresslock-setup: WARNING - " "EGRESSLOCK_$e491_v" || e491_ok=0
    [[ "$(e491_count "$e491_err" "EGRESSLOCK_$e491_v")" == 1 ]] || e491_ok=0
done
[[ "$e491_ctlerr" != *'is set but ignored'* ]] || e491_ok=0
[[ "$e491_rc" == "$e491_ctl_rc" && "$e491_out" == "$e491_ctl_out" ]] || e491_ok=0
e491_errs="$(printf '%s\n' "$e491_err" | strip_egl491_warnings)"
e491_ctls="$(printf '%s\n' "$e491_ctlerr" | strip_egl491_warnings)"
[[ "$e491_errs" == "$e491_ctls" ]] || e491_ok=0
[[ "$e491_out$e491_err" != *"$e491d/hook-units"* \
    && "$e491_out$e491_err" != *"$e491d/hook-defunits"* \
    && "$e491_out$e491_err" != *"$e491d/hook-debunits"* \
    && "$e491_out$e491_err" != *"$e491d/hook-etcunits"* \
    && "$e491_out$e491_err" != *"$e491d/decoy-systemctl"* \
    && "$e491_out$e491_err" != *"localhost/egl491-decoy:latest"* ]] || e491_ok=0
(( e491_ok )) \
    && e491 pass || e491 fail "setup host doctor: ignored hooks warn once each, rc/stdout equal the unset control (control rc=$e491_ctl_rc, rc=$e491_rc, out: $e491_out, err: $e491_err)"

# 2. Setup account slice, flag off: ACCOUNT_HOME is discarded in the
#    passwd branch (the account home comes from getent), warns once, and
#    the decoy home is never read or named. Both runs are otherwise
#    identical so the warning is the only delta.
mkdir -p "$e491d/accthome/.config/egresslock" \
         "$e491d/decoyhome/.config/egresslock" "$e491d/bin"
cat > "$e491d/accthome/.config/egresslock/main.conf" <<'EOF'
profile main 10.99.0.0/24
    rule allow-host git.example.test:443
    gateway 10.99.0.2 3128 main-allowlist
EOF
: > "$e491d/accthome/.config/egresslock/main-allowlist"
: > "$e491d/decoyhome/.config/egresslock/e491-keep"
cat > "$e491d/bin/id" <<'EOF'
#!/usr/bin/env bash
# Virtual test account: only existence is asked for by setup; the fake
# root takes the passwd branch this leg pins.
if [[ "${1:-}" == "-u" ]]; then echo 0; exit 0; fi
if [[ "${1:-}" == "e491acct" ]]; then exit 0; fi
exec /usr/bin/id "$@"
EOF
cat > "$e491d/bin/getent" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "passwd" && "\$2" == "e491acct" ]]; then
    printf 'e491acct:x:1000:1000::%s:/bin/sh\n' "$e491d/accthome"
    exit 0
fi
exec /usr/bin/getent "\$@"
EOF
chmod +x "$e491d/bin/id" "$e491d/bin/getent"
e491_actl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_ACCOUNT_HOME \
    PATH="$e491d/bin:$PATH" ARCMOCK_PASSWD_HOME="$e491d/accthome" \
    "$SKIT" --prefix "$e491d/prefix" --account e491acct --doctor 2>"$e491d/acct-ctl.err")"; e491_actl_rc=$?
e491_aout="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_ACCOUNT_HOME="$e491d/decoyhome" \
    PATH="$e491d/bin:$PATH" ARCMOCK_PASSWD_HOME="$e491d/accthome" \
    "$SKIT" --prefix "$e491d/prefix" --account e491acct --doctor 2>"$e491d/acct-hook.err")"; e491_arc=$?
e491_aerr="$(cat "$e491d/acct-hook.err")"
e491_actlerr="$(cat "$e491d/acct-ctl.err")"
e491_aerrs="$(printf '%s\n' "$e491_aerr" | strip_egl491_warnings)"
e491_actls="$(printf '%s\n' "$e491_actlerr" | strip_egl491_warnings)"
[[ "$e491_arc" == "$e491_actl_rc" && "$e491_aout" == "$e491_actl" \
    && "$e491_aout" == *"conf parse:"* \
    && "$e491_aerrs" == "$e491_actls" \
    && "$(e491_count "$e491_aerr" EGRESSLOCK_ACCOUNT_HOME)" == 1 \
    && "$e491_aerr" == *"egresslock-setup: WARNING - EGRESSLOCK_ACCOUNT_HOME $e491_hsent"* \
    && "$e491_actlerr" != *"EGRESSLOCK_ACCOUNT_HOME is set but ignored"* \
    && "$e491_aout$e491_aerr" != *"$e491d/decoyhome"* \
    && -e "$e491d/decoyhome/.config/egresslock/e491-keep" ]] \
    && e491 pass || e491 fail "setup account doctor: ACCOUNT_HOME warns once, decoy home never read (control rc=$e491_actl_rc, rc=$e491_arc, out: $e491_aout, err: $e491_aerr)"

# 3. D4 on all three kit scripts: a flag set to `true`, `0`, or empty
#    warns once with the unchanged stdout/rc and never echoes the value.
for e491_script in "$SKIT" "$KIT" "$UKIT"; do
    case "$(basename "$e491_script")" in
        egresslock-setup) e491_pfx="egresslock-setup: WARNING - " ;;
        install-kit.sh)   e491_pfx="install-kit: WARNING - " ;;
        *)                e491_pfx="uninstall-kit: WARNING - " ;;
    esac
    e491_fctl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT "$e491_script" --help 2>"$e491d/fv-ctl.err")"; e491_fctl_rc=$?
    e491_fctl_err="$(cat "$e491d/fv-ctl.err")"
    e491_fok=1
    [[ "$e491_fctl_rc" == 0 && -z "$e491_fctl_err" ]] || e491_fok=0
    for e491_fv in true 0 ''; do
        e491_fout="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT="$e491_fv" \
            "$e491_script" --help 2>"$e491d/fv.err")"; e491_frc=$?
        e491_ferr="$(cat "$e491d/fv.err")"
        [[ "$e491_frc" == "$e491_fctl_rc" && "$e491_fout" == "$e491_fctl" \
            && "$e491_ferr" == "${e491_pfx}EGRESSLOCK_KIT_ALLOW_NON_ROOT is set but is not the exact value 1, so test mode is off; test-harness overrides are ignored." \
            && "$e491_ferr" != *"EGRESSLOCK_KIT_ALLOW_NON_ROOT="* ]] || e491_fok=0
    done
    (( e491_fok )) \
        && e491 pass || e491 fail "$(basename "$e491_script"): wrong flag values warn once, rc/stdout unchanged, value not echoed (control rc=$e491_fctl_rc, err: $(cat "$e491d/fv.err"))"
done

# 4. Install-kit, flag off, real namespace root: the ignored selectors fall
#    back to production. UNIT_SRC is an absent path, UB_BIN a foreign file,
#    DEB_LIBDIR a .deb marker, and the rest decoy dirs/profiles — so a
#    live gate would fail or change the destinations rather than pass.
#    EGL-524-D4: the /usr/bin/egresslock overmount is a benign kit-wrapper
#    marker, not the foreign non-wrapper file (that stays the ignored
#    UB_BIN hook value), so a deb-shaped host cannot force the production
#    UB probe to refuse.
e491_install_ns_prepare() { # <root>
    local root="$1"
    mkdir -p "$root/default-units" "$root/default-bin" "$root/default-sbin" \
        "$root/hook-units" "$root/hook-bin" "$root/hook-sbin" \
        "$root/opt" "$root/shim" "$root/empty-lib" "$root/deb-libdir" "$root/foreign-ub"
    printf '#!/usr/bin/env bash\n# the namespace leg pins destinations, not co-install policy\nexit 1\n' \
        > "$root/shim/dpkg-query"
    chmod +x "$root/shim/dpkg-query"
    printf 'deb-kit\n' > "$root/deb-libdir/VERSION"
    printf '#!/bin/sh\necho foreign deb-shaped engine\n' > "$root/foreign-ub/egresslock"
    printf '#!/bin/sh\n# egresslock-path-wrapper prefix=/host-foreign\nexec true\n' \
        > "$root/ub-marker"
    printf 'podman (enforce)\n' > "$root/profiles-labeled"
}
e491i="$e491d/install-ns"; rm -rf "$e491i"
e491_install_ns_prepare "$e491i"
cat > "$e491i/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: uid 0 with fixture bind mounts over the production
# destinations. $1 = fixture root, $2 = install-kit.sh.
set -euo pipefail
d=$1; kit=$2
mkdir -p /etc/systemd/system /usr/local/bin /usr/local/sbin
mount --bind "$d/default-units" /etc/systemd/system
mount --bind "$d/default-bin" /usr/local/bin
mount --bind "$d/default-sbin" /usr/local/sbin
if [[ -e /usr/lib/egresslock ]]; then
    mount --bind "$d/empty-lib" /usr/lib/egresslock
fi
if [[ -e /usr/bin/egresslock ]]; then
    mount --bind "$d/ub-marker" /usr/bin/egresslock
fi
export PATH="$d/shim:$E491_TESTBIN:$PATH"
exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    EGRESSLOCK_UNIT_SRC="$d/absent-unitsrc" \
    EGRESSLOCK_UNIT_DIR="$d/hook-units" \
    EGRESSLOCK_PATH_BINDIR="$d/hook-bin" \
    EGRESSLOCK_PATH_SBINDIR="$d/hook-sbin" \
    EGRESSLOCK_UB_BIN="$d/foreign-ub/egresslock" \
    EGRESSLOCK_DEB_LIBDIR="$d/deb-libdir" \
    EGRESSLOCK_APPARMOR_PROFILES="$d/profiles-labeled" \
    "$kit" --prefix "$d/opt"
EOF
chmod +x "$e491i/run.sh"
if command -v unshare >/dev/null 2>&1 && unshare -rm true 2>/dev/null; then
    e491iout="$(E491_TESTBIN="$TESTROOT/bin" unshare -rm bash "$e491i/run.sh" "$e491i" "$KIT" 2>&1)"; e491irc=$?
    e491_ok=1
    for e491_v in UNIT_SRC UNIT_DIR PATH_BINDIR PATH_SBINDIR UB_BIN DEB_LIBDIR APPARMOR_PROFILES; do
        e491_named_warning "$e491iout" "install-kit: WARNING - " "EGRESSLOCK_$e491_v" || e491_ok=0
        [[ "$(e491_count "$e491iout" "EGRESSLOCK_$e491_v")" == 1 ]] || e491_ok=0
    done
    [[ "$e491irc" == 0 \
        && "$e491iout" == *"successfully installed! kit is at: $e491i/opt"* \
        && -f "$e491i/default-units/egresslock-verify@.service" \
        && -f "$e491i/default-units/egresslock-verify@.timer" \
        && -f "$e491i/default-bin/egresslock" \
        && -f "$e491i/default-sbin/egresslock-setup" \
        && "$(grep -c "^ExecStart=$e491i/opt/egresslock-verify$" \
              "$e491i/default-units/egresslock-verify@.service")" == 1 \
        && "$(sed -n 2p "$e491i/default-bin/egresslock")" \
           == "# egresslock-path-wrapper prefix=$e491i/opt" \
        && -z "$(ls -A "$e491i/hook-units")" \
        && -z "$(ls -A "$e491i/hook-bin")" \
        && -z "$(ls -A "$e491i/hook-sbin")" \
        && "$e491iout" != *"$e491i/absent-unitsrc"* \
        && "$e491iout" != *"$e491i/deb-libdir"* \
        && "$e491iout" != *"$e491i/foreign-ub"* \
        && "$e491iout" != *"$e491i/hook-units"* \
        && "$e491iout" != *"$e491i/hook-bin"* \
        && "$e491iout" != *"$e491i/hook-sbin"* \
        && "$e491iout" != *"$e491i/profiles-labeled"* \
        && "$e491iout" != *"EGRESSLOCK_UNIT_SRC="* \
        && "$e491iout" != *"EGRESSLOCK_UB_BIN="* ]] || e491_ok=0
    (( e491_ok )) \
        && e491 pass || e491 fail "install-kit: ignored selectors write only the production targets, never the decoys (rc=$e491irc, out: $e491iout)"
else
    skip "namespace-unavailable" "install-kit ignored-selector negative skipped: unshare -rm unavailable"
fi

# 4b. EGL-524-D5 pin: a deb-shaped host must not change the proofs above.
#     One private namespace farms a non-wrapper /usr/bin/egresslock and
#     /usr/lib/egresslock/VERSION (rbind mirrors + absolute-symlink farms
#     — relative ../realbin targets ENOENT once the farm is bound over
#     /usr/bin), then runs the two D3 selector bodies and the e491i body,
#     each against a fresh fixture root so wrapper-prefix guards cannot
#     interfere. Removing any neutralization overmount reds on a clean host.
e491v="$e491d/deb-shape"; rm -rf "$e491v"
mkdir -p "$e491v/realbin" "$e491v/reallib" "$e491v/farmbin" "$e491v/farmlib"
e434_sel_ns_prepare "$e491v/sel-ub" "$e491v/sel-ub/opt"
e434_sel_ns_prepare "$e491v/sel-deb" "$e491v/sel-deb/opt"
e491_install_ns_prepare "$e491v/install-ns"
cp "$e491i/run.sh" "$e491v/install-ns/run.sh"
chmod +x "$e491v/install-ns/run.sh"
cat > "$e491v/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: farm a deb-shaped /usr/bin + /usr/lib, then run
# the two selector bodies and the e491i body against it.
# $1 = root, $2 = kit, $3 = UB selector root, $4 = DEB selector root,
# $5 = e491i-style root, $6 = extra test PATH for e491i.
set -euo pipefail
d=$1; kit=$2; sel_ub=$3; sel_deb=$4; i_root=$5; testbin=$6
mount --rbind /usr/bin "$d/realbin"
mount --rbind /usr/lib "$d/reallib"
for p in "$d/realbin"/*; do
    ln -s "$p" "$d/farmbin/${p##*/}"
done
for p in "$d/reallib"/*; do
    ln -s "$p" "$d/farmlib/${p##*/}"
done
# The deb shape itself: a foreign engine on PATH and a libdir VERSION.
rm -f "$d/farmbin/egresslock"
printf '#!/bin/sh\n# the deb engine, not a kit PATH wrapper\n' > "$d/farmbin/egresslock"
chmod 0755 "$d/farmbin/egresslock"
rm -rf "$d/farmlib/egresslock"
mkdir -p "$d/farmlib/egresslock"
printf 'deb-kit\n' > "$d/farmlib/egresslock/VERSION"
mount --bind "$d/farmbin" /usr/bin
mount --bind "$d/farmlib" /usr/lib
printf 'ignored UB_BIN decoy\n' > "$d/decoy-ub"
printf 'ignored DEB_LIBDIR decoy\n' > "$d/decoy-lib"
set +e
bash "$sel_ub/run.sh" "$sel_ub" "$kit" EGRESSLOCK_UB_BIN "$d/decoy-ub" "$sel_ub/opt" > "$d/out-ub" 2>&1
echo $? > "$d/rc-ub"
bash "$sel_deb/run.sh" "$sel_deb" "$kit" EGRESSLOCK_DEB_LIBDIR "$d/decoy-lib" "$sel_deb/opt" > "$d/out-deb" 2>&1
echo $? > "$d/rc-deb"
E491_TESTBIN="$testbin" bash "$i_root/run.sh" "$i_root" "$kit" > "$d/out-i" 2>&1
echo $? > "$d/rc-i"
exit 0
EOF
chmod +x "$e491v/run.sh"
if e434_sel_ns_available; then
    e491vout="$(unshare -rm bash "$e491v/run.sh" "$e491v" "$KIT" \
        "$e491v/sel-ub" "$e491v/sel-deb" "$e491v/install-ns" "$TESTROOT/bin" 2>&1)"; e491vrc=$?
    e491v_rc_ub="$(cat "$e491v/rc-ub" 2>/dev/null)"
    e491v_rc_deb="$(cat "$e491v/rc-deb" 2>/dev/null)"
    e491v_rc_i="$(cat "$e491v/rc-i" 2>/dev/null)"
    e491v_out_ub="$(cat "$e491v/out-ub" 2>/dev/null)"
    e491v_out_deb="$(cat "$e491v/out-deb" 2>/dev/null)"
    e491v_out_i="$(cat "$e491v/out-i" 2>/dev/null)"
    e491v_ok=1
    [[ "$e491vrc" == 0 && "$e491v_rc_ub" == 0 && "$e491v_rc_deb" == 0 \
        && "$e491v_rc_i" == 0 ]] || e491v_ok=0
    [[ "$e491v_out_ub" == *"successfully installed! kit is at: $e491v/sel-ub/opt"* ]] || e491v_ok=0
    [[ "$e491v_out_deb" == *"successfully installed! kit is at: $e491v/sel-deb/opt"* ]] || e491v_ok=0
    [[ "$e491v_out_i" == *"successfully installed! kit is at: $e491v/install-ns/opt"* ]] || e491v_ok=0
    [[ "$e491v_out_ub" != *"exists and is not an egresslock kit PATH"* \
        && "$e491v_out_ub" != *"$e491v/decoy-ub"* ]] || e491v_ok=0
    [[ "$e491v_out_deb" != *"an egresslock .deb kit exists"* \
        && "$e491v_out_deb" != *"$e491v/decoy-lib"* ]] || e491v_ok=0
    [[ -f "$e491v/install-ns/default-units/egresslock-verify@.service" \
        && -f "$e491v/install-ns/default-units/egresslock-verify@.timer" \
        && -f "$e491v/install-ns/default-bin/egresslock" \
        && -f "$e491v/install-ns/default-sbin/egresslock-setup" \
        && "$(sed -n 2p "$e491v/install-ns/default-bin/egresslock")" \
           == "# egresslock-path-wrapper prefix=$e491v/install-ns/opt" ]] || e491v_ok=0
    (( e491v_ok )) \
        && e491 pass || e491 fail "deb-shaped host: selector and e491i proofs stay green (farm rc=$e491vrc, ub rc=$e491v_rc_ub, deb rc=$e491v_rc_deb, i rc=$e491v_rc_i, ub out: $e491v_out_ub, deb out: $e491v_out_deb, i out: $e491v_out_i)"
else
    skip "namespace-unavailable" "deb-shaped-host neutralization pin skipped: unshare -rm or bind mount unavailable"
fi

# 5. Uninstall-kit, flag off, namespace root: the unit/PATH/account hooks
#    are ignored, so the production targets are removed while the hook
#    sentinels and the decoy home stay, and the getent home is the one
#    purged. Each warning fires once; no decoy path is named.
e491u="$e491d/uninstall-ns"; mkdir -p "$e491u/default-units" "$e491u/default-bin" \
    "$e491u/default-sbin" "$e491u/hook-units" "$e491u/hook-bin" "$e491u/hook-sbin" \
    "$e491u/prefix/gateway" "$e491u/bin" "$e491u/accthome/.config/egresslock" \
    "$e491u/decoyhome/.config/egresslock"
printf '#!/bin/sh\nexit 0\n' > "$e491u/prefix/egresslock"; chmod +x "$e491u/prefix/egresslock"
: > "$e491u/prefix/egresslock-verify"
printf 'version: 0.0.0-e491\n' > "$e491u/prefix/VERSION"
: > "$e491u/prefix/gateway/Containerfile"
: > "$e491u/default-units/egresslock-verify@.service"
: > "$e491u/default-units/egresslock-verify@.timer"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec true\n' "$e491u/prefix" \
    > "$e491u/default-bin/egresslock"
printf '#!/bin/sh\n# egresslock-path-wrapper prefix=%s\nexec true\n' "$e491u/prefix" \
    > "$e491u/default-sbin/egresslock-setup"
: > "$e491u/hook-units/egresslock-verify@.service"
: > "$e491u/hook-units/egresslock-verify@.timer"
: > "$e491u/hook-bin/egresslock"
: > "$e491u/hook-sbin/egresslock-setup"
: > "$e491u/accthome/.config/egresslock/main.conf"
: > "$e491u/decoyhome/.config/egresslock/e491-keep"
cat > "$e491u/bin/id" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "e491acct" ]]; then exit 0; fi
exec /usr/bin/id "$@"
EOF
cat > "$e491u/bin/getent" <<EOF
#!/usr/bin/env bash
if [[ "\$1" == "passwd" && "\$2" == "e491acct" ]]; then
    printf 'e491acct:x:1000:1000::%s:/bin/sh\n' "$e491u/accthome"
    exit 0
fi
exec /usr/bin/getent "\$@"
EOF
chmod +x "$e491u/bin/id" "$e491u/bin/getent"
cat > "$e491u/run.sh" <<'EOF'
#!/usr/bin/env bash
# Inside `unshare -rm`: uid 0 with fixture bind mounts over the production
# destinations. $1 = fixture root, $2 = uninstall-kit.sh.
set -euo pipefail
d=$1; ukit=$2
mkdir -p /etc/systemd/system /usr/local/bin /usr/local/sbin
mount --bind "$d/default-units" /etc/systemd/system
mount --bind "$d/default-bin" /usr/local/bin
mount --bind "$d/default-sbin" /usr/local/sbin
export PATH="$d/bin:$E491_TESTBIN:$PATH"
exec env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT \
    EGRESSLOCK_UNIT_DIR="$d/hook-units" \
    EGRESSLOCK_PATH_BINDIR="$d/hook-bin" \
    EGRESSLOCK_PATH_SBINDIR="$d/hook-sbin" \
    EGRESSLOCK_ACCOUNT_HOME="$d/decoyhome" \
    "$ukit" --prefix "$d/prefix" --account e491acct --purge-account-data
EOF
chmod +x "$e491u/run.sh"
if command -v unshare >/dev/null 2>&1 && unshare -rm true 2>/dev/null; then
    e491uout="$(E491_TESTBIN="$TESTROOT/bin" unshare -rm bash "$e491u/run.sh" "$e491u" "$UKIT" 2>&1)"; e491urc=$?
    e491_ok=1
    for e491_v in UNIT_DIR PATH_BINDIR PATH_SBINDIR ACCOUNT_HOME; do
        e491_named_warning "$e491uout" "uninstall-kit: WARNING - " "EGRESSLOCK_$e491_v" || e491_ok=0
        [[ "$(e491_count "$e491uout" "EGRESSLOCK_$e491_v")" == 1 ]] || e491_ok=0
    done
    [[ "$e491urc" == 0 \
        && "$e491uout" == *"kit removed from $e491u/prefix; instanced templates removed; timers stopped"* \
        && ! -e "$e491u/prefix" \
        && ! -e "$e491u/default-units/egresslock-verify@.service" \
        && ! -e "$e491u/default-units/egresslock-verify@.timer" \
        && ! -e "$e491u/default-bin/egresslock" \
        && ! -e "$e491u/default-sbin/egresslock-setup" \
        && -e "$e491u/hook-units/egresslock-verify@.service" \
        && -e "$e491u/hook-units/egresslock-verify@.timer" \
        && -e "$e491u/hook-bin/egresslock" \
        && -e "$e491u/hook-sbin/egresslock-setup" \
        && ! -e "$e491u/accthome/.config/egresslock" \
        && -e "$e491u/decoyhome/.config/egresslock/e491-keep" \
        && "$e491uout" != *"$e491u/hook-units"* \
        && "$e491uout" != *"$e491u/hook-bin"* \
        && "$e491uout" != *"$e491u/hook-sbin"* \
        && "$e491uout" != *"$e491u/decoyhome"* \
        && "$e491uout" != *"EGRESSLOCK_UNIT_DIR="* \
        && "$e491uout" != *"EGRESSLOCK_ACCOUNT_HOME="* ]] || e491_ok=0
    (( e491_ok )) \
        && e491 pass || e491 fail "uninstall-kit: ignored hooks keep the production targets and the decoys (rc=$e491urc, out: $e491uout)"
else
    skip "namespace-unavailable" "uninstall-kit ignored-hook negative skipped: unshare -rm unavailable"
fi

# 6. Silence negatives: unset hooks, an empty-string hook (counts as
#    unset), and the flag on (hooks live/honored) all stay silent.
#    EGL-531-D3: EGRESSLOCK_SHARE is no longer an accepted-live name —
#    it moves to the warns arm, its one warning pinned where this leg
#    used to pin silence.
e491_sok=1
e491_sctl="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT -u EGRESSLOCK_GW_IMAGE \
    -u EGRESSLOCK_UNIT_DIR -u EGRESSLOCK_SHARE "$SKIT" --help 2>"$e491d/silent-ctl.err")"; e491_sctl_rc=$?
[[ "$e491_sctl_rc" == 0 && ! -s "$e491d/silent-ctl.err" ]] || e491_sok=0
e491_sout="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_GW_IMAGE= \
    "$SKIT" --help 2>"$e491d/silent-empty.err")"; e491_src=$?
[[ "$e491_src" == "$e491_sctl_rc" && "$e491_sout" == "$e491_sctl" \
    && ! -s "$e491d/silent-empty.err" ]] || e491_sok=0
e491_sout="$(env -u EGRESSLOCK_KIT_ALLOW_NON_ROOT EGRESSLOCK_SHARE="$e491d/share" \
    "$SKIT" --help 2>"$e491d/silent-share.err")"; e491_src=$?
e491_serr="$(cat "$e491d/silent-share.err")"
[[ "$e491_src" == "$e491_sctl_rc" && "$e491_sout" == "$e491_sctl" \
    && "$(e491_count "$e491_serr" EGRESSLOCK_SHARE)" == 1 \
    && "$(printf '%s\n' "$e491_serr" | grep -c 'is set but ignored' || true)" == 1 \
    && "$e491_serr" == *"EGRESSLOCK_SHARE $e491_hsent"* \
    && "$e491_serr" != *"$e491d/share"* ]] || e491_sok=0
e491_sout="$(env EGRESSLOCK_KIT_ALLOW_NON_ROOT=1 EGRESSLOCK_UNIT_DIR="$e491d/hook-units" \
    EGRESSLOCK_GW_IMAGE='localhost/egl491-on:latest' \
    "$SKIT" --help 2>"$e491d/silent-on.err")"; e491_src=$?
[[ "$e491_src" == "$e491_sctl_rc" && "$e491_sout" == "$e491_sctl" \
    && ! -s "$e491d/silent-on.err" ]] || e491_sok=0
(( e491_sok )) \
    && e491 pass || e491 fail "silence negatives: unset/empty/flag-on stay warning-free; the ignored SHARE hook warns once (control rc=$e491_sctl_rc, errs: $(cat "$e491d"/silent-*.err 2>/dev/null))"

section_end egl491

# --- EGL-558: battery closing block (subtotal rows + BATTERY TOTAL) -----
# Scratch tree: a copied tests/run.sh beside stub test-*.sh harnesses.
# run.sh takes tests_dir from BASH_SOURCE (tests/run.sh:77), and --serial
# skips the engine selection/weights machinery, so each probe is ~1s.
section_begin egl558 "EGL-558 battery closing block"
e558() { assert "$@"; }
e558d="$STATE/egl558"
rm -rf "$e558d"
mkdir -p "$e558d/tests"
cp "$TREE_ROOT/tests/run.sh" "$TREE_ROOT/tests/lib.sh" "$e558d/tests/"

# Green stub: two asserts, no skips, record + printed TOTAL via lib.sh.
cat > "$e558d/tests/test-a.sh" <<'EOF'
#!/usr/bin/env bash
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
section_begin e558a "EGL-558 scratch green"
assert pass; assert pass
section_end e558a
results_emit e558a
results_total
EOF
# Green stub with one named skip.
cat > "$e558d/tests/test-b.sh" <<'EOF'
#!/usr/bin/env bash
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
section_begin e558b "EGL-558 scratch skip"
assert pass
section_end e558b
skip "scratch-skip" "scratch skip (EGL-558 probe)"
results_emit e558b
results_total
EOF
chmod +x "$e558d/tests/test-a.sh" "$e558d/tests/test-b.sh"

# Probe 1 — all green: subtotal rows, one battery-wide TOTAL as the last
# numeric line, the per-harness TOTAL lines byte-identical, and the battery
# skipped count reconciled with `run.sh: skips`. An inherited record path
# must be dropped (a decoy file must not appear).
e558_decoy="$e558d/decoy.result"
e558rc=0
( cd "$e558d" && EGRESSLOCK_TEST_BATTERY_RESULT="$e558_decoy" \
    bash tests/run.sh --serial ) >"$e558d/green.out" 2>"$e558d/green.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 0 ]] || e558ok=0
[[ ! -e "$e558_decoy" ]] || e558ok=0
[[ ! -s "$e558d/green.err" ]] || e558ok=0
grep -qxF 'run.sh: subtotal — test-a.sh: 2 passed, 0 failed, 0 skipped' "$e558d/green.out" || e558ok=0
grep -qxF 'run.sh: subtotal — test-b.sh: 1 passed, 0 failed, 1 skipped' "$e558d/green.out" || e558ok=0
grep -qxF 'RESULTS TOTAL: 2 passed, 0 failed, 0 skipped (tree: no-git)' "$e558d/green.out" || e558ok=0
grep -qxF 'RESULTS TOTAL: 1 passed, 0 failed, 1 skipped (scratch-skip) (tree: no-git)' "$e558d/green.out" || e558ok=0
grep -q '^run.sh: skips — 1 ' "$e558d/green.out" || e558ok=0
[[ "$(grep -c '^BATTERY TOTAL:' "$e558d/green.out")" == 1 ]] || e558ok=0
e558_want=$'BATTERY TOTAL: 3 passed, 0 failed, 1 skipped (tree: no-git)\nrun.sh: egresslock tests done (rc=0)'
[[ "$(tail -n 2 "$e558d/green.out")" == "$e558_want" ]] || e558ok=0
(( e558ok )) && e558 pass || e558 fail "all-green closing block (rc=$e558rc, tail: $(tail -n 4 "$e558d/green.out" 2>/dev/null | tr '\n' '|'))"

# Probe 2 — red harness with a record: its counts still aggregate, the
# battery line prints, rc stays 1 (a red run must not lose its total).
cat > "$e558d/tests/test-red.sh" <<'EOF'
#!/usr/bin/env bash
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
section_begin e558r "EGL-558 scratch red"
assert pass; assert fail "scratch red A"; assert fail "scratch red B"
section_end e558r
results_emit e558r
results_total
[[ "$total_fail" -eq 0 ]]
EOF
chmod +x "$e558d/tests/test-red.sh"
e558rc=0
( cd "$e558d" && bash tests/run.sh --serial ) >"$e558d/red.out" 2>"$e558d/red.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 1 ]] || e558ok=0
grep -qxF 'run.sh: subtotal — test-red.sh: 1 passed, 2 failed, 0 skipped' "$e558d/red.out" || e558ok=0
grep -qxF 'BATTERY TOTAL: 4 passed, 2 failed, 1 skipped (tree: no-git)' "$e558d/red.out" || e558ok=0
grep -q 'battery TOTAL unavailable' "$e558d/red.err" && e558ok=0
(( e558ok )) && e558 pass || e558 fail "red-with-record aggregates its counts (rc=$e558rc, tail: $(tail -n 3 "$e558d/red.out" 2>/dev/null | tr '\n' '|'))"
rm -f "$e558d/tests/test-red.sh"

# Probe 3 — crash before a total: named refusal, no battery line, healthy
# rows still print, rc 1.
cat > "$e558d/tests/test-crash.sh" <<'EOF'
#!/usr/bin/env bash
echo "RESULTS (EGL-558 scratch crash): 5 passed, 0 failed"
echo "scratch crash before a TOTAL"
exit 1
EOF
chmod +x "$e558d/tests/test-crash.sh"
e558rc=0
( cd "$e558d" && bash tests/run.sh --serial ) >"$e558d/crash.out" 2>"$e558d/crash.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 1 ]] || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/crash.out" && e558ok=0
grep -qxF 'run.sh: FAIL battery TOTAL unavailable — test-crash.sh (EGL-558)' "$e558d/crash.err" || e558ok=0
grep -qxF 'run.sh: subtotal — test-a.sh: 2 passed, 0 failed, 0 skipped' "$e558d/crash.out" || e558ok=0
grep -qxF 'run.sh: subtotal — test-b.sh: 1 passed, 0 failed, 1 skipped' "$e558d/crash.out" || e558ok=0
(( e558ok )) && e558 pass || e558 fail "crash-before-total refuses the aggregate (rc=$e558rc, err: $(tr '\n' '|' < "$e558d/crash.err" 2>/dev/null))"
rm -f "$e558d/tests/test-crash.sh"

# Probe 4 — green harness with no record (the D5 gap): the run must not
# exit 0 without a battery total; refusal names the harness.
cat > "$e558d/tests/test-norec.sh" <<'EOF'
#!/usr/bin/env bash
echo "RESULTS TOTAL: 9 passed, 0 failed, 0 skipped (tree: no-git)"
exit 0
EOF
chmod +x "$e558d/tests/test-norec.sh"
e558rc=0
( cd "$e558d" && bash tests/run.sh --serial ) >"$e558d/norec.out" 2>"$e558d/norec.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 1 ]] || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/norec.out" && e558ok=0
grep -qxF 'run.sh: FAIL battery TOTAL unavailable — test-norec.sh (EGL-558)' "$e558d/norec.err" || e558ok=0
(( e558ok )) && e558 pass || e558 fail "green-without-record forces rc=1 and refuses (rc=$e558rc, err: $(tr '\n' '|' < "$e558d/norec.err" 2>/dev/null))"
rm -f "$e558d/tests/test-norec.sh"

# Probe 5 — disagreeing tree tags: refusal names the harness whose tag
# differs, no battery line, rows still print.
cat > "$e558d/tests/test-tree.sh" <<'EOF'
#!/usr/bin/env bash
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
section_begin e558t "EGL-558 scratch tree"
assert pass
section_end e558t
results_emit e558t
results_total
rf="$EGRESSLOCK_TEST_BATTERY_RESULT"
awk 'BEGIN{FS=OFS="\t"} $1=="tree"{$2="tree: git-checkout"} {print}' "$rf" > "$rf.tmp" && mv -f "$rf.tmp" "$rf"
EOF
chmod +x "$e558d/tests/test-tree.sh"
e558rc=0
( cd "$e558d" && bash tests/run.sh --serial ) >"$e558d/tree.out" 2>"$e558d/tree.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 1 ]] || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/tree.out" && e558ok=0
grep -qxF 'run.sh: FAIL battery TOTAL unavailable — test-tree.sh (EGL-558)' "$e558d/tree.err" || e558ok=0
[[ "$(grep -c '^run.sh: subtotal — ' "$e558d/tree.out")" == 3 ]] || e558ok=0
(( e558ok )) && e558 pass || e558 fail "tree-tag disagreement refuses the aggregate (rc=$e558rc, err: $(tr '\n' '|' < "$e558d/tree.err" 2>/dev/null))"
rm -f "$e558d/tests/test-tree.sh"

# Fake engine for the suppression/shard probes: four gated sections (the
# EGL-532 planner requires the arc12/egl139 alias pairing) and one pass each.
cat > "$e558d/tests/test-engine.sh" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == "--list-sections" ]]; then
    printf '%s\n' s1 s2 arc12 egl139
    exit 0
fi
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
if shard_section_run s1; then
section_begin s1 "EGL-558 scratch engine s1"
assert pass
section_end s1
results_emit s1
fi
if shard_section_run s2; then
section_begin s2 "EGL-558 scratch engine s2"
assert pass
section_end s2
results_emit s2
fi
if shard_section_run arc12; then
section_begin arc12 "EGL-558 scratch engine arc12"
assert pass
section_end arc12
results_emit arc12
fi
if shard_section_run egl139; then
section_begin egl139 "EGL-558 scratch engine egl139"
assert pass
section_end egl139
results_emit egl139
fi
arc14_pass=0; arc14_fail=0
egl140_pass=0; egl140_fail=0
if shard_section_run arc12; then
    echo "RESULTS (ARC-14 site defaults): $arc14_pass passed, $arc14_fail failed"
fi
if shard_section_run egl139; then
    echo "RESULTS (EGL-140 pin record witness): $egl140_pass passed, $egl140_fail failed"
fi
results_total
EOF
printf 's1\t100\ns2\t100\narc12\t100\negl139\t100\n' > "$e558d/tests/shard-weights.tsv"
chmod +x "$e558d/tests/test-engine.sh"

# Probe 6 — partial modes print no battery line and keep their caveat.
e558rc=0
( cd "$e558d" && bash tests/run.sh --section s1 ) >"$e558d/section.out" 2>"$e558d/section.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 0 ]] || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/section.out" && e558ok=0
grep -q '^run.sh: subtotal — ' "$e558d/section.out" && e558ok=0
grep -qxF 'run.sh: --section partial TOTAL over: s1 (not the battery total; EGL-464)' "$e558d/section.out" || e558ok=0
e558rc=0
( cd "$e558d" && bash tests/run.sh --shard 1/2 ) >"$e558d/shard1.out" 2>"$e558d/shard1.err" || e558rc=$?
[[ "$e558rc" == 0 ]] || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/shard1.out" && e558ok=0
grep -q '^run.sh: subtotal — ' "$e558d/shard1.out" && e558ok=0
grep -q '^run.sh: harness test-engine.sh shard 1/2 ' "$e558d/shard1.out" || e558ok=0
(( e558ok )) && e558 pass || e558 fail "partial modes suppress the battery block (section rc, shard rc=$e558rc)"

# Probe 7 — sharded engine: the parent-rendered merged TOTAL publishes the
# engine record, so the battery line sums it; shard children never write
# the inherited decoy path.
e558_decoy2="$e558d/decoy2.result"
e558rc=0
( cd "$e558d" && EGRESSLOCK_TEST_BATTERY_RESULT="$e558_decoy2" \
    bash tests/run.sh --shard 2 ) >"$e558d/shard2.out" 2>"$e558d/shard2.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 0 ]] || e558ok=0
[[ ! -e "$e558_decoy2" ]] || e558ok=0
grep -qxF 'run.sh: subtotal — test-engine.sh: 4 passed, 0 failed, 0 skipped' "$e558d/shard2.out" || e558ok=0
grep -qxF 'BATTERY TOTAL: 7 passed, 0 failed, 1 skipped (tree: no-git)' "$e558d/shard2.out" || e558ok=0
[[ "$(grep -c '^RESULTS TOTAL: 4 passed, 0 failed, 0 skipped (tree: no-git)$' "$e558d/shard2.out")" == 1 ]] || e558ok=0
(( e558ok )) && e558 pass || e558 fail "sharded engine merged record aggregates (rc=$e558rc, err: $(tr '\n' '|' < "$e558d/shard2.err" 2>/dev/null))"

# Real-run anchor: a single-harness run on the shipped tree keeps today's
# tail — a harness TOTAL, the skip/coverage trailer, done; no battery line.
e558rc=0
bash "$TREE_ROOT/tests/run.sh" --harness docs >"$e558d/docs.out" 2>"$e558d/docs.err" || e558rc=$?
e558ok=1
[[ "$e558rc" == 0 ]] || e558ok=0
grep -q '^RESULTS TOTAL: ' "$e558d/docs.out" || e558ok=0
grep -q '^BATTERY TOTAL:' "$e558d/docs.out" && e558ok=0
grep -q '^run.sh: subtotal — ' "$e558d/docs.out" && e558ok=0
(( e558ok )) && e558 pass || e558 fail "real --harness docs tail has no battery line (rc=$e558rc, tail: $(tail -n 3 "$e558d/docs.out" 2>/dev/null | tr '\n' '|'))"

section_end egl558

echo
results_emit arc16
results_emit egl85
results_emit arc17
results_emit egl433
results_emit egl555
results_emit egl121
results_emit egl463
results_emit egl258
results_emit egl43
results_emit egl420
results_emit egl49
results_emit arc18
results_emit egl328
results_emit egl51
results_emit arc19
results_emit egl38
results_emit egl409
results_emit arc22
results_emit a39
results_emit egl434
results_emit arc72
results_emit arc14
results_emit arc20
results_emit arc23
results_emit arc70
results_emit arc69s
results_emit egl50
results_emit egl55
results_emit egl59
results_emit egl60
results_emit egl68
results_emit egl90
results_emit egl83
results_emit egl115
results_emit egl84
results_emit egl203
results_emit egl240
results_emit egl287
results_emit egl200
results_emit egl581
results_emit egl491
results_emit egl558
# EGL-352: unconditional tail check — a leak books a fail-only counted
# egl352_guard section and reds TOTAL without moving a green count.
harness_stderr_guard_check
# EGL-184: the hand-maintained 31-term sums are replaced by the register
# (counted snapshots; no externals — every kit increment runs the funnels).
# Fail-closed completeness per EGL-184-D4; the TOTAL line keeps the
# EGL-99 skip count + tree-shape tag.
results_total
[[ "$total_fail" -eq 0 ]]
